require('dotenv').config({ path: '.env.local' });

const express = require('express');
const AWS = require('aws-sdk');
const helmet = require('helmet');
const jwt = require('jsonwebtoken');

// ============================================================================
// SECRETS LOADING
// ============================================================================

let secrets = {};

async function loadSecrets() {
  const NODE_ENV = process.env.NODE_ENV || 'development';

  if (NODE_ENV === 'production') {
    // Load from AWS Secrets Manager in production
    const secretsManager = new AWS.SecretsManager({
      region: process.env.AWS_REGION || 'us-east-1'
    });

    try {
      const secretId = process.env.SECRETS_ID || 'prod/app-secrets';
      const response = await secretsManager.getSecretValue({
        SecretId: secretId
      }).promise();

      secrets = JSON.parse(response.SecretString);
      console.log('✓ Secrets loaded from AWS Secrets Manager');

    } catch (error) {
      console.error('✗ Failed to load secrets:', error.message);
      process.exit(1);
    }

  } else if (NODE_ENV === 'staging') {
    // Load from environment variables for staging
    secrets = {
      JWT_SECRET: process.env.JWT_SECRET,
      DATABASE_URL: process.env.DATABASE_URL,
      API_KEY: process.env.API_KEY
    };
    console.log('✓ Secrets loaded from environment variables');

  } else {
    // Load from .env.local for development
    secrets = {
      JWT_SECRET: process.env.JWT_SECRET || 'dev-secret-change-me',
      DATABASE_URL: process.env.DATABASE_URL,
      API_KEY: process.env.API_KEY || 'dev-api-key'
    };
    console.log('✓ Secrets loaded from .env.local');
  }

  // Validate required secrets
  const required = ['JWT_SECRET'];
  const missing = required.filter(key => !secrets[key]);

  if (missing.length > 0) {
    console.error(`Missing required secrets: ${missing.join(', ')}`);
    process.exit(1);
  }

  return secrets;
}

// ============================================================================
// SECRET ACCESS HELPERS
// ============================================================================

/**
 * Get secret value safely (never log the value itself)
 */
function getSecret(name) {
  if (!secrets[name]) {
    throw new Error(`Secret '${name}' not found`);
  }
  return secrets[name];
}

/**
 * Check if secret exists
 */
function hasSecret(name) {
  return !!secrets[name];
}

/**
 * Validate secret format (without logging the value)
 */
function validateSecret(name, pattern) {
  const value = getSecret(name);
  if (!pattern.test(value)) {
    throw new Error(`Secret '${name}' has invalid format`);
  }
  return true;
}

// ============================================================================
// AUTHENTICATION MIDDLEWARE (using safe secret access)
// ============================================================================

const authenticateToken = (req, res, next) => {
  const authHeader = req.headers['authorization'];
  const token = authHeader && authHeader.split(' ')[1];

  if (!token) {
    return res.status(401).json({ error: 'Access token required' });
  }

  try {
    // Get secret safely
    const jwtSecret = getSecret('JWT_SECRET');
    jwt.verify(token, jwtSecret, (err, user) => {
      if (err) {
        return res.status(403).json({ error: 'Invalid or expired token' });
      }
      req.user = user;
      next();
    });
  } catch (error) {
    return res.status(500).json({ error: 'Authentication error' });
  }
};

// ============================================================================
// APPLICATION
// ============================================================================

async function createApp() {
  // Load secrets first
  await loadSecrets();

  const app = express();

  app.use(helmet());
  app.use(express.json({ limit: '10kb' }));

  // Protected route - uses secret safely
  app.get('/users', authenticateToken, (req, res) => {
    res.json([
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' }
    ]);
  });

  // Login endpoint - creates JWT using secret
  app.post('/login', (req, res) => {
    const { email, password } = req.body;

    if (email === 'test@example.com' && password === 'password123') {
      try {
        const user = { id: 1, email: 'test@example.com', role: 'admin' };
        const jwtSecret = getSecret('JWT_SECRET');
        const token = jwt.sign(user, jwtSecret, { expiresIn: '1h' });

        return res.json({ token });
      } catch (error) {
        return res.status(500).json({ error: 'Token generation failed' });
      }
    }

    res.status(401).json({ error: 'Invalid credentials' });
  });

  // Health check
  app.get('/health', (req, res) => {
    res.json({ status: 'ok' });
  });

  return app;
}

// ============================================================================
// STARTUP
// ============================================================================

const PORT = process.env.PORT || 3000;

createApp().then(app => {
  app.listen(PORT, () => {
    console.log(`✓ Server running on port ${PORT}`);
  });
}).catch(error => {
  console.error('Failed to start server:', error);
  process.exit(1);
});
