# Security Review of app.js

## Executive Summary
This is a basic Express.js application with minimal functionality. While the current implementation has limited attack surface, there are significant security improvements needed for production deployment.

---

## Critical Issues Found

### 1. **Missing Authentication & Authorization** ⚠️ CRITICAL
**Severity:** HIGH  
**OWASP Top 10:** #01 - Broken Authentication

**Issue:**
All endpoints are publicly accessible with no authentication mechanism. The `/users` endpoint exposes user data without any access controls.

**Current Code:**
```javascript
app.get('/users', (req, res) => {
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ]);
});
```

**Vulnerability:**
- Anyone can access sensitive user information
- No user identity verification
- No role-based access control (RBAC)

**Recommended Fix:**
```javascript
const jwt = require('jsonwebtoken');

// Middleware for JWT verification
const authenticateToken = (req, res, next) => {
  const authHeader = req.headers['authorization'];
  const token = authHeader && authHeader.split(' ')[1];

  if (!token) {
    return res.status(401).json({ error: 'Access token required' });
  }

  jwt.verify(token, process.env.JWT_SECRET, (err, user) => {
    if (err) {
      return res.status(403).json({ error: 'Invalid or expired token' });
    }
    req.user = user;
    next();
  });
};

// Protected endpoint
app.get('/users', authenticateToken, (req, res) => {
  // Only allow admin users to view all users
  if (req.user.role !== 'admin') {
    return res.status(403).json({ error: 'Insufficient permissions' });
  }

  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ]);
});
```

---

### 2. **Missing Input Validation** ⚠️ HIGH
**Severity:** HIGH  
**OWASP Top 10:** #03 - Injection

**Issue:**
No input validation on query parameters or request body. This leaves the application vulnerable to:
- NoSQL Injection
- SQL Injection (if database is added)
- XSS attacks
- Command Injection

**Current Code:**
```javascript
app.get('/users', (req, res) => {
  // No validation of incoming requests
```

**Recommended Fix:**
```javascript
const { query, validationResult } = require('express-validator');

// Add input validation middleware
const validateUserQuery = [
  query('id')
    .optional()
    .isInt({ min: 1 })
    .withMessage('ID must be a positive integer'),
  query('email')
    .optional()
    .isEmail()
    .withMessage('Invalid email format'),
  query('limit')
    .optional()
    .isInt({ min: 1, max: 100 })
    .withMessage('Limit must be between 1 and 100'),
];

app.get('/users', validateUserQuery, (req, res) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({ errors: errors.array() });
  }

  // Process validated input
  const { id, email, limit = 10 } = req.query;

  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ]);
});
```

---

### 3. **No HTTPS/TLS Enforcement** ⚠️ HIGH
**Severity:** HIGH  
**OWASP Top 10:** #02 - Cryptographic Failures

**Issue:**
Application serves over plain HTTP without encryption. All data in transit is unencrypted and vulnerable to man-in-the-middle (MITM) attacks.

**Recommended Fix:**
```javascript
const https = require('https');
const fs = require('fs');

// In production, use proper SSL certificates
const options = {
  key: fs.readFileSync('path/to/private-key.pem'),
  cert: fs.readFileSync('path/to/certificate.pem')
};

https.createServer(options, app).listen(3000, () => {
  console.log('Secure server running on port 3000');
});

// Redirect HTTP to HTTPS
const http = require('http');
http.createServer((req, res) => {
  res.writeHead(301, { 'Location': 'https://' + req.headers.host + req.url });
  res.end();
}).listen(80);
```

---

### 4. **Missing Security Headers** ⚠️ MEDIUM
**Severity:** MEDIUM  
**OWASP Top 10:** #05 - Security Misconfiguration

**Issue:**
No security headers configured. The application is vulnerable to:
- Clickjacking attacks
- MIME-sniffing attacks
- XSS attacks
- Missing Strict Transport Security (HSTS)

**Recommended Fix:**
```javascript
const helmet = require('helmet');

// Add helmet for security headers
app.use(helmet());

// Additional configuration
app.use(helmet.contentSecurityPolicy({
  directives: {
    defaultSrc: ["'self'"],
    scriptSrc: ["'self'", "'unsafe-inline'"],
    styleSrc: ["'self'", "'unsafe-inline'"],
    imgSrc: ["'self'", 'data:', 'https:'],
    connectSrc: ["'self'"],
    fontSrc: ["'self'"],
    objectSrc: ["'none'"],
    mediaSrc: ["'self'"],
    frameSrc: ["'none'"],
  },
}));

app.use(helmet.hsts({
  maxAge: 31536000, // 1 year
  includeSubDomains: true,
  preload: true
}));

app.use(helmet.frameguard({ action: 'deny' }));
app.use(helmet.noSniff());
app.use(helmet.xssFilter());
```

---

### 5. **No Rate Limiting / DDoS Protection** ⚠️ MEDIUM
**Severity:** MEDIUM  
**OWASP Top 10:** #05 - Security Misconfiguration

**Issue:**
No rate limiting allows unlimited requests, making the application vulnerable to:
- Brute force attacks
- Denial of Service (DoS) attacks
- Resource exhaustion

**Recommended Fix:**
```javascript
const rateLimit = require('express-rate-limit');

// Global rate limiter
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true, // Return rate limit info in `RateLimit-*` headers
  legacyHeaders: false, // Disable `X-RateLimit-*` headers
});

app.use(limiter);

// Stricter limit for authentication endpoints
const strictLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 5, // 5 attempts per 15 minutes
  skipSuccessfulRequests: true,
  skipFailedRequests: false,
});

app.post('/login', strictLimiter, (req, res) => {
  // Login endpoint
});
```

---

### 6. **Missing CORS Configuration** ⚠️ MEDIUM
**Severity:** MEDIUM  
**OWASP Top 10:** #04 - Insecure Design

**Issue:**
No CORS configuration could allow unauthorized cross-origin requests or overly permissive CORS settings.

**Current Behavior:** Express defaults to allowing all CORS requests

**Recommended Fix:**
```javascript
const cors = require('cors');

// Configure CORS properly
const corsOptions = {
  origin: function (origin, callback) {
    const allowedOrigins = ['https://example.com', 'https://app.example.com'];

    if (!origin || allowedOrigins.indexOf(origin) !== -1) {
      callback(null, true);
    } else {
      callback(new Error('Not allowed by CORS'));
    }
  },
  credentials: true,
  optionsSuccessStatus: 200,
  methods: ['GET', 'POST', 'PUT', 'DELETE'],
  allowedHeaders: ['Content-Type', 'Authorization'],
  maxAge: 3600 // Preflight cache time
};

app.use(cors(corsOptions));

// Don't allow credentials from all origins
app.options('*', cors(corsOptions));
```

---

### 7. **Sensitive Data Exposure** ⚠️ HIGH
**Severity:** HIGH  
**OWASP Top 10:** #02 - Cryptographic Failures

**Issue:**
Email addresses and user information are exposed without encryption or anonymization.

**Recommended Fix:**
```javascript
// Filter sensitive data
const sanitizeUser = (user, requestingUser) => {
  // Only show email to self or admins
  if (requestingUser.id === user.id || requestingUser.role === 'admin') {
    return user;
  }

  // Remove sensitive fields for other users
  const { email, ...sanitized } = user;
  return sanitized;
};

app.get('/users', authenticateToken, (req, res) => {
  const users = [
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ];

  const sanitized = users.map(user => sanitizeUser(user, req.user));
  res.json(sanitized);
});
```

---

### 8. **Missing Logging and Monitoring** ⚠️ MEDIUM
**Severity:** MEDIUM  
**OWASP Top 10:** #09 - Logging and Monitoring Failures

**Issue:**
No logging of security-relevant events makes it impossible to detect attacks or audit access.

**Recommended Fix:**
```javascript
const morgan = require('morgan');
const winston = require('winston');

// Configure logging
const logger = winston.createLogger({
  level: 'info',
  format: winston.format.json(),
  defaultMeta: { service: 'user-service' },
  transports: [
    new winston.transports.File({ filename: 'error.log', level: 'error' }),
    new winston.transports.File({ filename: 'combined.log' }),
  ],
});

if (process.env.NODE_ENV !== 'production') {
  logger.add(new winston.transports.Console({
    format: winston.format.simple(),
  }));
}

// HTTP request logging
app.use(morgan('combined', { stream: { write: message => logger.info(message) } }));

// Log security events
app.use((req, res, next) => {
  logger.info({
    event: 'http_request',
    method: req.method,
    path: req.path,
    ip: req.ip,
    timestamp: new Date().toISOString(),
  });
  next();
});

// Log authentication failures
app.get('/users', authenticateToken, (req, res, next) => {
  res.on('finish', () => {
    if (res.statusCode >= 400) {
      logger.warn({
        event: 'auth_failure',
        ip: req.ip,
        timestamp: new Date().toISOString(),
      });
    }
  });
  next();
});
```

---

### 9. **Missing Error Handling** ⚠️ MEDIUM
**Severity:** MEDIUM  
**OWASP Top 10:** #05 - Security Misconfiguration

**Issue:**
No error handling could expose stack traces and implementation details to attackers.

**Recommended Fix:**
```javascript
// Global error handler
app.use((err, req, res, next) => {
  // Log the error
  logger.error({
    event: 'error',
    message: err.message,
    stack: err.stack,
    ip: req.ip,
  });

  // Don't expose stack traces in production
  const isDevelopment = process.env.NODE_ENV === 'development';

  res.status(err.status || 500).json({
    error: {
      message: isDevelopment ? err.message : 'Internal Server Error',
      ...(isDevelopment && { stack: err.stack }),
    },
  });
});

// Handle 404 errors
app.use((req, res) => {
  res.status(404).json({ error: 'Not Found' });
});
```

---

### 10. **Missing Environment Configuration** ⚠️ MEDIUM
**Severity:** MEDIUM  
**OWASP Top 10:** #05 - Security Misconfiguration

**Issue:**
Hardcoded configuration and no environment-based settings management.

**Recommended Fix:**
```javascript
require('dotenv').config();

const config = {
  port: process.env.PORT || 3000,
  nodeEnv: process.env.NODE_ENV || 'development',
  jwtSecret: process.env.JWT_SECRET,
  corsOrigin: process.env.CORS_ORIGIN || 'http://localhost:3000',
  dbUrl: process.env.DATABASE_URL,
};

// Validate required environment variables
const requiredEnvVars = ['JWT_SECRET', 'DATABASE_URL'];
const missingEnvVars = requiredEnvVars.filter(envVar => !process.env[envVar]);

if (missingEnvVars.length > 0) {
  throw new Error(`Missing required environment variables: ${missingEnvVars.join(', ')}`);
}

module.exports = config;
```

---

### 11. **No SQL/NoSQL Injection Prevention** ⚠️ HIGH
**Severity:** HIGH  
**OWASP Top 10:** #03 - Injection

**Issue:**
If database queries are added, there's no indication of parameterized queries or injection prevention.

**Recommended Fix:**
```javascript
// If using MongoDB
const User = require('./models/User');

// VULNERABLE - DO NOT USE:
// User.findOne({ email: req.query.email })

// SAFE - Use parameterized queries/ORM:
app.get('/users/:id', async (req, res, next) => {
  try {
    const userId = parseInt(req.params.id);

    if (isNaN(userId)) {
      return res.status(400).json({ error: 'Invalid user ID' });
    }

    // Using ORM with parameterized queries
    const user = await User.findById(userId);

    if (!user) {
      return res.status(404).json({ error: 'User not found' });
    }

    res.json(user);
  } catch (error) {
    next(error);
  }
});
```

