const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const cors = require('cors');
const jwt = require('jsonwebtoken');
const { query, validationResult } = require('express-validator');
const morgan = require('morgan');
const winston = require('winston');
require('dotenv').config();

const app = express();

// ============ SECURITY CONFIGURATION ============

// Logger setup
const logger = winston.createLogger({
  level: process.env.LOG_LEVEL || 'info',
  format: winston.format.combine(
    winston.format.timestamp(),
    winston.format.errors({ stack: true }),
    winston.format.json()
  ),
  defaultMeta: { service: 'express-app' },
  transports: [
    new winston.transports.File({ filename: 'error.log', level: 'error' }),
    new winston.transports.File({ filename: 'combined.log' }),
  ],
});

if (process.env.NODE_ENV !== 'production') {
  logger.add(new winston.transports.Console({
    format: winston.format.simple(),
  }));
}

// Trust proxy for rate limiting behind reverse proxy
app.set('trust proxy', 1);

// ============ MIDDLEWARE ============

// Security headers with Helmet
app.use(helmet());
app.use(helmet.contentSecurityPolicy({
  directives: {
    defaultSrc: ["'self'"],
    scriptSrc: ["'self'"],
    styleSrc: ["'self'", "'unsafe-inline'"],
    imgSrc: ["'self'", 'data:', 'https:'],
    connectSrc: ["'self'"],
    fontSrc: ["'self'"],
    objectSrc: ["'none'"],
    mediaSrc: ["'self'"],
    frameSrc: ["'none'"],
  },
}));
app.use(helmet.hsts({
  maxAge: 31536000, // 1 year
  includeSubDomains: true,
  preload: true
}));

// CORS configuration - restrict to allowed origins
const corsOptions = {
  origin: function (origin, callback) {
    const allowedOrigins = (process.env.ALLOWED_ORIGINS || 'http://localhost:3000').split(',');

    if (!origin || allowedOrigins.includes(origin)) {
      callback(null, true);
    } else {
      logger.warn({ event: 'cors_rejected', origin });
      callback(new Error('Not allowed by CORS'));
    }
  },
  credentials: true,
  optionsSuccessStatus: 200,
  methods: ['GET', 'POST', 'PUT', 'DELETE', 'OPTIONS'],
  allowedHeaders: ['Content-Type', 'Authorization'],
  maxAge: 3600
};

app.use(cors(corsOptions));
app.options('*', cors(corsOptions));

// Rate limiting - global
const globalLimiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true,
  legacyHeaders: false,
  handler: (req, res) => {
    logger.warn({ event: 'rate_limit_exceeded', ip: req.ip });
    res.status(429).json({ error: 'Too many requests, please try again later.' });
  },
});

app.use(globalLimiter);

// Stricter rate limiter for authentication endpoints
const authLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 5,
  skipSuccessfulRequests: true,
  message: 'Too many failed authentication attempts',
  handler: (req, res) => {
    logger.warn({ event: 'auth_rate_limit_exceeded', ip: req.ip });
    res.status(429).json({ error: 'Too many failed attempts, please try again later.' });
  },
});

// Request size limits
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ limit: '10kb', extended: false }));

// HTTP request logging
app.use(morgan('combined', {
  stream: { write: message => logger.info(message) }
}));

// Request tracking middleware
app.use((req, res, next) => {
  const start = Date.now();

  res.on('finish', () => {
    const duration = Date.now() - start;
    logger.debug({
      event: 'http_request',
      method: req.method,
      path: req.path,
      statusCode: res.statusCode,
      duration: `${duration}ms`,
      ip: req.ip,
      userAgent: req.get('user-agent'),
    });
  });

  next();
});

// ============ AUTHENTICATION MIDDLEWARE ============

const authenticateToken = (req, res, next) => {
  const authHeader = req.headers['authorization'];
  const token = authHeader && authHeader.split(' ')[1];

  if (!token) {
    logger.warn({ event: 'auth_missing', ip: req.ip, path: req.path });
    return res.status(401).json({ error: 'Access token required' });
  }

  jwt.verify(token, process.env.JWT_SECRET, (err, user) => {
    if (err) {
      logger.warn({ 
        event: 'auth_invalid', 
        ip: req.ip, 
        path: req.path,
        error: err.message 
      });
      return res.status(403).json({ error: 'Invalid or expired token' });
    }
    req.user = user;
    next();
  });
};

// ============ AUTHORIZATION MIDDLEWARE ============

const requireRole = (roles) => {
  return (req, res, next) => {
    if (!req.user) {
      return res.status(401).json({ error: 'Authentication required' });
    }

    if (!roles.includes(req.user.role)) {
      logger.warn({
        event: 'unauthorized_access',
        userId: req.user.id,
        ip: req.ip,
        path: req.path,
        requiredRole: roles
      });
      return res.status(403).json({ error: 'Insufficient permissions' });
    }

    next();
  };
};

// ============ INPUT VALIDATION ============

const validateUserQuery = [
  query('id')
    .optional()
    .isInt({ min: 1 })
    .withMessage('ID must be a positive integer')
    .trim(),
  query('email')
    .optional()
    .isEmail()
    .withMessage('Invalid email format')
    .trim()
    .normalizeEmail(),
  query('limit')
    .optional()
    .isInt({ min: 1, max: 100 })
    .withMessage('Limit must be between 1 and 100'),
];

// ============ ROUTES ============

app.get('/health', (req, res) => {
  res.json({ 
    status: 'ok', 
    timestamp: new Date().toISOString(),
    uptime: process.uptime()
  });
});

app.get('/users', authenticateToken, requireRole(['admin']), validateUserQuery, (req, res, next) => {
  try {
    // Check for validation errors
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      logger.warn({
        event: 'validation_error',
        userId: req.user.id,
        errors: errors.array()
      });
      return res.status(400).json({ errors: errors.array() });
    }

    // Mock data - in production this would come from a database
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com', role: 'user' },
      { id: 2, name: 'Bob', email: 'bob@example.com', role: 'user' },
    ];

    // Apply limit from query
    const limit = Math.min(parseInt(req.query.limit) || 10, 100);
    const limitedUsers = users.slice(0, limit);

    logger.info({
      event: 'users_retrieved',
      userId: req.user.id,
      count: limitedUsers.length
    });

    res.json(limitedUsers);
  } catch (error) {
    next(error);
  }
});

// Login endpoint for demonstration
app.post('/login', authLimiter, express.json(), (req, res, next) => {
  try {
    const { username, password } = req.body;

    // Validation
    if (!username || !password) {
      logger.warn({ event: 'login_missing_credentials', ip: req.ip });
      return res.status(400).json({ error: 'Username and password required' });
    }

    // Mock authentication - in production, verify against database with bcrypt
    if (username === 'admin' && password === process.env.ADMIN_PASSWORD) {
      const token = jwt.sign(
        { id: 1, username: 'admin', role: 'admin' },
        process.env.JWT_SECRET,
        { expiresIn: '24h' }
      );

      logger.info({ event: 'login_success', username, ip: req.ip });
      return res.json({ token });
    }

    logger.warn({ event: 'login_failed', username, ip: req.ip });
    res.status(401).json({ error: 'Invalid credentials' });
  } catch (error) {
    next(error);
  }
});

// ============ ERROR HANDLING ============

// Validation error handler
app.use((err, req, res, next) => {
  if (err instanceof Error) {
    if (err.message === 'Not allowed by CORS') {
      logger.warn({ event: 'cors_error', origin: req.get('origin') });
      return res.status(403).json({ error: 'CORS policy violation' });
    }
  }
  next(err);
});

// Global error handler
app.use((err, req, res, next) => {
  logger.error({
    event: 'unhandled_error',
    message: err.message,
    stack: err.stack,
    ip: req.ip,
    path: req.path,
    method: req.method,
  });

  const isDevelopment = process.env.NODE_ENV === 'development';

  res.status(err.status || 500).json({
    error: isDevelopment ? err.message : 'Internal Server Error',
    ...(isDevelopment && { stack: err.stack }),
  });
});

// 404 handler
app.use((req, res) => {
  logger.warn({ event: 'not_found', path: req.path, method: req.method });
  res.status(404).json({ error: 'Not Found' });
});

// ============ START SERVER ============

const PORT = process.env.PORT || 3000;

app.listen(PORT, () => {
  logger.info({
    event: 'server_start',
    port: PORT,
    environment: process.env.NODE_ENV || 'development',
    timestamp: new Date().toISOString()
  });
  console.log(`Server running on port ${PORT}`);
});

module.exports = app;

