// src/config/secrets.js
// Secure Secrets Management Module

const { SecretsManagerClient, GetSecretValueCommand } = 
  require("@aws-sdk/client-secrets-manager");

/**
 * SecretsManager - Handles secure retrieval and caching of secrets
 * Supports: AWS Secrets Manager, HashiCorp Vault, .env (dev only)
 */
class SecretsManager {
  constructor() {
    this.secrets = null;
    this.lastFetch = 0;
    this.cacheTTL = 3600000; // 1 hour cache
    this.client = null;
    this.provider = process.env.SECRETS_PROVIDER || 'aws';

    // Initialize provider
    if (this.provider === 'aws') {
      this.client = new SecretsManagerClient({ 
        region: process.env.AWS_REGION || 'us-east-1' 
      });
    }
  }

  /**
   * Get secrets with caching
   */
  async get() {
    // Return cached secrets if still valid
    if (this.secrets && Date.now() - this.lastFetch < this.cacheTTL) {
      return this.secrets;
    }

    switch (this.provider) {
      case 'aws':
        return await this.getFromAWS();
      case 'vault':
        return await this.getFromVault();
      case 'env':
      default:
        return this.getFromEnv();
    }
  }

  /**
   * Get secrets from AWS Secrets Manager
   */
  async getFromAWS() {
    try {
      const secretId = process.env.SECRETS_ID || 
        `${process.env.NODE_ENV}/app-secrets`;

      const command = new GetSecretValueCommand({ SecretId: secretId });
      const response = await client.send(command);

      this.secrets = JSON.parse(response.SecretString);
      this.lastFetch = Date.now();

      return this.secrets;
    } catch (error) {
      if (process.env.NODE_ENV === 'production') {
        throw new Error(
          `Failed to retrieve production secrets from AWS: ${error.message}`
        );
      }

      // Fallback to .env in development
      console.warn('AWS Secrets Manager not available, using .env');
      return this.getFromEnv();
    }
  }

  /**
   * Get secrets from HashiCorp Vault
   */
  async getFromVault() {
    try {
      const vault = require('node-vault')({
        endpoint: process.env.VAULT_ADDR,
        token: process.env.VAULT_TOKEN,
      });

      const path = `secret/${process.env.NODE_ENV}/app`;
      const response = await vault.read(path);

      this.secrets = response.data.data;
      this.lastFetch = Date.now();

      return this.secrets;
    } catch (error) {
      if (process.env.NODE_ENV === 'production') {
        throw new Error(
          `Failed to retrieve secrets from Vault: ${error.message}`
        );
      }

      console.warn('Vault not available, using .env');
      return this.getFromEnv();
    }
  }

  /**
   * Get secrets from environment variables (.env)
   * Development only!
   */
  getFromEnv() {
    if (process.env.NODE_ENV === 'production') {
      throw new Error(
        'Cannot load production secrets from environment variables. ' +
        'Use AWS Secrets Manager, Vault, or another secure provider.'
      );
    }

    return {
      JWT_SECRET: process.env.JWT_SECRET,
      ADMIN_PASSWORD_HASH: process.env.ADMIN_PASSWORD_HASH,
      DATABASE_URL: process.env.DATABASE_URL,
      ALLOWED_ORIGINS: process.env.ALLOWED_ORIGINS,
    };
  }

  /**
   * Validate all required secrets are present and valid
   */
  validate(secrets) {
    const required = [
      'JWT_SECRET',
      'ADMIN_PASSWORD_HASH',
      'DATABASE_URL',
    ];

    const missing = required.filter(key => !secrets[key]);

    if (missing.length > 0) {
      throw new Error(
        `Missing required secrets: ${missing.join(', ')}\n` +
        'Configure these in your secrets manager or .env file'
      );
    }

    // Validate JWT secret strength
    if (secrets.JWT_SECRET.length < 32) {
      throw new Error(
        'JWT_SECRET must be at least 32 characters (256-bit). ' +
        'Generate with: node -e "console.log(require(\'crypto\').randomBytes(32).toString(\'hex\'))"'
      );
    }

    // Validate admin password hash format (bcrypt)
    if (!secrets.ADMIN_PASSWORD_HASH.startsWith('$2')) {
      throw new Error(
        'ADMIN_PASSWORD_HASH must be a bcrypt hash. ' +
        'Generate with: npm install bcryptjs && node -e "require(\'bcryptjs\').hash(\'password\', 12).then(console.log)"'
      );
    }

    // Validate database URL format
    const validDbPrefixes = ['mongodb://', 'postgresql://', 'mysql://', 'mongodb+srv://'];
    if (!validDbPrefixes.some(prefix => secrets.DATABASE_URL.startsWith(prefix))) {
      throw new Error(
        `DATABASE_URL must start with one of: ${validDbPrefixes.join(', ')}`
      );
    }

    return true;
  }

  /**
   * Mask a secret for safe logging
   * @param {string} secret - The secret to mask
   * @param {number} chars - Number of characters to show
   * @returns {string} Masked secret
   */
  mask(secret, chars = 4) {
    if (!secret || typeof secret !== 'string' || secret.length <= chars) {
      return '***';
    }
    return secret.substring(0, chars) + '***' + secret.substring(secret.length - 2);
  }

  /**
   * Get safe secret metadata for logging
   * @param {Object} secrets - Secrets object
   * @returns {Object} Safe metadata
   */
  getSafeMetadata(secrets) {
    return {
      JWT_SECRET: this.mask(secrets.JWT_SECRET),
      ADMIN_PASSWORD_HASH: this.mask(secrets.ADMIN_PASSWORD_HASH),
      DATABASE_URL: secrets.DATABASE_URL ? 
        secrets.DATABASE_URL.split('@')[0] + '@***' : '***',
      SENTRY_DSN: secrets.SENTRY_DSN ? 
        secrets.SENTRY_DSN.split('/')[2] + '/***' : 'not-set',
    };
  }

  /**
   * Clear cached secrets (for testing or secret rotation)
   */
  clear() {
    this.secrets = null;
    this.lastFetch = 0;
  }

  /**
   * Force refresh secrets from provider
   */
  async refresh() {
    this.clear();
    return await this.get();
  }
}

// Export singleton instance
module.exports = new SecretsManager();

