 * @param {string} username - Username
 * @param {string} password - Password (plaintext)
 * @returns {Promise<Object|null>} User object or null if invalid
 */
async function authenticateUser(username, password) {
  try {
    // Get secrets (includes ADMIN_PASSWORD_HASH)
    const secrets = await secretsManager.get();

    // Validate inputs
    if (!username || !password) {
      return null;
    }

    // Demo: Check against admin user
    // In production, this would query a database
    if (username === 'admin') {
      // Compare plaintext password with bcrypt hash
      const isValid = await bcrypt.compare(
        password,
        secrets.ADMIN_PASSWORD_HASH
      );

      if (isValid) {
        // Return user object (never include password)
        return {
          id: 1,
          username: 'admin',
          role: 'admin',
          email: 'admin@example.com',
        };
      }
    }

    // Invalid credentials
    return null;
  } catch (error) {
    console.error('Authentication error:', error.message);
    throw error;
  }
}

/**
 * Generate JWT token for authenticated user
 * @param {Object} user - User object with id, username, role
 * @returns {string} JWT token
 */
function generateToken(user) {
  try {
    // Get secrets - should be cached from initialization
    if (!secretsManager.secrets) {
      throw new Error('Secrets not initialized. Call initializeSecrets() on app startup.');
    }

    const token = jwt.sign(
      {
        id: user.id,
        username: user.username,
        role: user.role,
      },
      secretsManager.secrets.JWT_SECRET,
      {
        expiresIn: '24h',
        algorithm: 'HS256',
        issuer: 'app',
        subject: user.id.toString(),
      }
    );

    return token;
  } catch (error) {
    console.error('Token generation error:', error.message);
    throw error;
  }
}

/**
 * Verify and decode JWT token
 * @param {string} token - JWT token
 * @returns {Object|null} Decoded token or null if invalid
 */
function verifyToken(token) {
  try {
    if (!secretsManager.secrets) {
      throw new Error('Secrets not initialized');
    }

    const decoded = jwt.verify(
      token,
      secretsManager.secrets.JWT_SECRET,
      {
        algorithms: ['HS256'],
      }
    );

    return decoded;
  } catch (error) {
    // Log token verification failures
    if (error.name === 'TokenExpiredError') {
      return null; // Token expired
    } else if (error.name === 'JsonWebTokenError') {
      return null; // Invalid token
    }

    console.error('Token verification error:', error.message);
    return null;
  }
}

/**
 * Express middleware for JWT authentication
 */
function authenticateToken(req, res, next) {
  try {
    const authHeader = req.headers['authorization'];
    const token = authHeader && authHeader.split(' ')[1]; // Bearer TOKEN

    if (!token) {
      return res.status(401).json({ error: 'Access token required' });
    }

    // Verify token
    const user = verifyToken(token);

    if (!user) {
      return res.status(403).json({ error: 'Invalid or expired token' });
    }

    // Attach user to request
    req.user = user;
    next();
  } catch (error) {
    return res.status(500).json({ error: 'Authentication error' });
  }
}

/**
 * Express middleware for role-based authorization
 * @param {string|Array<string>} roles - Required role(s)
 */
function requireRole(roles) {
  const requiredRoles = Array.isArray(roles) ? roles : [roles];

  return (req, res, next) => {
    if (!req.user) {
      return res.status(401).json({ error: 'Authentication required' });
    }

    if (!requiredRoles.includes(req.user.role)) {
      return res.status(403).json({
        error: 'Insufficient permissions',
        required: requiredRoles,
      });
    }

    next();
  };
}

/**
 * Generate password hash
 * Utility function for creating admin password hashes
 * @param {string} password - Plain text password
 * @returns {Promise<string>} Bcrypt hash
 */
async function hashPassword(password) {
  if (!password || password.length < 8) {
    throw new Error('Password must be at least 8 characters');
  }

  try {
    const salt = await bcrypt.genSalt(12);
    const hash = await bcrypt.hash(password, salt);
    return hash;
  } catch (error) {
    throw new Error(`Password hashing failed: ${error.message}`);
  }
}

/**
 * Verify password against hash
 * @param {string} password - Plain text password
 * @param {string} hash - Bcrypt hash
 * @returns {Promise<boolean>} True if password matches
 */
async function verifyPassword(password, hash) {
  try {
    return await bcrypt.compare(password, hash);
  } catch (error) {
    throw new Error(`Password verification failed: ${error.message}`);
  }
}

module.exports = {
  authenticateUser,
  generateToken,
  verifyToken,
  authenticateToken,
  requireRole,
  hashPassword,
  verifyPassword,
};

// app-with-secure-secrets.js
// Complete Express app with Secure Secrets Management

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const cors = require('cors');
const morgan = require('morgan');
const winston = require('winston');

// Secure imports
const secretsManager = require('./src/config/secrets');
const auth = require('./src/middleware/auth-secure');

const app = express();

// ============ LOGGING ============

const logger = winston.createLogger({
  level: process.env.LOG_LEVEL || 'info',
  format: winston.format.combine(
    winston.format.timestamp(),
    winston.format.errors({ stack: true }),
    winston.format.json()
  ),
  defaultMeta: { service: 'express-app' },
  transports: [
    new winston.transports.File({ filename: 'error.log', level: 'error' }),
    new winston.transports.File({ filename: 'combined.log' }),
  ],
});

if (process.env.NODE_ENV !== 'production') {
  logger.add(new winston.transports.Console({
    format: winston.format.simple(),
  }));
}

// ============ INITIALIZATION FUNCTION ============

/**
 * Initialize application with secure secrets
 */
async function initializeApp() {
  try {
    // Load secrets
    const secrets = await secretsManager.get();

    // Validate secrets
    secretsManager.validate(secrets);

    // Store in secrets manager (already cached)
    logger.info({
      event: 'secrets_initialized',
      provider: process.env.SECRETS_PROVIDER || 'aws',
      metadata: secretsManager.getSafeMetadata(secrets),
    });

    return secrets;
  } catch (error) {
    logger.error({
      event: 'initialization_failed',
      error: error.message,
    });
    throw error;
  }
}

// ============ MIDDLEWARE ============

// Security headers
app.use(helmet());
app.use(helmet.contentSecurityPolicy({
  directives: {
    defaultSrc: ["'self'"],
    scriptSrc: ["'self'"],
    styleSrc: ["'self'", "'unsafe-inline'"],
    imgSrc: ["'self'", 'data:', 'https:'],
    connectSrc: ["'self'"],
  },
}));

// CORS
const corsOptions = {
  origin: (process.env.ALLOWED_ORIGINS || 'http://localhost:3000').split(','),
  credentials: true,
};
app.use(cors(corsOptions));

// Rate limiting
const globalLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 100,
  message: 'Too many requests',
});
app.use(globalLimiter);

const authLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 5,
  skipSuccessfulRequests: true,
});

// Logging & parsing
app.use(morgan('combined', { stream: { write: message => logger.info(message) } }));
app.use(express.json({ limit: '10kb' }));

// ============ ROUTES ============

/**
 * Health check endpoint
 */
app.get('/health', (req, res) => {
  res.json({
    status: 'ok',
    timestamp: new Date().toISOString(),
    uptime: process.uptime(),
  });
});

/**
 * Login endpoint - Secure password handling
 */
app.post('/login', authLimiter, async (req, res, next) => {
  try {
    const { username, password } = req.body;

    // Validate input
    if (!username || !password) {
      logger.warn({
        event: 'login_missing_credentials',
        ip: req.ip,
      });
      return res.status(400).json({
        error: 'Username and password required',
      });
    }

    // Authenticate user (bcrypt comparison)
    const user = await auth.authenticateUser(username, password);

    if (!user) {
      logger.warn({
        event: 'login_failed',
        username,
        ip: req.ip,
      });
      return res.status(401).json({
        error: 'Invalid credentials',
      });
    }

    // Generate token (with JWT secret from secrets manager)
    const token = auth.generateToken(user);

    logger.info({
      event: 'login_success',
      userId: user.id,
      username: user.username,
      ip: req.ip,
    });

    res.json({ token });
  } catch (error) {
    next(error);
  }
});

/**
 * Protected endpoint example
 */
app.get('/users', auth.authenticateToken, auth.requireRole(['admin']), (req, res) => {
  try {
    logger.info({
      event: 'users_retrieved',
      userId: req.user.id,
      username: req.user.username,
    });

    res.json([
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ]);
  } catch (error) {
    res.status(500).json({ error: 'Internal server error' });
  }
});

// ============ ERROR HANDLING ============

// 404 handler
app.use((req, res) => {
  res.status(404).json({ error: 'Not Found' });
});

// Global error handler
app.use((err, req, res, next) => {
  logger.error({
    event: 'unhandled_error',
    message: err.message,
    stack: process.env.NODE_ENV === 'development' ? err.stack : undefined,
  });

  res.status(err.status || 500).json({
    error: process.env.NODE_ENV === 'development' ? 
      err.message : 'Internal Server Error',
  });
});

// ============ SERVER STARTUP ============

const PORT = process.env.PORT || 3000;

async function startServer() {
  try {
    // Initialize with secrets
    await initializeApp();

    // Start server
    app.listen(PORT, () => {
      logger.info({
        event: 'server_started',
        port: PORT,
        environment: process.env.NODE_ENV || 'development',
        timestamp: new Date().toISOString(),
      });
      console.log(`✅ Server running on port ${PORT}`);
    });
  } catch (error) {
    logger.error({
      event: 'server_startup_failed',
      error: error.message,
    });
    console.error('❌ Server startup failed:', error.message);
    process.exit(1);
  }
}

// Start server
startServer();

module.exports = app;

