// Authentication middleware
const jwt = require('jsonwebtoken');
const logger = require('./logger');

/**
 * Generate JWT token
 * @param {Object} user - User object with id and role
 * @param {number} expiresIn - Token expiration time in seconds
 * @returns {string} JWT token
 */
function generateToken(user, expiresIn = 3600) {
  return jwt.sign(
    { 
      id: user.id, 
      email: user.email,
      role: user.role,
      iat: Math.floor(Date.now() / 1000),
    },
    process.env.JWT_SECRET,
    { expiresIn, algorithm: 'HS256' }
  );
}

/**
 * Authenticate JWT token from Authorization header
 */
function authenticateToken(req, res, next) {
  const authHeader = req.headers['authorization'];
  const token = authHeader && authHeader.split(' ')[1];

  if (!token) {
    logger.warn({
      event: 'unauthorized_access_no_token',
      path: req.path,
      ip: req.ip,
      timestamp: new Date().toISOString(),
    });

    return res.status(401).json({ 
      error: 'Access token required',
      code: 'NO_TOKEN',
    });
  }

  jwt.verify(token, process.env.JWT_SECRET, (err, user) => {
    if (err) {
      logger.warn({
        event: 'invalid_token',
        path: req.path,
        ip: req.ip,
        error: err.name,
        timestamp: new Date().toISOString(),
      });

      if (err.name === 'TokenExpiredError') {
        return res.status(403).json({ 
          error: 'Token expired',
          code: 'TOKEN_EXPIRED',
        });
      }

      return res.status(403).json({ 
        error: 'Invalid token',
        code: 'INVALID_TOKEN',
      });
    }

    req.user = user;
    req.startTime = Date.now();
    next();
  });
}

/**
 * Authorize specific roles
 * @param {string[]} allowedRoles - Array of allowed roles
 */
function authorizeRole(allowedRoles) {
  return (req, res, next) => {
    if (!req.user) {
      return res.status(401).json({ error: 'User not authenticated' });
    }

    if (!allowedRoles.includes(req.user.role)) {
      logger.warn({
        event: 'unauthorized_role',
        user_id: req.user.id,
        user_role: req.user.role,
        required_roles: allowedRoles,
        ip: req.ip,
        path: req.path,
        timestamp: new Date().toISOString(),
      });

      return res.status(403).json({ 
        error: 'Insufficient permissions',
        code: 'FORBIDDEN',
      });
    }

    next();
  };
}

/**
 * Refresh token middleware
 * Issues a new token if the old one is expired but still valid for refresh
 */
function refreshToken(req, res, next) {
  const authHeader = req.headers['authorization'];
  const token = authHeader && authHeader.split(' ')[1];

  if (!token) {
    return res.status(401).json({ error: 'Token required' });
  }

  jwt.verify(
    token, 
    process.env.JWT_SECRET, 
    { ignoreExpiration: true },
    (err, user) => {
      if (err) {
        return res.status(403).json({ error: 'Invalid token' });
      }

      // Check if token is expired
      const now = Math.floor(Date.now() / 1000);
      if (user.exp > now + 3600) {
        // Token is still valid for more than 1 hour
        return res.status(403).json({ 
          error: 'Token still valid, no refresh needed' 
        });
      }

      if (user.exp < now - 86400) {
        // Token expired more than 24 hours ago
        return res.status(403).json({ 
          error: 'Token expired too long ago, please login again' 
        });
      }

      // Issue new token
      const newToken = generateToken(user, 3600);
      res.json({ token: newToken });
    }
  );
}

module.exports = {
  generateToken,
  authenticateToken,
  authorizeRole,
  refreshToken,
};

