    .trim()
    .isLength({ min, max })
    .withMessage(`${fieldName} must be between ${min} and ${max} characters`)
    .notEmpty()
    .withMessage(`${fieldName} cannot be empty`)
    .matches(/^[a-zA-Z0-9\s\-_.@]+$/)
    .withMessage(`${fieldName} contains invalid characters`)
    .if(() => toLowerCase)
    .toLowerCase();
};

