// Input sanitization utilities
const DOMPurify = require('isomorphic-dompurify');

/**
 * Sanitize HTML input to prevent XSS
 * @param {string} input - User input
 * @returns {string} Sanitized input
 */
function sanitizeHtml(input) {
  if (typeof input !== 'string') return input;
  return DOMPurify.sanitize(input, { ALLOWED_TAGS: [] });
}

/**
 * Sanitize SQL input to prevent SQL injection
 * Note: Use parameterized queries instead of string concatenation
 * This is a fallback for defense in depth
 * @param {string} input - User input
 * @returns {string} Escaped input
 */
function escapeSql(input) {
  if (typeof input !== 'string') return input;

  return input
    .replace(/\\/g, '\\\\')
    .replace(/'/g, "''")
    .replace(/"/g, '\\"')
    .replace(/\0/g, '\\0')
    .replace(/\n/g, '\\n')
    .replace(/\r/g, '\\r')
    .replace(/\x1a/g, '\\Z');
}

/**
 * Sanitize filename to prevent directory traversal
 * @param {string} filename - Original filename
 * @returns {string} Safe filename
 */
function sanitizeFilename(filename) {
  if (typeof filename !== 'string') return '';

  return filename
    .replace(/\.\./g, '') // Remove parent directory references
    .replace(/[\/\\]/g, '') // Remove path separators
    .replace(/[^\w\s.-]/g, '') // Remove special characters
    .substring(0, 255); // Limit length
}

/**
 * Validate and sanitize email
 * @param {string} email - Email to validate
 * @returns {string|null} Sanitized email or null if invalid
 */
function sanitizeEmail(email) {
  if (typeof email !== 'string') return null;

  const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
  const sanitized = email.toLowerCase().trim();

  if (emailRegex.test(sanitized) && sanitized.length <= 254) {
    return sanitized;
  }

  return null;
}

/**
 * Validate and sanitize URL
 * @param {string} url - URL to validate
 * @returns {string|null} Sanitized URL or null if invalid
 */
function sanitizeUrl(url) {
  if (typeof url !== 'string') return null;

  try {
    const urlObject = new URL(url);

    // Only allow safe protocols
    if (!['http:', 'https:'].includes(urlObject.protocol)) {
      return null;
    }

    return urlObject.toString();
  } catch (e) {
    return null;
  }
}

/**
 * Sanitize JSON input
 * @param {any} input - Input to sanitize
 * @param {number} maxDepth - Maximum nesting depth
 * @param {number} currentDepth - Current depth
 * @returns {any} Sanitized input
 */
function sanitizeJson(input, maxDepth = 5, currentDepth = 0) {
  if (currentDepth > maxDepth) {
    throw new Error('JSON structure too deeply nested');
  }

  if (input === null || input === undefined) {
    return input;
  }

  if (typeof input === 'string') {
    return sanitizeHtml(input);
  }

  if (typeof input === 'object') {
    if (Array.isArray(input)) {
      return input.map(item => sanitizeJson(item, maxDepth, currentDepth + 1));
    }

    const sanitized = {};
    for (const key of Object.keys(input)) {
      // Validate key doesn't contain path traversal or injection attempts
      if (/^[a-zA-Z0-9_-]+$/.test(key)) {
        sanitized[key] = sanitizeJson(input[key], maxDepth, currentDepth + 1);
      }
    }
    return sanitized;
  }

  return input;
}

module.exports = {
  sanitizeHtml,
  escapeSql,
  sanitizeFilename,
  sanitizeEmail,
  sanitizeUrl,
  sanitizeJson,
};

