      { expiresIn: '1h' }
    );

    adminToken = jwt.sign(
      { id: 2, role: 'admin', email: 'admin@example.com' },
      process.env.JWT_SECRET,
      { expiresIn: '1h' }
    );
  });

  describe('Authentication Tests', () => {
    test('Should reject requests without token', async () => {
      const response = await request(app)
        .get('/users');

      expect(response.status).toBe(401);
      expect(response.body).toHaveProperty('error');
    });

    test('Should reject invalid tokens', async () => {
      const response = await request(app)
        .get('/users')
        .set('Authorization', 'Bearer invalid.token.here');

      expect(response.status).toBe(403);
      expect(response.body.code).toBe('INVALID_TOKEN');
    });

    test('Should accept valid token', async () => {
      const response = await request(app)
        .get('/users')
        .set('Authorization', `Bearer ${validToken}`);

      expect(response.status).toBe(200);
      expect(response.body).toHaveProperty('data');
    });
  });

  describe('Authorization Tests', () => {
    test('Regular user should not see admin data', async () => {
      const response = await request(app)
        .get('/users')
        .set('Authorization', `Bearer ${validToken}`);

      expect(response.status).toBe(200);
      // User should not see email field for non-admin
      response.body.data.forEach(user => {
        expect(user).not.toHaveProperty('email');
      });
    });

    test('Admin user should see admin data', async () => {
      const response = await request(app)
        .get('/users')
        .set('Authorization', `Bearer ${adminToken}`);

      expect(response.status).toBe(200);
      // Admin should see email field
      response.body.data.forEach(user => {
        expect(user).toHaveProperty('email');
      });
    });
  });

  describe('Input Validation Tests', () => {
    test('Should reject invalid limit parameter', async () => {
      const response = await request(app)
        .get('/users?limit=999')
        .set('Authorization', `Bearer ${validToken}`);

      expect(response.status).toBe(400);
      expect(response.body.error).toBe('Validation failed');
    });

    test('Should reject negative offset', async () => {
      const response = await request(app)
        .get('/users?offset=-1')
        .set('Authorization', `Bearer ${validToken}`);

      expect(response.status).toBe(400);
    });

    test('Should accept valid pagination', async () => {
      const response = await request(app)
        .get('/users?limit=10&offset=0')
        .set('Authorization', `Bearer ${validToken}`);

      expect(response.status).toBe(200);
      expect(response.body.pagination).toEqual({
        limit: 10,
        offset: 0,
        total: 2,
        hasMore: false,
      });
    });
  });

  describe('Security Headers Tests', () => {
    test('Should have HSTS header', async () => {
      const response = await request(app)
        .get('/health');

      expect(response.headers['strict-transport-security']).toBeDefined();
    });

    test('Should have X-Content-Type-Options header', async () => {
      const response = await request(app)
        .get('/health');

      expect(response.headers['x-content-type-options']).toBe('nosniff');
    });

    test('Should have X-Frame-Options header', async () => {
      const response = await request(app)
        .get('/health');

      expect(response.headers['x-frame-options']).toBe('DENY');
    });

    test('Should have CSP header', async () => {
      const response = await request(app)
        .get('/health');

      expect(response.headers['content-security-policy']).toBeDefined();
    });
  });

  describe('XSS Protection Tests', () => {
    test('Should sanitize script tags in query parameters', async () => {
      const response = await request(app)
        .get("/users?name=<script>alert('xss')</script>")
        .set('Authorization', `Bearer ${validToken}`);

      // Should not execute script, should return 400 for invalid param
      expect(response.status).toBeOneOf([200, 400]);
    });
  });

  describe('CORS Tests', () => {
    test('Should reject requests from unauthorized origins', async () => {
      const response = await request(app)
        .get('/health')
        .set('Origin', 'https://malicious.com');

      // Should either block or not include CORS headers
      const corsHeader = response.headers['access-control-allow-origin'];
      expect(corsHeader).toBeUndefined();
    });
  });

  describe('Rate Limiting Tests', () => {
    test('Health endpoint should have rate limiting', async () => {
      const requests = [];

      // Make multiple requests quickly
      for (let i = 0; i < 105; i++) {
        requests.push(
          request(app).get('/health')
        );
      }

      const responses = await Promise.all(requests);

      // At least one should be rate limited
      const rateLimited = responses.some(r => r.status === 429);
      expect(rateLimited).toBe(true);
    });
  });

  describe('Error Handling Tests', () => {
    test('Should not expose stack traces in production', async () => {
      process.env.NODE_ENV = 'production';

      const response = await request(app)
        .get('/nonexistent');

      expect(response.status).toBe(404);
      expect(response.body.error).toBeDefined();
      expect(response.body.stack).toBeUndefined();
    });

    test('Should return 404 for undefined routes', async () => {
      const response = await request(app)
        .get('/api/nonexistent/endpoint');

      expect(response.status).toBe(404);
      expect(response.body.code).toBe('RESOURCE_NOT_FOUND');
    });
  });

  describe('Content-Type Validation Tests', () => {
    test('Should reject requests with wrong Content-Type', async () => {
      const response = await request(app)
        .post('/users')
        .set('Content-Type', 'text/plain')
        .send('invalid');

      expect(response.status).toBe(415);
    });
  });
});

# Quick Security Implementation Guide

## Step-by-Step Implementation

### Step 1: Install Security Dependencies
```bash
npm install express helmet cors express-rate-limit express-validator jsonwebtoken dotenv winston morgan
npm install --save-dev nodemon jest supertest snyk
```

### Step 2: Configure Environment
```bash
cp .env.example .env
# Edit .env and add secure values
```

### Step 3: Use Hardened App
Replace your current `app.js` with `app.hardened.js`:
```bash
mv app.js app.original.js
cp app.hardened.js app.js
```

### Step 4: Add Middleware
Ensure these directories exist:
```bash
mkdir -p middleware utils logs tests
```

Copy middleware and utility files from this review.

### Step 5: Test Security
```bash
npm run test:security
npm run lint:security
npm audit
```

### Step 6: Deploy
```bash
npm start  # In production environment
```

---

## Common Security Issues & Fixes

### Issue 1: SQL Injection
**Problem:** String concatenation in SQL queries
```javascript
// ❌ VULNERABLE
const query = `SELECT * FROM users WHERE id = ${userId}`;
```

**Solution:** Use parameterized queries
```javascript
// ✅ SECURE
const query = 'SELECT * FROM users WHERE id = $1';
db.query(query, [userId]);
```

---

### Issue 2: XSS via User Input
**Problem:** Rendering unsanitized user input
```javascript
// ❌ VULNERABLE
res.json({ message: req.body.userInput });
```

**Solution:** Sanitize before returning
```javascript
// ✅ SECURE
const sanitizer = require('./utils/sanitizer');
const clean = sanitizer.sanitizeHtml(req.body.userInput);
res.json({ message: clean });
```

---

### Issue 3: Broken Authentication
**Problem:** No token validation
```javascript
// ❌ VULNERABLE
app.get('/sensitive', (req, res) => {
  res.json({ secret: 'data' });
});
```

**Solution:** Add authentication middleware
```javascript
// ✅ SECURE
const { authenticateToken } = require('./middleware/authMiddleware');
app.get('/sensitive', authenticateToken, (req, res) => {
  res.json({ secret: 'data' });
});
```

---

### Issue 4: Missing Security Headers
**Problem:** No Helmet.js
```javascript
// ❌ VULNERABLE
const app = express();
// Missing security middleware
```

**Solution:** Add Helmet
```javascript
// ✅ SECURE
const helmet = require('helmet');
const app = express();
app.use(helmet());
```

---

### Issue 5: No Rate Limiting
**Problem:** Brute force attacks possible
```javascript
// ❌ VULNERABLE
app.post('/login', (req, res) => {
  // No rate limiting
});
```

**Solution:** Add rate limiter
```javascript
// ✅ SECURE
const rateLimit = require('express-rate-limit');
const limiter = rateLimit({ windowMs: 15 * 60 * 1000, max: 5 });
app.post('/login', limiter, (req, res) => {
  // Protected
});
```

---

### Issue 6: Exposed Configuration
**Problem:** Secrets in code
```javascript
// ❌ VULNERABLE
const SECRET = 'my-super-secret-key';
const DATABASE_URL = 'postgres://user:pass@host/db';
```

**Solution:** Use environment variables
```javascript
// ✅ SECURE
require('dotenv').config();
const SECRET = process.env.JWT_SECRET;
const DATABASE_URL = process.env.DATABASE_URL;
```

---

### Issue 7: Information Leakage
**Problem:** Stack traces exposed
```javascript
// ❌ VULNERABLE
app.use((err, req, res, next) => {
  res.json({ error: err.message, stack: err.stack });
});
```

**Solution:** Hide details in production
```javascript
// ✅ SECURE
app.use((err, req, res, next) => {
  const isDev = process.env.NODE_ENV === 'development';
  res.json({
    error: isDev ? err.message : 'Internal Server Error',
    ...(isDev && { stack: err.stack }),
  });
});
```

---

### Issue 8: CORS Misconfiguration
**Problem:** Allow all origins
```javascript
// ❌ VULNERABLE
app.use(cors());
```

**Solution:** Whitelist origins
```javascript
// ✅ SECURE
const allowedOrigins = process.env.ALLOWED_ORIGINS.split(',');
app.use(cors({
  origin: allowedOrigins,
  credentials: true,
}));
```

---

### Issue 9: Sensitive Data Exposure
**Problem:** Return all fields
```javascript
// ❌ VULNERABLE
const users = await db.query('SELECT * FROM users');
res.json(users); // Includes passwords, emails, etc.
```

**Solution:** Filter by role
```javascript
// ✅ SECURE
const users = await db.query('SELECT id, name FROM users');
if (req.user.role === 'admin') {
  // Return additional fields
}
res.json(users);
```

---

### Issue 10: No Logging
**Problem:** Can't track security incidents
```javascript
// ❌ VULNERABLE
app.get('/sensitive', (req, res) => {
  // No logging
  res.json({ data });
});
```

**Solution:** Add comprehensive logging
```javascript
// ✅ SECURE
const logger = require('./utils/logger');
app.get('/sensitive', (req, res) => {
  logger.info({
    event: 'sensitive_data_accessed',
    user_id: req.user.id,
    ip: req.ip,
    timestamp: new Date().toISOString(),
  });
  res.json({ data });
});
```

