// config/azure-secrets.js
const { DefaultAzureCredential } = require('@azure/identity');
const { SecretClient } = require('@azure/keyvault-secrets');
const logger = require('./logger');

class AzureSecretsManager {
  constructor() {
    const credential = new DefaultAzureCredential();
    this.client = new SecretClient(
      `https://${process.env.KEYVAULT_NAME}.vault.azure.net/`,
      credential
    );
    this.cache = {};
  }

  async initialize() {
    try {
      const secrets = [
        'jwt-secret',
        'session-secret',
        'database-password',
        'email-password',
      ];

      for (const secretName of secrets) {
        const secret = await this.client.getSecret(secretName);
        this.cache[secretName] = secret.value;
      }

      logger.info({
        event: 'azure_keyvault_initialized',
        secrets_loaded: secrets.length,
      });
    } catch (error) {
      logger.error({
        event: 'azure_keyvault_failed',
        error: error.message,
      });
      throw error;
    }
  }

  getSecret(name) {
    if (!this.cache[name]) {
      throw new Error(`Secret not found: ${name}`);
    }
    return this.cache[name];
  }
}

module.exports = new AzureSecretsManager();
```

