// config/gcp-secrets.js
const { SecretManagerServiceClient } = require('@google-cloud/secret-manager');
const logger = require('./logger');

class GCPSecretsManager {
  constructor() {
    this.client = new SecretManagerServiceClient();
    this.project = process.env.GCP_PROJECT_ID;
    this.cache = {};
  }

  async initialize() {
    try {
      const secrets = ['jwt-secret', 'session-secret', 'database-url'];

      for (const secretName of secrets) {
        const name = this.client.secretVersionPath(
          this.project,
          secretName,
          'latest'
        );

        const [version] = await this.client.accessSecretVersion({ name });
        const secretValue = version.payload.data.toString('utf8');
        this.cache[secretName] = secretValue;
      }

      logger.info({
        event: 'gcp_secrets_initialized',
        secrets_loaded: secrets.length,
      });
    } catch (error) {
      logger.error({
        event: 'gcp_secrets_failed',
        error: error.message,
      });
      throw error;
    }
  }

  getSecret(name) {
    if (!this.cache[name]) {
      throw new Error(`Secret not found: ${name}`);
    }
    return this.cache[name];
  }
}

module.exports = new GCPSecretsManager();
