### Solution #5: Development-Safe .env (Fallback)

**For development only - NOT production:**

```javascript
// config/secrets-dev.js
const path = require('path');
const fs = require('fs');
const logger = require('./logger');

class DevSecretsManager {
  constructor() {
    this.cache = {};
    this.envFile = path.join(__dirname, '..', '.env');

    // Security warning
    if (process.env.NODE_ENV === 'production') {
      throw new Error(
        'CRITICAL: DevSecretsManager should NOT be used in production. Use AWS Secrets Manager, Vault, or similar.'
      );
    }
  }

  initialize() {
    // Check if .env file exists
    if (!fs.existsSync(this.envFile)) {
      throw new Error(`.env file not found at ${this.envFile}`);
    }

    // Check if .env is in .gitignore
    const gitignorePath = path.join(__dirname, '..', '.gitignore');
    if (fs.existsSync(gitignorePath)) {
      const gitignoreContent = fs.readFileSync(gitignorePath, 'utf8');
      if (!gitignoreContent.includes('.env')) {
        logger.warn({
          event: 'dangerous_gitignore',
          message: '.env not in .gitignore - .env could be committed!',
        });
      }
    }

    // Verify .env permissions (should be readable only by owner)
    const stats = fs.statSync(this.envFile);
    const mode = stats.mode & parseInt('777', 8);
    if ((mode & 0o077) !== 0) {
      logger.warn({
        event: 'insecure_env_permissions',
        mode: '0' + mode.toString(8),
        message: '.env file is readable by others! Should be 0600',
      });
    }

    // Load and cache secrets
    require('dotenv').config({ path: this.envFile });

    this.cache = {
      jwtSecret: process.env.JWT_SECRET,
      sessionSecret: process.env.SESSION_SECRET,
      databaseUrl: process.env.DATABASE_URL,
    };

    logger.warn({
      event: 'dev_secrets_loaded',
      message: 'Using development secrets from .env file. Do NOT use in production!',
    });
  }

  getSecret(name) {
    if (!this.cache[name]) {
      throw new Error(`Secret not found: ${name}`);
    }
    return this.cache[name];
  }
}

module.exports = new DevSecretsManager();
```

