// config/secret-rotator.js
const logger = require('./logger');

class SecretRotator {
  constructor(secretsManager) {
    this.secretsManager = secretsManager;
    this.rotationInterval = 24 * 60 * 60 * 1000; // 24 hours
  }

  start() {
    setInterval(async () => {
      try {
        await this.rotateSecrets();
      } catch (error) {
        logger.error({
          event: 'secret_rotation_failed',
          error: error.message,
          timestamp: new Date().toISOString(),
        });
      }
    }, this.rotationInterval);

    logger.info({
      event: 'secret_rotator_started',
      interval_hours: 24,
    });
  }

  async rotateSecrets() {
    // Reload secrets from manager
    await this.secretsManager.initialize();

    logger.info({
      event: 'secrets_rotated',
      timestamp: new Date().toISOString(),
    });
  }
}

module.exports = SecretRotator;
