### 4. Secure Secret Defaults

```javascript
// config/secret-validator.js
const logger = require('./logger');

class SecretValidator {
  static validate(secretName, secretValue) {
    const validators = {
      'jwt-secret': (val) => val && val.length >= 32,
      'session-secret': (val) => val && val.length >= 32,
      'database-url': (val) => val && val.includes('://'),
      'email-password': (val) => val && val.length >= 8,
    };

    const validator = validators[secretName];
    if (!validator) {
      throw new Error(`Unknown secret: ${secretName}`);
    }

    if (!validator(secretValue)) {
      const error = new Error(`Invalid secret format: ${secretName}`);
      logger.error({
        event: 'invalid_secret_format',
        secret: secretName,
        error: error.message,
      });
      throw error;
    }
  }

  static validateAll(secrets) {
    Object.entries(secrets).forEach(([name, value]) => {
      this.validate(name, value);
    });
  }
}

module.exports = SecretValidator;
