// File: config/aws-secrets.js
const { SecretsManagerClient, GetSecretValueCommand } = require('@aws-sdk/client-secrets-manager');
const logger = require('../utils/logger');

class AWSSecretsManager {
  constructor(config = {}) {
    this.client = new SecretsManagerClient({
      region: process.env.AWS_REGION || 'us-east-1',
      ...config,
    });
    this.cache = {};
    this.cacheTTL = 3600000; // 1 hour
    this.lastRefresh = {};
  }

  async getSecret(secretName) {
    // Check cache first
    if (this.isCached(secretName)) {
      logger.debug({
        event: 'secret_cache_hit',
        secret: secretName,
      });
      return this.cache[secretName];
    }

    try {
      logger.info({
        event: 'fetching_secret_from_aws',
        secret: secretName,
        timestamp: new Date().toISOString(),
      });

      const command = new GetSecretValueCommand({ SecretId: secretName });
      const response = await this.client.send(command);

      let secretValue;
      if (response.SecretString) {
        // Try to parse as JSON
        try {
          secretValue = JSON.parse(response.SecretString);
        } catch (e) {
          // If not JSON, use as-is
          secretValue = response.SecretString;
        }
      } else {
        secretValue = Buffer.from(response.SecretBinary).toString('ascii');
      }

      // Cache the secret
      this.cache[secretName] = secretValue;
      this.lastRefresh[secretName] = Date.now();

      logger.info({
        event: 'secret_retrieved',
        secret: secretName,
        timestamp: new Date().toISOString(),
      });

      return secretValue;
    } catch (error) {
      logger.error({
        event: 'secret_retrieval_failed',
        secret: secretName,
        error: error.message,
        code: error.__type,
        timestamp: new Date().toISOString(),
      });

      throw new Error(`Failed to retrieve secret: ${secretName}`);
    }
  }

  async getSecrets(secretNames) {
    const results = {};

    for (const name of secretNames) {
      try {
        results[name] = await this.getSecret(name);
      } catch (error) {
        logger.error({
          event: 'batch_secret_failed',
          secret: name,
          error: error.message,
        });
        throw error;
      }
    }

    return results;
  }

  isCached(secretName) {
    if (!this.cache[secretName]) return false;

    const age = Date.now() - (this.lastRefresh[secretName] || 0);
    if (age > this.cacheTTL) {
      delete this.cache[secretName];
      delete this.lastRefresh[secretName];
      return false;
    }

    return true;
  }

  async refreshSecret(secretName) {
    delete this.cache[secretName];
    delete this.lastRefresh[secretName];
    return this.getSecret(secretName);
  }

  clearCache() {
    this.cache = {};
    this.lastRefresh = {};
    logger.info({ event: 'secrets_cache_cleared' });
  }
}

module.exports = AWSSecretsManager;

