// File: config/vault-secrets.js
const vault = require('node-vault');
const logger = require('../utils/logger');

class VaultSecretsManager {
  constructor(config = {}) {
    this.vaultOptions = {
      endpoint: process.env.VAULT_ADDR || 'http://localhost:8200',
      token: process.env.VAULT_TOKEN,
      namespace: process.env.VAULT_NAMESPACE,
      ...config,
    };

    this.vault = vault(this.vaultOptions);
    this.cache = {};
    this.cacheTTL = 3600000; // 1 hour
    this.lastRefresh = {};
  }

  async initialize() {
    try {
      const health = await this.vault.status();

      logger.info({
        event: 'vault_initialized',
        sealed: health.sealed,
        version: health.version,
      });

      if (health.sealed) {
        throw new Error('Vault is sealed');
      }

      return true;
    } catch (error) {
      logger.error({
        event: 'vault_initialization_failed',
        error: error.message,
      });
      throw error;
    }
  }

  async getSecret(path) {
    if (this.isCached(path)) {
      return this.cache[path];
    }

    try {
      logger.info({
        event: 'fetching_secret_from_vault',
        path,
      });

      const response = await this.vault.read(path);

      // Handle different data formats
      let secretValue = response.data.data || response.data;

      this.cache[path] = secretValue;
      this.lastRefresh[path] = Date.now();

      return secretValue;
    } catch (error) {
      logger.error({
        event: 'vault_secret_retrieval_failed',
        path,
        error: error.message,
      });

      throw error;
    }
  }

  async getDynamicDatabaseCredentials(role) {
    try {
      logger.info({
        event: 'requesting_dynamic_db_credentials',
        role,
      });

      const response = await this.vault.read(`database/creds/${role}`);

      return {
        username: response.data.username,
        password: response.data.password,
        ttl: response.lease_duration,
        leaseId: response.lease_id,
      };
    } catch (error) {
      logger.error({
        event: 'dynamic_credentials_failed',
        role,
        error: error.message,
      });

      throw error;
    }
  }

  async renewLease(leaseId) {
    try {
      const response = await this.vault.write(`sys/leases/renew`, {
        lease_id: leaseId,
      });

      logger.info({
        event: 'lease_renewed',
        lease_id: leaseId,
        ttl: response.auth.lease_duration,
      });

      return response;
    } catch (error) {
      logger.error({
        event: 'lease_renewal_failed',
        lease_id: leaseId,
        error: error.message,
      });

      throw error;
    }
  }

  isCached(path) {
    if (!this.cache[path]) return false;

    const age = Date.now() - (this.lastRefresh[path] || 0);
    if (age > this.cacheTTL) {
      delete this.cache[path];
      delete this.lastRefresh[path];
      return false;
    }

    return true;
  }

  async refreshSecret(path) {
    delete this.cache[path];
    delete this.lastRefresh[path];
    return this.getSecret(path);
  }
}

module.exports = VaultSecretsManager;

