        return new AWSSecretsManager();

      case 'vault':
        const VaultSecretsManager = require('./vault-secrets');
        return new VaultSecretsManager();

      case 'azure':
        const AzureSecretsManager = require('./azure-secrets');
        return new AzureSecretsManager();

      case 'gcp':
        const GCPSecretsManager = require('./gcp-secrets');
        return new GCPSecretsManager();

      case 'development':
        const DevSecretsManager = require('./dev-secrets');
        return new DevSecretsManager();

      default:
        throw new Error(`Unknown secrets provider: ${provider}`);
    }
  }

  static async initialize(provider) {
    const manager = this.createManager(provider);

    if (typeof manager.initialize === 'function') {
      await manager.initialize();
    }

    logger.info({
      event: 'secrets_manager_initialized',
      provider: manager.constructor.name,
      environment: process.env.NODE_ENV,
    });

    return manager;
  }
}

module.exports = SecretsFactory;

