// File: app-with-secure-secrets.js
require('dotenv').config(); // Only for AWS credentials/provider config

const express = require('express');
const helmet = require('helmet');
const SecretsFactory = require('./config/secrets-factory');
const logger = require('./utils/logger');

const app = express();

// Store secrets manager in app context
let secretsManager;

// Middleware to attach secrets to request
app.use((req, res, next) => {
  req.secrets = {
    get: (name) => secretsManager.getSecret(name),
  };
  next();
});

// Apply security middleware
app.use(helmet());

// Authentication middleware with secrets
const authenticateToken = async (req, res, next) => {
  try {
    const jwtSecret = await secretsManager.getSecret('jwt-secret');
    const jwt = require('jsonwebtoken');
    const authHeader = req.headers['authorization'];
    const token = authHeader && authHeader.split(' ')[1];

    if (!token) {
      return res.status(401).json({ error: 'Token required' });
    }

    jwt.verify(token, jwtSecret, (err, user) => {
      if (err) {
        logger.warn({
          event: 'invalid_token',
          ip: req.ip,
          error: err.message,
        });
        return res.status(403).json({ error: 'Invalid token' });
      }
      req.user = user;
      next();
    });
  } catch (error) {
    logger.error({
      event: 'auth_secret_error',
      error: error.message,
    });
    res.status(500).json({ error: 'Authentication error' });
  }
};

// Protected endpoint
app.get('/api/secure', authenticateToken, (req, res) => {
  res.json({ message: 'This is secure' });
});

// Server startup
async function startServer() {
  try {
    // Initialize secrets manager
    const provider = process.env.SECRETS_PROVIDER || 'aws';
    secretsManager = await SecretsFactory.initialize(provider);

    // Verify critical secrets exist
    const criticalSecrets = ['jwt-secret', 'session-secret'];
    for (const secret of criticalSecrets) {
      await secretsManager.getSecret(secret);
    }

    logger.info({
      event: 'critical_secrets_verified',
      secrets: criticalSecrets,
    });

    // Start server
    const PORT = process.env.PORT || 3000;
    app.listen(PORT, () => {
      logger.info({
        event: 'server_started',
        port: PORT,
        secrets_provider: provider,
        timestamp: new Date().toISOString(),
      });
    });

  } catch (error) {
    logger.error({
      event: 'server_startup_failed',
      error: error.message,
      stack: error.stack,
    });
    process.exit(1);
  }
}

// Handle graceful shutdown
process.on('SIGTERM', () => {
  logger.info({ event: 'graceful_shutdown_initiated' });
  secretsManager.clearCache?.();
  process.exit(0);
});

startServer();

module.exports = app;

