const logger = require('../utils/logger');

class SecretsMonitor {
  constructor(secretsManager) {
    this.secretsManager = secretsManager;
    this.accessLog = [];
    this.maxLogSize = 1000;
  }

  async monitorSecret(secretName, threshold = 10) {
    const count = this.accessLog.filter(
      log => log.secret === secretName &&
      Date.now() - log.timestamp < 60000 // Last minute
    ).length;

    if (count > threshold) {
      logger.warn({
        event: 'excessive_secret_access',
        secret: secretName,
        access_count: count,
        threshold,
        alert: true,
      });
    }

    this.logAccess(secretName);
  }

  logAccess(secretName) {
    this.accessLog.push({
      secret: secretName,
      timestamp: Date.now(),
    });

    if (this.accessLog.length > this.maxLogSize) {
      this.accessLog.shift();
    }
  }

  getAccessStats(secretName) {
    const now = Date.now();
    const lastMinute = this.accessLog.filter(
      log => log.secret === secretName &&
      now - log.timestamp < 60000
    ).length;

    const lastHour = this.accessLog.filter(
      log => log.secret === secretName &&
      now - log.timestamp < 3600000
    ).length;

    return { lastMinute, lastHour };
  }
}

module.exports = SecretsMonitor;

// Usage:
const monitor = new SecretsMonitor(secretsManager);
await monitor.monitorSecret('jwt-secret', 100); // Alert if accessed >100 times/min

module.exports = { SecretsMonitor };

