const app = express();

// ============================================================================
// LOGGING CONFIGURATION
// ============================================================================

const logger = winston.createLogger({
  level: process.env.LOG_LEVEL || 'info',
  format: winston.format.combine(
    winston.format.timestamp(),
    winston.format.errors({ stack: true }),
    winston.format.json()
  ),
  defaultMeta: { service: 'secure-app' },
  transports: [
    new winston.transports.File({ 
      filename: 'logs/error.log', 
      level: 'error',
      maxsize: 5242880, // 5MB
      maxFiles: 5,
    }),
    new winston.transports.File({ filename: 'logs/combined.log' })
  ]
});

// Add console logging in development
if (process.env.NODE_ENV !== 'production') {
  logger.add(new winston.transports.Console({
    format: winston.format.simple()
  }));
}

// ============================================================================
// SECURITY MIDDLEWARE - PART 1: HEADERS & HTTPS
// ============================================================================

// 1. Security headers with Helmet
app.use(helmet());

// Additional security header configurations
app.use(helmet.contentSecurityPolicy({
  directives: {
    defaultSrc: ["'self'"],
    styleSrc: ["'self'", "'unsafe-inline'"],
    scriptSrc: ["'self'"],
    imgSrc: ["'self'", 'data:', 'https:'],
    connectSrc: ["'self'"],
  }
}));

app.use(helmet.referrerPolicy({ policy: 'strict-origin-when-cross-origin' }));

// 2. HTTPS enforcement for production
app.use((req, res, next) => {
  if (process.env.NODE_ENV === 'production' && !req.secure) {
    logger.warn('Non-HTTPS request attempted', { 
      url: req.url, 
      ip: req.ip 
    });
    return res.redirect(301, `https://${req.headers.host}${req.url}`);
  }
  next();
});

// HSTS Header
app.use((req, res, next) => {
  res.setHeader(
    'Strict-Transport-Security',
    'max-age=31536000; includeSubDomains; preload'
  );
  next();
});

// ============================================================================
// SECURITY MIDDLEWARE - PART 2: REQUEST PARSING & SIZE LIMITS
// ============================================================================

// 3. Limit request body size to prevent DoS attacks
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ limit: '10kb', extended: true }));

// ============================================================================
// SECURITY MIDDLEWARE - PART 3: CORS
// ============================================================================

// 4. CORS Configuration - Restrictive by default
const corsOptions = {
  origin: function (origin, callback) {
    const allowedOrigins = (process.env.ALLOWED_ORIGINS || 'http://localhost:3000').split(',');

    if (allowedOrigins.includes(origin) || !origin) {
      callback(null, true);
    } else {
      logger.warn('CORS rejection', { origin });
      callback(new Error('Not allowed by CORS'));
    }
  },
  credentials: true,
  methods: ['GET', 'POST', 'PUT', 'DELETE', 'OPTIONS'],
  allowedHeaders: ['Content-Type', 'Authorization'],
  exposedHeaders: ['X-Total-Count'],
  maxAge: 3600
};

app.use(cors(corsOptions));
app.options('*', cors(corsOptions));

// ============================================================================
// SECURITY MIDDLEWARE - PART 4: RATE LIMITING
// ============================================================================

// 5. General rate limiter
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later',
  standardHeaders: true, // Return rate limit info in `RateLimit-*` headers
  legacyHeaders: false, // Disable `X-RateLimit-*` headers
  keyGenerator: (req, res) => {
    // Use X-Forwarded-For if behind proxy
    return req.ip || req.connection.remoteAddress;
  },
  skip: (req, res) => {
    // Skip rate limiting for health checks
    return req.path === '/health';
  },
  handler: (req, res) => {
    logger.warn('Rate limit exceeded', { ip: req.ip, path: req.path });
    res.status(429).json({ error: 'Too many requests' });
  }
});

app.use('/api/', limiter);

// Stricter rate limiter for authentication endpoints
const authLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 5,
  skipSuccessfulRequests: true,
  message: 'Too many login attempts, please try again after 15 minutes'
});

// ============================================================================
// AUTHENTICATION MIDDLEWARE
// ============================================================================

/**
 * JWT Authentication Middleware
 * Verifies JWT token from Authorization header
 */
const authMiddleware = (req, res, next) => {
  const authHeader = req.headers.authorization;

  if (!authHeader) {
    logger.warn('Missing authorization header', { path: req.path, ip: req.ip });
    return res.status(401).json({ 
      error: 'No authorization header',
      code: 'MISSING_AUTH'
    });
  }

  const parts = authHeader.split(' ');
  if (parts.length !== 2 || parts[0] !== 'Bearer') {
    logger.warn('Invalid authorization header format', { path: req.path });
    return res.status(401).json({ 
      error: 'Invalid authorization header format',
      code: 'INVALID_AUTH_FORMAT'
    });
  }

  const token = parts[1];

  try {
    const decoded = jwt.verify(token, process.env.JWT_SECRET, {
      algorithms: ['HS256'],
      issuer: process.env.JWT_ISSUER || 'app',
    });

    req.user = decoded;
    logger.debug('JWT verified', { userId: decoded.id });
    next();
  } catch (error) {
    if (error.name === 'TokenExpiredError') {
      logger.warn('Expired token attempted', { 
        userId: error.decoded?.id,
        ip: req.ip 
      });
      return res.status(401).json({ 
        error: 'Token expired',
        code: 'TOKEN_EXPIRED'
      });
    }

    logger.warn('Invalid token', { error: error.message, ip: req.ip });
    return res.status(403).json({ 
      error: 'Invalid or malformed token',
      code: 'INVALID_TOKEN'
    });
  }
};

/**
 * Role-Based Access Control (RBAC) Middleware
 */
const requireRole = (allowedRoles) => {
  return (req, res, next) => {
    if (!req.user) {
      return res.status(401).json({ 
        error: 'Not authenticated',
        code: 'NOT_AUTHENTICATED'
      });
    }

    if (!allowedRoles.includes(req.user.role)) {
      logger.warn('Unauthorized access attempt', {
        userId: req.user.id,
        requiredRoles: allowedRoles,
        userRole: req.user.role,
        path: req.path,
        ip: req.ip
      });
      return res.status(403).json({ 
        error: 'Insufficient permissions',
        code: 'INSUFFICIENT_PERMISSIONS'
      });
    }

    next();
  };
};

