/**
 * List Users Endpoint
 * Requires authentication
 * Supports pagination with input validation
 */
app.get('/api/users', authMiddleware, [
  query('page')
    .optional()
    .isInt({ min: 1, max: 1000 })
    .toInt()
    .withMessage('Page must be between 1 and 1000'),
  query('limit')
    .optional()
    .isInt({ min: 1, max: 100 })
    .toInt()
    .withMessage('Limit must be between 1 and 100'),
  query('sort')
    .optional()
    .isIn(['id', 'name', 'email'])
    .withMessage('Invalid sort field'),
], (req, res) => {
  // Validate query parameters
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({ 
      error: 'Validation failed',
      details: errors.array() 
    });
  }

  const page = req.query.page || 1;
  const limit = req.query.limit || 10;

  // Sample data - in production, fetch from database
  const users = [
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ];

  // Return paginated results with minimal data exposure
  // Note: In production, filter data based on user role
  if (req.user.role === 'admin') {
    // Admins see all fields
    res.set('X-Total-Count', users.length);
    res.json({
      page,
      limit,
      total: users.length,
      data: users
    });
  } else {
    // Regular users see limited fields
    const sanitizedUsers = users.map(user => ({
      id: user.id,
      name: user.name
      // Exclude email for non-admin users
    }));

    res.set('X-Total-Count', sanitizedUsers.length);
    res.json({
      page,
      limit,
      total: sanitizedUsers.length,
      data: sanitizedUsers
    });
  }
});

/**
 * Get Single User
 * Requires authentication
 * Validates numeric ID
 */
app.get('/api/users/:id', authMiddleware, [
  query('fields')
    .optional()
    .custom((value) => {
      const allowed = ['id', 'name', 'email'];
      const fields = value.split(',');
      if (!fields.every(f => allowed.includes(f))) {
        throw new Error('Invalid field requested');
      }
      return true;
    })
    .withMessage('Invalid fields parameter'),
], (req, res) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({ 
      error: 'Validation failed',
      details: errors.array() 
    });
  }

  const userId = parseInt(req.params.id, 10);

  if (isNaN(userId)) {
    return res.status(400).json({ 
      error: 'Invalid user ID',
      code: 'INVALID_ID'
    });
  }

  // In production, fetch from database with proper query
  // NEVER use string concatenation for database queries
  const user = { id: userId, name: 'Alice', email: 'alice@example.com' };

  if (!user) {
    return res.status(404).json({ 
      error: 'User not found',
      code: 'NOT_FOUND'
    });
  }

  logger.info('User accessed', { userId, accessedBy: req.user.id });

  res.json(user);
});

// ============================================================================
// ERROR HANDLING
// ============================================================================

/**
 * 404 Not Found Handler
 */
app.use((req, res) => {
  logger.warn('404 Not Found', { path: req.path, method: req.method });
  res.status(404).json({ 
    error: 'Resource not found',
    code: 'NOT_FOUND'
  });
});

/**
 * Global Error Handler
 * Must be last in middleware chain
 */
app.use((err, req, res, next) => {
  const isDevelopment = process.env.NODE_ENV === 'development';
  const isValidationError = err.array && typeof err.array === 'function';

  logger.error('Unhandled error', {
    error: err.message,
    stack: err.stack,
    path: req.path,
    method: req.method,
    ip: req.ip,
    userId: req.user?.id
  });

  // Handle specific error types
  if (err.message === 'Not allowed by CORS') {
    return res.status(403).json({ 
      error: 'CORS policy violation',
      code: 'CORS_ERROR'
    });
  }

  if (isValidationError) {
    return res.status(422).json({
      error: 'Validation error',
      details: err.array()
    });
  }

  // Generic error response - don't expose internals in production
  const statusCode = err.statusCode || err.status || 500;
  const response = {
    error: isDevelopment ? err.message : 'Internal server error',
    code: err.code || 'INTERNAL_ERROR'
  };

  if (isDevelopment) {
    response.stack = err.stack;
    response.details = err.message;
  }

  res.status(statusCode).json(response);
});

