### Layer 2: Secret Loader Factory
```javascript
// secrets.js
const AWS = require('aws-sdk');
const dotenv = require('dotenv');

class SecretsLoader {
  async load(config) {
    if (config.useDotenv) {
      return this.loadFromDotenv(config.dotenvFile);
    } else if (config.useSecretsManager) {
      return this.loadFromSecretsManager(config);
    }
    throw new Error('No secrets loader configured');
  }

  loadFromDotenv(file) {
    const result = dotenv.config({ path: file });
    if (result.error) {
      throw new Error(`Failed to load ${file}: ${result.error}`);
    }
    return result.parsed;
  }

  async loadFromSecretsManager(config) {
    const secretsManager = new AWS.SecretsManager({ 
      region: config.region 
    });

    try {
      const data = await secretsManager.getSecretValue({
        SecretId: config.secretId
      }).promise();

      return JSON.parse(data.SecretString);
    } catch (error) {
      console.error('Failed to load secrets from manager:', error);
      throw error;
    }
  }
}

module.exports = new SecretsLoader();
```

### Layer 3: Application Initialization
```javascript
