// Comprehensive Secrets Management Implementation
// Production-ready examples for app.js

/**
 * ============================================================================
 * 1. SECRETS LOADER - Multi-backend Support
 * ============================================================================
 */

const AWS = require('aws-sdk');
const dotenv = require('dotenv');
const fs = require('fs');
const path = require('path');

class SecretsManager {
  constructor(options = {}) {
    this.environment = process.env.NODE_ENV || 'development';
    this.cache = null;
    this.cacheExpiry = null;
    this.cacheTTL = options.cacheTTL || 3600000; // 1 hour
  }

  /**
   * Load secrets based on environment and configuration
   */
  async load(strategy = 'auto') {
    // Return cached secrets if still valid
    if (this.cache && this.cacheExpiry > Date.now()) {
      console.log('[Secrets] Using cached secrets');
      return this.cache;
    }

    let secrets;

    if (strategy === 'auto') {
      // Auto-detect best strategy
      strategy = this.autoDetectStrategy();
    }

    console.log(`[Secrets] Loading via strategy: ${strategy}`);

    switch (strategy) {
      case 'aws-secrets-manager':
        secrets = await this.loadFromAWSSecretsManager();
        break;

      case 'aws-parameter-store':
        secrets = await this.loadFromParameterStore();
        break;

      case 'vault':
        secrets = await this.loadFromVault();
        break;

      case 'github-actions':
        secrets = this.loadFromGitHubActions();
        break;

      case 'dotenv':
        secrets = this.loadFromDotenv();
        break;

      case 'environment':
        secrets = this.loadFromEnvironment();
        break;

      default:
        throw new Error(`Unknown secrets strategy: ${strategy}`);
    }

    // Validate loaded secrets
    this.validateSecrets(secrets);

    // Cache secrets
    this.cache = secrets;
    this.cacheExpiry = Date.now() + this.cacheTTL;

    console.log('[Secrets] Secrets loaded and cached successfully');
    return secrets;
  }

  /**
   * Auto-detect the best strategy based on environment
   */
  autoDetectStrategy() {
    // Production: AWS Secrets Manager
    if (this.environment === 'production') {
      if (process.env.AWS_REGION && process.env.SECRETS_ID) {
        return 'aws-secrets-manager';
      }
      if (process.env.VAULT_ADDR && process.env.VAULT_TOKEN) {
        return 'vault';
      }
    }

    // CI/CD: GitHub Actions (GitHub-hosted or self-hosted)
    if (process.env.GITHUB_ACTIONS === 'true') {
      return 'github-actions';
    }

    // Staging: Parameter Store
    if (this.environment === 'staging' && process.env.AWS_REGION) {
      return 'aws-parameter-store';
    }

    // Development: Dotenv
    return 'dotenv';
  }

  /**
   * Load from AWS Secrets Manager (Recommended for AWS)
   */
  async loadFromAWSSecretsManager() {
    const secretsManager = new AWS.SecretsManager({
      region: process.env.AWS_REGION || 'us-east-1'
    });

    const secretId = process.env.SECRETS_ID || 'prod/app-secrets';

    try {
      console.log(`[Secrets] Fetching from AWS Secrets Manager: ${secretId}`);

      const data = await secretsManager.getSecretValue({
        SecretId: secretId
      }).promise();

      let secrets;

      if (data.SecretString) {
        secrets = JSON.parse(data.SecretString);
      } else if (data.SecretBinary) {
        secrets = JSON.parse(Buffer.from(data.SecretBinary, 'base64').toString('utf-8'));
      } else {
        throw new Error('Invalid secret format');
      }

      console.log(`[Secrets] Loaded ${Object.keys(secrets).length} secrets from AWS Secrets Manager`);
      return secrets;
    } catch (error) {
      if (error.code === 'ResourceNotFoundException') {
        throw new Error(`AWS Secrets Manager secret not found: ${secretId}`);
      }
      throw new Error(`Failed to load secrets from AWS: ${error.message}`);
    }
  }

  /**
   * Load from AWS Systems Manager Parameter Store
   */
  async loadFromParameterStore() {
    const ssm = new AWS.SSM({
      region: process.env.AWS_REGION || 'us-east-1'
    });

    const pathPrefix = process.env.PARAMETER_PATH || '/app/prod/';

    try {
      console.log(`[Secrets] Fetching from Parameter Store with path: ${pathPrefix}`);

      let secrets = {};
      let nextToken;

      // Paginate through all parameters
      do {
        const response = await ssm.getParametersByPath({
          Path: pathPrefix,
          Recursive: true,
          WithDecryption: true,
          NextToken: nextToken
        }).promise();

        response.Parameters.forEach(param => {
          const key = param.Name.replace(pathPrefix, '').replace(/\//g, '_').toUpperCase();
          secrets[key] = param.Value;
        });

        nextToken = response.NextToken;
      } while (nextToken);

      console.log(`[Secrets] Loaded ${Object.keys(secrets).length} parameters`);
      return secrets;
    } catch (error) {
      throw new Error(`Failed to load secrets from Parameter Store: ${error.message}`);
    }
  }

  /**
   * Load from HashiCorp Vault
   */
  async loadFromVault() {
    const vaultAddr = process.env.VAULT_ADDR;
    const vaultToken = process.env.VAULT_TOKEN;
    const vaultPath = process.env.VAULT_PATH || 'secret/data/prod/app';

    if (!vaultAddr || !vaultToken) {
      throw new Error('VAULT_ADDR and VAULT_TOKEN environment variables required');
    }

    try {
      console.log(`[Secrets] Fetching from Vault: ${vaultPath}`);

      const response = await fetch(`${vaultAddr}/v1/${vaultPath}`, {
        method: 'GET',
        headers: {
          'X-Vault-Token': vaultToken
        }
      });

      if (!response.ok) {
        throw new Error(`Vault returned status ${response.status}`);
      }

      const data = await response.json();
      const secrets = data.data.data;

      console.log(`[Secrets] Loaded ${Object.keys(secrets).length} secrets from Vault`);
      return secrets;
    } catch (error) {
      throw new Error(`Failed to load secrets from Vault: ${error.message}`);
    }
  }

  /**
   * Load from GitHub Actions environment variables
   */
  loadFromGitHubActions() {
    console.log('[Secrets] Loading from GitHub Actions environment');

    const secrets = {};
    const githubEnv = process.env;

    // GitHub Actions typically sets secrets as environment variables
    const secretKeys = [
      'DATABASE_URL',
      'AWS_ACCESS_KEY_ID',
      'AWS_SECRET_ACCESS_KEY',
      'STRIPE_SECRET_KEY',
      'ANTHROPIC_API_KEY',
      'LOGFIRE_TOKEN',
      'JWT_SECRET'
    ];

    secretKeys.forEach(key => {
      if (githubEnv[key]) {
        secrets[key] = githubEnv[key];
      }
    });

    console.log(`[Secrets] Loaded ${Object.keys(secrets).length} secrets from GitHub Actions`);
    return secrets;
  }

  /**
   * Load from .env file (Development only)
   */
  loadFromDotenv(envFile = '.env.local') {
    const filePath = path.join(process.cwd(), envFile);

    console.log(`[Secrets] Loading from .env file: ${filePath}`);

    if (!fs.existsSync(filePath)) {
      throw new Error(`
        Development .env file not found: ${filePath}

        Create one by copying .env.example:
        cp .env.example .env.local
      `);
    }

    const result = dotenv.config({ path: filePath });

    if (result.error) {
      throw new Error(`Failed to parse .env file: ${result.error}`);
    }

    console.log(`[Secrets] Loaded ${Object.keys(result.parsed).length} secrets from ${envFile}`);
    return result.parsed;
  }

  /**
   * Load directly from environment variables
   * (Already set via deployment, CI/CD, or shell)
   */
  loadFromEnvironment() {
    console.log('[Secrets] Loading from environment variables');

    const requiredKeys = [
      'DATABASE_URL',
      'AWS_ACCESS_KEY_ID',
      'AWS_SECRET_ACCESS_KEY',
      'STRIPE_SECRET_KEY',
      'ANTHROPIC_API_KEY',
      'LOGFIRE_TOKEN',
      'JWT_SECRET'
    ];

    const secrets = {};
    const missing = [];

    requiredKeys.forEach(key => {
      if (process.env[key]) {
        secrets[key] = process.env[key];
      } else {
        missing.push(key);
      }
    });

    if (missing.length > 0) {
      throw new Error(`
        Missing required environment variables:
        ${missing.join('\n')}
      `);
    }

    console.log(`[Secrets] Loaded ${Object.keys(secrets).length} secrets from environment`);
    return secrets;
  }

  /**
   * Validate that all required secrets are present
   */
  validateSecrets(secrets) {
    const required = [
      'DATABASE_URL',
      'AWS_ACCESS_KEY_ID',
      'AWS_SECRET_ACCESS_KEY',
      'STRIPE_SECRET_KEY',
      'ANTHROPIC_API_KEY',
      'LOGFIRE_TOKEN',
      'JWT_SECRET'
    ];

    const missing = required.filter(key => !secrets[key]);

    if (missing.length > 0) {
      throw new Error(`
        Missing required secrets:
        ${missing.join(', ')}

        Ensure all secrets are configured in your secrets management system.
      `);
    }

    // Validate formats
    if (!secrets.DATABASE_URL.startsWith('postgres://')) {
      throw new Error('DATABASE_URL must be a PostgreSQL connection string');
    }

    if (!secrets.AWS_ACCESS_KEY_ID.startsWith('AKIA')) {
      throw new Error('AWS_ACCESS_KEY_ID appears invalid (should start with AKIA)');
    }

    if (!secrets.JWT_SECRET || secrets.JWT_SECRET.length < 32) {
      throw new Error('JWT_SECRET must be at least 32 characters');
    }

    console.log('[Secrets] All secrets validated successfully');
  }

  /**
   * Get individual secret with fallback
   */
  getSecret(key, defaultValue = null) {
    if (!this.cache) {
      throw new Error('Secrets not loaded. Call load() first');
    }

    const value = this.cache[key];
    if (value === undefined && defaultValue === null) {
      throw new Error(`Secret not found: ${key}`);
    }

    return value || defaultValue;
  }

  /**
   * Clear cache to force reload
   */
  clearCache() {
    this.cache = null;
    this.cacheExpiry = null;
    console.log('[Secrets] Cache cleared');
  }

  /**
   * Get secret keys (for debugging, never return values)
   */
  listLoadedSecrets() {
    if (!this.cache) {
      throw new Error('Secrets not loaded');
    }

    return Object.keys(this.cache);
  }
}

/**
 * ============================================================================
 * 2. APPLICATION INITIALIZATION WITH SECRETS
 * ============================================================================
 */

async function createSecureApp() {
  const secretsManager = new SecretsManager();

  // Load secrets (auto-detect strategy)
  const secrets = await secretsManager.load();

  const express = require('express');
  const helmet = require('helmet');
  const cors = require('cors');
  const jwt = require('jsonwebtoken');

  const app = express();

  // Apply security middleware
  app.use(helmet());
  app.use(cors({
    origin: process.env.ALLOWED_ORIGINS?.split(',') || ['http://localhost:3000'],
    credentials: true
  }));

  // Use secrets in application
  const dbConfig = {
    url: secrets.DATABASE_URL,
    // Parse connection string for additional config
  };

  const stripeSecret = secrets.STRIPE_SECRET_KEY;
  const jwtSecret = secrets.JWT_SECRET;

  // JWT Middleware
  const authMiddleware = (req, res, next) => {
    const token = req.headers.authorization?.split(' ')[1];
    if (!token) return res.status(401).json({ error: 'No token' });

    try {
      req.user = jwt.verify(token, jwtSecret);
      next();
    } catch (err) {
      res.status(403).json({ error: 'Invalid token' });
    }
  };

  app.get('/health', (req, res) => {
    res.json({ 
      status: 'ok', 
      timestamp: new Date().toISOString(),
      secretsLoaded: secretsManager.listLoadedSecrets().length > 0
    });
  });

  app.get('/protected', authMiddleware, (req, res) => {
    res.json({ message: 'This endpoint uses secrets!' });
  });

  return app;
}

/**
 * ============================================================================
 * 3. ENVIRONMENT-SPECIFIC CONFIGURATIONS
 * ============================================================================
 */

const secretsConfigurations = {
  // Development
  development: {
    strategy: 'dotenv',
    envFile: '.env.local',
    cacheTTL: 3600000, // 1 hour
    logLevel: 'debug'
  },

  // Staging
  staging: {
    strategy: 'aws-parameter-store',
    pathPrefix: '/app/staging/',
    cacheTTL: 1800000, // 30 minutes
    logLevel: 'info'
  },

  // Production
  production: {
    strategy: 'aws-secrets-manager',
    secretId: process.env.SECRETS_ID || 'prod/app-secrets',
    cacheTTL: 900000, // 15 minutes (shorter for secrets rotation)
    logLevel: 'warn'
  }
};

/**
 * ============================================================================
 * 4. DOCKER SECRETS SUPPORT
 * ============================================================================
 */

class DockerSecretsManager extends SecretsManager {
  /**
   * Load secrets from Docker secrets (/run/secrets/)
   * Used in Docker Swarm or Kubernetes
   */
  async loadFromDockerSecrets() {
    const secretsDir = '/run/secrets';

    console.log(`[Secrets] Loading from Docker secrets directory: ${secretsDir}`);

    if (!fs.existsSync(secretsDir)) {
      throw new Error(`Docker secrets directory not found: ${secretsDir}`);
    }

    const secrets = {};
    const files = fs.readdirSync(secretsDir);

    files.forEach(file => {
      const filePath = path.join(secretsDir, file);
      const content = fs.readFileSync(filePath, 'utf8').trim();
      secrets[file.toUpperCase()] = content;
    });

    console.log(`[Secrets] Loaded ${Object.keys(secrets).length} Docker secrets`);
    return secrets;
  }
}

/**
 * ============================================================================
 * 5. SECRETS ROTATION HANDLER
 * ============================================================================
 */

class SecretsRotationHandler {
  constructor(secretsManager, rotationInterval = 86400000) { // 24 hours
    this.secretsManager = secretsManager;
    this.rotationInterval = rotationInterval;
    this.rotationTimer = null;
  }

  /**
   * Start automatic secrets rotation
   */
  startRotation() {
    console.log('[SecretsRotation] Starting automatic rotation handler');

    this.rotationTimer = setInterval(async () => {
      try {
        console.log('[SecretsRotation] Checking for updated secrets...');

        // Clear cache to force reload on next access
        this.secretsManager.clearCache();

        // Pre-load secrets to catch any issues early
        await this.secretsManager.load();

        console.log('[SecretsRotation] Secrets reloaded successfully');
      } catch (error) {
        console.error('[SecretsRotation] Error during rotation:', error);
        // Don't crash app, but alert
        this.alertRotationFailure(error);
      }
    }, this.rotationInterval);
  }

  /**
   * Stop automatic rotation
   */
  stopRotation() {
    if (this.rotationTimer) {
      clearInterval(this.rotationTimer);
      this.rotationTimer = null;
      console.log('[SecretsRotation] Rotation handler stopped');
    }
  }

  /**
   * Alert on rotation failure (send to monitoring system)
   */
  alertRotationFailure(error) {
    console.error('[SecretsRotation] ALERT: Secrets rotation failed!', error);
    // In production: send to monitoring service (DataDog, New Relic, etc.)
    // Example: sendToMonitoring('secrets_rotation_failed', { error: error.message });
  }
}

/**
 * ============================================================================
 * 6. USAGE EXAMPLE: COMPLETE APPLICATION START
 * ============================================================================
 */

async function main() {
  try {
    console.log('[App] Starting application with secure secrets management...');

    // Initialize secrets manager
    const secretsManager = new SecretsManager();

    // Load secrets (auto-detect best strategy)
    const secrets = await secretsManager.load();

    // Create secure app
    const app = await createSecureApp();

    // Set up automatic rotation (every 24 hours)
    const rotationHandler = new SecretsRotationHandler(secretsManager, 86400000);
    rotationHandler.startRotation();

    // Graceful shutdown
    const shutdown = () => {
      console.log('[App] Shutting down gracefully...');
      rotationHandler.stopRotation();
      secretsManager.clearCache();
      process.exit(0);
    };

    process.on('SIGTERM', shutdown);
    process.on('SIGINT', shutdown);

    // Start server
    const PORT = process.env.PORT || 3000;
    app.listen(PORT, () => {
      console.log(`[App] Server running on port ${PORT}`);
      console.log(`[App] Environment: ${process.env.NODE_ENV || 'development'}`);
      console.log(`[App] Secrets loaded: ${secretsManager.listLoadedSecrets().length}`);
    });

  } catch (error) {
    console.error('[App] Fatal error during startup:', error);
    process.exit(1);
  }
}

// Export for use in other modules
module.exports = {
  SecretsManager,
  DockerSecretsManager,
  SecretsRotationHandler,
  createSecureApp,
  main
};

// Start if run directly
if (require.main === module) {
  main();
}

