  logger.info({ event: 'SIGTERM_RECEIVED' });
  server.close(() => {
    logger.info({ event: 'SERVER_CLOSED' });
    process.exit(0);
  });
});

process.on('SIGINT', () => {
  logger.info({ event: 'SIGINT_RECEIVED' });
  server.close(() => {
    logger.info({ event: 'SERVER_CLOSED' });
    process.exit(0);
  });
});

