## A07:2021 - Authentication Failures

### Vulnerabilities Found

1. **No authentication system**
   - Public access to sensitive data
   - No user identification

2. **No session management**
   - No tokens
   - No expiration

### Fixes Applied

```javascript
// ❌ BEFORE - No authentication
app.get('/users', (req, res) => {
  res.json([...]); // Anyone can access!
});

// ✅ AFTER - JWT authentication
const jwt = require('jsonwebtoken');
const bcrypt = require('bcryptjs');

// Login endpoint
app.post('/api/login', [
  body('email').isEmail().normalizeEmail(),
  body('password').isLength({ min: 8 })
], (req, res) => {
  const user = findUser(req.body.email);

  if (!user || !bcrypt.compareSync(req.body.password, user.hashedPassword)) {
    logger.warn({ event: 'FAILED_LOGIN', email: req.body.email });
    return res.status(401).json({ error: 'Invalid credentials' });
  }

  const token = jwt.sign(
    {
      userId: user.id,
      email: user.email,
      role: user.role,
      iat: Math.floor(Date.now() / 1000),
      exp: Math.floor(Date.now() / 1000) + 3600, // 1 hour
      iss: 'myapp',
      aud: 'myapp-users'
    },
    process.env.JWT_SECRET,
    { algorithm: 'HS256' }
  );

  res.json({
    token,
    expiresIn: 3600,
    user: { id: user.id, email: user.email }
  });
});

// Protected endpoints
const authMiddleware = (req, res, next) => {
  const token = req.headers.authorization?.split(' ')[1];

  if (!token) {
    return res.status(401).json({ error: 'No token' });
  }

  try {
    const decoded = jwt.verify(token, process.env.JWT_SECRET, {
      algorithms: ['HS256'],
      issuer: 'myapp',
      audience: 'myapp-users'
    });
    req.user = decoded;
    next();
  } catch (error) {
    logger.warn({ event: 'TOKEN_INVALID', error: error.message });
    res.status(403).json({ error: 'Invalid token' });
  }
};

app.get('/api/users', authMiddleware, (req, res) => {
  res.json([...]);
});
```

### JWT Best Practices

```javascript
// ✅ Good practices
jwt.sign(payload, secret, {
  algorithm: 'HS256', // Use strong algorithm
  expiresIn: '1h', // Short expiration
  issuer: 'myapp', // Identify issuer
  audience: 'myapp-users', // Identify audience
  subject: userId // Identify subject
});

jwt.verify(token, secret, {
  algorithms: ['HS256'], // Whitelist algorithms
  issuer: 'myapp', // Verify issuer
  audience: 'myapp-users', // Verify audience
});

// ❌ Bad practices
jwt.sign(payload, secret); // No expiration, no issuer
jwt.verify(token, secret); // No algorithm check
```

### Implementation Checklist

- [ ] Implement strong password hashing (bcrypt)
- [ ] Enforce minimum password complexity
- [ ] Implement JWT with short expiration (1 hour)
- [ ] Implement refresh token mechanism
- [ ] Protect against token replay attacks
