## 🔒 SECURE IMPLEMENTATION (Days 1-7)

### Option 1: AWS Secrets Manager (Recommended for AWS)

```javascript
// secrets-manager.js
const AWS = require('aws-sdk');

const secretsManager = new AWS.SecretsManager({
  region: process.env.AWS_REGION || 'us-east-1'
});

let cachedSecrets = null;

async function getSecrets() {
  // Cache secrets to avoid repeated API calls
  if (cachedSecrets) {
    return cachedSecrets;
  }

  try {
    const secretName = process.env.SECRETS_ARN || 'myapp/production/secrets';

    const response = await secretsManager.getSecretValue({
      SecretId: secretName
    }).promise();

    // Parse JSON or return string value
    cachedSecrets = response.SecretString 
      ? JSON.parse(response.SecretString)
      : response.SecretBinary;

    return cachedSecrets;
  } catch (error) {
    console.error('Error retrieving secrets:', error);
    throw new Error('Failed to load secrets from AWS Secrets Manager');
  }
}

// Refresh cache periodically (every 5 minutes)
setInterval(async () => {
  try {
    cachedSecrets = null; // Invalidate cache
    await getSecrets(); // Fetch fresh copy
  } catch (error) {
    console.error('Error refreshing secrets cache:', error);
  }
}, 5 * 60 * 1000);

module.exports = { getSecrets };
```

**Usage in app-secure.js**:
```javascript
const { getSecrets } = require('./secrets-manager');

// At startup
(async () => {
  try {
    const secrets = await getSecrets();

    const app = express();
    // Use secrets throughout app
    const jwtSecret = secrets.JWT_SECRET;

    // ... rest of app
  } catch (error) {
    console.error('Failed to start application:', error);
    process.exit(1);
  }
})();
```

### Option 2: HashiCorp Vault (Multi-cloud Solution)

```javascript
// vault-manager.js
const axios = require('axios');

const vaultClient = axios.create({
  baseURL: process.env.VAULT_ADDR || 'https://vault.example.com',
  timeout: 5000,
  headers: {
    'X-Vault-Token': process.env.VAULT_TOKEN,
    'Content-Type': 'application/json'
  }
});

async function getSecretsFromVault() {
  try {
    const response = await vaultClient.get(
      `/v1/secret/data/myapp/${process.env.NODE_ENV || 'production'}`
    );

    return response.data.data.data; // Vault wraps data in data.data
  } catch (error) {
    console.error('Error retrieving secrets from Vault:', error);
    throw new Error('Failed to load secrets from HashiCorp Vault');
  }
}

module.exports = { getSecretsFromVault };
```

### Option 3: Azure Key Vault (Microsoft Cloud)

```javascript
// azure-keyvault-manager.js
const { SecretClient } = require("@azure/keyvault-secrets");
const { DefaultAzureCredential } = require("@azure/identity");

const vaultUrl = `https://${process.env.AZURE_KEY_VAULT_NAME}.vault.azure.net/`;
const credential = new DefaultAzureCredential();
const client = new SecretClient(vaultUrl, credential);

async function getSecretsFromAzure() {
  try {
    const secrets = {};
    const secretNames = [
      'jwt-secret',
      'database-url',
      'aws-access-key',
      'aws-secret-key',
      'stripe-secret',
      'anthropic-api-key'
    ];

    for (const name of secretNames) {
      const secret = await client.getSecret(name);
      secrets[name.replace(/-/g, '_').toUpperCase()] = secret.value;
    }

    return secrets;
  } catch (error) {
    console.error('Error retrieving secrets from Azure Key Vault:', error);
    throw new Error('Failed to load secrets from Azure Key Vault');
  }
}

module.exports = { getSecretsFromAzure };
```

### Option 4: Kubernetes Secrets (Container Orchestration)

