## 🏗️ COMPREHENSIVE SOLUTION (Days 7-30)

Create a unified secrets manager wrapper that supports multiple backends:

```javascript
// secrets-manager-unified.js
class SecretsManager {
  constructor() {
    this.backend = process.env.SECRETS_BACKEND || 'aws';
    this.secrets = null;
  }

  async initialize() {
    switch (this.backend) {
      case 'aws':
        return this._initializeAWS();
      case 'vault':
        return this._initializeVault();
      case 'azure':
        return this._initializeAzure();
      case 'kubernetes':
        return this._initializeKubernetes();
      case 'dotenv':
        return this._initializeDotenv(); // Development only
      default:
        throw new Error(`Unknown secrets backend: ${this.backend}`);
    }
  }

  async _initializeAWS() {
    const AWS = require('aws-sdk');
    const secretsManager = new AWS.SecretsManager();

    try {
      const response = await secretsManager.getSecretValue({
        SecretId: process.env.SECRETS_ARN || 'myapp/secrets'
      }).promise();

      this.secrets = JSON.parse(response.SecretString);
      console.log('✓ Loaded secrets from AWS Secrets Manager');
      return true;
    } catch (error) {
      console.error('✗ Failed to load from AWS:', error);
      throw error;
    }
  }

  async _initializeVault() {
    const axios = require('axios');

    try {
      const response = await axios.get(
        `${process.env.VAULT_ADDR}/v1/secret/data/myapp/${process.env.NODE_ENV}`,
        {
          headers: { 'X-Vault-Token': process.env.VAULT_TOKEN }
        }
      );

      this.secrets = response.data.data.data;
      console.log('✓ Loaded secrets from HashiCorp Vault');
      return true;
    } catch (error) {
      console.error('✗ Failed to load from Vault:', error);
      throw error;
    }
  }

  async _initializeAzure() {
    const { SecretClient } = require("@azure/keyvault-secrets");
    const { DefaultAzureCredential } = require("@azure/identity");

    try {
      const vaultUrl = `https://${process.env.AZURE_KEY_VAULT_NAME}.vault.azure.net/`;
      const client = new SecretClient(vaultUrl, new DefaultAzureCredential());

      this.secrets = {};
      const secretNames = [
        'jwtSecret', 'databaseUrl', 'awsAccessKeyId',
        'awsSecretAccessKey', 'stripeSecretKey', 'anthropicApiKey'
      ];

      for (const name of secretNames) {
        const secret = await client.getSecret(name);
        this.secrets[name] = secret.value;
      }

      console.log('✓ Loaded secrets from Azure Key Vault');
      return true;
    } catch (error) {
      console.error('✗ Failed to load from Azure:', error);
      throw error;
    }
  }

  _initializeKubernetes() {
    // Kubernetes mounts secrets as environment variables
    this.secrets = {
      JWT_SECRET: process.env.JWT_SECRET,
      DATABASE_URL: process.env.DATABASE_URL,
      AWS_ACCESS_KEY_ID: process.env.AWS_ACCESS_KEY_ID,
      AWS_SECRET_ACCESS_KEY: process.env.AWS_SECRET_ACCESS_KEY,
      STRIPE_SECRET_KEY: process.env.STRIPE_SECRET_KEY,
      ANTHROPIC_API_KEY: process.env.ANTHROPIC_API_KEY
    };

    console.log('✓ Loaded secrets from Kubernetes');
    return true;
  }

  async _initializeDotenv() {
    // Development only - insecure
    if (process.env.NODE_ENV === 'production') {
      throw new Error('dotenv backend cannot be used in production');
    }

    require('dotenv').config();

    this.secrets = {
      JWT_SECRET: process.env.JWT_SECRET,
      DATABASE_URL: process.env.DATABASE_URL,
      AWS_ACCESS_KEY_ID: process.env.AWS_ACCESS_KEY_ID,
      AWS_SECRET_ACCESS_KEY: process.env.AWS_SECRET_ACCESS_KEY,
      STRIPE_SECRET_KEY: process.env.STRIPE_SECRET_KEY,
      ANTHROPIC_API_KEY: process.env.ANTHROPIC_API_KEY
    };

    console.log('⚠️  Using dotenv for secrets (development only)');
    return true;
  }

  get(key) {
    if (!this.secrets) {
      throw new Error('SecretsManager not initialized. Call initialize() first.');
    }

    const value = this.secrets[key];
    if (!value) {
      throw new Error(`Secret "${key}" not found in secrets manager`);
    }

    return value;
  }

  getAll() {
    if (!this.secrets) {
      throw new Error('SecretsManager not initialized. Call initialize() first.');
    }

    return { ...this.secrets }; // Return copy to prevent mutation
  }

  // Auto-refresh secrets periodically
  async startAutoRefresh(intervalSeconds = 300) {
    setInterval(async () => {
      try {
