```javascript
// secrets-manager.js
const AWS = require('aws-sdk');

const secretsManager = new AWS.SecretsManager({
  region: process.env.AWS_REGION || 'us-east-1'
});

let cachedSecrets = null;
let lastFetch = null;

async function getSecrets() {
  const now = Date.now();

  // Cache for 5 minutes to avoid repeated API calls
  if (cachedSecrets && lastFetch && (now - lastFetch) < 5 * 60 * 1000) {
    return cachedSecrets;
  }

  try {
    const secretName = process.env.SECRETS_ARN || 'myapp/production/secrets';

    console.log(`[Secrets] Fetching from: ${secretName}`);

    const response = await secretsManager.getSecretValue({
      SecretId: secretName
    }).promise();

    cachedSecrets = JSON.parse(response.SecretString);
    lastFetch = now;

    console.log('[Secrets] ✓ Successfully loaded from AWS Secrets Manager');
    return cachedSecrets;
  } catch (error) {
    console.error('[Secrets] ✗ Error retrieving secrets:', error);
    throw new Error('Failed to load secrets from AWS Secrets Manager');
  }
}

// Refresh cache every 5 minutes
setInterval(async () => {
  try {
    cachedSecrets = null;
    lastFetch = null;
    await getSecrets();
    console.log('[Secrets] ✓ Cache refreshed');
  } catch (error) {
    console.error('[Secrets] ✗ Error refreshing cache:', error);
  }
}, 5 * 60 * 1000);

module.exports = { getSecrets };
```

