### Unified Secrets Manager

```javascript
// secrets-manager-unified.js
class SecretsManager {
  constructor() {
    this.backend = process.env.SECRETS_BACKEND || 'aws';
    this.secrets = null;
  }

  async initialize() {
    switch (this.backend) {
      case 'aws':
        return this._initializeAWS();
      case 'vault':
        return this._initializeVault();
      case 'dotenv':
        return this._initializeDotenv(); // Dev only
      default:
        throw new Error(`Unknown backend: ${this.backend}`);
    }
  }

  async _initializeAWS() {
    const AWS = require('aws-sdk');
    const sm = new AWS.SecretsManager();

    try {
      const response = await sm.getSecretValue({
        SecretId: process.env.SECRETS_ARN
      }).promise();

      this.secrets = JSON.parse(response.SecretString);
      console.log('[Secrets] ✓ AWS Secrets Manager initialized');
      return true;
    } catch (error) {
      console.error('[Secrets] ✗ AWS initialization failed:', error);
      throw error;
    }
  }

  async _initializeVault() {
    // Similar to above implementation
    const { getSecretsFromVault } = require('./vault-manager');
    this.secrets = await getSecretsFromVault();
    console.log('[Secrets] ✓ Vault initialized');
    return true;
  }

  async _initializeDotenv() {
    if (process.env.NODE_ENV === 'production') {
      throw new Error('Cannot use dotenv in production');
    }

    require('dotenv').config();
    this.secrets = {
      JWT_SECRET: process.env.JWT_SECRET,
      DATABASE_URL: process.env.DATABASE_URL,
      // ... other secrets
    };

    console.log('[Secrets] ⚠️  dotenv initialized (dev only)');
    return true;
  }

  get(key) {
    if (!this.secrets) {
      throw new Error('SecretsManager not initialized');
    }

    const value = this.secrets[key];
    if (!value) {
      throw new Error(`Secret "${key}" not found`);
    }

    return value;
  }

  getAll() {
    if (!this.secrets) {
      throw new Error('SecretsManager not initialized');
    }
    return { ...this.secrets };
  }
}

module.exports = new SecretsManager();
```

