// Secure application implementation with all best practices
// Production-ready version of app.js

require('dotenv').config();
const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const morgan = require('morgan');
const jwt = require('jsonwebtoken');
const { query, body, validationResult } = require('express-validator');
const winston = require('winston');

// ============================================================================
// CONFIGURATION & INITIALIZATION
// ============================================================================

const app = express();
const PORT = process.env.PORT || 3000;
const NODE_ENV = process.env.NODE_ENV || 'development';
const JWT_SECRET = process.env.JWT_SECRET;

// Configure logger
const logger = winston.createLogger({
  level: process.env.LOG_LEVEL || 'info',
  format: winston.format.combine(
    winston.format.timestamp(),
    winston.format.errors({ stack: true }),
    winston.format.json()
  ),
  transports: [
    new winston.transports.Console({ 
      format: winston.format.combine(
        winston.format.colorize(),
        winston.format.simple()
      )
    }),
    new winston.transports.File({ filename: 'logs/error.log', level: 'error' }),
    new winston.transports.File({ filename: 'logs/combined.log' })
  ]
});

// Validate required environment variables
if (NODE_ENV === 'production') {
  if (!JWT_SECRET) {
    logger.error('FATAL: JWT_SECRET must be set in production');
    process.exit(1);
  }
}

// ============================================================================
// SECURITY MIDDLEWARE
// ============================================================================

// 1. Security Headers
app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      styleSrc: ["'self'", "'unsafe-inline'"],
      scriptSrc: ["'self'"],
      imgSrc: ["'self'", 'data:', 'https:'],
    },
  },
  hsts: {
    maxAge: 31536000, // 1 year
    includeSubDomains: true,
    preload: true,
  },
  frameguard: { action: 'deny' },
  noSniff: true,
  xssFilter: true,
  referrerPolicy: { policy: 'strict-origin-when-cross-origin' },
  permissionsPolicy: {
    geolocation: [],
    microphone: [],
    camera: [],
  },
}));

// 2. CORS Configuration
const corsOptions = {
  origin: function (origin, callback) {
    const allowedOrigins = (process.env.ALLOWED_ORIGINS || '').split(',').filter(Boolean);

    // Allow requests with no origin (like mobile apps or curl requests)
    if (!origin || allowedOrigins.includes(origin)) {
      callback(null, true);
    } else {
      logger.warn(`CORS request blocked from origin: ${origin}`);
      callback(new Error('Not allowed by CORS'));
    }
  },
  methods: ['GET', 'POST', 'PUT', 'DELETE', 'OPTIONS'],
  allowedHeaders: ['Content-Type', 'Authorization'],
  credentials: true,
  maxAge: 3600, // 1 hour
};

if (NODE_ENV === 'development') {
  corsOptions.origin = '*'; // Allow all in development
}

app.use(cors(corsOptions));

// 3. Request Size Limits
app.use(express.json({ limit: '10mb' }));
app.use(express.urlencoded({ extended: false, limit: '10mb' }));

// 4. HTTP Request Logging
app.use(morgan('combined', { 
  stream: { 
    write: message => logger.http(message.trim()) 
  },
  skip: (req, res) => {
    // Skip logging health checks
    return req.path === '/health';
  }
}));

// 5. Rate Limiting
const generalLimiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true,
  legacyHeaders: false,
  skip: (req, res) => {
    // Skip rate limiting for health checks
    return req.path === '/health';
  }
});

const authLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 5, // Strict limit for auth
  skipSuccessfulRequests: true,
  message: 'Too many login attempts, please try again later.',
});

app.use(generalLimiter);

// 6. Content-Type Validation Middleware
app.use((req, res, next) => {
  if (['POST', 'PUT', 'PATCH'].includes(req.method)) {
    const contentType = req.get('Content-Type');
    if (!contentType || !contentType.includes('application/json')) {
      return res.status(415).json({ 
        error: 'Unsupported Media Type. Please use application/json' 
      });
    }
  }
  next();
});

// ============================================================================
// AUTHENTICATION MIDDLEWARE
// ============================================================================

/**
 * Verify JWT token and attach user to request
 */
const authenticate = (req, res, next) => {
  try {
    const authHeader = req.headers.authorization;

    if (!authHeader || !authHeader.startsWith('Bearer ')) {
      return res.status(401).json({ error: 'Missing or invalid authorization header' });
    }

    const token = authHeader.substring(7); // Remove 'Bearer ' prefix

    if (!JWT_SECRET) {
      logger.error('JWT_SECRET not configured');
      return res.status(500).json({ error: 'Server configuration error' });
    }

    const decoded = jwt.verify(token, JWT_SECRET);
    req.user = decoded;
    next();
  } catch (error) {
    logger.warn(`Authentication failed: ${error.message}`);
    return res.status(403).json({ error: 'Invalid or expired token' });
  }
};

/**
 * Verify user has admin role
 */
const requireAdmin = (req, res, next) => {
  if (req.user?.role !== 'admin') {
    logger.warn(`Unauthorized admin access attempt by user: ${req.user?.id}`);
    return res.status(403).json({ error: 'Forbidden: Admin access required' });
  }
  next();
};

// ============================================================================
// INPUT VALIDATION MIDDLEWARE
// ============================================================================

const validateUserSearch = [
  query('q')
    .optional()
    .trim()
    .isLength({ min: 1, max: 100 })
    .withMessage('Search query must be 1-100 characters')
    .matches(/^[a-zA-Z0-9\s\-._@]*$/)
    .withMessage('Search query contains invalid characters'),
];

const validateUserCreation = [
  body('name')
    .trim()
    .isLength({ min: 1, max: 100 })
    .withMessage('Name must be 1-100 characters')
    .matches(/^[a-zA-Z\s\-']*$/)
    .withMessage('Name contains invalid characters'),
  body('email')
    .trim()
    .isEmail()
    .withMessage('Invalid email format')
    .normalizeEmail(),
];

// ============================================================================
// ERROR HANDLING MIDDLEWARE
// ============================================================================

/**
 * Validation error handler
 */
const handleValidationErrors = (req, res, next) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({ 
      error: 'Validation failed',
      details: errors.array().map(err => ({
        field: err.param,
        message: err.msg
      }))
    });
  }
  next();
};

// ============================================================================
// ROUTES
// ============================================================================

/**
 * Health check endpoint
 * No auth required - used for monitoring
 */
app.get('/health', (req, res) => {
  res.json({ 
    status: 'ok', 
    timestamp: new Date().toISOString(),
    environment: NODE_ENV
  });
});

/**
 * Get current user info
 */
app.get('/me', authenticate, (req, res) => {
  res.json({
    id: req.user.id,
    email: req.user.email,
    role: req.user.role
  });
});

/**
 * Get all users (admin only)
 */
app.get('/users', 
  authenticate, 
  requireAdmin,
  validateUserSearch,
  handleValidationErrors,
  (req, res) => {
    try {
      // Mock database response
      const users = [
        { id: 1, name: 'Alice', email: 'alice@example.com', role: 'admin' },
        { id: 2, name: 'Bob', email: 'bob@example.com', role: 'user' },
      ];

      // Filter by search query if provided
      const searchQuery = req.query.q?.toLowerCase();
      const filtered = searchQuery 
        ? users.filter(u => 
            u.name.toLowerCase().includes(searchQuery) || 
            u.email.toLowerCase().includes(searchQuery)
          )
        : users;

      logger.info(`User list retrieved by admin ${req.user.id}. Results: ${filtered.length}`);
      res.json(filtered);
    } catch (error) {
      logger.error(`Error fetching users: ${error.message}`);
      res.status(500).json({ error: 'Failed to fetch users' });
    }
  }
);

/**
 * Get specific user (admin only or own user)
 */
app.get('/users/:id', authenticate, (req, res) => {
  try {
    const userId = parseInt(req.params.id, 10);

    // Validate ID is a number
    if (isNaN(userId)) {
      return res.status(400).json({ error: 'Invalid user ID format' });
    }

    // Only allow users to view their own profile or admins to view any
    if (req.user.id !== userId && req.user.role !== 'admin') {
      logger.warn(`Unauthorized user access attempt by user ${req.user.id} for user ${userId}`);
      return res.status(403).json({ error: 'Forbidden' });
    }

    // Mock database response
    const user = { id: userId, name: 'Alice', email: 'alice@example.com', role: 'user' };

    logger.info(`User ${userId} profile accessed by user ${req.user.id}`);
    res.json(user);
  } catch (error) {
    logger.error(`Error fetching user: ${error.message}`);
    res.status(500).json({ error: 'Failed to fetch user' });
  }
});

/**
 * Create new user (admin only)
 */
app.post('/users',
  authenticate,
  requireAdmin,
  validateUserCreation,
  handleValidationErrors,
  (req, res) => {
    try {
      const { name, email } = req.body;

      // Mock database insert
      const newUser = {
        id: Math.floor(Math.random() * 10000),
        name,
        email,
        role: 'user'
      };

      logger.info(`User created by admin ${req.user.id}: ${newUser.id}`);
      res.status(201).json(newUser);
    } catch (error) {
      logger.error(`Error creating user: ${error.message}`);
      res.status(500).json({ error: 'Failed to create user' });
    }
  }
);

// ============================================================================
// 404 AND ERROR HANDLERS
// ============================================================================

/**
 * 404 Not Found handler
 */
app.use((req, res) => {
  logger.warn(`404 Not Found: ${req.method} ${req.path}`);
  res.status(404).json({ error: 'Not Found' });
});

/**
 * Global error handler
 */
app.use((err, req, res, next) => {
  logger.error(`Unhandled error: ${err.message}`, { stack: err.stack });

  // Don't expose stack traces to clients in production
  const isDevelopment = NODE_ENV === 'development';

  const response = {
    error: err.message || 'Internal Server Error',
    ...(isDevelopment && { stack: err.stack })
  };

  const statusCode = err.statusCode || err.status || 500;
  res.status(statusCode).json(response);
});

// ============================================================================
// SERVER STARTUP
// ============================================================================

const server = app.listen(PORT, () => {
  logger.info(`Server running on port ${PORT} [${NODE_ENV}]`);
  logger.info(`Security checks: Headers ✓, Rate Limit ✓, CORS ✓, Authentication ✓`);
});

// Graceful shutdown
process.on('SIGTERM', () => {
  logger.info('SIGTERM signal received: closing HTTP server');
  server.close(() => {
    logger.info('HTTP server closed');
    process.exit(0);
  });
});

process.on('SIGINT', () => {
  logger.info('SIGINT signal received: closing HTTP server');
  server.close(() => {
    logger.info('HTTP server closed');
    process.exit(0);
  });
});

module.exports = app;

