## Automated Testing

### 1. Dependency Vulnerability Scanning

```bash
# Using npm audit (built-in)
npm audit
npm audit fix

# Using Snyk (recommended)
npm install -g snyk
snyk test
snyk monitor

# Using OWASP Dependency-Check
npm install -D snyk
```

### 2. Static Code Analysis (SAST)

```bash
# ESLint with security plugins
npm install --save-dev eslint eslint-plugin-security
```

Create `.eslintrc.json`:
```json
{
  "plugins": ["security"],
  "extends": ["eslint:recommended", "plugin:security/recommended"]
}
```

Run:
```bash
npx eslint .
```

### 3. Unit Tests for Security

Create `tests/security.test.js`:

```javascript
const request = require('supertest');
const app = require('../app_secure');

describe('Security Tests', () => {

  describe('Authentication', () => {
    test('Should return 401 for missing token', async () => {
      const res = await request(app)
        .get('/users');

      expect(res.status).toBe(401);
      expect(res.body.error).toBeDefined();
    });

    test('Should return 403 for invalid token', async () => {
      const res = await request(app)
        .get('/users')
        .set('Authorization', 'Bearer invalid-token');

      expect(res.status).toBe(403);
    });

    test('Should return 403 for non-admin accessing /users', async () => {
      const userToken = 'valid-user-token'; // Mock token

      const res = await request(app)
        .get('/users')
        .set('Authorization', `Bearer ${userToken}`);

      expect(res.status).toBe(403);
    });
  });

  describe('Input Validation', () => {
    test('Should reject invalid search query', async () => {
      const res = await request(app)
        .get('/users?q=<img src=x onerror="alert(1)">')
        .set('Authorization', 'Bearer admin-token');

      expect(res.status).toBe(400);
      expect(res.body.error).toBe('Validation failed');
    });

    test('Should reject overly long search query', async () => {
      const longQuery = 'a'.repeat(101);

      const res = await request(app)
        .get(`/users?q=${longQuery}`)
        .set('Authorization', 'Bearer admin-token');

      expect(res.status).toBe(400);
    });

    test('Should reject invalid email format', async () => {
      const res = await request(app)
        .post('/users')
        .set('Authorization', 'Bearer admin-token')
        .send({
          name: 'John Doe',
          email: 'not-an-email'
        });

      expect(res.status).toBe(400);
      expect(res.body.error).toBe('Validation failed');
    });
  });

  describe('Rate Limiting', () => {
    test('Should rate limit excessive requests', async () => {
      let lastStatus = 200;

      // Make many requests
      for (let i = 0; i < 110; i++) {
        const res = await request(app)
          .get('/health');
        lastStatus = res.status;
      }

      // Should eventually hit rate limit (429)
      expect(lastStatus).toBe(429);
    }, 30000);
  });

  describe('Security Headers', () => {
    test('Should include X-Content-Type-Options header', async () => {
      const res = await request(app).get('/health');

      expect(res.headers['x-content-type-options']).toBe('nosniff');
    });

    test('Should include X-Frame-Options header', async () => {
      const res = await request(app).get('/health');

      expect(res.headers['x-frame-options']).toBeDefined();
    });

    test('Should include Content-Security-Policy header', async () => {
      const res = await request(app).get('/health');

      expect(res.headers['content-security-policy']).toBeDefined();
    });

    test('Should include Strict-Transport-Security header', async () => {
      const res = await request(app).get('/health');

      expect(res.headers['strict-transport-security']).toBeDefined();
    });
  });

  describe('CORS', () => {
    test('Should reject requests from disallowed origins', async () => {
      const res = await request(app)
        .get('/health')
        .set('Origin', 'https://evil.com');

      // CORS headers should not be present for disallowed origin
      expect(res.headers['access-control-allow-origin']).toBeUndefined();
    });
  });

  describe('404 Handling', () => {
    test('Should return 404 for unknown routes', async () => {
      const res = await request(app)
        .get('/unknown-route');

      expect(res.status).toBe(404);
      expect(res.body.error).toBe('Not Found');
    });
  });

  describe('Content-Type Validation', () => {
    test('Should reject POST without JSON content-type', async () => {
      const res = await request(app)
        .post('/users')
        .set('Authorization', 'Bearer admin-token')
        .set('Content-Type', 'text/plain')
        .send('{"name":"test"}');

      expect(res.status).toBe(415);
    });
  });
});
