## 1. SQL Injection Prevention

### ❌ VULNERABLE (DO NOT USE)
```javascript
// Direct string concatenation - SQL Injection Risk!
app.get('/users/:id', (req, res) => {
  const userId = req.params.id;
  // DANGER: User input directly in SQL
  const query = `SELECT * FROM users WHERE id = ${userId}`;
  db.query(query, (err, results) => {
    if (err) throw err;
    res.json(results);
  });
});

// Attacker can do:
// GET /users/1; DROP TABLE users; --
// This would execute: SELECT * FROM users WHERE id = 1; DROP TABLE users; --
```

### ✅ SECURE FIX
```javascript
const mysql = require('mysql');
const pool = mysql.createPool({
  connectionLimit: 10,
  host: process.env.DB_HOST,
  user: process.env.DB_USER,
  password: process.env.DB_PASSWORD,
  database: process.env.DB_NAME
});

app.get('/users/:id', (req, res) => {
  const userId = parseInt(req.params.id, 10);

  // Validate input type
  if (isNaN(userId)) {
    return res.status(400).json({ error: 'Invalid user ID' });
  }

  // Use parameterized queries - placeholders prevent injection
  const query = 'SELECT id, name, email FROM users WHERE id = ?';

  pool.query(query, [userId], (err, results) => {
    if (err) {
      console.error('DB Error:', err.message);
      return res.status(500).json({ error: 'Database error' });
    }
    res.json(results);
  });
});
```

**With Sequelize/ORM:**
```javascript
const { User } = require('./models');

app.get('/users/:id', async (req, res) => {
  try {
    const userId = parseInt(req.params.id, 10);
    if (isNaN(userId)) {
      return res.status(400).json({ error: 'Invalid ID' });
    }

    // ORM handles parameterization automatically
    const user = await User.findByPk(userId, {
      attributes: { exclude: ['password'] } // Don't expose passwords
    });

    if (!user) {
      return res.status(404).json({ error: 'User not found' });
    }

    res.json(user);
  } catch (error) {
    res.status(500).json({ error: 'Server error' });
  }
});
```

