## 3. Command Injection Prevention

### ❌ VULNERABLE (DO NOT USE)
```javascript
const { exec } = require('child_process');

app.get('/ping', (req, res) => {
  const host = req.query.host;
  // DANGER: User input directly in command
  exec(`ping -c 4 ${host}`, (error, stdout, stderr) => {
    res.json({ output: stdout });
  });
});

// Attacker can do:
// GET /ping?host=8.8.8.8; cat /etc/passwd
// This would execute: ping -c 4 8.8.8.8; cat /etc/passwd
// Exposing the system password file!
```

### ✅ SECURE FIX
```javascript
const { exec } = require('child_process');
const { execFile } = require('child_process');
const { query, validationResult } = require('express-validator');

// Use execFile instead of exec (no shell)
app.get('/ping',
  query('host')
    .matches(/^[\d.]+$|^[a-zA-Z0-9.-]+$/)
    .withMessage('Invalid host format'),
  (req, res) => {
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({ errors: errors.array() });
    }

    const host = req.query.host;

    // execFile doesn't invoke shell, so injection impossible
    execFile('ping', ['-c', '4', host], (error, stdout, stderr) => {
      if (error) {
        return res.status(400).json({ error: 'Ping failed' });
      }
      res.json({ output: stdout });
    });
  }
);

// Or use whitelist approach
const ALLOWED_HOSTS = ['8.8.8.8', 'google.com', 'cloudflare.com'];

app.get('/ping',
  query('host').custom(value => {
    if (!ALLOWED_HOSTS.includes(value)) {
      throw new Error('Host not in whitelist');
    }
    return true;
  }),
  (req, res) => {
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({ errors: errors.array() });
    }

    const host = req.query.host;
    execFile('ping', ['-c', '4', host], (error, stdout) => {
      if (error) return res.status(400).json({ error: 'Ping failed' });
      res.json({ output: stdout });
    });
  }
);
```

