## 4. Path Traversal Prevention

### ❌ VULNERABLE (DO NOT USE)
```javascript
const fs = require('fs');
const path = require('path');

app.get('/download', (req, res) => {
  const filename = req.query.file;
  // DANGER: User input directly in file path
  const filepath = `/uploads/${filename}`;
  res.download(filepath);
});

// Attacker can do:
// GET /download?file=../../../etc/passwd
// This would download: /etc/passwd (system file!)
```

### ✅ SECURE FIX
```javascript
const fs = require('fs');
const path = require('path');
const { query, validationResult } = require('express-validator');

const UPLOAD_DIR = path.join(__dirname, 'uploads');

app.get('/download',
  query('file')
    .matches(/^[a-zA-Z0-9._-]+$/)
    .withMessage('Invalid filename'),
  (req, res) => {
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({ errors: errors.array() });
    }

    const filename = req.query.file;
    const filepath = path.join(UPLOAD_DIR, filename);

    // Ensure path is within uploads directory
    const realpath = path.resolve(filepath);
    const realuploaddir = path.resolve(UPLOAD_DIR);

    if (!realpath.startsWith(realuploaddir)) {
      return res.status(403).json({ error: 'Access denied' });
    }

    // Verify file exists
    if (!fs.existsSync(realpath)) {
      return res.status(404).json({ error: 'File not found' });
    }

    res.download(realpath);
  }
);

// Or use database with file ID
app.get('/download/:fileId',
  async (req, res) => {
    try {
      const fileId = parseInt(req.params.fileId, 10);
      if (isNaN(fileId)) {
        return res.status(400).json({ error: 'Invalid file ID' });
      }

      // Lookup file from database
      const file = await File.findByPk(fileId);
      if (!file) {
        return res.status(404).json({ error: 'File not found' });
      }

      // Verify user has access
      if (file.userId !== req.user.id && req.user.role !== 'admin') {
        return res.status(403).json({ error: 'Access denied' });
      }

      const filepath = path.join(UPLOAD_DIR, file.storedName);
      res.download(filepath, file.originalName);
    } catch (error) {
      res.status(500).json({ error: 'Server error' });
    }
  }
);
```

