## 5. Broken Authentication Prevention

### ❌ VULNERABLE (DO NOT USE)
```javascript
// Password stored in plaintext!
app.post('/login', (req, res) => {
  const { email, password } = req.body;

  // Query user
  db.query('SELECT * FROM users WHERE email = ?', [email], (err, users) => {
    if (users.length === 0) {
      return res.status(401).json({ error: 'Invalid credentials' });
    }

    // Direct password comparison - NO HASHING!
    if (users[0].password === password) {
      res.json({ token: 'some-token' });
    } else {
      res.status(401).json({ error: 'Invalid credentials' });
    }
  });
});

// Tokens with no expiration
app.post('/login-vulnerable', (req, res) => {
  const token = jwt.sign(
    { userId: user.id },
    SECRET
    // NO expiresIn - token never expires!
  );
  res.json({ token });
});
```

### ✅ SECURE FIX
```javascript
const bcrypt = require('bcrypt');
const jwt = require('jsonwebtoken');
const { body, validationResult } = require('express-validator');
const rateLimit = require('express-rate-limit');

// Rate limit login attempts
const loginLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 5,
  skipSuccessfulRequests: true,
  message: 'Too many login attempts'
});

app.post('/login',
  loginLimiter,
  body('email').isEmail().normalizeEmail(),
  body('password').isLength({ min: 8 }),
  async (req, res) => {
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({ errors: errors.array() });
    }

    try {
      const { email, password } = req.body;

      // Lookup user
      const user = await User.findOne({ where: { email } });
      if (!user) {
        // Don't reveal if user exists
        return res.status(401).json({ error: 'Invalid credentials' });
      }

      // Compare password with hash
      const isPasswordValid = await bcrypt.compare(password, user.passwordHash);
      if (!isPasswordValid) {
        return res.status(401).json({ error: 'Invalid credentials' });
      }

      // Create JWT with expiration
      const token = jwt.sign(
        {
          userId: user.id,
          email: user.email,
          role: user.role,
          iat: Math.floor(Date.now() / 1000)
        },
        process.env.JWT_SECRET,
        {
          expiresIn: '24h', // Token expires in 24 hours
          algorithm: 'HS256'
        }
      );

      // Also issue refresh token (longer expiry)
      const refreshToken = jwt.sign(
        { userId: user.id },
        process.env.JWT_REFRESH_SECRET,
        { expiresIn: '7d' }
      );

      // Log successful login
      logger.info(`User ${user.id} logged in successfully`);

      res.json({
        token,
        refreshToken,
        expiresIn: 86400 // 24 hours in seconds
      });
    } catch (error) {
      logger.error(`Login error: ${error.message}`);
      res.status(500).json({ error: 'Server error' });
    }
  }
);

// Hash password on registration
app.post('/register',
  body('email').isEmail().normalizeEmail(),
  body('password')
    .isLength({ min: 12 })
    .matches(/^(?=.*[A-Z])(?=.*[a-z])(?=.*\d)(?=.*[@$!%*?&])/)
    .withMessage('Password must contain uppercase, lowercase, number, and special character'),
  async (req, res) => {
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({ errors: errors.array() });
    }

    try {
      const { email, password } = req.body;

      // Check if user exists
      const existingUser = await User.findOne({ where: { email } });
      if (existingUser) {
        return res.status(409).json({ error: 'User already exists' });
      }

      // Hash password with bcrypt
      const saltRounds = 10; // More rounds = more secure but slower
      const passwordHash = await bcrypt.hash(password, saltRounds);

      // Create user
      const user = await User.create({
        email,
        passwordHash, // Store hash, not password
        role: 'user'
      });

      logger.info(`New user registered: ${user.id}`);

      res.status(201).json({ 
        id: user.id,
        email: user.email,
        message: 'User created successfully'
      });
    } catch (error) {
      logger.error(`Registration error: ${error.message}`);
      res.status(500).json({ error: 'Server error' });
    }
  }
);

// Verify token middleware
const authenticate = (req, res, next) => {
  try {
    const authHeader = req.headers.authorization;
    if (!authHeader?.startsWith('Bearer ')) {
      return res.status(401).json({ error: 'Missing token' });
    }

    const token = authHeader.substring(7);
    const decoded = jwt.verify(token, process.env.JWT_SECRET);

    req.user = decoded;
    next();
  } catch (error) {
    if (error.name === 'TokenExpiredError') {
      return res.status(401).json({ error: 'Token expired', code: 'TOKEN_EXPIRED' });
    }
    res.status(403).json({ error: 'Invalid token' });
  }
};
```

