## 6. Exposed Sensitive Data Prevention

### ❌ VULNERABLE (DO NOT USE)
```javascript
// Returning all user information
app.get('/users', (req, res) => {
  User.findAll().then(users => {
    res.json(users); // Includes passwords, secret fields, etc.
  });
});

// Exposing internal error details
app.get('/data', (req, res) => {
  try {
    // ...
  } catch (error) {
    res.status(500).json({
      error: error.message,
      stack: error.stack, // Exposes internal structure
      sqlQuery: error.sql  // Exposes database structure
    });
  }
});

// Logging sensitive information
app.post('/login', (req, res) => {
  console.log('User login:', req.body); // Logs passwords!
  // ...
});
```

### ✅ SECURE FIX
```javascript
// Only return necessary fields
app.get('/users', authenticate, requireAdmin, async (req, res) => {
  try {
    const users = await User.findAll({
      attributes: { 
        exclude: ['passwordHash', 'salt', 'twoFactorSecret'] 
      }
    });
    res.json(users);
  } catch (error) {
    res.status(500).json({ error: 'Server error' });
  }
});

// Specific endpoint for current user
app.get('/me', authenticate, async (req, res) => {
  try {
    const user = await User.findByPk(req.user.userId, {
      attributes: {
        exclude: ['passwordHash', 'salt', 'twoFactorSecret']
      }
    });
    res.json(user);
  } catch (error) {
    res.status(500).json({ error: 'Server error' });
  }
});

// Safe error handling
app.use((err, req, res, next) => {
  logger.error(`Error: ${err.message}`, {
    stack: err.stack,
    url: req.url,
    method: req.method,
    userId: req.user?.id
  });

  // Don't expose internal details to client
  const isDev = process.env.NODE_ENV === 'development';

  const response = {
    error: 'An error occurred',
    ...(isDev && { details: err.message })
  };

  res.status(err.status || 500).json(response);
});

// Safe logging with redaction
app.post('/login', (req, res) => {
  const { email } = req.body;
  logger.info(`Login attempt for email: ${email}`); // Don't log password!
  // ...
});

// Redaction utility
function redactSensitiveData(data) {
  const sensitive = ['password', 'creditCard', 'ssn', 'secret'];
  const redacted = { ...data };

  sensitive.forEach(key => {
    if (redacted[key]) {
      redacted[key] = '[REDACTED]';
    }
  });

  return redacted;
}

// Usage
logger.info('Request body:', redactSensitiveData(req.body));
```

---

## 7. CORS Misconfiguration Prevention

### ❌ VULNERABLE (DO NOT USE)
```javascript
// Allow all origins - DANGEROUS!
app.use(cors());

// Or explicitly
app.use(cors({
  origin: '*' // Allows any domain to access your API
}));

// In production this is a security risk!
```

### ✅ SECURE FIX
```javascript
const cors = require('cors');

// Whitelist allowed origins
const allowedOrigins = [
  'https://example.com',
  'https://app.example.com',
  'https://admin.example.com'
];

// Add development origins
if (process.env.NODE_ENV === 'development') {
  allowedOrigins.push('http://localhost:3000');
  allowedOrigins.push('http://localhost:3001');
}

const corsOptions = {
  origin: function (origin, callback) {
    if (!origin || allowedOrigins.includes(origin)) {
      callback(null, true);
    } else {
      logger.warn(`CORS rejected from origin: ${origin}`);
      callback(new Error('Not allowed by CORS'));
    }
  },
  credentials: true, // Allow cookies
  methods: ['GET', 'POST', 'PUT', 'DELETE'],
  allowedHeaders: ['Content-Type', 'Authorization'],
  maxAge: 3600 // Cache preflight for 1 hour
};

app.use(cors(corsOptions));

// Or configure per route
app.get('/public', cors(), (req, res) => {
  res.json({ data: 'public' });
});

app.get('/private', cors(corsOptions), authenticate, (req, res) => {
  res.json({ data: 'private' });
});
```

---

## 8. Insecure Dependencies Prevention

### ❌ VULNERABLE (DO NOT USE)
```json
{
  "dependencies": {
    "old-vulnerable-package": "1.0.0",
    "deprecated-library": "2.0.0"
  }
}
```

### ✅ SECURE FIX
```bash
# Check for vulnerabilities
npm audit

# Update packages
npm update

# Fix vulnerabilities
npm audit fix

# Check for outdated packages
npm outdated

# Use npm audit in CI/CD
# .github/workflows/security.yml
name: Security Check
on: [push, pull_request]
jobs:
  audit:
    runs-on: ubuntu-latest
    steps:
      - uses: actions/checkout@v3
      - uses: actions/setup-node@v3
      - run: npm ci
      - run: npm audit
      - run: npm audit --production # Check production deps only
```

Keep `package-lock.json` in version control:
```javascript
// Install dependencies consistently
npm ci // Use instead of npm install in production
```

---

## Summary Table

| Vulnerability | Vulnerable Code | Secure Fix |
|---|---|---|
| SQL Injection | `query(${userId})` | Parameterized: `query(?, [userId])` |
| XSS | `res.send(userInput)` | Escape: `.escape()` or sanitize |
| Command Injection | `exec('cmd ' + userInput)` | Use `execFile()` with args array |
| Path Traversal | `path(userPath)` | Validate with `path.resolve()` |
| Auth Bypass | No auth check | Implement JWT + authentication |
| Exposed Secrets | Hardcoded strings | Environment variables |
| Weak Passwords | Any password | Bcrypt with validation rules |
| Expired Tokens | No expiration | JWT with `expiresIn` |
| CORS Open | `origin: '*'` | Whitelist allowed origins |
| Outdated Packages | Old versions | `npm audit fix` regularly |

---

## Key Takeaways

1. **Always validate and escape user input** - on both client and server
2. **Use parameterized queries** - prevent SQL injection
3. **Hash passwords** - use bcrypt, never store plaintext
4. **Implement proper authentication** - JWT with expiration
5. **Use HTTPS** - encrypt data in transit
6. **Set security headers** - use helmet.js
7. **Keep dependencies updated** - run npm audit regularly
8. **Don't expose sensitive data** - exclude fields, handle errors carefully
9. **Implement rate limiting** - prevent brute force attacks
10. **Monitor and log** - track security events

