## Secure Implementation: Hybrid Approach

**Recommended for Immediate Production Use:**

```javascript
require('dotenv').config();

// Detect which secrets provider to use
const SECRETS_PROVIDER = process.env.SECRETS_PROVIDER || 'env';

let appSecrets = {};

// Secrets interface
class SecretsManager {
  static async initialize() {
    switch (SECRETS_PROVIDER) {
      case 'aws-secrets-manager':
        appSecrets = await loadFromAWSSecretsManager();
        break;

      case 'vault':
        appSecrets = await loadFromVault();
        break;

      case 'azure-keyvault':
        appSecrets = await loadFromAzureKeyVault();
        break;

      case 'env':
      default:
        appSecrets = loadFromEnv();
        validateSecrets();
        break;
    }

    return appSecrets;
  }

  static getSecret(key) {
    const value = appSecrets[key];
    if (!value) {
      throw new Error(`Secret "${key}" not found or empty`);
    }
    return value;
  }
}

// Development mode: Use .env
function loadFromEnv() {
  logger.warn('Loading secrets from environment variables (development mode)');

  if (process.env.NODE_ENV === 'production') {
    logger.error('⚠️  WARNING: Using .env in production is not secure!');
    logger.error('⚠️  Switch to AWS Secrets Manager, Vault, or Key Vault');
  }

  return {
    jwtSecret: process.env.JWT_SECRET,
    dbPassword: process.env.DB_PASSWORD,
    apiKey: process.env.API_KEY,
    port: process.env.PORT || 3000,
    nodeEnv: process.env.NODE_ENV || 'development',
  };
}

// Validate secrets before use
function validateSecrets() {
  const NODE_ENV = process.env.NODE_ENV || 'development';

  if (NODE_ENV === 'production') {
    if (!appSecrets.jwtSecret || appSecrets.jwtSecret.length < 32) {
      logger.error('FATAL: JWT_SECRET must be at least 32 characters');
      process.exit(1);
    }

    if (!appSecrets.dbPassword) {
      logger.error('FATAL: DB_PASSWORD must be set');
      process.exit(1);
    }
  }

  logger.info('Secrets validation passed');
}

// AWS Secrets Manager implementation
async function loadFromAWSSecretsManager() {
  const AWS = require('aws-sdk');
  const client = new AWS.SecretsManager();

  try {
    logger.info('Loading secrets from AWS Secrets Manager');

    const response = await client
      .getSecretValue({ 
        SecretId: `app/${process.env.NODE_ENV}/secrets` 
      })
      .promise();

    return JSON.parse(response.SecretString);
  } catch (error) {
    logger.error('Failed to load AWS Secrets:', error);
    process.exit(1);
  }
}

// Startup sequence
async function startApp() {
  await SecretsManager.initialize();

  // Now use secrets
  const JWT_SECRET = SecretsManager.getSecret('jwtSecret');
  app.listen(PORT, () => {
    logger.info('Server started with secure secrets manager');
  });
}

startApp().catch(error => {
  logger.error('Failed to start application:', error);
  process.exit(1);
});
