### Step 3: Create Secrets Manager Module

**File: `lib/secrets-manager.js`**

```javascript
const AWS = require('aws-sdk');
const logger = require('./logger');

class SecretsManager {
  constructor() {
    this.client = new AWS.SecretsManager({
      region: process.env.AWS_REGION || 'us-east-1'
    });
    this.cache = {};
    this.cacheTTL = 30 * 60 * 1000; // 30 minutes
  }

  /**
   * Get secret from AWS Secrets Manager with caching
   */
  async getSecret(secretId) {
    // Check cache
    if (this.cache[secretId]) {
      const { data, timestamp } = this.cache[secretId];
      if (Date.now() - timestamp < this.cacheTTL) {
        logger.debug(`Using cached secret: ${secretId}`);
        return data;
      }
    }

    try {
      logger.info(`Fetching secret from AWS: ${secretId}`);

      const response = await this.client
        .getSecretValue({ SecretId: secretId })
        .promise();

      let secret;

      if ('SecretString' in response) {
        secret = JSON.parse(response.SecretString);
      } else {
        secret = Buffer.from(response.SecretBinary, 'base64').toString('ascii');
      }

      // Cache the secret
      this.cache[secretId] = {
        data: secret,
        timestamp: Date.now()
      };

      return secret;
    } catch (error) {
      logger.error(`Failed to fetch secret ${secretId}:`, error);
      throw error;
    }
  }

  /**
   * Get specific key from secret
   */
  async get(secretId, key) {
    const secret = await this.getSecret(secretId);
    return secret[key];
  }

  /**
   * Rotate secret
   */
  async rotateSecret(secretId) {
    try {
      logger.info(`Rotating secret: ${secretId}`);

      await this.client
        .rotateSecret({
          SecretId: secretId,
          RotationLambdaARN: process.env.ROTATION_LAMBDA_ARN,
          RotationRules: {
            AutomaticallyAfterDays: 30
          }
        })
        .promise();

      // Clear cache to force reload
      delete this.cache[secretId];

      logger.info(`Secret ${secretId} rotation initiated`);
    } catch (error) {
      logger.error(`Failed to rotate secret:`, error);
      throw error;
    }
  }

  /**
   * Clear cache
   */
  clearCache(secretId = null) {
    if (secretId) {
      delete this.cache[secretId];
      logger.debug(`Cache cleared for: ${secretId}`);
    } else {
      this.cache = {};
      logger.debug('Cache cleared');
    }
  }
}

module.exports = new SecretsManager();
```

### Step 4: Update app.js to Use AWS Secrets

**File: `app.js` (updated)**

```javascript
require('dotenv').config();
const express = require('express');
const secretsManager = require('./lib/secrets-manager');
const logger = require('./lib/logger');

const app = express();
let JWT_SECRET;
let DB_PASSWORD;
let API_KEY;

/**
 * Initialize secrets on startup
 */
async function initializeSecrets() {
  try {
    const NODE_ENV = process.env.NODE_ENV || 'development';

    if (process.env.SECRETS_PROVIDER === 'aws-secrets-manager') {
      logger.info('Initializing AWS Secrets Manager');

      // Load all secrets
      const jwtSecret = await secretsManager.get(
        `app/${NODE_ENV}/jwt-secret`,
        'JWT_SECRET'
      );

      const dbSecret = await secretsManager.get(
        `app/${NODE_ENV}/db`,
        'DB_PASSWORD'
      );

      const apiKey = await secretsManager.get(
        `app/${NODE_ENV}/api-keys`,
        'API_KEY'
      );

      JWT_SECRET = jwtSecret;
      DB_PASSWORD = dbSecret;
      API_KEY = apiKey;

      logger.info('✅ Secrets loaded from AWS Secrets Manager');
    } else {
      // Fallback to environment variables
      logger.warn('⚠️  Using environment variables for secrets (development mode)');

      JWT_SECRET = process.env.JWT_SECRET;
      DB_PASSWORD = process.env.DB_PASSWORD;
      API_KEY = process.env.API_KEY;
    }

    // Validate secrets
    if (!JWT_SECRET || JWT_SECRET.length < 32) {
      throw new Error('JWT_SECRET must be at least 32 characters');
    }

    if (NODE_ENV === 'production' && !DB_PASSWORD) {
      throw new Error('DB_PASSWORD is required in production');
    }
  } catch (error) {
    logger.error('Failed to initialize secrets:', error);
    process.exit(1);
  }
}

/**
 * Authentication middleware using secrets
 */
const authenticate = (req, res, next) => {
  try {
    const authHeader = req.headers.authorization;

    if (!authHeader?.startsWith('Bearer ')) {
      return res.status(401).json({ error: 'Missing token' });
    }

    const token = authHeader.substring(7);
    const decoded = jwt.verify(token, JWT_SECRET);
    req.user = decoded;
    next();
  } catch (error) {
    res.status(403).json({ error: 'Invalid token' });
  }
};

// Routes and middleware...

/**
 * Startup sequence
 */
async function start() {
  try {
    await initializeSecrets();

    const PORT = process.env.PORT || 3000;
    app.listen(PORT, () => {
      logger.info(`Server started on port ${PORT}`);
    });
  } catch (error) {
    logger.error('Failed to start server:', error);
    process.exit(1);
  }
}

start();
