### Step 3: Create Vault Module

**File: `lib/vault-secrets-manager.js`**

```javascript
const vault = require('node-vault')({
  endpoint: process.env.VAULT_ADDR || 'http://localhost:8200',
  token: process.env.VAULT_TOKEN,
});

const logger = require('./logger');

class VaultSecretsManager {
  constructor() {
    this.cache = {};
    this.cacheTTL = 30 * 60 * 1000; // 30 minutes
  }

  /**
   * Authenticate with Vault using AppRole
   */
  async authenticateWithAppRole() {
    try {
      logger.info('Authenticating with Vault using AppRole');

      const result = await vault.appRoleLogin({
        role_id: process.env.VAULT_ROLE_ID,
        secret_id: process.env.VAULT_SECRET_ID,
      });

      vault.token = result.auth.client_token;
      logger.info('✅ AppRole authentication successful');
    } catch (error) {
      logger.error('Failed to authenticate with Vault:', error);
      throw error;
    }
  }

  /**
   * Get secret from Vault with caching
   */
  async getSecret(secretPath) {
    // Check cache
    if (this.cache[secretPath]) {
      const { data, timestamp } = this.cache[secretPath];
      if (Date.now() - timestamp < this.cacheTTL) {
        logger.debug(`Using cached secret: ${secretPath}`);
        return data;
      }
    }

    try {
      logger.info(`Fetching secret from Vault: ${secretPath}`);

      const response = await vault.read(secretPath);
      const secret = response.data.data || response.data;

      // Cache the secret
      this.cache[secretPath] = {
        data: secret,
        timestamp: Date.now()
      };

      return secret;
    } catch (error) {
      logger.error(`Failed to fetch secret from Vault:`, error);
      throw error;
    }
  }

  /**
   * Store secret in Vault
   */
  async writeSecret(secretPath, data) {
    try {
      logger.info(`Writing secret to Vault: ${secretPath}`);

      await vault.write(secretPath, data);

      // Clear cache
      delete this.cache[secretPath];

      logger.info(`✅ Secret written: ${secretPath}`);
    } catch (error) {
      logger.error('Failed to write secret:', error);
      throw error;
    }
  }

  /**
   * Clear cache
   */
  clearCache(secretPath = null) {
    if (secretPath) {
      delete this.cache[secretPath];
    } else {
      this.cache = {};
    }
  }
}

module.exports = new VaultSecretsManager();
```

