      `https://${process.env.KEYVAULT_NAME}.vault.azure.net/`,
      credential
    );
    this.cache = {};
    this.cacheTTL = 30 * 60 * 1000; // 30 minutes
  }

  /**
   * Get secret from Azure Key Vault
   */
  async getSecret(secretName) {
    // Check cache
    if (this.cache[secretName]) {
      const { value, timestamp } = this.cache[secretName];
      if (Date.now() - timestamp < this.cacheTTL) {
        logger.debug(`Using cached secret: ${secretName}`);
        return value;
      }
    }

    try {
      logger.info(`Fetching secret from Key Vault: ${secretName}`);

      const secret = await this.client.getSecret(secretName);

      // Cache the secret
      this.cache[secretName] = {
        value: secret.value,
        timestamp: Date.now()
      };

      return secret.value;
    } catch (error) {
      logger.error(`Failed to fetch secret:`, error);
      throw error;
    }
  }

  /**
   * Set secret in Azure Key Vault
   */
  async setSecret(secretName, value) {
    try {
      logger.info(`Setting secret in Key Vault: ${secretName}`);

      await this.client.setSecret(secretName, value);

      // Clear cache
      delete this.cache[secretName];

      logger.info(`✅ Secret set: ${secretName}`);
    } catch (error) {
      logger.error('Failed to set secret:', error);
      throw error;
    }
  }

  /**
   * Clear cache
   */
  clearCache(secretName = null) {
    if (secretName) {
      delete this.cache[secretName];
    } else {
      this.cache = {};
    }
  }
}

module.exports = new AzureSecretsManager();
