## Hybrid Approach (Recommended)

**File: `lib/unified-secrets-manager.js`**

```javascript
const logger = require('./logger');

class UnifiedSecretsManager {
  constructor() {
    this.provider = null;
    this.fallbackProvider = null;
  }

  /**
   * Initialize based on environment
   */
  async initialize() {
    const provider = process.env.SECRETS_PROVIDER || 'env';

    switch (provider) {
      case 'aws-secrets-manager':
        this.provider = require('./secrets-manager');
        this.fallbackProvider = require('./env-secrets-manager');
        logger.info('Using AWS Secrets Manager (with env fallback)');
        break;

      case 'vault':
        this.provider = require('./vault-secrets-manager');
        await this.provider.authenticateWithAppRole();
        this.fallbackProvider = require('./env-secrets-manager');
        logger.info('Using HashiCorp Vault (with env fallback)');
        break;

      case 'azure-keyvault':
        this.provider = require('./azure-secrets-manager');
        this.fallbackProvider = require('./env-secrets-manager');
        logger.info('Using Azure Key Vault (with env fallback)');
        break;

      case 'env':
      default:
        logger.warn('Using environment variables (development only)');
        this.provider = require('./env-secrets-manager');
        break;
    }

    return this;
  }

  /**
   * Get secret with fallback
   */
  async get(secretId, key = null) {
    try {
      // Try primary provider
      const secret = await this.provider.getSecret(secretId);
      return key ? secret[key] : secret;
    } catch (error) {
      logger.warn(`Failed to get secret from primary provider: ${error.message}`);

      if (this.fallbackProvider) {
        logger.info('Falling back to environment variables');
        return this.fallbackProvider.getSecret(secretId);
      }

      throw error;
    }
  }

  /**
   * Rotate secret
   */
  async rotate(secretId) {
    if (this.provider.rotateSecret) {
      return await this.provider.rotateSecret(secretId);
    }
    throw new Error('Secret rotation not supported by this provider');
  }
}

module.exports = UnifiedSecretsManager;
```

