# Security Review of app.js

## Executive Summary
This review identifies several critical security vulnerabilities and missing best practices in the current implementation. While the application is relatively simple, it lacks essential security measures for production use.

---

## Critical Vulnerabilities Found

### 1. 🔴 CRITICAL: No Authentication/Authorization
**Severity:** CRITICAL (OWASP #01 - Broken Authentication)

**Issue:** 
- `/users` endpoint exposes sensitive user data without any authentication
- No access control checks are performed
- Sensitive information (emails) is publicly accessible

**Current Code:**
```javascript
app.get('/users', (req, res) => {
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ]);
});
```

**Vulnerable Scenarios:**
- Any unauthenticated user can access the endpoint
- No rate limiting prevents brute force attacks
- No audit logging of who accessed the data

**Recommendations:**

#### Option A: JWT Authentication
```javascript
const jwt = require('jsonwebtoken');

const verifyToken = (req, res, next) => {
  const token = req.headers['authorization']?.split(' ')[1];

  if (!token) {
    return res.status(401).json({ error: 'No authentication token provided' });
  }

  try {
    const decoded = jwt.verify(token, process.env.JWT_SECRET);
    req.user = decoded;
    next();
  } catch (error) {
    return res.status(403).json({ error: 'Invalid or expired token' });
  }
};

app.get('/users', verifyToken, (req, res) => {
  // Only authenticated users can access
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ]);
});
```

#### Option B: OAuth 2.0 / OpenID Connect
```javascript
const passport = require('passport');
const OAuthStrategy = require('passport-oauth2');

// Configure with your OAuth provider
passport.use(new OAuthStrategy({
    authorizationURL: 'https://oauth-provider.com/authorize',
    tokenURL: 'https://oauth-provider.com/token',
    clientID: process.env.OAUTH_CLIENT_ID,
    clientSecret: process.env.OAUTH_CLIENT_SECRET,
    callbackURL: process.env.OAUTH_CALLBACK_URL
  }, (accessToken, refreshToken, profile, done) => {
    // Verify user and create session
    return done(null, profile);
  })
);

app.get('/users', passport.authenticate('oauth2'), (req, res) => {
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ]);
});
```

---

### 2. 🔴 HIGH: No Input Validation
**Severity:** HIGH (OWASP #03 - Injection, #04 - Insecure Deserialization)

**Issue:**
- No query parameters are validated
- No validation of request headers
- Could be exploited with path traversal or injection attacks

**Example Attack Vectors:**
```
GET /users?id=1; DROP TABLE users; --
GET /users?id=../../../etc/passwd
GET /users?callback=<img src=x onerror="alert('xss')">
```

**Recommendations:**

```javascript
const { query, validationResult } = require('express-validator');

// Validation middleware
const validateUserQuery = [
  query('id')
    .optional()
    .isInt({ min: 1, max: 10000 })
    .withMessage('Invalid user ID'),
  query('limit')
    .optional()
    .isInt({ min: 1, max: 100 })
    .withMessage('Limit must be between 1 and 100'),
  query('search')
    .optional()
    .trim()
    .isLength({ max: 100 })
    .escape()
    .withMessage('Search term too long or contains invalid characters'),
];

const handleValidationErrors = (req, res, next) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({ 
      errors: errors.array(),
      message: 'Validation failed'
    });
  }
  next();
};

app.get('/users', validateUserQuery, handleValidationErrors, (req, res) => {
  // Safe to use req.query now
  const { id, search } = req.query;

  let users = [
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ];

  if (search) {
    users = users.filter(u => 
      u.name.toLowerCase().includes(search.toLowerCase())
    );
  }

  res.json(users);
});
```

---

### 3. 🔴 HIGH: Sensitive Data Exposure
**Severity:** HIGH (OWASP #02 - Cryptographic Failures)

**Issue:**
- Email addresses are exposed without encryption
- No HTTPS requirement (only HTTP on port 3000)
- Sensitive data returned without field filtering
- No data masking for non-admin users

**Recommendations:**

```javascript
// 1. Enforce HTTPS in production
const helmet = require('helmet');

app.use(helmet()); // Sets various HTTP headers for security

app.use((req, res, next) => {
  if (process.env.NODE_ENV === 'production' && !req.secure) {
    return res.status(403).json({ error: 'HTTPS required' });
  }
  next();
});

// 2. Field-level access control
const getUsersWithFieldFiltering = (users, req) => {
  const isAdmin = req.user?.role === 'admin';

  return users.map(user => ({
    id: user.id,
    name: user.name,
    email: isAdmin ? user.email : undefined, // Hide email from non-admins
  }));
};

// 3. Encrypt sensitive data at rest
const crypto = require('crypto');

const encryptEmail = (email) => {
  const cipher = crypto.createCipher('aes-256-cbc', process.env.ENCRYPTION_KEY);
  let encrypted = cipher.update(email, 'utf8', 'hex');
  encrypted += cipher.final('hex');
  return encrypted;
};

const decryptEmail = (encrypted) => {
  const decipher = crypto.createDecipher('aes-256-cbc', process.env.ENCRYPTION_KEY);
  let decrypted = decipher.update(encrypted, 'hex', 'utf8');
  decrypted += decipher.final('utf8');
  return decrypted;
};
```

---

### 4. 🟠 MEDIUM: Missing Security Headers
**Severity:** MEDIUM (OWASP #05 - Security Misconfiguration)

**Issue:**
- No Content Security Policy (CSP)
- No X-Frame-Options to prevent clickjacking
- No X-Content-Type-Options to prevent MIME sniffing
- No HSTS for HTTPS enforcement
- No CORS policy configured

**Recommendations:**

```javascript
const helmet = require('helmet');
const cors = require('cors');

// Security headers
app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      scriptSrc: ["'self'"],
      styleSrc: ["'self'", "'unsafe-inline'"],
      imgSrc: ["'self'", 'data:', 'https:'],
      connectSrc: ["'self'"],
      fontSrc: ["'self'"],
      objectSrc: ["'none'"],
      upgradeInsecureRequests: [],
    },
  },
  hsts: {
    maxAge: 31536000, // 1 year
    includeSubDomains: true,
    preload: true,
  },
  frameguard: { action: 'deny' },
  xssFilter: true,
  noSniff: true,
}));

// CORS configuration - whitelist allowed origins
const allowedOrigins = [
  'https://example.com',
  'https://app.example.com',
];

app.use(cors({
  origin: (origin, callback) => {
    if (!origin || allowedOrigins.includes(origin)) {
      callback(null, true);
    } else {
      callback(new Error('Not allowed by CORS'));
    }
  },
  credentials: true,
  methods: ['GET', 'POST', 'PUT', 'DELETE'],
  allowedHeaders: ['Content-Type', 'Authorization'],
  maxAge: 3600,
}));

// Additional security headers
app.use((req, res, next) => {
  res.setHeader('X-Content-Type-Options', 'nosniff');
  res.setHeader('X-Frame-Options', 'DENY');
  res.setHeader('X-XSS-Protection', '1; mode=block');
  res.setHeader('Strict-Transport-Security', 'max-age=31536000; includeSubDomains');
  next();
});
```

---

### 5. 🟠 MEDIUM: No Rate Limiting
**Severity:** MEDIUM (OWASP #11 - Broken Access Control, DDoS prevention)

**Issue:**
- Endpoints can be called unlimited times
- Vulnerable to brute force attacks
- No protection against DoS attacks

**Recommendations:**

```javascript
const rateLimit = require('express-rate-limit');

// General rate limiter
const generalLimiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later',
  standardHeaders: true, // Return rate limit info in the `RateLimit-*` headers
  legacyHeaders: false, // Disable the `X-RateLimit-*` headers
  skip: (req) => req.user?.role === 'admin', // Allow admins unlimited
});

// Strict limiter for authentication endpoints
const authLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 5, // Only 5 attempts per 15 minutes
  skipSuccessfulRequests: true, // Don't count successful requests
  message: 'Too many login attempts, please try again later',
});

// Apply limiters
app.use('/users', generalLimiter);
app.post('/login', authLimiter, (req, res) => {
  // Login logic
});
```

---

### 6. 🟠 MEDIUM: No Logging and Monitoring
**Severity:** MEDIUM (OWASP #09 - Logging and Monitoring)

**Issue:**
- No security events are logged
- No audit trail of data access
- Cannot detect or investigate security incidents

**Recommendations:**

```javascript
const winston = require('winston');

// Configure logging
const logger = winston.createLogger({
  level: 'info',
  format: winston.format.json(),
  defaultMeta: { service: 'user-api' },
  transports: [
    // Log errors to file
    new winston.transports.File({ 
      filename: 'logs/error.log', 
      level: 'error',
      maxsize: 5242880, // 5MB
      maxFiles: 5,
    }),
    // Log all activity to file
    new winston.transports.File({ 
      filename: 'logs/combined.log',
      maxsize: 5242880,
      maxFiles: 5,
    }),
  ],
});

if (process.env.NODE_ENV !== 'production') {
  logger.add(new winston.transports.Console({
    format: winston.format.simple(),
  }));
}

// Audit logging middleware
const auditLog = (req, res, next) => {
  const originalJson = res.json.bind(res);

  res.json = function(data) {
    logger.info('API Request', {
      method: req.method,
      path: req.path,
      query: req.query,
      user: req.user?.id,
      ip: req.ip,
      statusCode: res.statusCode,
      timestamp: new Date().toISOString(),
    });
    return originalJson(data);
  };

  next();
};

app.use(auditLog);

// Error logging
app.use((err, req, res, next) => {
  logger.error('Application Error', {
    error: err.message,
    stack: err.stack,
    path: req.path,
    method: req.method,
    user: req.user?.id,
    timestamp: new Date().toISOString(),
  });

  res.status(500).json({ 
    error: 'Internal server error',
    requestId: req.id, // For correlation
  });
});
```

---

### 7. 🟡 LOW: No Error Handling
**Severity:** MEDIUM (OWASP #10 - Vulnerable and Outdated Components)

**Issue:**
- Unhandled exceptions could expose stack traces
- No centralized error handling
- Default Express error messages reveal too much information

**Recommendations:**

```javascript
// Custom error class
class AppError extends Error {
  constructor(message, statusCode) {
    super(message);
    this.statusCode = statusCode;
    Error.captureStackTrace(this, this.constructor);
  }
}

// Global error handler
app.use((err, req, res, next) => {
  const status = err.statusCode || 500;
  const message = err.message || 'Internal Server Error';

  // Don't expose stack trace in production
  const response = {
    status,
    message,
    ...(process.env.NODE_ENV !== 'production' && { stack: err.stack }),
  };

  logger.error('Unhandled Error', {
    error: message,
    stack: err.stack,
    path: req.path,
    timestamp: new Date().toISOString(),
  });

  res.status(status).json(response);
});

// Catch 404 and forward to error handler
app.use((req, res, next) => {
  const err = new AppError('Not Found', 404);
  next(err);
});
```

---

### 8. 🟡 LOW: No Environment Configuration
**Severity:** MEDIUM (OWASP #05 - Security Misconfiguration)

**Issue:**
- Hardcoded port and no environment variable usage
- No configuration management
- Could expose sensitive data in version control

**Recommendations:**

```javascript
require('dotenv').config(); // Load environment variables

const express = require('express');
const app = express();

const PORT = process.env.PORT || 3000;
const NODE_ENV = process.env.NODE_ENV || 'development';

// Validate required environment variables
const requiredEnvVars = [
  'JWT_SECRET',
  'ENCRYPTION_KEY',
  'DATABASE_URL',
];

if (NODE_ENV === 'production') {
  const missing = requiredEnvVars.filter(v => !process.env[v]);
  if (missing.length > 0) {
    throw new Error(`Missing required environment variables: ${missing.join(', ')}`);
  }
}

// Example .env file
// NODE_ENV=production
// PORT=3000
// JWT_SECRET=your-secret-key-here
// ENCRYPTION_KEY=your-encryption-key
// DATABASE_URL=postgresql://user:pass@host/db

app.listen(PORT, () => {
  console.log(`Server running on port ${PORT} in ${NODE_ENV} mode`);
});
```

---

### 9. 🔴 HIGH: No Request Size Limits
**Severity:** HIGH (OWASP #01 - Injection, DoS attacks)

**Issue:**
- Large requests could cause memory exhaustion
- No protection against payload attacks

**Recommendations:**

```javascript
// Limit request sizes
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ limit: '10kb', extended: false }));

// Limit query string length
const queryParser = require('qs');
app.set('query parser', (str) => {
  if (str.length > 500) {
    throw new Error('Query string too long');
  }
  return queryParser.parse(str);
});
```

