## Secure Implementation Example

Here's a complete secure version of the application:

```javascript
require('dotenv').config();
const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const { query, validationResult } = require('express-validator');
const jwt = require('jsonwebtoken');
const winston = require('winston');

const app = express();

// ==================== CONFIGURATION ====================
const PORT = process.env.PORT || 3000;
const NODE_ENV = process.env.NODE_ENV || 'development';

// Validate environment variables
if (NODE_ENV === 'production') {
  const required = ['JWT_SECRET', 'ENCRYPTION_KEY'];
  const missing = required.filter(v => !process.env[v]);
  if (missing.length > 0) {
    throw new Error(`Missing env vars: ${missing.join(', ')}`);
  }
}

// ==================== LOGGING ====================
const logger = winston.createLogger({
  level: 'info',
  format: winston.format.json(),
  transports: [
    new winston.transports.File({ 
      filename: 'logs/error.log', 
      level: 'error' 
    }),
    new winston.transports.File({ filename: 'logs/combined.log' }),
  ],
});

if (NODE_ENV !== 'production') {
  logger.add(new winston.transports.Console({
    format: winston.format.simple(),
  }));
}

// ==================== SECURITY MIDDLEWARE ====================
// Security headers
app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      scriptSrc: ["'self'"],
    },
  },
  hsts: { maxAge: 31536000, includeSubDomains: true },
}));

// CORS
app.use(cors({
  origin: process.env.ALLOWED_ORIGINS?.split(',') || 'http://localhost:3000',
  credentials: true,
  methods: ['GET', 'POST'],
}));

// Request size limits
app.use(express.json({ limit: '10kb' }));

// Rate limiting
const generalLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 100,
  message: 'Too many requests',
});

const authLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 5,
  skipSuccessfulRequests: true,
});

app.use(generalLimiter);

// ==================== AUTHENTICATION ====================
const verifyToken = (req, res, next) => {
  const token = req.headers['authorization']?.split(' ')[1];

  if (!token) {
    logger.warn('Missing authentication token', { ip: req.ip });
    return res.status(401).json({ error: 'No token provided' });
  }

  try {
    const decoded = jwt.verify(token, process.env.JWT_SECRET);
    req.user = decoded;
    next();
  } catch (error) {
    logger.warn('Invalid token', { ip: req.ip, error: error.message });
    return res.status(403).json({ error: 'Invalid token' });
  }
};

// ==================== VALIDATION ====================
const validateUserQuery = [
  query('id')
    .optional()
    .isInt({ min: 1 })
    .withMessage('Invalid user ID'),
  query('limit')
    .optional()
    .isInt({ min: 1, max: 100 })
    .withMessage('Limit must be 1-100'),
];

const handleValidationErrors = (req, res, next) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    logger.warn('Validation failed', { 
      path: req.path, 
      errors: errors.array() 
    });
    return res.status(400).json({ errors: errors.array() });
  }
  next();
};

// ==================== ROUTES ====================
app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

app.get('/users', 
  verifyToken, 
  validateUserQuery, 
  handleValidationErrors, 
  (req, res) => {
    const users = [
      { id: 1, name: 'Alice', email: req.user?.role === 'admin' ? 'alice@example.com' : undefined },
      { id: 2, name: 'Bob', email: req.user?.role === 'admin' ? 'bob@example.com' : undefined },
    ];

    logger.info('Users accessed', { 
      userId: req.user.id, 
      ip: req.ip 
    });

    res.json(users);
  }
);

// ==================== ERROR HANDLING ====================
app.use((err, req, res, next) => {
  logger.error('Unhandled error', {
    message: err.message,
    path: req.path,
    ip: req.ip,
  });

  const status = err.statusCode || 500;
  const message = NODE_ENV === 'production' 
    ? 'Internal server error' 
    : err.message;

  res.status(status).json({ error: message });
});

// ==================== SERVER ====================
app.listen(PORT, () => {
  console.log(`Server running on port ${PORT} in ${NODE_ENV} mode`);
});

module.exports = app;
```

