The current implementation is not suitable for production use. It requires significant security hardening before deployment. Prioritize authentication, input validation, and security headers as the first steps. Implement monitoring and logging to detect future issues early.

/**
 * Secure Express Application Example
 * This is a hardened version of app.js addressing all identified vulnerabilities
 */

require('dotenv').config();
const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const { query, validationResult } = require('express-validator');
const jwt = require('jsonwebtoken');
const winston = require('winston');

const app = express();

// ==================== CONFIGURATION ====================
const PORT = process.env.PORT || 3000;
const NODE_ENV = process.env.NODE_ENV || 'development';

// Validate required environment variables in production
if (NODE_ENV === 'production') {
  const requiredEnvVars = ['JWT_SECRET', 'ENCRYPTION_KEY', 'DB_URL'];
  const missing = requiredEnvVars.filter(v => !process.env[v]);
  if (missing.length > 0) {
    throw new Error(`Missing required environment variables: ${missing.join(', ')}`);
  }
}

// ==================== LOGGING CONFIGURATION ====================
const logger = winston.createLogger({
  level: process.env.LOG_LEVEL || 'info',
  format: winston.format.combine(
    winston.format.timestamp(),
    winston.format.errors({ stack: true }),
    winston.format.json()
  ),
  defaultMeta: { service: 'secure-api' },
  transports: [
    new winston.transports.File({ 
      filename: 'logs/error.log', 
      level: 'error',
      maxsize: 5242880, // 5MB
      maxFiles: 5,
    }),
    new winston.transports.File({ 
      filename: 'logs/combined.log',
      maxsize: 5242880,
      maxFiles: 5,
    }),
  ],
});

if (NODE_ENV !== 'production') {
  logger.add(new winston.transports.Console({
    format: winston.format.combine(
      winston.format.colorize(),
      winston.format.simple()
    ),
  }));
}

// ==================== SECURITY MIDDLEWARE ====================

/**
 * Helmet: Sets various HTTP headers for security
 * - Content-Security-Policy: Prevent XSS
 * - X-Frame-Options: Prevent clickjacking
 * - X-Content-Type-Options: Prevent MIME sniffing
 * - Strict-Transport-Security: Enforce HTTPS
 */
app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      scriptSrc: ["'self'"],
      styleSrc: ["'self'", "'unsafe-inline'"],
      imgSrc: ["'self'", 'data:', 'https:'],
      connectSrc: ["'self'"],
      fontSrc: ["'self'"],
      objectSrc: ["'none'"],
      upgradeInsecureRequests: [],
    },
  },
  hsts: {
    maxAge: 31536000, // 1 year in seconds
    includeSubDomains: true,
    preload: true,
  },
  frameguard: { action: 'deny' },
  xssFilter: true,
  noSniff: true,
  referrerPolicy: { policy: 'no-referrer' },
}));

/**
 * CORS: Configure Cross-Origin Resource Sharing
 * Whitelist allowed origins to prevent unauthorized access
 */
const allowedOrigins = (process.env.ALLOWED_ORIGINS || 'http://localhost:3000').split(',');

app.use(cors({
  origin: (origin, callback) => {
    if (!origin || allowedOrigins.includes(origin)) {
      callback(null, true);
    } else {
      logger.warn('CORS request from unauthorized origin', { origin });
      callback(new Error('Not allowed by CORS'));
    }
  },
  credentials: true,
  methods: ['GET', 'POST', 'PUT', 'DELETE', 'OPTIONS'],
  allowedHeaders: ['Content-Type', 'Authorization'],
  exposedHeaders: ['X-Total-Count', 'X-Page-Number'],
  maxAge: 3600, // 1 hour
}));

/**
 * Request Size Limits: Prevent large payload attacks
 */
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ limit: '10kb', extended: false }));

/**
 * HTTPS Enforcement in Production
 */
app.use((req, res, next) => {
  if (NODE_ENV === 'production' && !req.secure && req.get('x-forwarded-proto') !== 'https') {
    logger.warn('Non-HTTPS request received', { ip: req.ip, path: req.path });
    return res.status(403).json({ error: 'HTTPS required' });
  }
  next();
});

// ==================== RATE LIMITING ====================

/**
 * General rate limiter: Protect all endpoints from abuse
 */
const generalLimiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: (req, res) => {
    // Allow admins more requests
    if (req.user?.role === 'admin') {
      return 1000;
    }
    return 100;
  },
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true, // Return rate limit info in RateLimit-* headers
  legacyHeaders: false, // Disable X-RateLimit-* headers
  keyGenerator: (req) => {
    // Use user ID if authenticated, otherwise use IP
    return req.user?.id || req.ip;
  },
  store: new (require('rate-limit-redis'))({
    client: require('redis').createClient(),
    prefix: 'rate-limit:',
  }),
  handler: (req, res) => {
    logger.warn('Rate limit exceeded', { 
      ip: req.ip, 
      userId: req.user?.id,
      path: req.path 
    });
    res.status(429).json({ 
      error: 'Too many requests',
      retryAfter: req.rateLimit.resetTime 
    });
  },
});

/**
 * Authentication rate limiter: Stricter limits on sensitive endpoints
 */
const authLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 5, // Only 5 attempts per 15 minutes
  skipSuccessfulRequests: true, // Don't count successful requests
  message: 'Too many login attempts. Please try again later.',
  skipFailedRequests: false,
});

app.use(generalLimiter);

// ==================== AUTHENTICATION ====================

/**
 * JWT Token Verification Middleware
 * Validates JWT tokens in Authorization header
 */
const verifyToken = (req, res, next) => {
  const authHeader = req.headers['authorization'];
  const token = authHeader?.split(' ')[1]; // Bearer <token>

  if (!token) {
    logger.warn('Missing authentication token', { 
      ip: req.ip,
      path: req.path,
      userAgent: req.get('user-agent'),
    });
    return res.status(401).json({ 
      error: 'No authentication token provided',
      code: 'MISSING_TOKEN',
    });
  }

  try {
    const decoded = jwt.verify(token, process.env.JWT_SECRET);
    req.user = decoded;
    logger.debug('Token verified', { userId: decoded.id });
    next();
  } catch (error) {
    logger.warn('Invalid authentication token', { 
      ip: req.ip,
      path: req.path,
      error: error.message,
    });

    const message = error.name === 'TokenExpiredError' 
      ? 'Token has expired' 
      : 'Invalid token';

    return res.status(403).json({ 
      error: message,
      code: 'INVALID_TOKEN',
    });
  }
};

/**
 * Authorization Middleware
 * Check if user has required role
 */
const authorize = (requiredRoles = []) => {
  return (req, res, next) => {
    if (!req.user) {
      return res.status(401).json({ error: 'Authentication required' });
    }

    if (requiredRoles.length > 0 && !requiredRoles.includes(req.user.role)) {
      logger.warn('Unauthorized access attempt', {
        userId: req.user.id,
        requiredRoles,
        userRole: req.user.role,
        path: req.path,
      });
      return res.status(403).json({ 
        error: 'Insufficient permissions',
        code: 'FORBIDDEN',
      });
    }

    next();
  };
};

// ==================== INPUT VALIDATION ====================

/**
 * Validation middleware for user queries
 * Validates and sanitizes all query parameters
 */
const validateUserQuery = [
  query('id')
    .optional()
    .isInt({ min: 1, max: 999999 })
    .withMessage('User ID must be a positive integer'),

  query('limit')
    .optional()
    .isInt({ min: 1, max: 100 })
    .withMessage('Limit must be between 1 and 100'),

  query('offset')
    .optional()
    .isInt({ min: 0 })
    .withMessage('Offset must be a non-negative integer'),

  query('search')
    .optional()
    .trim()
    .isLength({ min: 1, max: 100 })
    .withMessage('Search term must be 1-100 characters')
    .escape() // Sanitize to prevent XSS
    .withMessage('Search term contains invalid characters'),

  query('sortBy')
    .optional()
    .isIn(['id', 'name', 'email', 'createdAt'])
    .withMessage('Invalid sort field'),

  query('sortOrder')
    .optional()
    .isIn(['asc', 'desc'])
    .withMessage('Sort order must be asc or desc'),
];

/**
 * Handle validation errors
 */
const handleValidationErrors = (req, res, next) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    logger.warn('Validation failed', { 
      path: req.path,
      userId: req.user?.id,
      errors: errors.array(),
    });

    return res.status(400).json({ 
      error: 'Validation failed',
      details: errors.array(),
      code: 'VALIDATION_ERROR',
    });
  }
  next();
};

// ==================== AUDIT LOGGING ====================

/**
 * Audit logging middleware
 * Logs all API requests for security auditing
 */
const auditLog = (req, res, next) => {
  const startTime = Date.now();

  // Capture response details
  const originalJson = res.json.bind(res);
  res.json = function(data) {
    const duration = Date.now() - startTime;

    logger.info('API Request', {
      method: req.method,
      path: req.path,
      query: sanitizeQuery(req.query),
      userId: req.user?.id,
      userRole: req.user?.role,
      ip: req.ip,
      statusCode: res.statusCode,
      duration: `${duration}ms`,
      userAgent: req.get('user-agent'),
      timestamp: new Date().toISOString(),
    });

    return originalJson(data);
  };

  next();
};

/**
 * Sanitize sensitive data from logs
 */
const sanitizeQuery = (query) => {
  const sanitized = { ...query };
  const sensitiveFields = ['password', 'token', 'apiKey', 'secret'];

  sensitiveFields.forEach(field => {
    if (sanitized[field]) {
      sanitized[field] = '***REDACTED***';
    }
  });

  return sanitized;
};

app.use(auditLog);

// ==================== ROUTES ====================

/**
 * Health Check Endpoint
 * No authentication required for monitoring/load balancers
 */
app.get('/health', (req, res) => {
  res.json({ 
    status: 'ok',
    timestamp: new Date().toISOString(),
    environment: NODE_ENV,
  });
});

/**
 * Get Users Endpoint
 * Requires authentication
 * Demonstrates proper input validation and authorization
 */
app.get('/users',
  verifyToken,
  validateUserQuery,
  handleValidationErrors,
  (req, res) => {
    try {
      const { id, search, limit = 10, offset = 0 } = req.query;

      // Mock database
      let users = [
        { id: 1, name: 'Alice', email: 'alice@example.com', role: 'admin', createdAt: '2024-01-01' },
        { id: 2, name: 'Bob', email: 'bob@example.com', role: 'user', createdAt: '2024-01-02' },
      ];

      // Filter by ID if provided
      if (id) {
        users = users.filter(u => u.id === parseInt(id));
      }

      // Filter by search if provided
      if (search) {
        users = users.filter(u =>
          u.name.toLowerCase().includes(search.toLowerCase()) ||
          u.email.toLowerCase().includes(search.toLowerCase())
        );
      }

      // Apply field-level access control
      // Non-admin users cannot see other users' emails
      if (req.user.role !== 'admin') {
        users = users.map(u => ({
          id: u.id,
          name: u.name,
          role: u.role,
          createdAt: u.createdAt,
          // email is excluded for non-admins
        }));
      }

      // Apply pagination
      const total = users.length;
      users = users.slice(offset, offset + limit);

      res.set('X-Total-Count', total.toString());
      res.set('X-Page-Number', Math.floor(offset / limit).toString());

      res.json({
        data: users,
        pagination: {
          total,
          limit,
          offset,
          pages: Math.ceil(total / limit),
        },
      });

    } catch (error) {
      logger.error('Error in /users endpoint', {
        error: error.message,
        stack: error.stack,
        userId: req.user?.id,
      });

      res.status(500).json({ 
        error: 'Failed to retrieve users',
        code: 'INTERNAL_ERROR',
      });
    }
  }
);

/**
 * Get User by ID Endpoint
 * More restricted - requires admin role
 */
app.get('/users/:id',
  verifyToken,
  authorize(['admin']),
  (req, res) => {
    try {
      const userId = parseInt(req.params.id);

      if (isNaN(userId)) {
        return res.status(400).json({ 
          error: 'Invalid user ID',
          code: 'INVALID_ID',
        });
      }

      // Mock database
      const user = { 
        id: userId, 
        name: 'Alice', 
        email: 'alice@example.com',
        role: 'admin',
        createdAt: '2024-01-01',
      };

      if (!user) {
        return res.status(404).json({ 
          error: 'User not found',
          code: 'NOT_FOUND',
        });
      }

      res.json(user);

    } catch (error) {
      logger.error('Error fetching user', { error: error.message });
      res.status(500).json({ 
        error: 'Failed to retrieve user',
        code: 'INTERNAL_ERROR',
      });
    }
  }
);

// ==================== ERROR HANDLING ====================

/**
 * Custom error class
 */
class AppError extends Error {
  constructor(message, statusCode, code = 'INTERNAL_ERROR') {
    super(message);
    this.statusCode = statusCode;
    this.code = code;
    Error.captureStackTrace(this, this.constructor);
  }
}

/**
 * 404 Handler
 */
app.use((req, res, next) => {
  const error = new AppError('Not Found', 404, 'NOT_FOUND');
  next(error);
});

/**
 * Global Error Handler
 * Catches all errors and returns appropriate responses
 */
app.use((err, req, res, next) => {
  const statusCode = err.statusCode || 500;
  let message = err.message || 'Internal Server Error';
  const code = err.code || 'INTERNAL_ERROR';

  // Don't expose stack traces in production
  const isProduction = NODE_ENV === 'production';

  logger.error('Unhandled Error', {
    error: message,
    stack: err.stack,
    path: req.path,
    method: req.method,
    userId: req.user?.id,
    statusCode,
    code,
    timestamp: new Date().toISOString(),
  });

  // Sanitize error message for production
  if (isProduction && statusCode === 500) {
    message = 'Internal server error';
  }

  const response = {
    error: message,
    code,
    ...(process.env.DEBUG === 'true' && { stack: err.stack }),
  };

  res.status(statusCode).json(response);
});

// ==================== SERVER STARTUP ====================

const server = app.listen(PORT, () => {
  logger.info(`Server started`, {
    port: PORT,
    environment: NODE_ENV,
    nodeVersion: process.version,
    timestamp: new Date().toISOString(),
  });
});

/**
 * Graceful Shutdown
 */
process.on('SIGTERM', () => {
  logger.info('SIGTERM received, shutting down gracefully');

  server.close(() => {
    logger.info('Server closed');
    process.exit(0);
  });

  // Force shutdown after 30 seconds
  setTimeout(() => {
    logger.error('Forced shutdown after 30 seconds');
    process.exit(1);
  }, 30000);
});

// ==================== UNHANDLED EXCEPTION HANDLER ====================

process.on('uncaughtException', (error) => {
  logger.error('Uncaught Exception', {
    message: error.message,
    stack: error.stack,
  });
  process.exit(1);
});

process.on('unhandledRejection', (reason, promise) => {
  logger.error('Unhandled Rejection', {
    reason,
    promise: promise.toString(),
  });
});

module.exports = app;

