## Option 1: AWS Secrets Manager (Recommended)

### Simple Implementation (< 100 lines)

```javascript
// secrets-manager.js
const { SecretsManagerClient, GetSecretValueCommand } = require("@aws-sdk/client-secrets-manager");
const logger = require('./logger');

/**
 * Simple AWS Secrets Manager wrapper with caching
 */
class SecretsManager {
  constructor(options = {}) {
    this.client = new SecretsManagerClient({
      region: options.region || process.env.AWS_REGION || 'us-east-1'
    });

    this.cache = new Map();
    this.cacheTTL = (options.cacheTTLMinutes || 60) * 60 * 1000;
    this.fetchTimeouts = new Map();
  }

  /**
   * Get secret with caching
   */
  async getSecret(secretName) {
    // Return from cache if valid
    const cached = this.cache.get(secretName);
    if (cached && Date.now() < cached.expiry) {
      logger.debug(`Using cached secret: ${secretName}`);
      return cached.value;
    }

    // Fetch from AWS
    logger.info(`Fetching secret from AWS: ${secretName}`);

    try {
      const command = new GetSecretValueCommand({
        SecretId: secretName,
        VersionStage: 'AWSCURRENT'
      });

      const response = await this.client.send(command);

      let secretValue;
      if ('SecretString' in response) {
        secretValue = response.SecretString;

        // Try to parse as JSON
        try {
          secretValue = JSON.parse(secretValue);
        } catch (e) {
          // Keep as string if not JSON
        }
      } else if ('SecretBinary' in response) {
        secretValue = Buffer.from(response.SecretBinary, 'base64').toString('ascii');
      }

      // Cache the secret
      this.cache.set(secretName, {
        value: secretValue,
        expiry: Date.now() + this.cacheTTL
      });

      logger.info(`Successfully cached secret: ${secretName}`);
      return secretValue;

    } catch (error) {
      logger.error(`Failed to fetch secret ${secretName}:`, error);

      // Return cached value even if expired (graceful degradation)
      if (cached) {
        logger.warn(`Using expired cached secret as fallback: ${secretName}`);
        return cached.value;
      }

      throw new Error(`Failed to retrieve secret: ${secretName}`);
    }
  }

  /**
   * Get multiple secrets efficiently
   */
  async getSecrets(secretNames) {
    const secrets = await Promise.all(
      secretNames.map(name => this.getSecret(name))
    );

    return secretNames.reduce((obj, name, index) => {
      obj[name] = secrets[index];
      return obj;
    }, {});
  }

  /**
   * Invalidate cache (for testing or manual rotation)
   */
  invalidate(secretName) {
    this.cache.delete(secretName);
    logger.info(`Invalidated cache for: ${secretName}`);
  }

  /**
   * Clear all cache
   */
  clearCache() {
    this.cache.clear();
    logger.info('Cleared all secrets cache');
  }
}

module.exports = SecretsManager;
```

### Usage in Application

```javascript
// app.js with AWS Secrets Manager

const express = require('express');
const SecretsManager = require('./secrets-manager');
const logger = require('./logger');

const app = express();
const secretsManager = new SecretsManager({
  region: 'us-east-1',
  cacheTTLMinutes: 60
});

/**
 * Initialize app with secrets
 */
async function initializeApp() {
  try {
    logger.info('Initializing application...');

    // Define secrets to fetch
    const secretNames = [
      'prod/app/jwt-secret',
      'prod/app/db-url',
      'prod/app/encryption-key',
      'prod/app/redis-url',
      'prod/app/sentry-dsn'
    ];

    // Fetch all secrets concurrently
    const secrets = await secretsManager.getSecrets(secretNames);

    // Store in global config (accessible via middleware)
    global.appSecrets = {
      jwtSecret: secrets['prod/app/jwt-secret'],
      dbUrl: secrets['prod/app/db-url'],
      encryptionKey: secrets['prod/app/encryption-key'],
      redisUrl: secrets['prod/app/redis-url'],
      sentryDsn: secrets['prod/app/sentry-dsn']
    };

    // Verify all critical secrets loaded
    const requiredSecrets = ['jwtSecret', 'dbUrl', 'encryptionKey'];
    for (const secret of requiredSecrets) {
      if (!global.appSecrets[secret]) {
        throw new Error(`Missing critical secret: ${secret}`);
      }
    }

    logger.info('✅ Application initialized with secrets from AWS');

  } catch (error) {
    logger.error('❌ Failed to initialize application:', error);
    process.exit(1);
  }
}

// Routes
app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

app.get('/users', (req, res) => {
  // Use secrets from global config
  // jwt.verify(token, global.appSecrets.jwtSecret);
  res.json([
    { id: 1, name: 'Alice' },
    { id: 2, name: 'Bob' }
  ]);
});

// Startup
async function start() {
  try {
    await initializeApp();

    const PORT = process.env.PORT || 3000;
    app.listen(PORT, () => {
      logger.info(`✅ Server running on port ${PORT}`);
    });

  } catch (error) {
    logger.error('Failed to start application:', error);
    process.exit(1);
  }
}

// Only start if not in test mode
if (require.main === module) {
