// vault-secrets.js

const vault = require('node-vault')({
  endpoint: process.env.VAULT_ADDR || 'http://localhost:8200',
  token: process.env.VAULT_TOKEN
});

/**
 * Fetch secrets from Vault
 */
async function getSecretsFromVault() {
  try {
    // Read static secrets
    const appSecrets = await vault.read('secret/data/app');
    return appSecrets.data.data;

  } catch (error) {
    console.error('Failed to read secrets from Vault:', error);
    throw error;
  }
}

/**
 * Get database credentials (dynamic)
 */
async function getDatabaseCredentials() {
  try {
    const response = await vault.read('database/creds/readonly');
    return {
      username: response.data.username,
      password: response.data.password,
      ttl: response.lease_duration
    };

  } catch (error) {
    console.error('Failed to get database credentials:', error);
    throw error;
  }
}

