    expect(sanitized.JWT_SECRET).toBe('***REDACTED***');
    expect(sanitized.normal_field).toBe('normal-value');
  });
});

// Helper function to sanitize logging
function sanitizeForLogging(obj) {
  const sensitive = ['SECRET', 'PASSWORD', 'KEY', 'TOKEN', 'API_KEY'];

  return Object.entries(obj).reduce((acc, [key, value]) => {
    if (sensitive.some(s => key.toUpperCase().includes(s))) {
      acc[key] = '***REDACTED***';
    } else {
      acc[key] = value;
    }
    return acc;
  }, {});
}
