# Security Review of app.js

## Executive Summary
This application has **CRITICAL** security vulnerabilities across multiple OWASP Top 10 categories. The application lacks fundamental security controls including authentication, authorization, input validation, rate limiting, and proper error handling. Below are detailed findings and recommendations.

---

## 1. CRITICAL: Missing Authentication & Authorization

### Issue
- **Severity**: CRITICAL
- **OWASP**: A07:2021 – Identification and Authentication Failures, A01:2021 – Broken Access Control
- **Description**: The `/users` endpoint exposes sensitive user data (names and emails) without any authentication mechanism.

### Current Code
```javascript
app.get('/users', (req, res) => {
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ]);
});
```

### Risks
- Any unauthenticated user can access user data
- No ability to control who sees what data
- Violates privacy regulations (GDPR, CCPA, etc.)

### Recommendation
Implement JWT-based authentication with proper middleware:

```javascript
const express = require('express');
const jwt = require('jsonwebtoken');
const app = express();

// Secret key should be stored in environment variables
const SECRET_KEY = process.env.JWT_SECRET || 'your-secret-key';

// Authentication middleware
const authenticateToken = (req, res, next) => {
  const authHeader = req.headers['authorization'];
  const token = authHeader && authHeader.split(' ')[1]; // Bearer TOKEN

  if (!token) {
    return res.status(401).json({ error: 'Access token required' });
  }

  jwt.verify(token, SECRET_KEY, (err, user) => {
    if (err) {
      return res.status(403).json({ error: 'Invalid or expired token' });
    }
    req.user = user;
    next();
  });
};

// Protected endpoint with authentication
app.get('/users', authenticateToken, (req, res) => {
  // Additional authorization check
  if (req.user.role !== 'admin') {
    return res.status(403).json({ error: 'Insufficient permissions' });
  }

  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ]);
});

// Login endpoint to obtain token
app.post('/login', express.json(), (req, res) => {
  // TODO: Verify credentials against database
  const user = { id: 1, username: 'admin', role: 'admin' };
  const token = jwt.sign(user, SECRET_KEY, { expiresIn: '1h' });
  res.json({ token });
});
```

---

## 2. HIGH: Missing Input Validation

### Issue
- **Severity**: HIGH
- **OWASP**: A03:2021 – Injection
- **Description**: No validation of query parameters, headers, or body data. Attackers could send malicious input.

### Current Code
The app doesn't validate any incoming data.

### Risks
- SQL Injection (if database queries are added)
- NoSQL Injection
- XSS attacks
- Command injection
- Denial of Service

### Recommendation
Add comprehensive input validation:

```javascript
const express = require('express');
const { body, query, validationResult } = require('express-validator');
const app = express();

app.use(express.json({ limit: '10mb' })); // Limit payload size

// Validation middleware
const validateInput = (req, res, next) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({ errors: errors.array() });
  }
  next();
};

// Protected endpoint with input validation
app.get('/users', 
  query('page').optional().isInt({ min: 1, max: 1000 }),
  query('limit').optional().isInt({ min: 1, max: 100 }),
  validateInput,
  (req, res) => {
    const page = req.query.page || 1;
    const limit = req.query.limit || 10;

    // Use validated parameters safely
    res.json([
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ]);
  }
);

// POST endpoint with body validation
app.post('/users',
  body('name').isString().trim().isLength({ min: 1, max: 100 }),
  body('email').isEmail().normalizeEmail(),
  validateInput,
  (req, res) => {
    // Process validated data
    res.status(201).json({ message: 'User created' });
  }
);
```

---

## 3. HIGH: Sensitive Data Exposure

### Issue
- **Severity**: HIGH
- **OWASP**: A02:2021 – Cryptographic Failures, A04:2021 – Insecure Design
- **Description**: Exposing email addresses and user information without encryption or access controls.

### Risks
- Privacy violations
- Information used for targeted phishing/attacks
- GDPR/CCPA compliance violations

### Recommendation
Implement data encryption and masking:

```javascript
// Sensitive data handling
const crypto = require('crypto');

// Mask email for non-privileged users
function maskEmail(email) {
  if (!email) return email;
  const [name, domain] = email.split('@');
  const masked = name.substring(0, 2) + '*'.repeat(name.length - 2) + '@' + domain;
  return masked;
}

// Encrypt sensitive data at rest (example)
function encryptData(data, encryptionKey) {
  const iv = crypto.randomBytes(16);
  const cipher = crypto.createCipheriv('aes-256-cbc', Buffer.from(encryptionKey), iv);
  let encrypted = cipher.update(data);
  encrypted = Buffer.concat([encrypted, cipher.final()]);
  return iv.toString('hex') + ':' + encrypted.toString('hex');
}

app.get('/users', authenticateToken, (req, res) => {
  if (req.user.role !== 'admin') {
    // Non-admin users see masked emails
    return res.json([
      { id: 1, name: 'Alice', email: maskEmail('alice@example.com') },
      { id: 2, name: 'Bob', email: maskEmail('bob@example.com') },
    ]);
  }

  // Admin users see full data
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ]);
});
```

---

## 4. HIGH: Missing Security Headers

### Issue
- **Severity**: HIGH
- **OWASP**: A05:2021 – Security Misconfiguration
- **Description**: No security headers to protect against common attacks (XSS, Clickjacking, etc.)

### Current Code
No security headers are set.

### Risks
- Clickjacking attacks
- XSS attacks
- MIME sniffing
- Insecure transport

### Recommendation
Add security headers using helmet middleware:

```javascript
const express = require('express');
const helmet = require('helmet');
const app = express();

// Apply helmet middleware for security headers
app.use(helmet());

// Additional custom security headers
app.use((req, res, next) => {
  // Prevent MIME sniffing
  res.setHeader('X-Content-Type-Options', 'nosniff');

  // Enable XSS protection
  res.setHeader('X-XSS-Protection', '1; mode=block');

  // Prevent clickjacking
  res.setHeader('X-Frame-Options', 'DENY');

  // Content Security Policy
  res.setHeader('Content-Security-Policy', 
    "default-src 'self'; script-src 'self' 'unsafe-inline'; style-src 'self' 'unsafe-inline'");

  // Referrer Policy
  res.setHeader('Referrer-Policy', 'strict-origin-when-cross-origin');

  // Feature Policy
  res.setHeader('Permissions-Policy', 'geolocation=(), microphone=(), camera=()');

  next();
});

app.listen(3000, () => {
  console.log('Server running on port 3000');
});
```

---

## 5. HIGH: No Rate Limiting

### Issue
- **Severity**: HIGH
- **OWASP**: A04:2021 – Insecure Design
- **Description**: No protection against brute force attacks, DoS, or credential stuffing.

### Risks
- Denial of Service attacks
- Brute force password cracking
- API abuse
- Resource exhaustion

### Recommendation
Implement rate limiting:

```javascript
const express = require('express');
const rateLimit = require('express-rate-limit');
const RedisStore = require('rate-limit-redis');
const redis = require('redis');
const app = express();

// Connect to Redis (or use in-memory store for development)
const redisClient = redis.createClient();

// General rate limiter
const generalLimiter = rateLimit({
  store: new RedisStore({
    client: redisClient,
    prefix: 'rl:general:',
  }),
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true, // Return rate limit info in the `RateLimit-*` headers
  legacyHeaders: false,
});

// Stricter limiter for login attempts
const loginLimiter = rateLimit({
  store: new RedisStore({
    client: redisClient,
    prefix: 'rl:login:',
  }),
  windowMs: 15 * 60 * 1000,
  max: 5, // Limit to 5 login attempts
  skipSuccessfulRequests: true, // Don't count successful requests
  message: 'Too many login attempts, please try again after 15 minutes.',
});

// Apply general rate limiter to all routes
app.use(generalLimiter);

app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

// Apply stricter rate limiter to login
app.post('/login', loginLimiter, express.json(), (req, res) => {
  // Login logic here
  res.json({ token: 'token_here' });
});

app.listen(3000, () => {
  console.log('Server running on port 3000');
});
```

---

## 6. MEDIUM: No Error Handling & Information Disclosure

### Issue
- **Severity**: MEDIUM
- **OWASP**: A01:2021 – Broken Access Control, A05:2021 – Security Misconfiguration
- **Description**: No global error handler; unhandled exceptions could leak sensitive information.

### Risks
- Stack traces exposing system information
- Unhandled errors crashing the application
- Information disclosure through error messages

### Recommendation
Implement comprehensive error handling:

```javascript
const express = require('express');
const app = express();

app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

app.get('/users', (req, res) => {
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ]);
});

// 404 handler
app.use((req, res) => {
  res.status(404).json({ 
    error: 'Endpoint not found',
    path: req.path 
  });
});

// Global error handler (MUST be last)
app.use((err, req, res, next) => {
  // Log error securely (without sensitive data)
  console.error('Error:', {
    message: err.message,
    path: req.path,
    method: req.method,
    ip: req.ip,
    timestamp: new Date().toISOString(),
  });

  // Determine status code
  const statusCode = err.statusCode || 500;

  // Don't expose stack traces in production
  if (process.env.NODE_ENV === 'production') {
    return res.status(statusCode).json({
      error: 'An error occurred processing your request',
      requestId: req.id, // Useful for support
    });
  }

  // In development, include more details
  res.status(statusCode).json({
    error: err.message,
    ...(process.env.NODE_ENV !== 'production' && { stack: err.stack }),
  });
});

app.listen(3000, () => {
  console.log('Server running on port 3000');
});
```

