## 9. MEDIUM: Missing Logging & Monitoring

### Issue
- **Severity**: MEDIUM
- **OWASP**: A09:2021 – Security Logging and Monitoring Failures
- **Description**: No security logging for authentication, authorization, or suspicious activities.

### Risks
- Cannot detect attacks
- Cannot audit user actions
- Compliance violations (SOC 2, HIPAA, etc.)

### Recommendation
Implement security logging:

```javascript
const express = require('express');
const winston = require('winston');
const app = express();

// Configure security logger
const securityLogger = winston.createLogger({
  level: 'info',
  format: winston.format.json(),
  transports: [
    new winston.transports.File({ 
      filename: 'logs/security.log',
      level: 'warn'
    }),
    new winston.transports.File({ 
      filename: 'logs/combined.log' 
    })
  ],
});

// Log security events middleware
app.use((req, res, next) => {
  const originalSend = res.send;

  res.send = function(data) {
    // Log authentication failures
    if (res.statusCode === 401 || res.statusCode === 403) {
      securityLogger.warn({
        event: 'authentication_failure',
        ip: req.ip,
        path: req.path,
        method: req.method,
        statusCode: res.statusCode,
        timestamp: new Date().toISOString(),
      });
    }

    res.send = originalSend;
    return res.send(data);
  };

  next();
});

// Log successful authentication
app.post('/login', express.json(), (req, res) => {
  // Assume login logic here
  securityLogger.info({
    event: 'user_login',
    userId: 'user123',
    ip: req.ip,
    timestamp: new Date().toISOString(),
  });

  res.json({ token: 'token_here' });
});

app.listen(3000, () => {
  console.log('Server running on port 3000');
});
```

