      health.checks.database = 'error';
    }

    // Check cache
    try {
      // await redis.ping();
      health.checks.cache = 'ok';
    } catch (err) {
      health.status = 'degraded';
      health.checks.cache = 'error';
    }

    const statusCode = health.status === 'ok' ? 200 : 503;
    res.status(statusCode).json(health);
  } catch (err) {
    res.status(500).json({ 
      status: 'error',
      message: 'Health check failed'
    });
  }
});
