require('dotenv').config({ override: false }); // Only use .env if exists
const express = require('express');
const AWS = require('aws-sdk');

const app = express();
const NODE_ENV = process.env.NODE_ENV || 'development';

// ============================================================================
// SECURITY: Secrets Management
// ============================================================================

let secrets = {};

async function initializeSecrets() {
  if (NODE_ENV === 'production' || NODE_ENV === 'staging') {
    // Load from AWS Secrets Manager in production
    await loadFromSecretsManager();
  } else {
    // Load from .env in development only
    loadFromEnvironment();
  }

  // Validate all required secrets are present
  validateSecrets();
}

async function loadFromSecretsManager() {
  try {
    const secretsManager = new AWS.SecretsManager({
      region: process.env.AWS_REGION || 'us-east-1'
    });

    const secretName = process.env.SECRETS_NAME || `app-${NODE_ENV}`;

    const data = await secretsManager.getSecretValue({
      SecretId: secretName
    }).promise();

    if (data.SecretString) {
      secrets = JSON.parse(data.SecretString);
      console.log('✅ Secrets loaded from AWS Secrets Manager');
    } else if (data.SecretBinary) {
      secrets = JSON.parse(Buffer.from(data.SecretBinary, 'base64').toString('utf8'));
    }
  } catch (error) {
    console.error('❌ FATAL: Failed to load secrets from AWS Secrets Manager');
    console.error('Error:', error.message);
    process.exit(1);
  }
}

function loadFromEnvironment() {
  try {
    secrets = {
      JWT_SECRET: process.env.JWT_SECRET,
      DB_HOST: process.env.DB_HOST,
      DB_PORT: process.env.DB_PORT,
      DB_NAME: process.env.DB_NAME,
      DB_USER: process.env.DB_USER,
      DB_PASSWORD: process.env.DB_PASSWORD,
      // Add other secrets as needed
    };
    console.log('⚠️  Secrets loaded from environment variables (development only)');
  } catch (error) {
    console.error('❌ Failed to load environment variables');
    process.exit(1);
  }
}

function validateSecrets() {
  const required = [
    'JWT_SECRET',
    'DB_PASSWORD',
    'DB_USER'
  ];

  const missing = required.filter(key => !secrets[key]);

  if (missing.length > 0) {
    console.error(`❌ FATAL: Missing required secrets: ${missing.join(', ')}`);
    process.exit(1);
  }

  if (NODE_ENV === 'production' && secrets.JWT_SECRET.includes('your-super-secret')) {
    console.error('❌ FATAL: Using placeholder secrets in production!');
    process.exit(1);
  }

  console.log('✅ All required secrets validated');
}

function getSecret(key) {
  if (!secrets[key]) {
    console.error(`❌ Secret not found: ${key}`);
    throw new Error(`Missing secret: ${key}`);
  }
  return secrets[key];
}

// Export functions
module.exports = {
  initializeSecrets,
  getSecret,
  secrets: () => secrets // For testing only
};
