/**
 * SECURE APPLICATION EXAMPLE
 * This is a hardened version addressing all identified security vulnerabilities
 */

const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const jwt = require('jsonwebtoken');
const mongoSanitize = require('express-mongo-sanitize');
const morgan = require('morgan');
const { body, query, validationResult, param } = require('express-validator');

require('dotenv').config();

const app = express();

// ============ CONFIGURATION ============
const JWT_SECRET = process.env.JWT_SECRET || 'change-this-in-production';
const NODE_ENV = process.env.NODE_ENV || 'development';
const PORT = process.env.PORT || 3000;

// ============ SECURITY MIDDLEWARE ============

/**
 * 1. Set comprehensive security HTTP headers
 * Addresses: Missing Security Headers vulnerability
 */
app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      scriptSrc: ["'self'"],
      styleSrc: ["'self'", "'unsafe-inline'"],
      imgSrc: ["'self'", 'data:', 'https:'],
      connectSrc: ["'self'"],
      fontSrc: ["'self'"],
      objectSrc: ["'none'"],
      frameSrc: ["'none'"],
    },
  },
  hsts: {
    maxAge: 31536000, // 1 year in seconds
    includeSubDomains: true,
    preload: true,
  },
}));

/**
 * 2. CORS configuration with explicit origin whitelist
 * Addresses: No CORS Configuration vulnerability
 */
const corsOptions = {
  origin: (origin, callback) => {
    const allowedOrigins = process.env.ALLOWED_ORIGINS 
      ? process.env.ALLOWED_ORIGINS.split(',') 
      : ['http://localhost:3000'];

    // Allow requests with no origin (mobile apps, Postman, curl requests)
    if (!origin || allowedOrigins.includes(origin)) {
      callback(null, true);
    } else {
      callback(new Error('Not allowed by CORS'));
    }
  },
  credentials: true,
  methods: ['GET', 'POST', 'PUT', 'DELETE', 'OPTIONS'],
  allowedHeaders: ['Content-Type', 'Authorization'],
  maxAge: 3600, // Preflight cache
  optionsSuccessStatus: 200,
};
app.use(cors(corsOptions));

/**
 * 3. Enforce HTTPS in production
 * Addresses: Missing HTTPS Enforcement vulnerability
 */
if (NODE_ENV === 'production') {
  app.use((req, res, next) => {
    // Check if behind proxy (common in production)
    if (req.header('x-forwarded-proto') !== 'https') {
      return res.redirect(`https://${req.header('host')}${req.url}`);
    }
    next();
  });
}

/**
 * 4. Body parsing with size limits
 * Addresses: No Input Size Limits vulnerability
 */
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ limit: '10kb', extended: true }));

/**
 * 5. Sanitize against NoSQL/MongoDB injection
 * Addresses: Unvalidated User-Generated Input vulnerability
 */
app.use(mongoSanitize());

/**
 * 6. Request logging
 * Addresses: No Logging & Monitoring vulnerability
 */
app.use(morgan('combined'));

/**
 * 7. Rate limiting - general
 * Addresses: No Rate Limiting / Brute Force Protection vulnerability
 */
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Requests per window
  message: 'Too many requests from this IP',
  standardHeaders: true,
  legacyHeaders: false,
  skip: (req) => req.path === '/health', // Don't rate limit health check
});

/**
 * 8. Stricter rate limiting for authentication endpoints
 * Addresses: Brute Force Protection
 */
const authLimiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 5, // Only 5 login attempts
  skipSuccessfulRequests: true,
  message: 'Too many login attempts. Try again later.',
});

app.use('/api/', limiter);

// ============ AUTHENTICATION MIDDLEWARE ============

/**
 * JWT Authentication Middleware
 * Addresses: Missing Authentication & Authorization vulnerability
 */
const authenticateToken = (req, res, next) => {
  const authHeader = req.headers['authorization'];
  const token = authHeader && authHeader.split(' ')[1];

  if (!token) {
    return res.status(401).json({ 
      error: 'Authentication required',
      code: 'NO_TOKEN' 
    });
  }

  jwt.verify(token, JWT_SECRET, (err, user) => {
    if (err) {
      // Log suspicious activity
      console.warn(`[SECURITY] Invalid token attempt from ${req.ip}`);
      return res.status(403).json({ 
        error: 'Invalid or expired token',
        code: 'INVALID_TOKEN' 
      });
    }
    req.user = user;
    next();
  });
};

/**
 * Authorization middleware - role-based access control
 * Addresses: Broken Access Control vulnerability
 */
const authorizeRole = (allowedRoles) => {
  return (req, res, next) => {
    if (!req.user || !allowedRoles.includes(req.user.role)) {
      console.warn(`[SECURITY] Unauthorized access attempt: ${req.user?.id} tried to access ${req.path}`);
      return res.status(403).json({ 
        error: 'Insufficient permissions',
        code: 'FORBIDDEN' 
      });
    }
    next();
  };
};

// ============ PUBLIC ROUTES ============

/**
