app.get('/api/users', 
  authenticateToken,
  query('role')
    .optional()
    .isIn(['user', 'admin'])
    .withMessage('Invalid role filter'),
  (req, res) => {
    // Validate query parameters
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({ 
        error: 'Validation failed',
        details: errors.array() 
      });
    }

    // Mock user data
    let users = [
      { id: 1, name: 'Alice', email: 'alice@example.com', role: 'admin' },
      { id: 2, name: 'Bob', email: 'bob@example.com', role: 'user' },
    ];

    // Filter data based on user's role
    // Address: Sensitive Data Exposure vulnerability
    if (req.user.role !== 'admin') {
      // Regular users don't see email addresses or role
      users = users.map(({ email, role, ...rest }) => rest);
    }

    // Apply role filter if requested
    const roleFilter = req.query.role;
    if (roleFilter) {
      users = users.filter(u => u.role === roleFilter);
    }

    res.json(users);
  }
);

/**
 * Get user by ID
 * Addresses: Broken Access Control, Input Validation
 */
app.get('/api/users/:id',
  authenticateToken,
  param('id')
    .isInt({ min: 1 })
    .withMessage('Invalid user ID'),
  (req, res) => {
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({ 
        error: 'Validation failed',
        details: errors.array() 
      });
    }

    const userId = parseInt(req.params.id);

    // Access control: users can only view their own profile, admins can view all
    if (req.user.id !== userId && req.user.role !== 'admin') {
      console.warn(`[SECURITY] Unauthorized access to user ${userId} by user ${req.user.id}`);
      return res.status(403).json({ 
        error: 'Cannot access this user\'s data',
        code: 'FORBIDDEN' 
      });
    }

    // Mock data
    const user = { id: userId, name: 'Alice', email: 'alice@example.com', role: 'user' };

    // Admins see all data, users see limited data
    if (req.user.role !== 'admin' && req.user.id === userId) {
      // Users can see their own email
      return res.json(user);
    } else if (req.user.role === 'admin') {
      return res.json(user);
    }

    res.status(404).json({ error: 'User not found' });
  }
);

/**
 * Create user (admin only)
 * Addresses: Broken Access Control, Input Validation
 */
app.post('/api/users',
  authenticateToken,
  authorizeRole(['admin']),
  body('name')
    .trim()
    .isLength({ min: 1, max: 100 })
