 * Addresses: Broken Access Control, Input Validation
 */
app.put('/api/users/:id',
  authenticateToken,
  param('id')
    .isInt({ min: 1 })
    .withMessage('Invalid user ID'),
  body('name')
    .optional()
    .trim()
    .isLength({ min: 1, max: 100 })
    .withMessage('Name must be 1-100 characters'),
  (req, res) => {
