 * Addresses: Broken Access Control
 */
app.delete('/api/users/:id',
  authenticateToken,
  authorizeRole(['admin']),
  param('id')
    .isInt({ min: 1 })
    .withMessage('Invalid user ID'),
  (req, res) => {
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({ 
        error: 'Validation failed',
        details: errors.array() 
      });
    }

    const userId = parseInt(req.params.id);
    console.warn(`[SECURITY] User ${userId} deleted by admin ${req.user.id}`);

    res.json({ message: 'User deleted successfully', id: userId });
  }
);

// ============ ERROR HANDLING ============

/**
 * 404 handler
 * Addresses: Missing Error Handling vulnerability
 */
app.use((req, res) => {
  res.status(404).json({ 
    error: 'Endpoint not found',
    path: req.path,
    method: req.method 
  });
});

/**
 * Global error handler
 * Addresses: Missing Error Handling & Information Disclosure vulnerabilities
 */
app.use((err, req, res, next) => {
  // Log error server-side
  console.error('[ERROR]', {
    message: err.message,
    status: err.status || 500,
    path: req.path,
    method: req.method,
    ip: req.ip,
    timestamp: new Date().toISOString(),
    ...(NODE_ENV === 'development' && { stack: err.stack }),
  });

  // Determine status code
  const statusCode = err.status || 500;

  // Send safe error response (don't expose stack traces in production)
  res.status(statusCode).json({
    error: {
      message: NODE_ENV === 'development' 
        ? err.message 
        : 'Internal Server Error',
      code: err.code || 'INTERNAL_ERROR',
      ...(NODE_ENV === 'development' && { stack: err.stack }),
    },
  });
});

// ============ SERVER STARTUP ============

const server = app.listen(PORT, () => {
