## Secure Secrets Architecture

### Pattern 1: Secrets Manager with Caching

```javascript
const NodeCache = require('node-cache');
const secretsCache = new NodeCache({ 
  stdTTL: 3600, // Cache for 1 hour
  checkperiod: 600, // Check every 10 min
});

async function getSecret(secretName) {
  // Check cache first
  const cached = secretsCache.get(secretName);
  if (cached) {
    return cached;
  }

  // Load from Secrets Manager
  const secret = await loadFromSecretsManager(secretName);

  // Cache it
  secretsCache.set(secretName, secret);

  return secret;
}

// Usage
const JWT_SECRET = await getSecret('jwt-secret');
```

### Pattern 2: Lazy Loading with Error Handling

```javascript
class SecretsManager {
  constructor(provider) {
    this.provider = provider; // AWS, Vault, etc.
    this.secrets = {};
    this.errors = 0;
    this.maxRetries = 3;
  }

  async getSecret(name) {
    if (this.secrets[name]) {
      return this.secrets[name];
    }

    try {
      const secret = await this.provider.get(name);
      this.secrets[name] = secret;
      this.errors = 0; // Reset error counter
      return secret;
    } catch (error) {
      this.errors++;

      if (this.errors >= this.maxRetries) {
        console.error(`[CRITICAL] Failed to load secret: ${name}`);
        process.exit(1); // Fail fast
      }

      throw error;
    }
  }
}

// Usage
const manager = new SecretsManager(awsProvider);
const JWT_SECRET = await manager.getSecret('jwt-secret');
```

### Pattern 3: Environment-Specific Loading

```javascript
async function loadSecretsForEnvironment() {
  const env = process.env.NODE_ENV || 'development';

  if (env === 'production') {
    // Use Secrets Manager
    return await loadFromSecretsManager();
  } else if (env === 'staging') {
    // Use Secrets Manager with staging config
    return await loadFromSecretsManager('staging');
  } else {
    // Development: use .env with validation
    validateDevelopmentSecrets();
    return loadFromDotenv();
  }
}

function validateDevelopmentSecrets() {
  const required = ['JWT_SECRET', 'DB_USER', 'DB_PASS'];
  const missing = required.filter(key => !process.env[key]);

  if (missing.length > 0) {
    throw new Error(`Missing required secrets: ${missing.join(', ')}`);
  }
}
```

