// npm install aws-sdk

const AWS = require('aws-sdk');

class AWSSecretsManager {
  constructor(region = 'us-east-1') {
    this.client = new AWS.SecretsManager({ region });
    this.cache = new Map();
    this.cacheExpiry = new Map();
    this.cacheTTL = 3600000; // 1 hour
  }

  async getSecret(secretName) {
    // Check cache first
    if (this.isCacheValid(secretName)) {
      return this.cache.get(secretName);
    }

    try {
      const response = await this.client
        .getSecretValue({ SecretId: secretName })
        .promise();

      let secretValue;
      if (response.SecretString) {
        secretValue = JSON.parse(response.SecretString);
      } else {
        secretValue = Buffer.from(response.SecretBinary, 'base64').toString();
      }

      // Cache the secret
      this.cache.set(secretName, secretValue);
      this.cacheExpiry.set(
        secretName,
        Date.now() + this.cacheTTL
      );

      console.log(`[SECRETS] Loaded secret: ${secretName}`);
      return secretValue;
    } catch (error) {
      console.error(
        `[SECRETS] Error loading secret ${secretName}:`,
        error.message
      );
      throw error;
    }
  }

  isCacheValid(secretName) {
    const expiry = this.cacheExpiry.get(secretName);
    return expiry && Date.now() < expiry;
  }

  clearCache(secretName) {
    this.cache.delete(secretName);
    this.cacheExpiry.delete(secretName);
  }
}

