// npm install node-vault

const VaultClient = require('node-vault');

class VaultSecretsManager {
  constructor(options = {}) {
    this.vault = new VaultClient({
      endpoint: options.endpoint || process.env.VAULT_ADDR,
      token: options.token || process.env.VAULT_TOKEN,
    });

    this.cache = new Map();
    this.cacheTTL = 3600000; // 1 hour
  }

  async getSecret(path) {
    // Check cache
    const cached = this.cache.get(path);
    if (cached && Date.now() < cached.expiry) {
      return cached.data;
    }

    try {
      const secret = await this.vault.read(`secret/data/${path}`);
      const secretData = secret.data.data;

      // Cache it
      this.cache.set(path, {
        data: secretData,
        expiry: Date.now() + this.cacheTTL,
      });

      console.log(`[VAULT] Loaded secret: ${path}`);
      return secretData;
    } catch (error) {
      console.error(`[VAULT] Error loading secret ${path}:`, error.message);
      throw error;
    }
  }

  async rotateSecret(path, newValue) {
    try {
      await this.vault.write(`secret/data/${path}`, {
        data: newValue,
      });

      // Invalidate cache
      this.cache.delete(path);

      console.log(`[VAULT] Rotated secret: ${path}`);
    } catch (error) {
      console.error(`[VAULT] Error rotating secret ${path}:`, error.message);
      throw error;
    }
  }
}

