        data: field.value,
        expiry: Date.now() + this.cacheTTL,
      });

      console.log(`[1PASSWORD] Loaded secret: ${fieldName}`);
      return field.value;
    } catch (error) {
      console.error(
        `[1PASSWORD] Error loading secret ${fieldName}:`,
        error.message
      );
      throw error;
    }
  }
}

