      console.error(`Missing required secrets: ${missing.join(', ')}`);
      process.exit(1);
    }
  }
}

// Usage in app.js
async function loadSecretsAndInitializeApp() {
  try {
    const secretsManager = SecretsManagerFactory.create();

    const JWT_SECRET = await secretsManager.getSecret('JWT_SECRET');
    const NODE_ENV = await secretsManager.getSecret('NODE_ENV');
    const PORT = await secretsManager.getSecret('PORT');

    console.log(`[APP] Initialized with environment: ${NODE_ENV}`);

    return { JWT_SECRET, NODE_ENV, PORT };
  } catch (error) {
    console.error('[APP] Failed to load secrets:', error.message);
    process.exit(1);
  }
}

// ============================================================================
// COMPLETE APP.JS INTEGRATION
// ============================================================================

const express = require('express');
const helmet = require('helmet');

async function startApp() {
  try {
    // Load secrets based on environment
    const secretsManager = SecretsManagerFactory.create();
    const JWT_SECRET = await secretsManager.getSecret('JWT_SECRET');
    const NODE_ENV = await secretsManager.getSecret('NODE_ENV');
    const PORT = await secretsManager.getSecret('PORT');

    // Create Express app
    const app = express();

    // Add security middleware
    app.use(helmet());

    // Routes use JWT_SECRET
    app.use((req, res, next) => {
      req.JWT_SECRET = JWT_SECRET;
      next();
    });

    app.get('/health', (req, res) => {
      res.json({ status: 'ok' });
    });

    // Start server
    app.listen(PORT, () => {
      console.log(`[APP] Server running on port ${PORT} (${NODE_ENV})`);
      console.log(`[SECRETS] Using provider: ${process.env.SECRETS_PROVIDER || 'dotenv'}`);
    });

    // Graceful shutdown
    process.on('SIGTERM', () => {
      console.log('[APP] SIGTERM received, shutting down gracefully...');
      process.exit(0);
    });
  } catch (error) {
    console.error('[APP] Fatal error during startup:', error);
    process.exit(1);
  }
}

// Start the app
startApp();

module.exports = {
  AWSSecretsManager,
  VaultSecretsManager,
  GCPSecretsManager,
  AzureKeyVaultManager,
  DopplerSecretsManager,
  OnePasswordSecretsManager,
  SecretsManagerFactory,
};

