npm audit

# Use OWASP ZAP or Burp Suite for penetration testing
# Use npm package: snyk for continuous security monitoring
npm install -g snyk
snyk test
```

---

## References
- [OWASP Top 10 2021](https://owasp.org/Top10/)
- [Express.js Security Best Practices](https://expressjs.com/en/advanced/best-practice-security.html)
- [Node.js Security Checklist](https://blog.risingstack.com/node-js-security-checklist/)

/**
 * Secure version of app.js with all security recommendations implemented
 * This is a production-ready template with proper security hardening
 */

require('dotenv').config();
const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const mongoSanitize = require('express-mongo-sanitize');
const xss = require('xss-clean');
const { query, body, validationResult } = require('express-validator');
const jwt = require('jsonwebtoken');
const winston = require('winston');
const https = require('https');
const fs = require('fs');

// ============================================================================
// CONFIGURATION
// ============================================================================

const PORT = process.env.PORT || 3000;
const NODE_ENV = process.env.NODE_ENV || 'development';
const JWT_SECRET = process.env.JWT_SECRET;

// Validate critical environment variables in production
if (NODE_ENV === 'production' && !JWT_SECRET) {
  throw new Error('CRITICAL: JWT_SECRET environment variable is required in production');
}

// ============================================================================
// LOGGING SETUP
// ============================================================================

const logger = winston.createLogger({
  level: process.env.LOG_LEVEL || 'info',
  format: winston.format.combine(
    winston.format.timestamp(),
    winston.format.errors({ stack: true }),
    winston.format.json()
  ),
  defaultMeta: { service: 'secure-app' },
  transports: [
    new winston.transports.File({ filename: 'logs/error.log', level: 'error' }),
    new winston.transports.File({ filename: 'logs/combined.log' })
  ]
});

if (NODE_ENV !== 'production') {
  logger.add(new winston.transports.Console({
    format: winston.format.combine(
      winston.format.colorize(),
      winston.format.simple()
    )
  }));
}

// ============================================================================
// EXPRESS APP SETUP
// ============================================================================

const app = express();

// ============================================================================
// SECURITY MIDDLEWARE
// ============================================================================

// 1. Helmet: Set security headers
app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      styleSrc: ["'self'", "'unsafe-inline'"],
      scriptSrc: ["'self'"],
      imgSrc: ["'self'", 'data:', 'https:']
    }
  },
  hsts: {
    maxAge: 31536000, // 1 year in seconds
    includeSubDomains: true,
    preload: true
  }
}));

// 2. CORS Configuration
app.use(cors({
  origin: process.env.ALLOWED_ORIGINS?.split(',') || 
    (NODE_ENV === 'production' ? [] : ['http://localhost:3000']),
  credentials: true,
  methods: ['GET', 'POST', 'PUT', 'DELETE'],
  allowedHeaders: ['Content-Type', 'Authorization'],
  maxAge: 600 // Preflight cache time in seconds
}));

// 3. Body Parser with size limits
app.use(express.json({ limit: '10kb' })); // Prevent large payloads
app.use(express.urlencoded({ limit: '10kb', extended: true }));

// 4. Data Sanitization
app.use(mongoSanitize()); // Prevent NoSQL injection
app.use(xss()); // Prevent XSS attacks

// 5. Rate Limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true, // Return rate limit info in RateLimit-* headers
  legacyHeaders: false // Disable X-RateLimit-* headers
});

const strictLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 5, // Stricter limit for sensitive endpoints
  skipSuccessfulRequests: true // Don't count successful requests
});

app.use(limiter);

// 6. Request ID for tracking
const { v4: uuidv4 } = require('uuid');
app.use((req, res, next) => {
  req.id = uuidv4();
  res.setHeader('X-Request-ID', req.id);
  next();
});

// ============================================================================
// LOGGING MIDDLEWARE
// ============================================================================

app.use((req, res, next) => {
  const startTime = Date.now();

  // Log request
  logger.info({
    event: 'request_started',
    method: req.method,
    path: req.path,
    query: req.query,
    ip: req.ip,
    userAgent: req.get('user-agent'),
    requestId: req.id
  });

  // Log response
  res.on('finish', () => {
    const duration = Date.now() - startTime;
    const logLevel = res.statusCode >= 400 ? 'warn' : 'info';

    logger[logLevel]({
      event: 'request_completed',
      method: req.method,
      path: req.path,
      status: res.statusCode,
      duration: `${duration}ms`,
      ip: req.ip,
      user: req.user?.id,
      requestId: req.id
    });

    // Log security events
    if (res.statusCode === 401 || res.statusCode === 403) {
      logger.warn({
        event: 'unauthorized_access_attempt',
        method: req.method,
        path: req.path,
        status: res.statusCode,
        ip: req.ip,
        user: req.user?.id,
        requestId: req.id
      });
    }
  });

  next();
});

// ============================================================================
// AUTHENTICATION MIDDLEWARE
// ============================================================================

/**
 * Verify JWT token from Authorization header
 * Expected format: Authorization: Bearer <token>
 */
function authenticateToken(req, res, next) {
  const authHeader = req.headers['authorization'];
  const token = authHeader && authHeader.split(' ')[1]; // Extract token after "Bearer"

  if (!token) {
    logger.warn({
      event: 'missing_auth_token',
      path: req.path,
      ip: req.ip,
      requestId: req.id
    });
    return res.status(401).json({ 
      error: 'Access token required',
      requestId: req.id 
    });
  }

  jwt.verify(token, JWT_SECRET, (err, user) => {
    if (err) {
      logger.warn({
        event: 'invalid_token',
        path: req.path,
        ip: req.ip,
        error: err.message,
        requestId: req.id
      });
      return res.status(403).json({ 
        error: 'Invalid or expired token',
        requestId: req.id 
      });
    }

    req.user = user;
    next();
  });
}

/**
 * Verify admin role
 */
function authorizeAdmin(req, res, next) {
  if (!req.user || !req.user.isAdmin) {
    logger.warn({
      event: 'unauthorized_admin_attempt',
      path: req.path,
      ip: req.ip,
      user: req.user?.id,
      requestId: req.id
    });
    return res.status(403).json({ 
      error: 'Admin access required',
      requestId: req.id 
    });
  }
  next();
}

// ============================================================================
// ROUTES
// ============================================================================

/**
 * Health check endpoint (public)
 */
app.get('/health', (req, res) => {
  res.json({ 
    status: 'ok', 
    timestamp: new Date().toISOString(),
    requestId: req.id
  });
});

/**
 * Login endpoint - Issue JWT token
 * POST /login
 * Body: { username: string, password: string }
 */
app.post('/login', 
  express.json(),
  strictLimiter,
  [
    body('username').trim().notEmpty().withMessage('Username is required')
      .isLength({ min: 3, max: 50 }).withMessage('Username must be 3-50 characters'),
    body('password').notEmpty().withMessage('Password is required')
      .isLength({ min: 8 }).withMessage('Password must be at least 8 characters')
  ],
  (req, res) => {
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({ 
        errors: errors.array(),
        requestId: req.id 
      });
    }

    const { username, password } = req.body;

    // TODO: Validate credentials against database with bcrypt
    // This is a placeholder - implement proper authentication
    if (username === 'demo' && password === 'Demo@123') {
      const user = { 
        id: 1, 
        username: username,
        isAdmin: false 
      };
      const token = jwt.sign(user, JWT_SECRET, { expiresIn: '1h' });

      logger.info({
        event: 'login_successful',
        user: username,
        ip: req.ip,
        requestId: req.id
      });

      return res.json({ 
        token,
        expiresIn: '1h',
        requestId: req.id 
      });
    }

    logger.warn({
      event: 'login_failed',
      username: username,
      ip: req.ip,
      requestId: req.id
    });

    res.status(401).json({ 
      error: 'Invalid credentials',
      requestId: req.id 
    });
  }
);

/**
 * Get all users (authenticated only)
 * GET /users?limit=10&offset=0
 */
app.get('/users',
  authenticateToken,
  [
    query('limit').optional().isInt({ min: 1, max: 100 }).toInt(),
    query('offset').optional().isInt({ min: 0 }).toInt()
  ],
  (req, res) => {
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({ 
        errors: errors.array(),
        requestId: req.id 
      });
    }

    const limit = req.query.limit || 10;
    const offset = req.query.offset || 0;

    const allUsers = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    // Hide sensitive data in production for non-admin users
    let users = allUsers;
    if (NODE_ENV === 'production' && !req.user.isAdmin) {
      users = users.map(user => ({
        id: user.id,
        name: user.name
        // Email hidden from non-admin users
      }));
    }

    const paginatedUsers = users.slice(offset, offset + limit);

    res.json({
      data: paginatedUsers,
      pagination: {
        limit,
        offset,
        total: users.length
      },
      requestId: req.id
    });
  }
);

/**
 * Get user by ID (authenticated only)
 * GET /users/:id
 */
app.get('/users/:id',
  authenticateToken,
  [
    query('id').isInt().toInt()
  ],
  (req, res) => {
    const userId = parseInt(req.params.id, 10);

    if (isNaN(userId)) {
      return res.status(400).json({ 
        error: 'Invalid user ID',
        requestId: req.id 
      });
    }

    const user = { id: userId, name: 'User Name', email: 'user@example.com' };

    // Don't expose email to non-admin users in production
    if (NODE_ENV === 'production' && !req.user.isAdmin) {
      delete user.email;
    }

    res.json({
      data: user,
      requestId: req.id
    });
  }
);

/**
 * Create new user (admin only)
 * POST /users
 */
app.post('/users',
  express.json(),
  authenticateToken,
  authorizeAdmin,
  [
    body('name').trim().notEmpty().withMessage('Name is required')
      .isLength({ min: 2, max: 100 }).withMessage('Name must be 2-100 characters'),
    body('email').isEmail().withMessage('Valid email is required')
      .normalizeEmail(),
  ],
  (req, res) => {
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({ 
        errors: errors.array(),
        requestId: req.id 
      });
    }

    const { name, email } = req.body;

    logger.info({
      event: 'user_created',
      name: name,
      email: email,
      createdBy: req.user.id,
      requestId: req.id
    });

    res.status(201).json({ 
      id: 3, 
      name, 
      email,
      requestId: req.id 
    });
  }
);

// ============================================================================
// ERROR HANDLING
// ============================================================================

/**
 * 404 Not Found handler
 */
app.use((req, res) => {
  logger.warn({
    event: '404_not_found',
    method: req.method,
    path: req.path,
    ip: req.ip,
    requestId: req.id
  });

  res.status(404).json({ 
    error: 'Endpoint not found',
    requestId: req.id 
  });
});

/**
 * Global error handler
 * All errors should be caught and handled here
 */
app.use((err, req, res, next) => {
  logger.error({
    event: 'unhandled_error',
    error: err.message,
    stack: err.stack,
    path: req.path,
    method: req.method,
    ip: req.ip,
    requestId: req.id
  });

  const statusCode = err.statusCode || 500;
  const message = NODE_ENV === 'production' 
    ? 'Internal server error' 
    : err.message;

  res.status(statusCode).json({
    error: message,
    requestId: req.id
  });
});

// ============================================================================
// SERVER STARTUP
// ============================================================================

// Only use HTTPS in production with proper certificates
if (NODE_ENV === 'production' && process.env.SSL_KEY && process.env.SSL_CERT) {
  try {
    const options = {
      key: fs.readFileSync(process.env.SSL_KEY),
      cert: fs.readFileSync(process.env.SSL_CERT)
    };

    https.createServer(options, app).listen(PORT, () => {
      logger.info({
        event: 'server_started',
        port: PORT,
        environment: NODE_ENV,
        protocol: 'HTTPS'
      });
    });

    // Redirect HTTP to HTTPS
    const http = require('http');
    http.createServer((req, res) => {
      res.writeHead(301, { Location: `https://${req.headers.host}${req.url}` });
      res.end();
    }).listen(80);
  } catch (err) {
    logger.error({
      event: 'ssl_cert_error',
      error: err.message
    });
    process.exit(1);
  }
} else {
  app.listen(PORT, () => {
    logger.info({
      event: 'server_started',
      port: PORT,
      environment: NODE_ENV,
      protocol: NODE_ENV === 'production' ? 'HTTP (WARNING: Not secure!)' : 'HTTP'
    });
  });
}

// ============================================================================
// GRACEFUL SHUTDOWN
// ============================================================================

process.on('unhandledRejection', (reason, promise) => {
  logger.error({
    event: 'unhandled_rejection',
    reason: reason,
    promise: promise
  });
  process.exit(1);
});

process.on('uncaughtException', (error) => {
  logger.error({
    event: 'uncaught_exception',
    error: error.message,
    stack: error.stack
  });
  process.exit(1);
});

process.on('SIGTERM', () => {
  logger.info({
    event: 'sigterm_received',
    message: 'Gracefully shutting down'
  });
  process.exit(0);
});

module.exports = app;

