## Common Security Vulnerabilities and Fixes

### 1. SQL Injection
**Problem**: User input directly in SQL queries
```javascript
// WRONG ❌
const query = `SELECT * FROM users WHERE name = '${req.body.name}'`;

// CORRECT ✅
const query = 'SELECT * FROM users WHERE name = ?';
db.query(query, [req.body.name]);
```

### 2. NoSQL Injection
**Problem**: User input directly in MongoDB queries
```javascript
// WRONG ❌
db.users.find({ name: req.body.name });

// CORRECT ✅
const sanitizedInput = mongoSanitize(req.body.name);
db.users.find({ name: sanitizedInput });
```

### 3. Cross-Site Scripting (XSS)
**Problem**: Unescaped user input in HTML responses
```javascript
// WRONG ❌
res.send(`<h1>${req.body.title}</h1>`);

// CORRECT ✅
const xss = require('xss');
const cleanTitle = xss(req.body.title);
res.send(`<h1>${cleanTitle}</h1>`);
```

### 4. Missing Authentication
**Problem**: No verification of user identity
```javascript
// WRONG ❌
app.get('/admin', (req, res) => {
  res.json({ data: 'sensitive' });
});

// CORRECT ✅
app.get('/admin', authenticateToken, authorizeAdmin, (req, res) => {
  res.json({ data: 'sensitive' });
});
```

### 5. Missing Authorization
**Problem**: No verification of user permissions
```javascript
// WRONG ❌
if (req.user) { // Only checks if user exists
  res.json(allData);
}

// CORRECT ✅
if (req.user && req.user.isAdmin) { // Checks role
  res.json(allData);
}
```

### 6. Sensitive Data Exposure
**Problem**: Exposing sensitive information
```javascript
// WRONG ❌
res.json(user); // Includes password hash, SSN, etc.

// CORRECT ✅
res.json({
  id: user.id,
  name: user.name
  // Exclude sensitive fields
});
```

### 7. Missing Input Validation
**Problem**: Accepting invalid input
```javascript
// WRONG ❌
app.post('/users', (req, res) => {
  const { email } = req.body;
  // Process without validation
});

// CORRECT ✅
const { body, validationResult } = require('express-validator');

app.post('/users',
  [body('email').isEmail().normalizeEmail()],
  (req, res) => {
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({ errors: errors.array() });
    }
    const { email } = req.body;
    // Process validated email
  }
);
```

### 8. Weak Password Storage
**Problem**: Storing passwords in plaintext or with weak hashing
```javascript
// WRONG ❌
user.password = req.body.password; // Plaintext
user.password = md5(req.body.password); // MD5 is weak

// CORRECT ✅
const bcrypt = require('bcryptjs');
const salt = await bcrypt.genSalt(10);
user.password = await bcrypt.hash(req.body.password, salt);

// Verify
const isValid = await bcrypt.compare(inputPassword, user.password);
```

### 9. Insecure Direct Object Reference (IDOR)
**Problem**: No permission check on resource IDs
```javascript
// WRONG ❌
app.get('/users/:id', (req, res) => {
  const user = db.getUser(req.params.id);
  res.json(user); // Any user can access any other user
});

// CORRECT ✅
app.get('/users/:id', authenticateToken, (req, res) => {
  if (req.user.id !== req.params.id && !req.user.isAdmin) {
    return res.status(403).json({ error: 'Forbidden' });
  }
  const user = db.getUser(req.params.id);
  res.json(user);
});
```

### 10. Broken Authentication
**Problem**: Weak session management
```javascript
// WRONG ❌
res.cookie('userId', userId); // Unsecured cookie

// CORRECT ✅
res.cookie('token', token, {
  httpOnly: true, // Not accessible to JavaScript
  secure: true, // Only sent over HTTPS
  sameSite: 'strict', // CSRF protection
  maxAge: 3600000 // 1 hour
});
```

