# Side-by-Side Security Comparison

## Vulnerability #1: Missing Authentication

### ❌ VULNERABLE (Original app.js)
```javascript
app.get('/users', (req, res) => {
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ]);
});

// Anyone can access this endpoint without any credentials!
// curl http://localhost:3000/users → Works ✗
```

### ✅ SECURE (app-secure.js)
```javascript
// First, add authentication middleware
function authenticateToken(req, res, next) {
  const authHeader = req.headers['authorization'];
  const token = authHeader && authHeader.split(' ')[1];

  if (!token) {
    return res.status(401).json({ error: 'Access token required' });
  }

  jwt.verify(token, JWT_SECRET, (err, user) => {
    if (err) {
      return res.status(403).json({ error: 'Invalid or expired token' });
    }
    req.user = user;
    next();
  });
}

// Then protect the endpoint
app.get('/users', authenticateToken, (req, res) => {
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ]);
});

// Now authentication is required!
// curl http://localhost:3000/users → 401 Unauthorized ✓
// curl -H "Authorization: Bearer TOKEN" http://localhost:3000/users → Works ✓
```

