```

### ✅ SECURE (app-secure.js)
```javascript
const logger = require('./logger');

// Global error handler
app.use((err, req, res, next) => {
  // Log full error details (internal only)
  logger.error({
    event: 'unhandled_error',
    error: err.message,
    stack: err.stack,
    requestId: req.id
  });

  const statusCode = err.statusCode || 500;

