### Recommended Pattern:
```javascript
const AWS = require('aws-sdk');
const logger = require('./logger');

class SecretsManager {
  constructor() {
    this.NODE_ENV = process.env.NODE_ENV || 'development';
    this.secrets = null;
    this.lastLoad = null;
    this.cacheTTL = 3600000; // 1 hour
  }

  async initialize() {
    if (this.NODE_ENV === 'development') {
      // Development: Load from .env
      require('dotenv').config();
      this.secrets = {
        jwtSecret: process.env.JWT_SECRET,
        databaseUrl: process.env.DATABASE_URL,
        apiKeys: {}
      };
      logger.warn('⚠️  Using .env file for secrets (DEVELOPMENT ONLY)');
    } else if (this.NODE_ENV === 'production') {
      // Production: Load from AWS Secrets Manager
      await this.loadFromSecretsManager();
    } else {
      throw new Error(`Unknown NODE_ENV: ${this.NODE_ENV}`);
    }

    this.validateSecrets();
    this.lastLoad = Date.now();
  }

  async loadFromSecretsManager() {
    try {
      const secretsManager = new AWS.SecretsManager({
        region: process.env.AWS_REGION || 'us-east-1'
      });

      const response = await secretsManager.getSecretValue({
        SecretId: process.env.SECRET_ID || 'my-app/secrets'
      }).promise();

      if ('SecretString' in response) {
        this.secrets = JSON.parse(response.SecretString);
        logger.info('✓ Secrets loaded from AWS Secrets Manager');
      } else {
        throw new Error('SecretBinary not supported');
      }
    } catch (error) {
      logger.error('CRITICAL: Failed to load secrets from AWS', {
        error: error.message,
        secretId: process.env.SECRET_ID
      });
      throw error;
    }
  }

  validateSecrets() {
    const required = ['jwtSecret', 'databaseUrl'];
    const missing = required.filter(key => !this.secrets[key]);

    if (missing.length > 0) {
      throw new Error(`Missing required secrets: ${missing.join(', ')}`);
    }

    // Additional validation
    if (this.secrets.jwtSecret.length < 32) {
      throw new Error('JWT_SECRET must be at least 32 characters');
    }

    logger.info('✓ All required secrets validated');
  }

  get(key) {
    if (!this.secrets) {
      throw new Error('Secrets not initialized. Call initialize() first');
    }

    if (!(key in this.secrets)) {
      throw new Error(`Unknown secret: ${key}`);
    }

    return this.secrets[key];
  }

  async refreshIfNeeded() {
    // Refresh secrets periodically (e.g., for rotation)
    if (this.NODE_ENV === 'production') {
      const timeSinceLoad = Date.now() - this.lastLoad;
      if (timeSinceLoad > this.cacheTTL) {
        logger.info('Refreshing secrets from AWS');
        await this.loadFromSecretsManager();
        this.validateSecrets();
      }
    }
  }

  // Log secret access (without exposing the secret)
  logAccess(secretName) {
    logger.debug({
      event: 'secret_accessed',
      secret: secretName,
      timestamp: new Date().toISOString()
    });
  }
}

// Usage in app.js
const secretsManager = new SecretsManager();

async function initializeApp() {
  try {
    // Initialize secrets before app starts
    await secretsManager.initialize();

    const JWT_SECRET = secretsManager.get('jwtSecret');
    const DATABASE_URL = secretsManager.get('databaseUrl');

    // Periodically refresh
    setInterval(async () => {
      await secretsManager.refreshIfNeeded();
    }, 300000); // Every 5 minutes

    // ... rest of app initialization
  } catch (error) {
    logger.error('Failed to initialize application', { error });
    process.exit(1);
  }
}
