/**
 * Enhanced Secure App with Proper Secrets Management
 * Supports: AWS Secrets Manager, Azure Key Vault, GCP Secret Manager, HashiCorp Vault, or .env (dev only)
 */

const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const mongoSanitize = require('express-mongo-sanitize');
const xss = require('xss-clean');
const { query, body, validationResult } = require('express-validator');
const jwt = require('jsonwebtoken');
const winston = require('winston');
const https = require('https');
const fs = require('fs');
const crypto = require('crypto');
const { v4: uuidv4 } = require('uuid');

// ============================================================================
// SECRETS MANAGEMENT
// ============================================================================

/**
 * Unified Secrets Manager supporting multiple backends
 * Supports: AWS Secrets Manager, Azure Key Vault, GCP Secret Manager, 
 * HashiCorp Vault, .env (development only)
 */
class SecretsManager {
  constructor() {
    this.NODE_ENV = process.env.NODE_ENV || 'development';
    this.backend = process.env.SECRETS_BACKEND || 'dotenv'; // dotenv, aws, azure, gcp, vault
    this.secrets = null;
    this.lastLoad = null;
    this.cacheTTL = parseInt(process.env.SECRETS_CACHE_TTL || '3600000'); // 1 hour
    this.logger = null;
  }

  setLogger(logger) {
    this.logger = logger;
  }

  log(level, message, meta = {}) {
    if (this.logger) {
      this.logger[level]({ event: 'secrets_manager', message, ...meta });
    }
  }

  async initialize() {
    try {
      switch (this.backend) {
        case 'aws':
          await this.initializeAWS();
          break;
        case 'azure':
          await this.initializeAzure();
          break;
        case 'gcp':
          await this.initializeGCP();
          break;
        case 'vault':
          await this.initializeVault();
          break;
        case 'dotenv':
        default:
          this.initializeDotenv();
          break;
      }

      this.validateSecrets();
      this.lastLoad = Date.now();
      this.log('info', `✓ Secrets loaded from ${this.backend}`, {
        backend: this.backend,
        environment: this.NODE_ENV
      });
    } catch (error) {
      this.log('error', `Failed to initialize secrets: ${error.message}`, {
        backend: this.backend,
        error: error.message
      });
      throw error;
    }
  }

  // ========== Backend Implementations ==========

  initializeDotenv() {
    if (this.NODE_ENV === 'production') {
      throw new Error('❌ FATAL: Cannot use .env file in production. Set SECRETS_BACKEND to aws, azure, gcp, or vault.');
    }

    require('dotenv').config();

    this.secrets = {
      jwtSecret: process.env.JWT_SECRET,
      databaseUrl: process.env.DATABASE_URL || '',
      apiKeys: {},
      backendUsed: 'dotenv (DEVELOPMENT ONLY)'
    };

    this.log('warn', '⚠️  Using .env file (DEVELOPMENT ONLY)', {
      hint: 'Switch to AWS/Azure/GCP/Vault for production'
    });
  }

  async initializeAWS() {
    try {
      const AWS = require('aws-sdk');

      const secretsManager = new AWS.SecretsManager({
        region: process.env.AWS_REGION || 'us-east-1'
      });

      const response = await secretsManager.getSecretValue({
        SecretId: process.env.SECRET_ID || 'my-app/secrets'
      }).promise();

      if ('SecretString' in response) {
        this.secrets = JSON.parse(response.SecretString);
        this.secrets.backendUsed = 'AWS Secrets Manager';
      } else {
        throw new Error('SecretBinary format not supported');
      }
    } catch (error) {
      this.log('error', 'AWS Secrets Manager initialization failed', {
        secretId: process.env.SECRET_ID,
        region: process.env.AWS_REGION,
        error: error.message
      });
      throw error;
    }
  }

  async initializeAzure() {
    try {
      const { SecretClient } = require('@azure/keyvault-secrets');
      const { DefaultAzureCredential } = require('@azure/identity');

      const credential = new DefaultAzureCredential();
      const client = new SecretClient(
        `https://${process.env.AZURE_KEY_VAULT_NAME}.vault.azure.net/`,
        credential
      );

      const jwtSecretRef = await client.getSecret('jwt-secret');
      const databaseUrlRef = await client.getSecret('database-url');

      this.secrets = {
        jwtSecret: jwtSecretRef.value,
        databaseUrl: databaseUrlRef.value,
        apiKeys: {},
        backendUsed: 'Azure Key Vault'
      };
    } catch (error) {
      this.log('error', 'Azure Key Vault initialization failed', {
        keyVaultName: process.env.AZURE_KEY_VAULT_NAME,
        error: error.message
      });
      throw error;
    }
  }

  async initializeGCP() {
    try {
      const { SecretManagerServiceClient } = require('@google-cloud/secret-manager');

      const client = new SecretManagerServiceClient();
      const projectId = process.env.GCP_PROJECT_ID;

      const getSecret = async (secretName) => {
        const name = client.secretVersionPath(projectId, secretName, 'latest');
        const [version] = await client.accessSecretVersion({ name });
        return version.payload.data.toString('utf8');
      };

      this.secrets = {
        jwtSecret: await getSecret('jwt-secret'),
        databaseUrl: await getSecret('database-url'),
        apiKeys: {},
        backendUsed: 'GCP Secret Manager'
      };
    } catch (error) {
      this.log('error', 'GCP Secret Manager initialization failed', {
        projectId: process.env.GCP_PROJECT_ID,
        error: error.message
      });
      throw error;
    }
  }

  async initializeVault() {
    try {
      const vault = require('node-vault')({
        endpoint: process.env.VAULT_ADDR || 'http://127.0.0.1:8200',
        token: process.env.VAULT_TOKEN
      });

      const response = await vault.read(`secret/data/${process.env.VAULT_PATH || 'my-app'}`);

      this.secrets = {
        ...response.data.data,
        apiKeys: response.data.data.apiKeys || {},
        backendUsed: 'HashiCorp Vault'
      };
    } catch (error) {
      this.log('error', 'HashiCorp Vault initialization failed', {
        vaultAddr: process.env.VAULT_ADDR,
        vaultPath: process.env.VAULT_PATH,
        error: error.message
      });
      throw error;
    }
  }

  // ========== Validation & Access ==========

  validateSecrets() {
    const required = ['jwtSecret'];
    const missing = required.filter(key => !this.secrets[key]);

    if (missing.length > 0) {
      throw new Error(`Missing required secrets: ${missing.join(', ')}`);
    }

    // Validate JWT secret strength
    if (typeof this.secrets.jwtSecret === 'string' && 
        this.secrets.jwtSecret.length < 32) {
      throw new Error('JWT_SECRET must be at least 32 characters');
    }

    this.log('info', '✓ All required secrets validated');
  }

  get(key, throwIfMissing = true) {
    if (!this.secrets) {
      throw new Error('Secrets not initialized. Call initialize() first.');
    }

    if (!(key in this.secrets)) {
      if (throwIfMissing) {
        this.log('warn', `Unknown secret requested: ${key}`);
        throw new Error(`Unknown secret: ${key}`);
      }
      return undefined;
    }

    // Log access without exposing the value
    this.log('debug', `Secret accessed: ${key}`, {
      source: this.secrets.backendUsed
    });

    return this.secrets[key];
  }

  async refreshIfNeeded() {
    if (this.backend === 'dotenv') {
      return; // No refresh for dev
    }

    const timeSinceLoad = Date.now() - this.lastLoad;
    if (timeSinceLoad > this.cacheTTL) {
      this.log('info', 'Refreshing secrets from backend', {
        timeSinceLoad: `${timeSinceLoad / 1000 / 60} minutes`
      });

      await this.initialize();
    }
  }

  getBackendInfo() {
    return {
      backend: this.backend,
      environment: this.NODE_ENV,
      usedBackend: this.secrets?.backendUsed || 'unknown',
      lastLoad: this.lastLoad,
      cacheTTL: this.cacheTTL
    };
  }
}

// ============================================================================
// LOGGING SETUP
// ============================================================================

const logger = winston.createLogger({
  level: process.env.LOG_LEVEL || 'info',
  format: winston.format.combine(
    winston.format.timestamp(),
    winston.format.errors({ stack: true }),
    winston.format.json()
  ),
  defaultMeta: { service: 'secure-app' },
  transports: [
    new winston.transports.File({ filename: 'logs/error.log', level: 'error' }),
    new winston.transports.File({ filename: 'logs/combined.log' })
  ]
});

if (process.env.NODE_ENV !== 'production') {
  logger.add(new winston.transports.Console({
    format: winston.format.combine(
      winston.format.colorize(),
      winston.format.simple()
    )
  }));
}

// ============================================================================
// INITIALIZE SECRETS
// ============================================================================

const secretsManager = new SecretsManager();
secretsManager.setLogger(logger);

let JWT_SECRET;
let DATABASE_URL;
let APP_INITIALIZED = false;

async function initializeApp() {
  try {
    // Load secrets
    await secretsManager.initialize();

