    JWT_SECRET = secretsManager.get('jwtSecret', true);
    DATABASE_URL = secretsManager.get('databaseUrl', false);

    logger.info('✓ Application initialization successful', {
      secretsBackend: secretsManager.getBackendInfo()
    });

    APP_INITIALIZED = true;

    // Setup periodic refresh for production
    if (process.env.NODE_ENV === 'production') {
      setInterval(async () => {
        try {
          await secretsManager.refreshIfNeeded();
        } catch (error) {
          logger.error('Failed to refresh secrets', { error: error.message });
        }
      }, 300000); // Every 5 minutes
    }
  } catch (error) {
    logger.error('CRITICAL: Application initialization failed', {
      error: error.message,
      backend: secretsManager.backend
    });
    process.exit(1);
  }
}

