// ROUTES
// ============================================================================

// Health check with secrets backend info
app.get('/health', (req, res) => {
  res.json({ 
    status: 'ok', 
    timestamp: new Date().toISOString(),
    requestId: req.id,
    secretsBackend: NODE_ENV === 'production' ? 
      secretsManager.getBackendInfo() : 
      'hidden (development)'
  });
});

// Login endpoint
app.post('/login', 
  express.json(),
  strictLimiter,
  [
    body('username').trim().notEmpty().withMessage('Username is required')
      .isLength({ min: 3, max: 50 }).withMessage('Username must be 3-50 characters'),
    body('password').notEmpty().withMessage('Password is required')
      .isLength({ min: 8 }).withMessage('Password must be at least 8 characters')
  ],
  (req, res) => {
    if (!APP_INITIALIZED) {
      return res.status(503).json({ error: 'Service not initialized' });
    }

    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({ 
        errors: errors.array(),
        requestId: req.id 
      });
    }

    const { username, password } = req.body;

    // TODO: Validate credentials against database with bcrypt
    if (username === 'demo' && password === 'Demo@123') {
      const user = { 
        id: 1, 
        username: username,
        isAdmin: false 
      };
      const token = jwt.sign(user, JWT_SECRET, { expiresIn: '1h' });

      logger.info({
        event: 'login_successful',
        user: username,
        ip: req.ip,
        requestId: req.id
      });

      return res.json({ 
        token,
        expiresIn: '1h',
        requestId: req.id 
      });
    }

    logger.warn({
      event: 'login_failed',
      username: username,
      ip: req.ip,
      requestId: req.id
    });

    res.status(401).json({ 
      error: 'Invalid credentials',
      requestId: req.id 
    });
  }
);

// Get all users
app.get('/users',
  authenticateToken,
  [
    query('limit').optional().isInt({ min: 1, max: 100 }).toInt(),
    query('offset').optional().isInt({ min: 0 }).toInt()
  ],
  (req, res) => {
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({ 
        errors: errors.array(),
        requestId: req.id 
      });
    }

    const limit = req.query.limit || 10;
    const offset = req.query.offset || 0;

    const allUsers = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    let users = allUsers;
    if (NODE_ENV === 'production' && !req.user.isAdmin) {
      users = users.map(user => ({
        id: user.id,
        name: user.name
      }));
    }

    const paginatedUsers = users.slice(offset, offset + limit);

    res.json({
      data: paginatedUsers,
      pagination: {
        limit,
        offset,
        total: users.length
      },
      requestId: req.id
    });
  }
);

// ============================================================================
// ERROR HANDLING
// ============================================================================

app.use((req, res) => {
  logger.warn({
    event: '404_not_found',
    method: req.method,
    path: req.path,
    requestId: req.id
  });

  res.status(404).json({ 
    error: 'Endpoint not found',
    requestId: req.id 
  });
});

app.use((err, req, res, next) => {
  logger.error({
    event: 'unhandled_error',
    error: err.message,
    stack: err.stack,
    path: req.path,
    requestId: req.id
  });

  const statusCode = err.statusCode || 500;
  const message = NODE_ENV === 'production' 
    ? 'Internal server error' 
    : err.message;

  res.status(statusCode).json({
    error: message,
    requestId: req.id
  });
});

// ============================================================================
// SERVER STARTUP
// ============================================================================

async function startServer() {
  try {
    // Initialize secrets first
    await initializeApp();

    if (NODE_ENV === 'production' && process.env.SSL_KEY && process.env.SSL_CERT) {
      try {
        const options = {
          key: fs.readFileSync(process.env.SSL_KEY),
          cert: fs.readFileSync(process.env.SSL_CERT)
        };

        https.createServer(options, app).listen(PORT, () => {
          logger.info({
            event: 'server_started',
            port: PORT,
            environment: NODE_ENV,
            protocol: 'HTTPS',
            secretsBackend: secretsManager.backend
          });
        });

        const http = require('http');
        http.createServer((req, res) => {
          res.writeHead(301, { Location: `https://${req.headers.host}${req.url}` });
          res.end();
        }).listen(80);
      } catch (err) {
        logger.error({
          event: 'ssl_cert_error',
          error: err.message
        });
        process.exit(1);
      }
    } else {
      app.listen(PORT, () => {
        logger.info({
          event: 'server_started',
          port: PORT,
          environment: NODE_ENV,
          protocol: NODE_ENV === 'production' ? 'HTTP (WARNING: Not secure!)' : 'HTTP',
          secretsBackend: secretsManager.backend
        });
      });
    }
  } catch (error) {
    logger.error('Failed to start server', { error: error.message });
    process.exit(1);
  }
}

// ============================================================================
// GRACEFUL SHUTDOWN
// ============================================================================

process.on('unhandledRejection', (reason, promise) => {
  logger.error({
    event: 'unhandled_rejection',
    reason: reason
  });
  process.exit(1);
});

process.on('uncaughtException', (error) => {
  logger.error({
    event: 'uncaught_exception',
    error: error.message,
    stack: error.stack
  });
  process.exit(1);
});

process.on('SIGTERM', () => {
  logger.info({
    event: 'sigterm_received',
    message: 'Gracefully shutting down'
  });
  process.exit(0);
});

// Start the server
if (require.main === module) {
  startServer();
}

module.exports = app;

