/**
 * SECURE VERSION OF app.js
 * Implements OWASP Top 10 protections
 * 
 * Installation:
 * npm install express helmet cors express-rate-limit jsonwebtoken express-validator morgan winston
 */

const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const jwt = require('jsonwebtoken');
const { query, body, validationResult } = require('express-validator');
const morgan = require('morgan');
const winston = require('winston');

const app = express();

// ==================== CONFIGURATION ====================
const SECRET_KEY = process.env.JWT_SECRET || 'change-this-in-production';
const PORT = process.env.PORT || 3000;
const NODE_ENV = process.env.NODE_ENV || 'development';

// ==================== LOGGING ====================
const logger = winston.createLogger({
  level: 'info',
  format: winston.format.combine(
    winston.format.timestamp(),
    winston.format.errors({ stack: true }),
    winston.format.json()
  ),
  defaultMeta: { service: 'app-service' },
  transports: [
    new winston.transports.File({ filename: 'logs/error.log', level: 'error' }),
    new winston.transports.File({ filename: 'logs/combined.log' })
  ]
});

if (NODE_ENV !== 'production') {
  logger.add(new winston.transports.Console({
    format: winston.format.simple()
  }));
}

app.use(morgan('combined', {
  stream: { write: message => logger.info(message.trim()) }
}));

// ==================== SECURITY MIDDLEWARE ====================

// 1. Security Headers (prevents XSS, clickjacking, MIME sniffing)
app.use(helmet());
app.use(helmet.contentSecurityPolicy({
  directives: {
    defaultSrc: ["'self'"],
    scriptSrc: ["'self'"],
    styleSrc: ["'self'", "'unsafe-inline'"],
    imgSrc: ["'self'", 'data:', 'https:'],
  },
}));

// 2. CORS Configuration (prevent unauthorized cross-origin requests)
const corsOptions = {
  origin: process.env.ALLOWED_ORIGINS?.split(',') || ['http://localhost:3000'],
  credentials: true,
  optionsSuccessStatus: 200,
  methods: ['GET', 'POST', 'PUT', 'DELETE', 'OPTIONS'],
  allowedHeaders: ['Content-Type', 'Authorization'],
  maxAge: 86400 // 24 hours
};
app.use(cors(corsOptions));

// 3. Body Parser with size limits (prevent DoS attacks)
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ limit: '10kb', extended: false }));

// 4. Rate Limiting (prevent brute force and DoS)
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  standardHeaders: true, // Return rate limit info in the `RateLimit-*` headers
  legacyHeaders: false, // Disable the `X-RateLimit-*` headers
  handler: (req, res) => {
    logger.warn(`Rate limit exceeded for IP: ${req.ip}`);
    res.status(429).json({ error: 'Too many requests, please try again later.' });
  },
  skip: (req) => {
    // Skip rate limiting for health checks in production
    if (NODE_ENV === 'production' && req.path === '/health') {
      return true;
    }
    return false;
  }
});
app.use(limiter);

// Stricter rate limiter for authentication endpoints
const authLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 5, // Max 5 login attempts per 15 minutes
  skipSuccessfulRequests: true, // Don't count successful requests
  handler: (req, res) => {
    logger.warn(`Auth rate limit exceeded for IP: ${req.ip}`);
    res.status(429).json({ error: 'Too many login attempts. Please try again later.' });
  }
});

// ==================== AUTHENTICATION MIDDLEWARE ====================

/**
 * Middleware to verify JWT token
 * OWASP A01: Authentication
 */
function authenticateToken(req, res, next) {
  try {
    const authHeader = req.headers['authorization'];

    if (!authHeader) {
      logger.warn(`Unauthorized access attempt (no token) from ${req.ip} to ${req.path}`);
      return res.status(401).json({ 
        error: 'Access token required',
        code: 'NO_TOKEN'
      });
    }

    // Extract token from "Bearer <token>"
    const parts = authHeader.split(' ');
    if (parts.length !== 2 || parts[0] !== 'Bearer') {
      logger.warn(`Invalid authorization header format from ${req.ip}`);
      return res.status(401).json({ 
        error: 'Invalid authorization header format',
        code: 'INVALID_FORMAT'
      });
    }

    const token = parts[1];

    jwt.verify(token, SECRET_KEY, (err, user) => {
      if (err) {
        logger.warn(`Invalid/expired token from ${req.ip}: ${err.message}`);
        return res.status(403).json({ 
          error: 'Invalid or expired token',
          code: 'INVALID_TOKEN'
        });
      }

      req.user = user;
      req.token = token;
      next();
    });
  } catch (error) {
    logger.error(`Authentication middleware error: ${error.message}`, error);
    res.status(500).json({ error: 'Authentication error' });
  }
}

/**
 * Middleware to verify user role
 * OWASP A01: Access Control
 */
function authorizeRole(requiredRole) {
  return (req, res, next) => {
    if (!req.user || !req.user.role) {
      logger.warn(`Authorization check failed: user not authenticated from ${req.ip}`);
      return res.status(401).json({ error: 'User not authenticated' });
    }

    if (req.user.role !== requiredRole && requiredRole !== '*') {
      logger.warn(`Authorization denied: user ${req.user.id} has role '${req.user.role}', required '${requiredRole}'`);
      return res.status(403).json({ 
        error: 'Insufficient permissions',
        code: 'FORBIDDEN'
      });
    }

    next();
  };
}

// ==================== ROUTES ====================

/**
 * Health check endpoint
 * No authentication required for monitoring/load balancing
 */
app.get('/health', (req, res) => {
  res.json({ 
    status: 'ok', 
    timestamp: new Date().toISOString(),
    uptime: process.uptime()
  });
});

/**
 * Login endpoint
 * OWASP A01: Authentication
 * OWASP A03: Injection (input validation)
 * OWASP A04: DoS (rate limiting)
 */
app.post('/login', 
  authLimiter,
  body('username')
    .trim()
    .notEmpty().withMessage('Username is required')
    .isLength({ min: 3, max: 50 }).withMessage('Username must be 3-50 characters')
    .matches(/^[a-zA-Z0-9_-]+$/).withMessage('Username can only contain alphanumeric, underscore, and dash')
    .escape(),
  body('password')
    .notEmpty().withMessage('Password is required')
    .isLength({ min: 8 }).withMessage('Password must be at least 8 characters'),
  (req, res) => {
    try {
      // Validate input
      const errors = validationResult(req);
      if (!errors.isEmpty()) {
        logger.warn(`Login validation failed from ${req.ip}: ${JSON.stringify(errors.array())}`);
        return res.status(400).json({ 
          error: 'Validation failed',
          details: errors.array() 
        });
      }

      const { username, password } = req.body;

      // SECURITY: In production, validate against database with bcrypt hash
      // DO NOT store plain text passwords
      // Example:
      // const user = await User.findByUsername(username);
      // if (!user || !await bcrypt.compare(password, user.passwordHash)) {
      //   logger.warn(`Failed login for user: ${username}`);
      //   return res.status(401).json({ error: 'Invalid credentials' });
      // }

      // Demo authentication (NEVER use in production)
      if (username === 'testuser' && password === 'testpass123') {
        const user = { 
          id: 1, 
          username: 'testuser', 
          role: 'admin',
          email: 'test@example.com'
        };

        const token = jwt.sign(user, SECRET_KEY, { 
          expiresIn: '1h',
          algorithm: 'HS256'
        });

        logger.info(`Successful login for user: ${username}`);

        return res.json({ 
          token,
          expiresIn: 3600,
          tokenType: 'Bearer'
        });
      }

      logger.warn(`Failed login attempt for user: ${username} from ${req.ip}`);
      res.status(401).json({ 
        error: 'Invalid credentials',
        code: 'AUTH_FAILED'
      });
    } catch (error) {
      logger.error(`Login endpoint error: ${error.message}`, error);
      res.status(500).json({ error: 'Authentication error' });
    }
  }
);

/**
 * Get all users (admin only)
 * OWASP A01: Authentication & Authorization
 * OWASP A03: Injection (input validation)
 * OWASP A06: Vulnerable Components (no sensitive data)
 */
app.get('/users', 
  authenticateToken,
  authorizeRole('admin'),
  query('page')
    .optional()
    .isInt({ min: 1 }).toInt()
    .withMessage('Page must be a positive integer'),
  query('limit')
    .optional()
    .isInt({ min: 1, max: 100 }).toInt()
    .withMessage('Limit must be between 1 and 100'),
  (req, res) => {
    try {
      const errors = validationResult(req);
      if (!errors.isEmpty()) {
        return res.status(400).json({ 
          error: 'Validation failed',
          details: errors.array() 
        });
      }

      const page = req.query.page || 1;
      const limit = req.query.limit || 10;

      logger.info(`User ${req.user.id} (${req.user.username}) accessed /users endpoint (page: ${page}, limit: ${limit})`);

      // NOTE: Email addresses have been removed from this response to protect PII
      // OWASP A01: Data Minimization
      const users = [
        { id: 1, username: 'alice', role: 'user', createdAt: '2024-01-01T00:00:00Z' },
        { id: 2, username: 'bob', role: 'user', createdAt: '2024-01-02T00:00:00Z' },
      ];

      res.json({
        data: users,
        pagination: {
          page,
          limit,
          total: users.length,
          pages: Math.ceil(users.length / limit)
        }
      });
    } catch (error) {
      logger.error(`/users endpoint error: ${error.message}`, error);
      res.status(500).json({ error: 'Internal server error' });
    }
  }
);

/**
 * Get current user's profile
 * OWASP A01: Authentication
 */
app.get('/me', 
  authenticateToken,
  (req, res) => {
    try {
      logger.info(`User ${req.user.id} accessed /me endpoint`);

      res.json({
        id: req.user.id,
        username: req.user.username,
        role: req.user.role,
        email: req.user.email
      });
    } catch (error) {
      logger.error(`/me endpoint error: ${error.message}`, error);
      res.status(500).json({ error: 'Internal server error' });
    }
  }
);

/**
 * Logout endpoint (frontend should discard token)
 */
app.post('/logout', 
  authenticateToken,
  (req, res) => {
    try {
      logger.info(`User ${req.user.id} logged out`);

      // In production, you might want to invalidate tokens by:
      // - Adding token to a blacklist (Redis)
      // - Implementing token revocation in database

      res.json({ message: 'Logged out successfully' });
    } catch (error) {
      logger.error(`/logout endpoint error: ${error.message}`, error);
      res.status(500).json({ error: 'Logout error' });
    }
  }
);

// ==================== ERROR HANDLING ====================

/**
 * 404 Not Found handler
 * OWASP A05: Security Misconfiguration
 */
app.use((req, res) => {
  logger.warn(`404 Not Found: ${req.method} ${req.path} from ${req.ip}`);
  res.status(404).json({ 
    error: 'Endpoint not found',
    path: req.path,
    method: req.method
  });
});

/**
 * Global error handler
 * OWASP A07: Identification & Authentication Failures (no info leakage)
 */
app.use((err, req, res, next) => {
  const errorId = `ERR_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`;

  logger.error(`Error ${errorId}: ${err.message}`, {
    error: err,
    path: req.path,
    method: req.method,
    ip: req.ip,
    userId: req.user?.id
  });

  // Don't expose internal error details to client in production
  const response = {
    error: NODE_ENV === 'production' ? 'Internal server error' : err.message,
    errorId: NODE_ENV === 'production' ? errorId : undefined,
    code: err.code || 'INTERNAL_ERROR'
  };

  // Only include stack trace in development
  if (NODE_ENV === 'development') {
    response.stack = err.stack;
  }

  res.status(err.status || err.statusCode || 500).json(response);
});

// ==================== SERVER STARTUP ====================

const server = app.listen(PORT, () => {
  logger.info(`Server started on port ${PORT} (${NODE_ENV})`);
  console.log(`✓ Server running on http://localhost:${PORT}`);

  if (NODE_ENV === 'development') {
    console.log('⚠ WARNING: Running in development mode. Use production settings for deployment.');
  }
});

// Graceful shutdown
process.on('SIGTERM', () => {
  logger.info('SIGTERM signal received: closing HTTP server');
  server.close(() => {
    logger.info('HTTP server closed');
    process.exit(0);
  });
});

process.on('SIGINT', () => {
  logger.info('SIGINT signal received: closing HTTP server');
  server.close(() => {
    logger.info('HTTP server closed');
    process.exit(0);
  });
});

// Handle uncaught exceptions
process.on('uncaughtException', (error) => {
  logger.error('Uncaught Exception:', error);
  process.exit(1);
});

process.on('unhandledRejection', (reason, promise) => {
  logger.error('Unhandled Rejection at:', promise, 'reason:', reason);
  process.exit(1);
});

module.exports = app;

