// config/secrets.js
const path = require('path');
const fs = require('fs');

// Load .env file
require('dotenv').config({
  path: path.resolve(__dirname, '../.env')
});

// Validate required secrets
const requiredSecrets = [
  'JWT_SECRET',
  'NODE_ENV',
  'PORT'
];

const optionalSecrets = [
  'DATABASE_URL',
  'ALLOWED_ORIGINS',
  'SSL_KEY_PATH',
  'SSL_CERT_PATH'
];

// Validation function
function validateSecrets() {
  const errors = [];

  // Check required secrets
  for (const secret of requiredSecrets) {
    if (!process.env[secret]) {
      errors.push(`Missing required secret: ${secret}`);
    }
  }

  // Validate JWT_SECRET strength
  if (process.env.JWT_SECRET && process.env.JWT_SECRET.length < 32) {
    errors.push('JWT_SECRET must be at least 32 characters');
  }

  // Validate NODE_ENV
  const validEnvs = ['development', 'staging', 'production'];
  if (!validEnvs.includes(process.env.NODE_ENV)) {
    errors.push(`NODE_ENV must be one of: ${validEnvs.join(', ')}`);
  }

  // Validate PORT is numeric
  if (isNaN(parseInt(process.env.PORT))) {
    errors.push('PORT must be a valid number');
  }

  // If errors, fail fast
  if (errors.length > 0) {
    console.error('🔴 CONFIGURATION ERRORS:');
    errors.forEach(err => console.error(`   - ${err}`));
    process.exit(1);
  }

  console.log('✅ All secrets validated successfully');
}

// Get secret with fallback validation
function getSecret(name, options = {}) {
  const value = process.env[name];

  if (!value && options.required) {
    throw new Error(`Required secret not found: ${name}`);
  }

  // Validate minimum length if specified
  if (value && options.minLength && value.length < options.minLength) {
    throw new Error(`Secret ${name} too short (minimum: ${options.minLength})`);
  }

  // Validate format if specified
  if (value && options.pattern && !options.pattern.test(value)) {
    throw new Error(`Secret ${name} invalid format`);
  }

  return value || options.default;
}

module.exports = {
  validateSecrets,
  getSecret,
  // Exported secrets
  JWT_SECRET: getSecret('JWT_SECRET', {
    required: true,
    minLength: 32
  }),
  PORT: parseInt(getSecret('PORT', { default: '3000' })),
  NODE_ENV: getSecret('NODE_ENV', {
    default: 'development',
    pattern: /^(development|staging|production)$/
  }),
  ALLOWED_ORIGINS: getSecret('ALLOWED_ORIGINS', {
    default: 'http://localhost:3000'
  }),
  DATABASE_URL: getSecret('DATABASE_URL', {
    required: process.env.NODE_ENV === 'production'
  }),
  SSL_KEY_PATH: getSecret('SSL_KEY_PATH'),
  SSL_CERT_PATH: getSecret('SSL_CERT_PATH')
};
