### ✅ Solution 2: AWS Secrets Manager (Production)

For production deployments on AWS:

```javascript
// config/aws-secrets.js
const AWS = require('aws-sdk');
const client = new AWS.SecretsManager({
  region: process.env.AWS_REGION || 'us-east-1'
});

async function getSecret(secretName) {
  try {
    const data = await client.getSecretValue({ 
      SecretId: secretName 
    }).promise();

    if ('SecretString' in data) {
      return JSON.parse(data.SecretString);
    } else {
      return Buffer.from(data.SecretBinary, 'base64').toString('ascii');
    }
  } catch (error) {
    console.error(`Failed to retrieve secret: ${secretName}`);
    throw error;
  }
}

async function loadSecrets() {
  try {
    // Load all secrets in parallel
    const [appSecrets, dbSecrets] = await Promise.all([
      getSecret('app/production/secrets'),
      getSecret('app/production/database')
    ]);

    return {
      JWT_SECRET: appSecrets.jwt_secret,
      ALLOWED_ORIGINS: appSecrets.allowed_origins,
      DATABASE_URL: dbSecrets.connection_string,
      // ... other secrets
    };
  } catch (error) {
    console.error('Fatal: Could not load secrets from AWS Secrets Manager');
    process.exit(1);
  }
}

module.exports = {
  loadSecrets,
  getSecret
};
```

