// CRITICAL: Load environment variables FIRST
require('dotenv').config();

const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const jwt = require('jsonwebtoken');
const { query, body, validationResult } = require('express-validator');
const morgan = require('morgan');
const winston = require('winston');
const path = require('path');

const app = express();

// ==================== SECRETS CONFIGURATION ====================

/**
 * Secrets Validator Module
 * Ensures all required secrets are configured correctly
 */
class SecretsValidator {
  constructor() {
    this.errors = [];
    this.warnings = [];
  }

  validate() {
    // Check JWT_SECRET (CRITICAL)
    this.validateJWTSecret();

    // Check NODE_ENV
    this.validateNodeEnv();

    // Check PORT
    this.validatePort();

    // Check ALLOWED_ORIGINS
    this.validateAllowedOrigins();

    // Check production-specific secrets
    if (process.env.NODE_ENV === 'production') {
      this.validateProductionSecrets();
    }

    // Report errors and warnings
    this.report();
  }

  validateJWTSecret() {
    const secret = process.env.JWT_SECRET;

    // Check if present
    if (!secret) {
      this.errors.push('JWT_SECRET is not set (CRITICAL - cannot sign tokens)');
      return;
    }

    // Check length
    if (secret.length < 32) {
      this.errors.push(`JWT_SECRET too short: ${secret.length} chars (minimum: 32)`);
    }

    // Check for common placeholder values
    const placeholders = [
      'change-this',
      'changeme',
      'your-secret',
      'secret',
      'password',
      'key'
    ];

    if (placeholders.some(p => secret.toLowerCase().includes(p))) {
      this.errors.push('JWT_SECRET appears to be a placeholder value');
    }

    // Check if it looks randomly generated
    // A proper secret should have good entropy
    const uniqueChars = new Set(secret).size;
    if (uniqueChars < 20) {
      this.warnings.push(`JWT_SECRET has low entropy (${uniqueChars} unique chars)`);
    }
  }

  validateNodeEnv() {
    const nodeEnv = process.env.NODE_ENV;
    const validEnvs = ['development', 'staging', 'production'];

    if (!nodeEnv) {
      this.warnings.push('NODE_ENV not set, defaulting to development');
      return;
    }

    if (!validEnvs.includes(nodeEnv)) {
      this.errors.push(`Invalid NODE_ENV: "${nodeEnv}" (must be: ${validEnvs.join(', ')})`);
    }
  }

  validatePort() {
    const port = process.env.PORT;

    if (!port) {
      this.warnings.push('PORT not set, defaulting to 3000');
      return;
    }

    const portNum = parseInt(port);
    if (isNaN(portNum)) {
      this.errors.push(`PORT is not a valid number: ${port}`);
    } else if (portNum < 1 || portNum > 65535) {
      this.errors.push(`PORT out of valid range: ${portNum} (must be 1-65535)`);
    }
  }

  validateAllowedOrigins() {
    const origins = process.env.ALLOWED_ORIGINS;

    if (!origins) {
      this.warnings.push('ALLOWED_ORIGINS not set, using default (localhost)');
      return;
    }

    // Validate URL format
    const urlRegex = /^https?:\/\/.+/i;
    const originList = origins.split(',');

    for (const origin of originList) {
      const trimmed = origin.trim();
      if (!urlRegex.test(trimmed)) {
        this.errors.push(`Invalid ALLOWED_ORIGINS format: "${trimmed}"`);
      }
    }
  }

  validateProductionSecrets() {
    // In production, additional secrets are required

    // DATABASE_URL (if using database)
    if (process.env.DATABASE_URL) {
      if (!process.env.DATABASE_URL.includes('://')) {
        this.errors.push('DATABASE_URL invalid format');
      }
    }

    // SSL certificate paths (if using HTTPS)
    if (process.env.SSL_KEY_PATH && !process.env.SSL_CERT_PATH) {
      this.errors.push('SSL_CERT_PATH required when SSL_KEY_PATH is set');
    }

    if (process.env.SSL_CERT_PATH && !process.env.SSL_KEY_PATH) {
      this.errors.push('SSL_KEY_PATH required when SSL_CERT_PATH is set');
    }
  }

  report() {
    // Report warnings
    if (this.warnings.length > 0) {
      console.warn('⚠️  CONFIGURATION WARNINGS:');
      this.warnings.forEach(w => console.warn(`   - ${w}`));
      console.warn('');
    }

    // Report errors and fail if any
    if (this.errors.length > 0) {
      console.error('🔴 CONFIGURATION ERRORS:');
      this.errors.forEach(e => console.error(`   - ${e}`));
      console.error('');
      console.error('Please fix these configuration issues before continuing.');
      process.exit(1);
    }
  }
}

// Safe secrets getter - no fallbacks!
function getSecret(name, options = {}) {
  const value = process.env[name];

  if (!value) {
    if (options.required) {
      throw new Error(`Required secret not configured: ${name}`);
    }
    return options.default;
  }

  return value;
}

