      logger.warn(`Unauthorized access attempt (no token) from ${req.ip} to ${req.path}`);
      return res.status(401).json({ 
        error: 'Access token required',
        code: 'NO_TOKEN'
      });
    }

    const parts = authHeader.split(' ');
    if (parts.length !== 2 || parts[0] !== 'Bearer') {
      logger.warn(`Invalid authorization header from ${req.ip}`);
      return res.status(401).json({ 
        error: 'Invalid authorization header',
        code: 'INVALID_FORMAT'
      });
    }

    const token = parts[1];

    jwt.verify(token, SECRET_KEY, (err, user) => {
      if (err) {
        logger.warn(`Invalid token from ${req.ip}: ${err.message}`);
        return res.status(403).json({ 
          error: 'Invalid or expired token',
          code: 'INVALID_TOKEN'
        });
      }

      req.user = user;
      next();
    });
  } catch (error) {
    logger.error(`Authentication error: ${error.message}`, error);
    res.status(500).json({ error: 'Authentication error' });
  }
}

function authorizeRole(requiredRole) {
  return (req, res, next) => {
    if (!req.user || !req.user.role) {
      logger.warn(`Authorization check failed from ${req.ip}`);
      return res.status(401).json({ error: 'User not authenticated' });
    }

    if (req.user.role !== requiredRole && requiredRole !== '*') {
      logger.warn(`Authorization denied for user ${req.user.id}: has '${req.user.role}', required '${requiredRole}'`);
      return res.status(403).json({ 
        error: 'Insufficient permissions',
        code: 'FORBIDDEN'
      });
    }

    next();
  };
}

// ==================== ROUTES ====================

app.get('/health', (req, res) => {
  res.json({ 
    status: 'ok', 
    timestamp: new Date().toISOString(),
    uptime: process.uptime()
  });
});

app.post('/login', 
  authLimiter,
  body('username')
    .trim()
    .notEmpty().withMessage('Username required')
    .isLength({ min: 3, max: 50 }).withMessage('Username 3-50 chars')
    .matches(/^[a-zA-Z0-9_-]+$/).withMessage('Invalid username format')
    .escape(),
  body('password')
    .notEmpty().withMessage('Password required')
    .isLength({ min: 8 }).withMessage('Password minimum 8 chars'),
  (req, res) => {
    try {
      const errors = validationResult(req);
      if (!errors.isEmpty()) {
        logger.warn(`Login validation failed from ${req.ip}`);
        return res.status(400).json({ error: 'Validation failed', details: errors.array() });
      }

      const { username, password } = req.body;

      // Demo auth - in production use bcrypt + database
      if (username === 'testuser' && password === 'testpass123') {
        const user = { 
          id: 1, 
          username: 'testuser', 
          role: 'admin'
        };

        const token = jwt.sign(user, SECRET_KEY, { 
          expiresIn: '1h',
          algorithm: 'HS256'
        });

        logger.info(`Successful login for user: ${username}`);

        return res.json({ 
          token,
          expiresIn: 3600,
          tokenType: 'Bearer'
        });
      }

      logger.warn(`Failed login attempt for user: ${username} from ${req.ip}`);
      res.status(401).json({ error: 'Invalid credentials' });
    } catch (error) {
      logger.error(`Login error: ${error.message}`, error);
      res.status(500).json({ error: 'Authentication error' });
    }
  }
);

app.get('/users', 
  authenticateToken,
  authorizeRole('admin'),
  (req, res) => {
    try {
      logger.info(`User ${req.user.id} accessed /users endpoint`);

      // No PII exposed
      const users = [
        { id: 1, username: 'alice', role: 'user' },
        { id: 2, username: 'bob', role: 'user' },
      ];

      res.json({ data: users });
    } catch (error) {
      logger.error(`/users error: ${error.message}`, error);
      res.status(500).json({ error: 'Internal error' });
    }
  }
);

app.get('/me', 
  authenticateToken,
  (req, res) => {
    try {
      logger.info(`User ${req.user.id} accessed /me endpoint`);
      res.json({
        id: req.user.id,
        username: req.user.username,
        role: req.user.role
      });
    } catch (error) {
      logger.error(`/me error: ${error.message}`, error);
      res.status(500).json({ error: 'Internal error' });
    }
  }
);

// ==================== ERROR HANDLING ====================

app.use((req, res) => {
  logger.warn(`404: ${req.method} ${req.path} from ${req.ip}`);
  res.status(404).json({ error: 'Endpoint not found' });
});

app.use((err, req, res, next) => {
  const errorId = `ERR_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`;

  logger.error(`Error ${errorId}: ${err.message}`, {
    error: err,
    path: req.path,
    method: req.method,
    ip: req.ip
  });

  const response = {
    error: NODE_ENV === 'production' ? 'Internal server error' : err.message,
    errorId: NODE_ENV === 'production' ? errorId : undefined,
    code: err.code || 'INTERNAL_ERROR'
  };

  if (NODE_ENV === 'development') {
    response.stack = err.stack;
  }

  res.status(err.status || 500).json(response);
});

// ==================== SERVER STARTUP ====================

const server = app.listen(PORT, () => {
  logger.info(`✅ Server started successfully`, {
    PORT,
    NODE_ENV,
    secrets_loaded: true,
    timestamp: new Date().toISOString()
  });
  console.log(`✅ Server running on http://localhost:${PORT}`);
  console.log(`📊 Environment: ${NODE_ENV}`);
  console.log(`🔒 Secrets: ✅ Loaded and validated`);
});

// Graceful shutdown
process.on('SIGTERM', () => {
  logger.info('SIGTERM received, closing server');
  server.close(() => {
    logger.info('Server closed');
    process.exit(0);
  });
});

process.on('SIGINT', () => {
  logger.info('SIGINT received, closing server');
  server.close(() => {
    logger.info('Server closed');
    process.exit(0);
  });
});

process.on('uncaughtException', (error) => {
  logger.error('Uncaught exception', error);
  process.exit(1);
});

process.on('unhandledRejection', (reason, promise) => {
  logger.error('Unhandled rejection', { reason, promise });
  process.exit(1);
});

module.exports = app;

