// Secure version of app.js with all recommended security measures implemented

require('dotenv').config();
const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const mongoSanitize = require('express-mongo-sanitize');
const jwt = require('jsonwebtoken');
const { body, query, validationResult } = require('express-validator');
const morgan = require('morgan');
const fs = require('fs');
const path = require('path');

const app = express();

// ============= SECURITY CONFIGURATION =============

// 1. HELMET - Set security HTTP headers
app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      scriptSrc: ["'self'"],
      styleSrc: ["'self'", "'unsafe-inline'"],
      imgSrc: ["'self'", 'data:', 'https:']
    }
  },
  hsts: {
    maxAge: 31536000, // 1 year
    includeSubDomains: true,
    preload: true
  }
}));

// 2. SANITIZATION - Prevent NoSQL injection
app.use(mongoSanitize());

// 3. CORS - Whitelist allowed origins
const corsOptions = {
  origin: (process.env.ALLOWED_ORIGINS || 'http://localhost:3000').split(','),
  credentials: true,
  methods: ['GET', 'POST', 'PUT', 'DELETE', 'OPTIONS'],
  allowedHeaders: ['Content-Type', 'Authorization'],
  optionsSuccessStatus: 200,
  maxAge: 86400 // 24 hours
};
app.use(cors(corsOptions));

// 4. REQUEST SIZE LIMITS - Prevent buffer overflow attacks
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ limit: '10kb', extended: true }));

// 5. HTTPS ENFORCEMENT
if (process.env.NODE_ENV === 'production') {
  app.use((req, res, next) => {
    if (!req.secure && req.get('x-forwarded-proto') !== 'https') {
      return res.redirect(307, `https://${req.get('host')}${req.originalUrl}`);
    }
    next();
  });
}

// 6. LOGGING - Morgan for request logging
const logsDir = path.join(__dirname, 'logs');
if (!fs.existsSync(logsDir)) {
  fs.mkdirSync(logsDir);
}

const accessLogStream = fs.createWriteStream(
  path.join(logsDir, 'access.log'),
  { flags: 'a' }
);

morgan.token('user-id', (req) => req.user?.id || 'anonymous');

const morganFormat = ':remote-addr - :user-id [:date[clf]] ":method :url HTTP/:http-version" :status :res[content-length] ":referrer" ":user-agent"';

app.use(morgan(morganFormat, { stream: accessLogStream }));

if (process.env.NODE_ENV !== 'production') {
  app.use(morgan(morganFormat)); // Console logging in development
}

// 7. RATE LIMITING
const generalLimiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later',
  standardHeaders: true,
  legacyHeaders: false,
  skip: (req) => {
    // Skip rate limiting for health checks from localhost
    return req.ip === '127.0.0.1' && req.path === '/health';
  }
});

const authLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 5, // 5 login attempts per 15 minutes
  message: 'Too many login attempts, please try again later',
  standardHeaders: true,
  legacyHeaders: false,
  skipSuccessfulRequests: true
});

app.use(generalLimiter);

// ============= AUTHENTICATION MIDDLEWARE =============

/**
 * Middleware to authenticate JWT tokens
 */
const authenticateToken = (req, res, next) => {
  const authHeader = req.headers['authorization'];
  const token = authHeader && authHeader.split(' ')[1]; // Extract token from "Bearer TOKEN"

  if (!token) {
    return res.status(401).json({
      error: 'Access token required',
      code: 'NO_TOKEN'
    });
  }

  jwt.verify(token, process.env.JWT_SECRET || 'your-secret-key', (err, user) => {
    if (err) {
      const statusCode = err.name === 'TokenExpiredError' ? 401 : 403;
      return res.status(statusCode).json({
        error: err.name === 'TokenExpiredError' ? 'Token expired' : 'Invalid token',
        code: err.name
      });
    }

    req.user = user;
    next();
  });
};

/**
 * Authorization middleware to check user roles
 */
const authorize = (requiredRoles) => {
  return (req, res, next) => {
    if (!req.user) {
      return res.status(401).json({ error: 'Not authenticated' });
    }

    if (!requiredRoles.includes(req.user.role)) {
      console.warn(`[SECURITY] Unauthorized access attempt by user ${req.user.id} to protected resource`);
      return res.status(403).json({
        error: 'Insufficient permissions',
        required: requiredRoles,
        current: req.user.role
      });
    }

    next();
  };
};

// ============= ROUTES =============

/**
 * Health check endpoint - Public, no auth required
 */
app.get('/health', (req, res) => {
  res.json({
    status: 'ok',
    timestamp: new Date().toISOString(),
    environment: process.env.NODE_ENV || 'development'
  });
});

/**
 * Get users - Protected endpoint with validation and authorization
 */
app.get('/users',
  authenticateToken,
  authorize(['admin']), // Only admins can access
  query('limit')
    .optional()
    .isInt({ min: 1, max: 100 })
    .withMessage('Limit must be between 1 and 100')
    .toInt(),
  query('offset')
    .optional()
    .isInt({ min: 0 })
    .withMessage('Offset must be a non-negative integer')
    .toInt(),
  (req, res) => {
    // Validate query parameters
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({
        error: 'Invalid query parameters',
        details: errors.array()
      });
    }

    const limit = req.query.limit || 10;
    const offset = req.query.offset || 0;

    // Mock data - In real app, fetch from database
    const allUsers = [
      { id: 1, name: 'Alice', email: 'alice@example.com', role: 'admin' },
      { id: 2, name: 'Bob', email: 'bob@example.com', role: 'user' },
    ];

    // Paginate results
    const users = allUsers.slice(offset, offset + limit);

    // Log successful admin access
    console.log(`[AUDIT] User ${req.user.id} (${req.user.role}) accessed /users endpoint`);

    res.json({
      success: true,
      data: users,
      pagination: {
        limit,
        offset,
        total: allUsers.length
      }
    });
  }
);

/**
 * Get user by ID - Protected endpoint with ID validation
 */
app.get('/users/:id',
  authenticateToken,
  query('id')
    .isInt({ min: 1 })
    .withMessage('User ID must be a positive integer'),
  (req, res) => {
    // Validate ID format
    const id = parseInt(req.params.id);
    if (isNaN(id) || id < 1) {
      return res.status(400).json({
        error: 'Invalid user ID format'
      });
    }

    // Authorization check - Users can only view their own profile unless admin
    if (req.user.role !== 'admin' && req.user.id !== id) {
      console.warn(`[SECURITY] Unauthorized access attempt by user ${req.user.id} to user ${id} profile`);
      return res.status(403).json({
        error: 'Cannot access other users data'
      });
    }

    // Mock data
    const mockUsers = {
      1: { id: 1, name: 'Alice', email: 'alice@example.com', role: 'admin' },
      2: { id: 2, name: 'Bob', email: 'bob@example.com', role: 'user' },
    };

    const user = mockUsers[id];
    if (!user) {
      return res.status(404).json({ error: 'User not found' });
    }

    // Mask sensitive data for non-admin users
    if (req.user.role !== 'admin') {
      user.email = user.email.replace(/(.{2})(.*)(@.*)/, '$1***$3');
    }

    res.json({ success: true, data: user });
  }
);

/**
 * Create new user - Protected endpoint with input validation
 */
app.post('/users',
  authenticateToken,
  authorize(['admin']),
  authLimiter, // Additional rate limiting for sensitive operation
  body('name')
    .trim()
    .notEmpty().withMessage('Name is required')
    .isLength({ min: 1, max: 100 }).withMessage('Name must be 1-100 characters')
    .escape(), // XSS protection
  body('email')
    .isEmail().normalizeEmail()
    .withMessage('Valid email is required'),
  body('role')
    .isIn(['user', 'admin']).withMessage('Role must be user or admin'),
  (req, res) => {
    // Validate input
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({
        error: 'Validation failed',
        details: errors.array()
      });
    }

    const { name, email, role } = req.body;

    // In real app: Check if user exists, hash password, save to database
    console.log(`[AUDIT] User ${req.user.id} created new user: ${email}`);

    res.status(201).json({
      success: true,
      message: 'User created successfully',
      data: { id: 3, name, email, role }
    });
  }
);

/**
 * Login endpoint - No auth required, but rate limited
 */
app.post('/login',
  authLimiter,
  body('email').isEmail().normalizeEmail(),
  body('password').notEmpty(),
  (req, res) => {
    // Validate input
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({
        error: 'Invalid credentials'
      });
    }

    const { email, password } = req.body;

    // In real app: Query database, hash verification, etc.
