# Result: User with ID 1 returned safely

# Invalid ID:
curl "http://localhost:3000/users/invalid?id=invalid"
# Result: 400 - "User ID must be a positive integer"

# SQL injection attempt:
curl "http://localhost:3000/users/1 OR 1=1?id=1 OR 1=1"
# Result: 400 - Rejected by validator
# No SQL injection possible with parameterized query
