### Solution 2: Use AWS Secrets Manager (AWS)

**Priority: HIGH (for AWS environments)**

```javascript
// Install: npm install @aws-sdk/client-secrets-manager

const { SecretsManagerClient, GetSecretValueCommand } = require('@aws-sdk/client-secrets-manager');

class SecretsManager {
  constructor() {
    this.client = new SecretsManagerClient({ region: process.env.AWS_REGION });
    this.cache = {};
  }

  async getSecret(secretName) {
    // Check cache first
    if (this.cache[secretName]) {
      return this.cache[secretName];
    }

    try {
      const response = await this.client.send(
        new GetSecretValueCommand({ SecretId: secretName })
      );

      let secret;
      if ('SecretString' in response) {
        secret = JSON.parse(response.SecretString);
      } else {
        secret = Buffer.from(response.SecretBinary, 'base64').toString('ascii');
      }

      // Cache for 1 hour
      this.cache[secretName] = secret;
      setTimeout(() => delete this.cache[secretName], 3600000);

      return secret;
    } catch (error) {
      console.error(`Failed to retrieve secret: ${secretName}`, error);
      throw error;
    }
  }
}

// Usage
const secretsManager = new SecretsManager();

const jwtSecret = await secretsManager.getSecret('production/jwt-secret');
const dbUrl = await secretsManager.getSecret('production/database-url');
