      // Check database URL security
      if (secretName === 'DATABASE_URL') {
        if (process.env.NODE_ENV === 'production') {
          if (!value.startsWith('postgres://') && !value.startsWith('mongodb://')) {
            console.warn(`⚠️  Verify DATABASE_URL scheme for: ${secretName}`);
          }
        }
      }
    }

    if (missing.length > 0) {
      throw new Error(
        `Missing required secrets: ${missing.join(', ')}. ` +
        'Please set these environment variables or configure your secrets backend.'
      );
    }

    if (weak.length > 0) {
      const message = `⚠️  Weak secrets detected: ${weak.join(', ')}`;
      console.warn(`[SecretsManager] ${message}`);

      if (process.env.NODE_ENV === 'production') {
        throw new Error(message);
      }
    }

    console.log('  ✓ All secrets validated');
  }

  /**
   * Get a secret by name
   */
  get(secretName) {
    if (!this.validated) {
      throw new Error(
        'SecretsManager not validated. Call initialize() first.'
      );
    }

    const value = this.secrets[secretName];

    if (!value) {
      throw new Error(`Secret not found: ${secretName}`);
    }

    return value;
  }

  /**
   * Map AWS secret names to local keys
   */
  mapSecretName(awsName) {
    const mapping = {
      'production/jwt-secret': 'JWT_SECRET',
      'production/database-url': 'DATABASE_URL',
      'production/stripe-key': 'STRIPE_SECRET_KEY',
      'production/anthropic-key': 'ANTHROPIC_API_KEY',
      'production/logfire-token': 'LOGFIRE_TOKEN'
    };
    return mapping[awsName] || awsName;
  }

  /**
   * Get all secrets (use with caution - only for logging to non-sensitive outputs)
   */
  getAllSecrets() {
    if (!this.validated) {
      throw new Error('SecretsManager not validated.');
    }

    return { ...this.secrets };
  }

  /**
   * Rotate a secret (requires manual update in secrets backend)
   */
  async rotate(secretName) {
    console.log(`[SecretsManager] Rotating secret: ${secretName}`);
    console.log(`Please update ${secretName} in your secrets backend`);
    console.log('Restart the application to load the new secret');
  }
}

// Singleton instance
const manager = new SecretsManager();

module.exports = manager;
```

