### 8. **MEDIUM: Logging Sensitive Data Risk**

**Severity:** 🟡 MEDIUM  
**OWASP:** A09:2021 – Logging and Monitoring Failures

#### Issue:
If credentials or sensitive data are logged, they could be exposed in logs.

#### Recommendations:

**8.1 - Implement Safe Logging**
```javascript
const express = require('express');
const winston = require('winston');
const app = express();

// Create logger
const logger = winston.createLogger({
  level: process.env.LOG_LEVEL || 'info',
  format: winston.format.json(),
  transports: [
    new winston.transports.File({ 
      filename: 'error.log', 
      level: 'error',
      maxsize: 5242880, // 5MB
      maxFiles: 5,
    }),
    new winston.transports.File({ 
      filename: 'combined.log',
      maxsize: 5242880,
      maxFiles: 5,
    }),
  ],
});

if (process.env.NODE_ENV !== 'production') {
  logger.add(new winston.transports.Console({
    format: winston.format.simple(),
  }));
}

// Sanitize sensitive data before logging
const sanitize = (obj) => {
  const sanitized = JSON.parse(JSON.stringify(obj));
  const sensitiveKeys = ['password', 'token', 'secret', 'key', 'authorization'];

  const sanitizeObj = (obj) => {
    for (const key in obj) {
      if (sensitiveKeys.some(sensitive => key.toLowerCase().includes(sensitive))) {
        obj[key] = '[REDACTED]';
      } else if (typeof obj[key] === 'object' && obj[key] !== null) {
        sanitizeObj(obj[key]);
      }
    }
  };

  sanitizeObj(sanitized);
  return sanitized;
};

// Middleware to log requests (without sensitive data)
app.use((req, res, next) => {
  logger.info({
    method: req.method,
    url: req.url,
    ip: req.ip,
    body: sanitize(req.body),
  });
  next();
});

app.listen(3000);
```

