### 9. **MEDIUM: No Error Handling / Information Disclosure**

**Severity:** 🟡 MEDIUM  
**OWASP:** A01:2021 – Broken Access Control

#### Issue:
Stack traces and error details could leak sensitive information about the application architecture.

#### Recommendations:

**9.1 - Implement Proper Error Handling**
```javascript
const express = require('express');
const app = express();

// Error handling middleware
app.use((err, req, res, next) => {
  const logger = require('./logger'); // Your logger instance

  // Log full error for debugging (with stack trace)
  logger.error({
    message: err.message,
    stack: err.stack,
    url: req.url,
    method: req.method,
    timestamp: new Date().toISOString(),
  });

  // Don't expose error details to client in production
  const response = {
    message: process.env.NODE_ENV === 'production' 
      ? 'Internal Server Error' 
      : err.message,
  };

  if (process.env.NODE_ENV === 'production') {
    // Only include error ID for customer support reference
    response.errorId = `ERR-${Date.now()}`;
  } else {
    response.stack = err.stack;
  }

  res.status(err.status || 500).json(response);
});

// 404 handler
app.use((req, res) => {
  res.status(404).json({ 
    message: 'Not Found',
    path: process.env.NODE_ENV === 'production' ? undefined : req.path,
  });
});

app.listen(3000);
```

