    // 3. Verify rate limiting is independent per user
    // (User 1 shouldn't affect User 2's rate limit)
    const token2 = jwt.sign(
      { id: 2, role: 'user' },
      process.env.JWT_SECRET || 'test-secret'
    );

    const userRes2 = await request(app)
      .get('/users/2')
      .set('Authorization', `Bearer ${token2}`)
      .expect(403); // Different user, so forbidden
  });

  test('should prevent privilege escalation', async () => {
    const userToken = jwt.sign(
      { id: 1, role: 'user' },
      process.env.JWT_SECRET || 'test-secret'
    );

    // User tries to modify their own token to be admin
    const tamperToken = jwt.sign(
      { id: 1, role: 'admin' },
      'wrong-secret' // Different secret
    );

    const res = await request(app)
      .get('/users')
      .set('Authorization', `Bearer ${tamperToken}`)
      .expect(403); // Should fail verification
  });
});

module.exports = {
  validToken,
  adminToken,
