### Best Practice 2: Implement Secret Rotation

```javascript
// AWS Lambda function to rotate secrets
exports.rotateSecret = async (event) => {
  const {
    SecretId,
    ClientRequestToken,
    Step,
    SecretVersion
  } = event;

  const client = new SecretsManagerClient();

  if (Step === 'create-secret') {
    // Generate new secret
    const newSecret = generateNewSecret();

    await client.send(new PutSecretValueCommand({
      SecretId,
      ClientRequestToken,
      SecretString: JSON.stringify(newSecret)
    }));
  }

  if (Step === 'set-secret') {
    // Update application to use new secret
    const secret = await getSecretValue(SecretId, SecretVersion);
    await updateApplicationSecret(secret);
  }

  if (Step === 'finish-secret') {
    // Verify rotation worked
    const isValid = await validateSecret(SecretId, SecretVersion);
    if (!isValid) throw new Error('Rotation validation failed');
  }

  if (Step === 'test-secret') {
    // Test the new secret
    const isWorking = await testSecret(SecretId, SecretVersion);
    if (!isWorking) throw new Error('Secret test failed');
  }
};
```

