/**
 * AWS Secrets Manager Integration for Express.js
 * Production-ready implementation
 */

const { SecretsManagerClient, GetSecretValueCommand, DescribeSecretCommand } = require('@aws-sdk/client-secrets-manager');
const logger = require('./logger');

/**
 * Cache implementation for secrets
 * Reduces API calls and improves performance
 */
class SecretsCache {
  constructor(ttlMs = 60 * 60 * 1000) { // 1 hour default
    this.cache = new Map();
    this.ttlMs = ttlMs;
  }

  set(key, value) {
    this.cache.set(key, {
      value,
      expiresAt: Date.now() + this.ttlMs
    });
    logger.debug(`Secret cached: ${key}`);
  }

  get(key) {
    const entry = this.cache.get(key);

    if (!entry) {
      return null;
    }

    if (Date.now() > entry.expiresAt) {
      this.cache.delete(key);
      logger.debug(`Secret cache expired: ${key}`);
      return null;
    }

    logger.debug(`Secret served from cache: ${key}`);
    return entry.value;
  }

  clear(key) {
    if (key) {
      this.cache.delete(key);
      logger.debug(`Secret cache cleared: ${key}`);
    } else {
      this.cache.clear();
      logger.debug('All secret cache cleared');
    }
  }

  size() {
    return this.cache.size;
  }
}

/**
 * Secrets Manager Client
 * Handles all secret retrieval and caching
 */
class SecretsManager {
  constructor(options = {}) {
    this.region = options.region || process.env.AWS_REGION || 'us-east-1';
    this.environment = options.environment || process.env.NODE_ENV || 'development';
    this.cache = new SecretsCache(options.cacheTtlMs);

    // Only initialize AWS client in production
    if (this.environment === 'production') {
      this.client = new SecretsManagerClient({ region: this.region });
    }

    // Track metrics
    this.metrics = {
      totalRequests: 0,
      cacheHits: 0,
      cacheMisses: 0,
      errors: 0
    };
  }

  /**
   * Get a single secret value
   * Automatically cached and refreshed
   */
  async getSecret(secretName, options = {}) {
    this.metrics.totalRequests++;

    const cacheKey = `${this.environment}:${secretName}`;

    // Check cache first
    const cached = this.cache.get(cacheKey);
    if (cached) {
      this.metrics.cacheHits++;
      return cached;
    }

    // In development, use .env file
    if (this.environment !== 'production') {
      return this._getLocalSecret(secretName);
    }

    this.metrics.cacheMisses++;

    try {
      logger.info(`Retrieving secret: ${secretName}`);

      const response = await this.client.send(
        new GetSecretValueCommand({ SecretId: secretName })
      );

      const secretValue = response.SecretString 
        ? JSON.parse(response.SecretString)
        : response.SecretBinary;

      // Cache the secret
      this.cache.set(cacheKey, secretValue);

      logger.info(`Secret retrieved successfully: ${secretName}`);

      return secretValue;
    } catch (error) {
      this.metrics.errors++;
      logger.error({
        message: `Failed to retrieve secret: ${secretName}`,
        error: error.message,
        code: error.$metadata?.httpStatusCode
      });

      // Fallback to environment variable if secret retrieval fails
      if (options.fallback) {
        logger.warn(`Using fallback for secret: ${secretName}`);
        return this._getLocalSecret(secretName);
      }

      throw new Error(`Failed to retrieve secret ${secretName}: ${error.message}`);
    }
  }

  /**
   * Get multiple secrets at once
   * More efficient than individual calls
   */
  async getSecrets(secretNames = []) {
    const secrets = {};

    for (const name of secretNames) {
      try {
        secrets[name] = await this.getSecret(name);
      } catch (error) {
        logger.error(`Failed to load secret ${name}: ${error.message}`);
        // Continue loading other secrets even if one fails
      }
    }

    return secrets;
  }

  /**
   * Get all application secrets
   * Convenience method for common secrets
   */
  async getAllAppSecrets() {
    const requiredSecrets = [
      'app/jwt-secret',
      'app/database-url',
      'app/stripe-key',
      'app/anthropic-api-key',
      'app/logfire-token'
    ];

    return this.getSecrets(requiredSecrets);
  }

  /**
   * Get secret for local development (from environment)
   */
  _getLocalSecret(secretName) {
    // Map secret names to environment variables
    const secretMap = {
      'app/jwt-secret': 'JWT_SECRET',
      'app/database-url': 'DATABASE_URL',
      'app/stripe-key': 'STRIPE_SECRET_KEY',
      'app/anthropic-api-key': 'ANTHROPIC_API_KEY',
      'app/logfire-token': 'LOGFIRE_TOKEN'
    };

    const envVar = secretMap[secretName];
    if (!envVar || !process.env[envVar]) {
      throw new Error(`Secret ${secretName} not found in environment`);
    }

    return process.env[envVar];
  }

  /**
   * Refresh a specific secret (force reload from Secrets Manager)
   */
  async refreshSecret(secretName) {
    const cacheKey = `${this.environment}:${secretName}`;
    this.cache.clear(cacheKey);
    return this.getSecret(secretName);
  }

  /**
   * Refresh all cached secrets
   */
  async refreshAllSecrets() {
    this.cache.clear();
    logger.info('All secrets cache cleared');
  }

  /**
   * Validate secret exists and is accessible
   */
  async validateSecret(secretName) {
    if (this.environment !== 'production') {
      return { valid: true, reason: 'Development mode' };
    }

    try {
      await this.client.send(
        new DescribeSecretCommand({ SecretId: secretName })
      );
      return { valid: true };
    } catch (error) {
      return { 
        valid: false, 
        reason: error.message 
      };
    }
  }

  /**
   * Get metrics about secrets manager performance
   */
  getMetrics() {
    return {
      ...this.metrics,
      cacheSize: this.cache.size(),
      hitRate: this.metrics.totalRequests > 0 
        ? ((this.metrics.cacheHits / this.metrics.totalRequests) * 100).toFixed(2) + '%'
        : 'N/A'
    };
  }

  /**
   * Reset metrics
   */
  resetMetrics() {
    this.metrics = {
      totalRequests: 0,
      cacheHits: 0,
      cacheMisses: 0,
      errors: 0
    };
  }
}

module.exports = SecretsManager;

/**
 * Usage Examples:
 * 
 * // Initialize
 * const SecretsManager = require('./secrets-manager');
 * const secretsManager = new SecretsManager({
 *   region: 'us-east-1',
 *   environment: process.env.NODE_ENV,
 *   cacheTtlMs: 60 * 60 * 1000 // 1 hour
 * });
 * 
 * // Get single secret
 * const jwtSecret = await secretsManager.getSecret('app/jwt-secret');
 * 
 * // Get all secrets
 * const secrets = await secretsManager.getAllAppSecrets();
 * 
 * // In Express middleware
 * app.use(async (req, res, next) => {
 *   req.secrets = await secretsManager.getAllAppSecrets();
 *   next();
 * });
 * 
 * // Refresh cache
 * app.post('/admin/refresh-secrets', authenticateToken, async (req, res) => {
 *   await secretsManager.refreshAllSecrets();
 *   res.json({ message: 'Secrets refreshed' });
 * });
 * 
 * // Get metrics
 * app.get('/admin/secrets-metrics', authenticateToken, (req, res) => {
 *   res.json(secretsManager.getMetrics());
 * });
 */

/**
 * Secure Express Application with AWS Secrets Manager
 * Production-ready implementation
 */

const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const jwt = require('jsonwebtoken');
const { body, param, validationResult } = require('express-validator');
const winston = require('winston');
const SecretsManager = require('./secrets-manager');

// ============================================
// CONFIGURATION
// ============================================

const NODE_ENV = process.env.NODE_ENV || 'development';
const PORT = process.env.PORT || 3000;

// For development, load .env
if (NODE_ENV !== 'production') {
  require('dotenv').config();
}

// ============================================
// LOGGER SETUP
// ============================================

const logger = winston.createLogger({
  level: process.env.LOG_LEVEL || 'info',
  format: winston.format.json(),
  transports: [
    new winston.transports.File({ filename: 'error.log', level: 'error' }),
    new winston.transports.File({ filename: 'combined.log' }),
  ],
});

if (NODE_ENV !== 'production') {
  logger.add(new winston.transports.Console({
    format: winston.format.simple(),
  }));
}

// ============================================
// SECRETS MANAGER INITIALIZATION
// ============================================

const secretsManager = new SecretsManager({
  region: process.env.AWS_REGION || 'us-east-1',
  environment: NODE_ENV,
  cacheTtlMs: 60 * 60 * 1000, // 1 hour cache
});

// Store loaded secrets globally (cached in SecretsManager)
let appSecrets = null;

async function loadSecrets() {
  try {
    logger.info('Loading application secrets...');

    const requiredSecrets = [
      'app/jwt-secret',
      'app/database-url',
      'app/allowed-origins'
    ];

    appSecrets = await secretsManager.getSecrets(requiredSecrets);

    if (!appSecrets['app/jwt-secret']) {
      throw new Error('JWT_SECRET not found in secrets');
    }

    logger.info('Secrets loaded successfully');
    return appSecrets;
  } catch (error) {
    logger.error({
      message: 'Failed to load secrets',
      error: error.message
    });

    // In development, this is non-fatal (env vars are used)
    if (NODE_ENV === 'production') {
      process.exit(1); // Critical failure in production
    }
  }
}

// ============================================
// EXPRESS APPLICATION SETUP
// ============================================

const app = express();

// ============================================
// SECURITY MIDDLEWARE
// ============================================

// Helmet for security headers
app.use(helmet());

// CORS with environment-aware configuration
app.use(cors({
  origin: (origin, callback) => {
    const allowedOrigins = process.env.ALLOWED_ORIGINS?.split(',') || 
                          ['http://localhost:3000'];

    if (!origin || allowedOrigins.includes(origin)) {
      callback(null, true);
    } else {
      logger.warn({ message: 'CORS violation', origin });
      callback(new Error('Not allowed by CORS'));
    }
  },
  credentials: true,
  optionsSuccessStatus: 200,
}));

// Rate limiting
const generalLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 100,
  message: 'Too many requests',
  standardHeaders: true,
  legacyHeaders: false,
  keyGenerator: (req) => req.user?.id || req.ip,
});

const loginLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 5,
  skipSuccessfulRequests: true,
  message: 'Too many login attempts',
});

app.use(generalLimiter);

// Body parser with size limits
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ extended: false, limit: '10kb' }));

// ============================================
// REQUEST LOGGING
// ============================================

const sanitize = (obj) => {
  const clone = JSON.parse(JSON.stringify(obj));
  const sensitiveKeys = ['password', 'token', 'secret', 'key', 'authorization'];

  const sanitizeObj = (obj) => {
    for (const key in obj) {
      if (sensitiveKeys.some(s => key.toLowerCase().includes(s))) {
        obj[key] = '[REDACTED]';
      } else if (typeof obj[key] === 'object' && obj[key] !== null) {
        sanitizeObj(obj[key]);
      }
    }
  };

  sanitizeObj(clone);
  return clone;
};

app.use((req, res, next) => {
  logger.info({
    timestamp: new Date().toISOString(),
    method: req.method,
    url: req.url,
    ip: req.ip,
    userId: req.user?.id,
    body: sanitize(req.body),
  });
  next();
});

// ============================================
// AUTHENTICATION MIDDLEWARE
// ============================================

const authenticateToken = (req, res, next) => {
  const authHeader = req.headers['authorization'];
  const token = authHeader && authHeader.split(' ')[1];

  if (!token) {
    logger.warn({ message: 'No token provided', ip: req.ip });
    return res.status(401).json({ error: 'Access token required' });
  }

  jwt.verify(token, appSecrets['app/jwt-secret'], (err, user) => {
    if (err) {
      logger.warn({ message: 'Invalid token', ip: req.ip, error: err.message });
      return res.status(403).json({ error: 'Invalid or expired token' });
    }
    req.user = user;
    next();
  });
};

const authorizeRole = (...roles) => {
  return (req, res, next) => {
    if (!roles.includes(req.user.role)) {
      logger.warn({
        message: 'Unauthorized role access',
        userId: req.user.id,
        userRole: req.user.role,
        requiredRoles: roles,
      });
      return res.status(403).json({ error: 'Insufficient permissions' });
    }
    next();
  };
};

// ============================================
// ROUTES
// ============================================

// Health check (public)
app.get('/health', (req, res) => {
  res.json({
    status: 'ok',
    timestamp: new Date().toISOString(),
    environment: NODE_ENV,
  });
});

// Secrets metrics (admin only)
app.get('/admin/secrets-metrics', authenticateToken, authorizeRole('admin'), (req, res) => {
  res.json(secretsManager.getMetrics());
});

// Refresh secrets cache (admin only)
app.post('/admin/refresh-secrets', authenticateToken, authorizeRole('admin'), async (req, res) => {
  try {
    await secretsManager.refreshAllSecrets();
    logger.info('Secrets cache refreshed by admin');
    res.json({ message: 'Secrets cache refreshed' });
  } catch (error) {
    logger.error(`Failed to refresh secrets: ${error.message}`);
    res.status(500).json({ error: 'Failed to refresh secrets' });
  }
});

// Login endpoint
app.post('/login', 
  loginLimiter,
  body('username').trim().isLength({ min: 1, max: 100 }).escape(),
  body('password').isLength({ min: 8, max: 128 }),
  async (req, res) => {
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      logger.warn({ message: 'Login validation failed', errors: errors.array() });
      return res.status(400).json({ errors: errors.array() });
    }

    try {
      // TODO: Verify credentials against database with bcrypt
      const user = { 
        id: 1, 
        username: req.body.username, 
        role: 'user' 
      };

      const token = jwt.sign(
        user,
        appSecrets['app/jwt-secret'],
        { expiresIn: '1h' }
      );

      logger.info({
        message: 'User logged in',
        userId: user.id,
        username: user.username,
      });

      res.json({
        token,
        expiresIn: 3600,
        user: { id: user.id, username: user.username },
      });
    } catch (error) {
      logger.error({ message: 'Login error', error: error.message });
      res.status(500).json({ error: 'Internal Server Error' });
    }
  }
);

// Get all users (protected - admin only)
app.get('/users',
  authenticateToken,
  authorizeRole('admin'),
  (req, res) => {
    try {
      logger.info({ message: 'Users list retrieved', userId: req.user.id });

      res.json([
        { id: 1, name: 'Alice', email: 'alice@example.com' },
        { id: 2, name: 'Bob', email: 'bob@example.com' },
      ]);
    } catch (error) {
      logger.error({ message: 'Error fetching users', error: error.message });
      res.status(500).json({ error: 'Internal Server Error' });
    }
  }
);

// Get single user (protected)
app.get('/users/:id',
  authenticateToken,
  param('id').isInt({ min: 1 }).toInt(),
  (req, res) => {
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({ errors: errors.array() });
    }

    try {
      const targetId = req.params.id;

      // Authorization check
      if (targetId !== req.user.id && req.user.role !== 'admin') {
        logger.warn({
          message: 'Unauthorized user data access',
          userId: req.user.id,
          targetId,
        });
        return res.status(403).json({ error: 'Unauthorized' });
      }

      res.json({
        id: targetId,
        name: 'User Name',
        email: 'user@example.com',
      });
    } catch (error) {
      logger.error({ message: 'Error fetching user', error: error.message });
      res.status(500).json({ error: 'Internal Server Error' });
    }
  }
);

// ============================================
// ERROR HANDLING
// ============================================

app.use((err, req, res, next) => {
  logger.error({
    timestamp: new Date().toISOString(),
    message: err.message,
    stack: err.stack,
    url: req.url,
    method: req.method,
    userId: req.user?.id,
  });

  const response = {
    message: NODE_ENV === 'production'
      ? 'Internal Server Error'
      : err.message,
  };

  if (NODE_ENV === 'production') {
    response.errorId = `ERR-${Date.now()}`;
  } else {
    response.stack = err.stack;
  }

  res.status(err.status || 500).json(response);
});

// 404 Handler
app.use((req, res) => {
  logger.warn({
    message: 'Resource not found',
    path: req.path,
    method: req.method,
    ip: req.ip,
  });
  res.status(404).json({ error: 'Not Found' });
});

// ============================================
// SERVER STARTUP
// ============================================

async function startServer() {
  try {
    // Load secrets before starting server
    await loadSecrets();

    const server = app.listen(PORT, () => {
      logger.info({
        message: 'Server started',
        port: PORT,
        environment: NODE_ENV,
        secretsCached: secretsManager.getMetrics().cacheSize,
      });
    });

    // Graceful shutdown
    process.on('SIGTERM', () => {
      logger.info('SIGTERM received, closing server gracefully');
      server.close(() => {
        logger.info('Server closed');
        process.exit(0);
      });
    });

    process.on('SIGINT', () => {
      logger.info('SIGINT received, closing server gracefully');
      server.close(() => {
        logger.info('Server closed');
        process.exit(0);
      });
    });

  } catch (error) {
    logger.error({
      message: 'Failed to start server',
      error: error.message,
    });
    process.exit(1);
  }
}

// Start the server
startServer();

module.exports = app;

