# Security Review Report: app.js

**Date:** 2024
**Severity Levels:** Critical | High | Medium | Low | Info

---

## Executive Summary

The current application is a basic Express.js server with minimal functionality. While the code is relatively simple, there are several critical security vulnerabilities and missing security hardening measures that must be addressed before production deployment.

**Overall Risk Rating:** 🔴 **HIGH**

---

## 1. CRITICAL VULNERABILITIES

### 1.1 🔴 No Input Validation & Query Parameter Injection
**Severity:** CRITICAL (OWASP A03:2021 – Injection)

**Issue:**
- No query parameters are being validated or sanitized
- The `/users` endpoint doesn't filter results based on parameters
- Future parameter handling could be vulnerable to injection attacks

**Current Code:**
```javascript
app.get('/users', (req, res) => {
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ]);
});
```

**Attack Scenario:**
```
GET /users?id=1; DROP TABLE users;--
GET /users?search=<img src=x onerror=alert('XSS')>
```

**Recommendation - Secure Implementation:**
```javascript
const { query, validationResult } = require('express-validator');

// Add input validation middleware
const validateUserQuery = [
  query('id').optional().isInt().toInt(),
  query('search').optional().trim().isLength({ max: 100 }),
  query('limit').optional().isInt({ min: 1, max: 100 }).toInt(),
  query('offset').optional().isInt({ min: 0 }).toInt(),
];

app.get('/users', validateUserQuery, (req, res) => {
  // Check for validation errors
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({ errors: errors.array() });
  }

  const { id, search, limit = 10, offset = 0 } = req.query;
  let users = [
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ];

  // Apply filters safely
  if (id) {
    users = users.filter(u => u.id === id);
  }

  if (search) {
    users = users.filter(u => 
      u.name.toLowerCase().includes(search.toLowerCase()) ||
      u.email.toLowerCase().includes(search.toLowerCase())
    );
  }

  // Apply pagination
  users = users.slice(offset, offset + limit);

  res.json(users);
});
```

---

### 1.2 🔴 No Authentication/Authorization
**Severity:** CRITICAL (OWASP A01:2021 – Broken Access Control)

**Issue:**
- All endpoints are completely unauthenticated
- No access control checks
- Sensitive user data (email) is exposed to anyone
- No rate limiting or request authentication

**Attack Scenario:**
```bash
curl http://localhost:3000/users  # Anyone can access
curl http://localhost:3000/health # No auth required
```

**Recommendation - Secure Implementation:**
```javascript
const jwt = require('jsonwebtoken');
const rateLimit = require('express-rate-limit');

const JWT_SECRET = process.env.JWT_SECRET || 'your-secret-key';

// Rate limiting middleware
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP',
  standardHeaders: true,
  legacyHeaders: false,
});

app.use(limiter);

// Authentication middleware
const authenticateToken = (req, res, next) => {
  const authHeader = req.headers['authorization'];
  const token = authHeader && authHeader.split(' ')[1]; // Bearer TOKEN

  if (!token) {
    return res.status(401).json({ error: 'Access token required' });
  }

  jwt.verify(token, JWT_SECRET, (err, user) => {
    if (err) {
      return res.status(403).json({ error: 'Invalid or expired token' });
    }
    req.user = user;
    next();
  });
};

// Protected endpoint
app.get('/users', authenticateToken, (req, res) => {
  // Only authenticated users can access
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ]);
});

// Login endpoint
app.post('/login', (req, res) => {
  // In production, verify username/password against database
  const user = { id: 1, username: 'user' };
  const token = jwt.sign(user, JWT_SECRET, { expiresIn: '1h' });
  res.json({ token });
});
```

---

### 1.3 🔴 No HTTPS/TLS Enforcement
**Severity:** CRITICAL (OWASP A02:2021 – Cryptographic Failures)

**Issue:**
- No HTTPS configuration
- Data transmitted in plaintext
- Vulnerable to man-in-the-middle (MITM) attacks
- Authentication tokens exposed if HTTP is used

**Recommendation:**
```javascript
const https = require('https');
const fs = require('fs');

// In production, use proper certificates (Let's Encrypt)
const options = {
  key: fs.readFileSync('path/to/private-key.pem'),
  cert: fs.readFileSync('path/to/certificate.pem')
};

https.createServer(options, app).listen(443, () => {
  console.log('Secure server running on port 443');
});

// Redirect HTTP to HTTPS
const httpApp = express();
httpApp.use((req, res) => {
  res.redirect(`https://${req.headers.host}${req.url}`);
});
httpApp.listen(80);

// Or use Express middleware for local development
const forceHttps = (req, res, next) => {
  if (req.header('x-forwarded-proto') !== 'https') {
    res.redirect(`https://${req.header('host')}${req.url}`);
  } else {
    next();
  }
};

app.use(forceHttps);
```

---

## 2. HIGH SEVERITY ISSUES

### 2.1 🟠 Missing Security Headers
**Severity:** HIGH (OWASP A01:2021 – Broken Access Control)

**Issue:**
- No Content-Security-Policy (CSP)
- No X-Frame-Options header (clickjacking protection)
- No X-Content-Type-Options (MIME type sniffing)
- No Strict-Transport-Security (HSTS)
- No X-XSS-Protection

**Recommendation:**
```javascript
const helmet = require('helmet');

// Use Helmet.js for security headers
app.use(helmet());

// Or configure manually
app.use((req, res, next) => {
  // Prevent clickjacking
  res.setHeader('X-Frame-Options', 'DENY');

  // Prevent MIME type sniffing
  res.setHeader('X-Content-Type-Options', 'nosniff');

  // Enable XSS protection
  res.setHeader('X-XSS-Protection', '1; mode=block');

  // HSTS - force HTTPS
  res.setHeader('Strict-Transport-Security', 'max-age=31536000; includeSubDomains');

  // CSP - restrict content sources
  res.setHeader(
    'Content-Security-Policy',
    "default-src 'self'; script-src 'self'; style-src 'self' 'unsafe-inline'"
  );

  // Referrer policy
  res.setHeader('Referrer-Policy', 'strict-origin-when-cross-origin');

  next();
});
```

---

### 2.2 🟠 Missing CORS Protection
**Severity:** HIGH

**Issue:**
- No CORS headers configured
- Might allow unauthorized cross-origin requests
- Could lead to credential exposure

**Recommendation:**
```javascript
const cors = require('cors');

// Whitelist allowed origins
const allowedOrigins = [
  'https://yourapp.com',
  'https://www.yourapp.com'
];

const corsOptions = {
  origin: function(origin, callback) {
    if (allowedOrigins.indexOf(origin) !== -1 || !origin) {
      callback(null, true);
    } else {
      callback(new Error('Not allowed by CORS'));
    }
  },
  credentials: true,
  methods: ['GET', 'POST', 'PUT', 'DELETE', 'OPTIONS'],
  allowedHeaders: ['Content-Type', 'Authorization'],
  maxAge: 3600
};

app.use(cors(corsOptions));
```

---

### 2.3 🟠 Sensitive Data Exposure
**Severity:** HIGH (OWASP A02:2021 – Cryptographic Failures)

**Issue:**
- Email addresses are exposed without filtering
- User details could contain sensitive information
- No data masking based on user permissions
- Timestamps reveal server internals

**Recommendation:**
```javascript
// Create data sanitization layer
const sanitizeUser = (user, requestingUser) => {
  // If requesting user is not admin, mask certain fields
  if (requestingUser.role !== 'admin') {
    return {
      id: user.id,
      name: user.name,
      // email is not included for non-admin users
    };
  }
  return user; // Admin can see all fields
};

app.get('/users/:id', authenticateToken, (req, res) => {
  const users = [
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ];

  const user = users.find(u => u.id === parseInt(req.params.id));

  if (!user) {
    return res.status(404).json({ error: 'User not found' });
  }

  // Apply sanitization
  const sanitized = sanitizeUser(user, req.user);
  res.json(sanitized);
});
```

---

## 3. MEDIUM SEVERITY ISSUES

### 3.1 🟡 Missing Error Handling & Information Disclosure
**Severity:** MEDIUM (OWASP A01:2021 – Broken Access Control)

**Issue:**
- No error handling middleware
- Stack traces could be exposed in production
- Unhandled exceptions could crash the server
- No logging mechanism

**Recommendation:**
```javascript
const winston = require('winston');

// Setup logging
const logger = winston.createLogger({
  level: 'info',
  format: winston.format.json(),
  transports: [
    new winston.transports.File({ filename: 'error.log', level: 'error' }),
    new winston.transports.File({ filename: 'combined.log' }),
  ],
});

// Error handling middleware
app.use((err, req, res, next) => {
  logger.error({
    message: err.message,
    stack: err.stack,
    path: req.path,
    method: req.method,
  });

  // Don't expose stack traces in production
  const isDevelopment = process.env.NODE_ENV === 'development';

  res.status(err.status || 500).json({
    error: isDevelopment ? err.message : 'Internal server error',
    ...(isDevelopment && { stack: err.stack }),
  });
});

// 404 handler
app.use((req, res) => {
  res.status(404).json({ error: 'Not found' });
});
```

---

### 3.2 🟡 No Input Type Validation on Status Endpoint
**Severity:** MEDIUM

**Issue:**
- `/health` endpoint could be abused for information gathering
- No rate limiting on health checks
- Could be used for DDoS reconnaissance

**Recommendation:**
