```javascript
require('dotenv').config();
const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const { query, validationResult } = require('express-validator');
const jwt = require('jsonwebtoken');
const winston = require('winston');
const { v4: uuidv4 } = require('uuid');

const app = express();
const PORT = process.env.PORT || 3000;
const NODE_ENV = process.env.NODE_ENV || 'development';
const JWT_SECRET = process.env.JWT_SECRET || 'dev-secret-key';

// ============ LOGGING ============
const logger = winston.createLogger({
  level: 'info',
  format: winston.format.json(),
  defaultMeta: { service: 'api' },
  transports: [
    new winston.transports.File({ filename: 'error.log', level: 'error' }),
    new winston.transports.File({ filename: 'combined.log' }),
  ],
});

if (NODE_ENV !== 'production') {
  logger.add(new winston.transports.Console({
    format: winston.format.simple(),
  }));
}

// ============ SECURITY MIDDLEWARE ============

// Security headers
app.use(helmet());

// CORS
const allowedOrigins = process.env.ALLOWED_ORIGINS?.split(',') || ['http://localhost:3000'];
app.use(cors({
  origin: allowedOrigins,
  credentials: true,
  methods: ['GET', 'POST', 'PUT', 'DELETE', 'OPTIONS'],
  allowedHeaders: ['Content-Type', 'Authorization'],
  maxAge: 3600,
}));

// Rate limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 100,
  standardHeaders: true,
  legacyHeaders: false,
  handler: (req, res) => {
    logger.warn({ requestId: req.id, message: 'Rate limit exceeded' });
    res.status(429).json({ error: 'Too many requests' });
  },
});
app.use(limiter);

// Body parsing with limits
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ limit: '10kb', extended: true }));

// Request ID tracking
app.use((req, res, next) => {
  req.id = uuidv4();
  res.setHeader('X-Request-ID', req.id);
  next();
});

// ============ AUTHENTICATION ============

const authenticateToken = (req, res, next) => {
  const authHeader = req.headers['authorization'];
  const token = authHeader && authHeader.split(' ')[1];

  if (!token) {
    return res.status(401).json({ error: 'Access token required' });
  }

  jwt.verify(token, JWT_SECRET, (err, user) => {
    if (err) {
      logger.warn({ requestId: req.id, error: 'Invalid token' });
      return res.status(403).json({ error: 'Invalid or expired token' });
    }
    req.user = user;
    next();
  });
};

// ============ ROUTES ============

// Health check (minimal rate limit)
app.get('/health', rateLimit({
  windowMs: 60 * 1000,
  max: 1000,
}), (req, res) => {
  res.setHeader('Cache-Control', 'no-store');
  res.json({ 
    status: 'ok',
    timestamp: new Date().toISOString(),
  });
});

// Input validation
const validateUserQuery = [
  query('id').optional().isInt().toInt(),
  query('search').optional().trim().isLength({ max: 100 }).escape(),
  query('limit').optional().isInt({ min: 1, max: 100 }).toInt(),
  query('offset').optional().isInt({ min: 0 }).toInt(),
];

// Secure users endpoint
app.get('/users', 
  authenticateToken,
  validateUserQuery,
  (req, res) => {
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({ 
        requestId: req.id,
        errors: errors.array() 
      });
    }

    const { id, search, limit = 10, offset = 0 } = req.query;

    let users = [
      { id: 1, name: 'Alice', email: 'alice@example.com', role: 'user' },
      { id: 2, name: 'Bob', email: 'bob@example.com', role: 'user' },
    ];

    // Apply filters
    if (id) {
      users = users.filter(u => u.id === id);
    }

    if (search) {
      users = users.filter(u =>
        u.name.toLowerCase().includes(search.toLowerCase())
      );
    }

    // Sanitize data based on user role
    users = users.map(user => {
      if (req.user.role === 'admin') {
        return user;
      }
      // Non-admin users don't see email
      const { email, ...sanitized } = user;
      return sanitized;
    });

    // Apply pagination
    const total = users.length;
    users = users.slice(offset, offset + limit);

    logger.info({
      requestId: req.id,
      action: 'users_list',
      userId: req.user.id,
      count: users.length,
    });

    res.json({
      data: users,
      pagination: { offset, limit, total },
    });
  }
);

// ============ ERROR HANDLING ============

// 404 handler
app.use((req, res) => {
  logger.warn({
    requestId: req.id,
    message: '404 Not Found',
    path: req.path,
  });
  res.status(404).json({ 
    requestId: req.id,
    error: 'Not found' 
  });
});

// Error handler
app.use((err, req, res, next) => {
  logger.error({
    requestId: req.id,
    message: err.message,
    stack: err.stack,
  });

  const isDevelopment = NODE_ENV === 'development';

  res.status(err.status || 500).json({
    requestId: req.id,
    error: isDevelopment ? err.message : 'Internal server error',
    ...(isDevelopment && { stack: err.stack }),
  });
});

// ============ SERVER ============

app.listen(PORT, () => {
  logger.info({
    message: 'Server started',
    port: PORT,
    env: NODE_ENV,
  });
});

module.exports = app;
