/**
 * Sanitize user data based on requesting user's role
 * @param {Object} user - User object
 * @param {Object} requestingUser - User making the request
 * @returns {Object} Sanitized user object
 */
const sanitizeUser = (user, requestingUser) => {
  const sanitized = {
    id: user.id,
    name: user.name,
  };

  // Admin can see all fields
  if (requestingUser?.role === 'admin') {
    sanitized.email = user.email;
    sanitized.role = user.role;
    sanitized.createdAt = user.createdAt;
  }

  return sanitized;
};

/**
 * Generate JWT token
 * @param {Object} user - User object
 * @returns {string} JWT token
 */
const generateToken = (user) => {
  return jwt.sign(
    {
      id: user.id,
      username: user.email,
      role: user.role,
    },
    JWT_SECRET,
    { expiresIn: JWT_EXPIRY }
  );
};

/**
 * Handle validation errors
 * @param {Request} req - Express request
 * @param {Response} res - Express response
 * @returns {boolean} True if validation failed
 */
const handleValidationErrors = (req, res) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    res.status(400).json({
      error: 'Validation failed',
      requestId: req.id,
      details: errors.array().map(err => ({
        field: err.param,
        message: err.msg,
      })),
    });
    return true;
  }
  return false;
};

