    .withMessage('Invalid characters in search'),

  query('limit')
    .optional()
    .isInt({ min: 1, max: 100 })
    .withMessage('Limit must be 1-100')
    .toInt(),
];

app.get('/users', validateUserQuery, (req, res) => {
