**Fixed Code:**
```javascript
const rateLimit = require('express-rate-limit');

// Global rate limiter
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Max 100 requests per window
  message: 'Too many requests',
  standardHeaders: true,
  legacyHeaders: false,
});

// Stricter limit for auth endpoints
const authLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 5, // Max 5 login attempts
  skipSuccessfulRequests: true, // Don't count successful logins
});

app.use(limiter);

app.get('/users', (req, res) => {
  res.json([...]);
});

app.post('/login', authLimiter, (req, res) => {
  // Only 5 failed attempts per 15 minutes
});
```

**Result:**
```bash
# After 100 requests in 15 minutes:
curl http://localhost:3000/users
# 429 Too Many Requests
# RateLimit-Limit: 100
# RateLimit-Remaining: 0
# RateLimit-Reset: 1234567890
```

---

### Issue #5: Sensitive Data Exposure (HIGH)

**Original Code - VULNERABLE:**
```javascript
app.get('/users', (req, res) => {
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },  // Email exposed!
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ]);
  // No data filtering based on user role
});
```

**Problem:**
- All users see everyone's email addresses
- No role-based data access control
- Sensitive info exposed to non-admins

**Fixed Code:**
```javascript
// Sanitize based on user role
const sanitizeUser = (user, requestingUser) => {
  const sanitized = {
    id: user.id,
    name: user.name,
  };

  // Only admin can see email
  if (requestingUser.role === 'admin') {
    sanitized.email = user.email;
    sanitized.role = user.role;
  }

  return sanitized;
};

app.get('/users', authenticateToken, (req, res) => {
  let users = [
    { id: 1, name: 'Alice', email: 'alice@example.com', role: 'admin' },
    { id: 2, name: 'Bob', email: 'bob@example.com', role: 'user' },
  ];

  // Apply sanitization
  users = users.map(user => sanitizeUser(user, req.user));

  res.json(users);
});
```

**Result - Non-admin user:**
```json
[
  { "id": 1, "name": "Alice" },
  { "id": 2, "name": "Bob" }
]
```

**Result - Admin user:**
```json
[
  { "id": 1, "name": "Alice", "email": "alice@example.com", "role": "admin" },
  { "id": 2, "name": "Bob", "email": "bob@example.com", "role": "user" }
]
```

---

### Issue #6: No HTTPS (CRITICAL)

**Original Code - VULNERABLE:**
```javascript
app.listen(3000, () => {
  console.log('Server running on port 3000');
  // HTTP only - all data transmitted in plaintext!
});
```

**Risk:** MITM attack, credential theft, token interception

**Fixed Code:**
```javascript
const https = require('https');
const fs = require('fs');

// Force HTTPS redirect
app.use((req, res, next) => {
  if (req.header('x-forwarded-proto') !== 'https') {
    res.redirect(`https://${req.header('host')}${req.url}`);
  } else {
    next();
  }
});

// In production with real certificates
const options = {
  key: fs.readFileSync('/etc/ssl/private/key.pem'),
  cert: fs.readFileSync('/etc/ssl/certs/cert.pem'),
};

https.createServer(options, app).listen(443, () => {
  console.log('Secure server running on port 443');
});

// Redirect HTTP to HTTPS
const httpApp = express();
httpApp.use((req, res) => {
  res.redirect(`https://${req.headers.host}${req.url}`);
});
httpApp.listen(80);
```

---

### Issue #7: No Error Handling (MEDIUM)

**Original Code - VULNERABLE:**
```javascript
app.get('/users', (req, res) => {
  try {
    res.json([...]);
  }
  // No catch block - unhandled exceptions crash server!
});

// No error middleware - stack traces exposed in production
```

**Fixed Code:**
```javascript
const winston = require('winston');

// Setup logging
const logger = winston.createLogger({
  level: 'info',
  format: winston.format.json(),
  transports: [
    new winston.transports.File({ filename: 'error.log', level: 'error' }),
    new winston.transports.File({ filename: 'combined.log' }),
  ],
});

// Error handling middleware
app.use((err, req, res, next) => {
  logger.error({
    message: err.message,
    stack: err.stack,
    path: req.path,
  });

  // Don't expose stack trace in production
  const isDevelopment = process.env.NODE_ENV === 'development';

  res.status(err.status || 500).json({
    error: isDevelopment ? err.message : 'Internal server error',
    ...(isDevelopment && { stack: err.stack }),
  });
});

// Catch unhandled exceptions
process.on('uncaughtException', (err) => {
  logger.error({ message: 'Uncaught Exception', error: err });
  process.exit(1);
});

process.on('unhandledRejection', (reason) => {
  logger.error({ message: 'Unhandled Rejection', reason });
  process.exit(1);
});
```

---

### Issue #8: CORS Not Configured (HIGH)

**Original Code - VULNERABLE:**
```javascript
// No CORS configuration = allows ANY origin
app.get('/users', (req, res) => {
  res.json([...]);
});
```

**Attack:**
```javascript
// Malicious website can access your API
// From attacker.com
fetch('http://localhost:3000/users').then(r => r.json())
  .then(data => sendToAttacker(data));
```

**Fixed Code:**
```javascript
const cors = require('cors');

const allowedOrigins = [
  'https://yourapp.com',
  'https://www.yourapp.com',
];

app.use(cors({
  origin: (origin, callback) => {
    if (!origin || allowedOrigins.includes(origin)) {
      callback(null, true);
    } else {
      callback(new Error('CORS not allowed'));
    }
  },
  credentials: true,
  methods: ['GET', 'POST', 'PUT', 'DELETE'],
  allowedHeaders: ['Content-Type', 'Authorization'],
  maxAge: 3600,
}));
```

**Result:**
```bash
# From attacker.com
curl -H "Origin: https://attacker.com" http://localhost:3000/users
# 403 Forbidden - CORS request blocked
```

---

## Quick Fix Checklist

| Issue | Severity | Quick Fix | Package |
|-------|----------|-----------|---------|
| No Authentication | 🔴 CRITICAL | Add JWT middleware | jsonwebtoken |
| No Input Validation | 🔴 CRITICAL | Add validators | express-validator |
| No Security Headers | 🟠 HIGH | Use helmet | helmet |
| No Rate Limiting | 🟠 HIGH | Add limiter | express-rate-limit |
| Data Exposed | 🟠 HIGH | Sanitize output | Custom |
| No HTTPS | 🔴 CRITICAL | Enable TLS/SSL | Built-in https |
| No Error Handling | 🟡 MEDIUM | Add error middleware | Winston |
| No CORS Config | 🟠 HIGH | Configure CORS | cors |
| No Logging | 🟡 MEDIUM | Add logging | winston |
| No Rate Limit Auth | 🟠 HIGH | Strict auth limits | express-rate-limit |

---

## Production Deployment Checklist

- [ ] Enable HTTPS/TLS
- [ ] Set JWT_SECRET to unique value
- [ ] Configure ALLOWED_ORIGINS for CORS
- [ ] Set NODE_ENV=production
- [ ] Enable all security middleware
- [ ] Run `npm audit` - zero high/critical vulnerabilities
- [ ] Database parameterized queries
- [ ] Passwords hashed with bcrypt
- [ ] Logging configured and monitored
- [ ] Rate limiting configured
- [ ] Error handling in place
- [ ] Secrets in .env, not in code
- [ ] package-lock.json committed
- [ ] All endpoints authenticated/authorized
- [ ] Input validation on all endpoints
- [ ] Penetration testing completed

---

## Testing the Fixes

```bash
# 1. Start secure server
npm run dev

# 2. Test authentication
curl http://localhost:3000/users
# Should get 401 error

# 3. Get token
TOKEN=$(curl -X POST http://localhost:3000/login \
  -H "Content-Type: application/json" \
  -d '{"username":"alice@example.com","password":"demo-password-123"}' \
  | jq -r '.token')

# 4. Use token
curl -H "Authorization: Bearer $TOKEN" http://localhost:3000/users
# Should succeed

# 5. Test input validation
curl -H "Authorization: Bearer $TOKEN" "http://localhost:3000/users?limit=invalid"
# Should get 400 validation error

# 6. Test rate limiting
for i in {1..150}; do curl http://localhost:3000/health; done
# After 100 requests should get 429 Too Many Requests

# 7. Check security headers
curl -i http://localhost:3000/health
# Should see X-Frame-Options, CSP, HSTS headers
```

All fixes demonstrated! 🎉

