### Step 2: Create Secrets Manager Module

```javascript
// secrets.js
const AWS = require('aws-sdk');
const vault = require('node-vault');
const logger = require('./logger'); // Your logger

class SecretsManager {
  constructor() {
    this.env = process.env.NODE_ENV || 'development';
    this.secretsCache = new Map();
    this.cacheTTL = 60 * 60 * 1000; // 1 hour
    this.initializeManager();
  }

  initializeManager() {
    if (this.env === 'production') {
      this.awsClient = new AWS.SecretsManager({
        region: process.env.AWS_REGION || 'us-east-1'
      });
    } else if (this.env === 'staging') {
      this.vaultClient = vault({
        endpoint: process.env.VAULT_ADDR || 'http://localhost:8200',
        token: process.env.VAULT_TOKEN
      });
    }
  }

  /**
   * Get secret with caching
   * @param {string} secretName - Name or path of secret
   * @returns {Promise<string|object>}
   */
  async getSecret(secretName) {
    // Check cache first
    const cached = this.getFromCache(secretName);
    if (cached) {
      logger.info({ 
        message: 'Secret retrieved from cache',
        secretName 
      });
      return cached;
    }

    let secret;
    switch (this.env) {
      case 'production':
        secret = await this.getFromAWSSecretsManager(secretName);
        break;
      case 'staging':
        secret = await this.getFromVault(secretName);
        break;
      default:
        secret = await this.getFromEnv(secretName);
    }

    // Cache the secret
    this.setInCache(secretName, secret);

    logger.info({
      message: 'Secret retrieved successfully',
      secretName,
      source: this.env
    });

    return secret;
  }

  /**
   * Retrieve from AWS Secrets Manager
   */
  async getFromAWSSecretsManager(secretName) {
    try {
      const result = await this.awsClient.getSecretValue({
        SecretId: secretName
      }).promise();

      if ('SecretString' in result) {
        try {
          return JSON.parse(result.SecretString);
        } catch {
          return result.SecretString;
        }
      }

      return result.SecretBinary;
    } catch (error) {
      logger.error({
        message: 'Failed to retrieve from AWS Secrets Manager',
        secretName,
        error: error.message
      });
      throw new Error(`Secret retrieval failed: ${secretName}`);
    }
  }

  /**
   * Retrieve from HashiCorp Vault
   */
  async getFromVault(secretName) {
    try {
      const path = `secret/data/staging/${secretName}`;
      const result = await this.vaultClient.read(path);
      return result.data.data;
    } catch (error) {
      logger.error({
        message: 'Failed to retrieve from Vault',
        secretName,
        error: error.message
      });
      throw new Error(`Secret retrieval failed: ${secretName}`);
    }
  }

  /**
   * Retrieve from environment variables (.env)
   */
  async getFromEnv(secretName) {
    const value = process.env[secretName];

    if (!value) {
      logger.error({
        message: 'Secret not found in environment',
        secretName
      });
      throw new Error(`Secret not found: ${secretName}`);
    }

    // Validate secret is not a default
    if (value.includes('change-in-production') || 
        value === 'dev-secret' ||
        value === 'test-secret') {
      logger.warn({
        message: 'Warning: Using default/test secret value',
        secretName
      });
    }

    return value;
  }

  /**
   * Cache management
   */
  getFromCache(key) {
    const cached = this.secretsCache.get(key);
    if (!cached) return null;

    const { value, timestamp } = cached;
    const isExpired = Date.now() - timestamp > this.cacheTTL;

    if (isExpired) {
      this.secretsCache.delete(key);
      return null;
    }

    return value;
  }

  setInCache(key, value) {
    this.secretsCache.set(key, {
      value,
      timestamp: Date.now()
    });
  }

  /**
   * Rotate secret (for AWS)
   */
  async rotateSecret(secretName) {
    if (this.env !== 'production') {
      throw new Error('Secret rotation only available in production');
    }

    try {
      await this.awsClient.rotateSecret({
        SecretId: secretName
      }).promise();

      // Invalidate cache after rotation
      this.secretsCache.delete(secretName);

      logger.info({
        message: 'Secret rotated successfully',
        secretName
      });
    } catch (error) {
      logger.error({
        message: 'Failed to rotate secret',
        secretName,
        error: error.message
      });
      throw error;
    }
  }

  /**
   * Validate required secrets exist
   */
  async validateRequiredSecrets(requiredSecrets) {
    const missing = [];

    for (const secret of requiredSecrets) {
      try {
        await this.getSecret(secret);
      } catch {
        missing.push(secret);
      }
    }

    if (missing.length > 0) {
      const error = `Missing required secrets: ${missing.join(', ')}`;
      logger.error({ message: error });
      throw new Error(error);
    }

    logger.info({
      message: 'All required secrets validated',
      count: requiredSecrets.length
    });
  }
}

module.exports = new SecretsManager();
```

