/**
 * SECURE SECRETS MANAGER - Production-Ready Implementation
 * Supports AWS Secrets Manager, HashiCorp Vault, and Local .env
 */

const logger = require('./logger'); // Assumes you have winston logger

class SecretsManager {
  constructor(config = {}) {
    this.env = process.env.NODE_ENV || 'development';
    this.secretsCache = new Map();
    this.cacheTTL = config.cacheTTL || 60 * 60 * 1000; // 1 hour default
    this.cacheEnabled = config.cacheEnabled !== false; // Default true

    this.initialize();
  }

  /**
   * Initialize secrets manager based on environment
   */
  initialize() {
    logger.info({
      message: 'Initializing Secrets Manager',
      environment: this.env,
      cacheEnabled: this.cacheEnabled,
      cacheTTL: this.cacheTTL
    });

    switch (this.env) {
      case 'production':
        this.initializeAWS();
        break;
      case 'staging':
        this.initializeVault();
        break;
      default:
        this.initializeEnv();
    }
  }

  /**
   * Initialize AWS Secrets Manager
   */
  initializeAWS() {
    try {
      // Lazy load AWS SDK only when needed
      const AWS = require('aws-sdk');
      this.awsClient = new AWS.SecretsManager({
        region: process.env.AWS_REGION || 'us-east-1'
      });
      this.provider = 'AWS Secrets Manager';
      logger.info({ message: 'AWS Secrets Manager initialized' });
    } catch (error) {
      logger.error({
        message: 'Failed to initialize AWS Secrets Manager',
        error: error.message
      });
      throw error;
    }
  }

  /**
   * Initialize HashiCorp Vault
   */
  initializeVault() {
    try {
      const vault = require('node-vault');
      this.vaultClient = vault({
        endpoint: process.env.VAULT_ADDR || 'http://localhost:8200',
        token: process.env.VAULT_TOKEN
      });
      this.provider = 'HashiCorp Vault';
      logger.info({ 
        message: 'HashiCorp Vault initialized',
        endpoint: process.env.VAULT_ADDR
      });
    } catch (error) {
      logger.error({
        message: 'Failed to initialize HashiCorp Vault',
        error: error.message
      });
      throw error;
    }
  }

  /**
   * Initialize local .env for development
   */
  initializeEnv() {
    try {
      require('dotenv').config();
      this.provider = 'Environment Variables (.env)';
      logger.info({ message: 'Local .env initialized' });
    } catch (error) {
      logger.warn({
        message: 'Failed to load .env file',
        error: error.message
      });
    }
  }

  /**
   * Main method to get secret
   * @param {string} secretName - Name/path of the secret
   * @param {object} options - Optional configuration
   * @returns {Promise<any>}
   */
  async getSecret(secretName, options = {}) {
    if (!secretName) {
      throw new Error('Secret name is required');
    }

    // Check cache if enabled
    if (this.cacheEnabled && !options.skipCache) {
      const cached = this.getFromCache(secretName);
      if (cached) {
        logger.debug({
          message: 'Secret retrieved from cache',
          secretName
        });
        return cached;
      }
    }

    let secret;

    try {
      switch (this.env) {
        case 'production':
          secret = await this.getFromAWS(secretName);
          break;
        case 'staging':
          secret = await this.getFromVault(secretName);
          break;
        default:
          secret = this.getFromEnv(secretName);
      }

      // Cache the secret
      if (this.cacheEnabled && !options.skipCache) {
        this.setInCache(secretName, secret);
      }

      // Audit log (be careful not to log secret value!)
      logger.info({
        message: 'Secret retrieved successfully',
        secretName,
        source: this.provider
      });

      return secret;

    } catch (error) {
      logger.error({
        message: 'Failed to retrieve secret',
        secretName,
        environment: this.env,
        error: error.message
      });
      throw error;
    }
  }

  /**
   * Get secret from AWS Secrets Manager
   * @private
   */
  async getFromAWS(secretName) {
    if (!this.awsClient) {
      throw new Error('AWS Secrets Manager not initialized');
    }

    try {
      const result = await this.awsClient.getSecretValue({
        SecretId: secretName
      }).promise();

      // Handle different secret types
      if ('SecretString' in result) {
        try {
          // Try to parse as JSON
          return JSON.parse(result.SecretString);
        } catch {
          // Return as plain string if not JSON
          return result.SecretString;
        }
      } else if ('SecretBinary' in result) {
        return result.SecretBinary;
      }

      throw new Error('Secret has no value');

    } catch (error) {
      if (error.code === 'ResourceNotFoundException') {
        throw new Error(`Secret not found in AWS Secrets Manager: ${secretName}`);
      }
      throw error;
    }
  }

  /**
   * Get secret from HashiCorp Vault
   * @private
   */
  async getFromVault(secretName) {
    if (!this.vaultClient) {
      throw new Error('Vault client not initialized');
    }

    try {
      // Construct path - assumes secrets at secret/data/staging/{secretName}
      const path = `secret/data/staging/${secretName}`;
      const result = await this.vaultClient.read(path);

      if (!result.data || !result.data.data) {
        throw new Error(`No data found for secret: ${secretName}`);
      }

      return result.data.data;

    } catch (error) {
      if (error.message.includes('permission denied')) {
        throw new Error(`Permission denied accessing secret: ${secretName}`);
      }
      if (error.message.includes('not found')) {
        throw new Error(`Secret not found in Vault: ${secretName}`);
      }
      throw error;
    }
  }

  /**
   * Get secret from environment variables
   * @private
   */
  getFromEnv(secretName) {
    const value = process.env[secretName];

    if (!value) {
      throw new Error(`Secret not found in environment: ${secretName}`);
    }

    // Warn if using test/default values
    if (this.isDefaultValue(value)) {
      logger.warn({
        message: 'Using default/test secret value',
        secretName,
        warning: 'This should only be used in development'
      });
    }

    return value;
  }

  /**
   * Check if value is a known default/test value
   * @private
   */
  isDefaultValue(value) {
    const defaults = [
      'change-in-production',
      'dev-secret',
      'test-secret',
      'demo-password-123',
      'default-key',
      'placeholder'
    ];

    return defaults.some(d => value.toLowerCase().includes(d.toLowerCase()));
  }

  /**
   * Batch get multiple secrets
   * @param {string[]} secretNames - Array of secret names
   * @returns {Promise<object>}
   */
  async getSecrets(secretNames) {
    if (!Array.isArray(secretNames)) {
      throw new Error('secretNames must be an array');
    }

    const results = {};
    const errors = {};

    for (const name of secretNames) {
      try {
        results[name] = await this.getSecret(name);
      } catch (error) {
        errors[name] = error.message;
      }
    }

    return { results, errors };
  }

  /**
   * Validate that all required secrets exist
   * @param {string[]} requiredSecrets - Array of required secret names
   * @throws {Error} if any required secrets are missing
   */
  async validateRequiredSecrets(requiredSecrets) {
    logger.info({
      message: 'Validating required secrets',
      count: requiredSecrets.length
    });

    const missing = [];

    for (const secret of requiredSecrets) {
      try {
        await this.getSecret(secret, { skipCache: true });
      } catch {
        missing.push(secret);
      }
    }

    if (missing.length > 0) {
      const error = `Missing required secrets: ${missing.join(', ')}`;
      logger.error({ message: error, missing });
      throw new Error(error);
    }

    logger.info({
      message: 'All required secrets validated successfully',
      count: requiredSecrets.length
    });
  }

  /**
   * Cache management - Get from cache
   * @private
   */
  getFromCache(key) {
    const cached = this.secretsCache.get(key);
    if (!cached) return null;

    const { value, timestamp } = cached;
    const isExpired = Date.now() - timestamp > this.cacheTTL;

    if (isExpired) {
      this.secretsCache.delete(key);
      logger.debug({
        message: 'Expired cache entry removed',
        secretName: key
      });
      return null;
    }

    return value;
  }

  /**
   * Cache management - Set in cache
   * @private
   */
  setInCache(key, value) {
    this.secretsCache.set(key, {
      value,
      timestamp: Date.now()
    });
  }

  /**
   * Clear entire cache
   */
  clearCache() {
    const size = this.secretsCache.size;
    this.secretsCache.clear();
    logger.info({
      message: 'Secrets cache cleared',
      entriesCleared: size
    });
  }

  /**
   * Clear specific cache entry
   */
  clearCacheEntry(secretName) {
    const existed = this.secretsCache.has(secretName);
    this.secretsCache.delete(secretName);

    if (existed) {
      logger.debug({
        message: 'Cache entry cleared',
        secretName
      });
    }
  }

  /**
   * Rotate secret (AWS Secrets Manager only)
   * @param {string} secretName - Name of secret to rotate
   */
  async rotateSecret(secretName) {
    if (this.env !== 'production') {
      throw new Error('Secret rotation only available in production');
    }

    if (!this.awsClient) {
      throw new Error('AWS Secrets Manager not initialized');
    }

    try {
      logger.info({
        message: 'Initiating secret rotation',
        secretName,
        timestamp: new Date().toISOString()
      });

      await this.awsClient.rotateSecret({
        SecretId: secretName
      }).promise();

      // Invalidate cache after rotation
      this.clearCacheEntry(secretName);

      logger.info({
        message: 'Secret rotated successfully',
        secretName
      });

    } catch (error) {
      logger.error({
        message: 'Failed to rotate secret',
        secretName,
        error: error.message
      });
      throw error;
    }
  }

  /**
   * Get cache statistics
   * @returns {object}
   */
  getCacheStats() {
    return {
      size: this.secretsCache.size,
      enabled: this.cacheEnabled,
      ttl: this.cacheTTL,
      entries: Array.from(this.secretsCache.keys())
    };
  }

  /**
   * Get manager status
   * @returns {object}
   */
  getStatus() {
    return {
      environment: this.env,
      provider: this.provider,
      cacheEnabled: this.cacheEnabled,
      cacheSize: this.secretsCache.size,
      cacheTTL: this.cacheTTL
    };
  }
}

// Create singleton instance
module.exports = SecretsManager;

/**
 * APP.JS - Updated with Secure Secrets Management
 * Uses SecretsManager for all sensitive credentials
 */

require('dotenv').config();
const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const { query, body, validationResult } = require('express-validator');
const jwt = require('jsonwebtoken');
const bcrypt = require('bcryptjs');
const winston = require('winston');
const { v4: uuidv4 } = require('uuid');

// Import secure secrets manager
const SecretsManager = require('./secrets-manager');

// ============================================
// LOGGER SETUP (Before secrets initialization)
// ============================================

const logger = winston.createLogger({
  level: process.env.LOG_LEVEL || 'info',
  format: winston.format.combine(
    winston.format.timestamp(),
    winston.format.errors({ stack: true }),
    winston.format.json()
  ),
  defaultMeta: { service: 'secure-api' },
  transports: [
    new winston.transports.File({ 
      filename: 'logs/error.log', 
      level: 'error',
      maxsize: 5242880,
      maxFiles: 5,
    }),
    new winston.transports.File({ 
      filename: 'logs/combined.log',
      maxsize: 5242880,
      maxFiles: 5,
    }),
  ],
});

if (process.env.NODE_ENV !== 'production') {
  logger.add(new winston.transports.Console({
    format: winston.format.combine(
      winston.format.colorize(),
      winston.format.simple()
    ),
  }));
}

// ============================================
// INITIALIZATION
// ============================================

const app = express();
const PORT = process.env.PORT || 3000;
const NODE_ENV = process.env.NODE_ENV || 'development';

// Initialize secrets manager
const secretsManager = new SecretsManager({
  cacheTTL: 60 * 60 * 1000, // 1 hour
  cacheEnabled: true
});

logger.info({
  message: 'Application starting',
  environment: NODE_ENV,
  secretsProvider: secretsManager.getStatus().provider
});

// ============================================
// CONFIGURATION INITIALIZATION
// ============================================

let JWT_SECRET;
let ALLOWED_ORIGINS;
let BCRYPT_ROUNDS = 10;

/**
 * Initialize application with secrets
 * Must be called before starting the server
 */
const initializeSecrets = async () => {
  try {
    logger.info({ message: 'Loading secrets...' });

    // Define required secrets
    const requiredSecrets = ['JWT_SECRET'];

    // Validate all required secrets exist
    await secretsManager.validateRequiredSecrets(requiredSecrets);

    // Load secrets
    JWT_SECRET = await secretsManager.getSecret('JWT_SECRET');

    // Validate JWT_SECRET is not empty or default value
    if (!JWT_SECRET || JWT_SECRET.length < 32) {
      throw new Error('JWT_SECRET must be at least 32 characters long');
    }

    // Load optional secrets with fallbacks
    try {
      ALLOWED_ORIGINS = await secretsManager.getSecret('ALLOWED_ORIGINS');
    } catch {
      ALLOWED_ORIGINS = process.env.ALLOWED_ORIGINS || 'http://localhost:3000';
      logger.warn({
        message: 'Using fallback for ALLOWED_ORIGINS',
        value: ALLOWED_ORIGINS
      });
    }

    // Load bcrypt rounds if specified
    try {
      const rounds = await secretsManager.getSecret('BCRYPT_ROUNDS');
      BCRYPT_ROUNDS = parseInt(rounds, 10);
    } catch {
      BCRYPT_ROUNDS = 10; // Default
    }

    logger.info({
      message: 'Secrets loaded successfully',
      secretsCount: requiredSecrets.length,
      cacheStats: secretsManager.getCacheStats()
    });

  } catch (error) {
    logger.error({
      message: 'Failed to initialize secrets',
      error: error.message
    });

    if (NODE_ENV === 'production') {
      logger.error({ message: 'FATAL: Cannot start in production without secrets' });
      process.exit(1);
    } else {
      logger.warn({ message: 'Continuing in development mode' });
      // Set development defaults (never use in production)
      JWT_SECRET = 'dev-secret-key-CHANGE-IN-PRODUCTION';
      ALLOWED_ORIGINS = 'http://localhost:3000';
    }
  }
};

// ============================================
// SECURITY MIDDLEWARE
// ============================================

// 1. Security Headers
app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      scriptSrc: ["'self'"],
      styleSrc: ["'self'", "'unsafe-inline'"],
      imgSrc: ["'self'", 'data:', 'https:'],
      connectSrc: ["'self'"],
      fontSrc: ["'self'"],
      objectSrc: ["'none'"],
      mediaSrc: ["'self'"],
      frameSrc: ["'none'"],
    },
  },
  hsts: {
    maxAge: 31536000,
    includeSubDomains: true,
    preload: true,
  },
  referrerPolicy: { policy: 'strict-origin-when-cross-origin' },
}));

// 2. CORS
app.use(cors({
  origin: (origin, callback) => {
    const origins = ALLOWED_ORIGINS.split(',').map(o => o.trim());
    if (!origin || origins.includes(origin)) {
      callback(null, true);
    } else {
      logger.warn({ origin, message: 'CORS origin rejected' });
      callback(new Error('CORS not allowed'));
    }
  },
  credentials: true,
  methods: ['GET', 'POST', 'PUT', 'DELETE', 'OPTIONS'],
  allowedHeaders: ['Content-Type', 'Authorization'],
  exposedHeaders: ['X-Request-ID'],
  maxAge: 3600,
}));

// 3. Rate Limiting
const globalLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 100,
  standardHeaders: true,
  legacyHeaders: false,
  skip: () => NODE_ENV === 'development',
  handler: (req, res) => {
    logger.warn({
      requestId: req.id,
      ip: req.ip,
      message: 'Rate limit exceeded',
    });
    res.status(429).json({
      error: 'Too many requests. Please try again later.'
    });
  },
});

app.use(globalLimiter);

const authLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 5,
  skipSuccessfulRequests: true,
  message: 'Too many login attempts',
});

// 4. Body Parser
app.use(express.json({ limit: '10kb', strict: true }));
app.use(express.urlencoded({ limit: '10kb', extended: false }));

// 5. Request ID Tracking
app.use((req, res, next) => {
  req.id = uuidv4();
  res.setHeader('X-Request-ID', req.id);

  logger.info({
    requestId: req.id,
    method: req.method,
    path: req.path,
    ip: req.ip,
  });

  res.on('finish', () => {
    logger.info({
      requestId: req.id,
      statusCode: res.statusCode,
    });
  });

  next();
});

// 6. Content-Type Validation
app.use((req, res, next) => {
  if (['POST', 'PUT', 'PATCH'].includes(req.method)) {
    const contentType = req.get('content-type');
    if (!contentType || !contentType.includes('application/json')) {
      return res.status(415).json({
        error: 'Content-Type must be application/json',
        requestId: req.id,
      });
    }
  }
  next();
});

// ============================================
// AUTHENTICATION MIDDLEWARE
// ============================================

const authenticateToken = (req, res, next) => {
  const authHeader = req.headers['authorization'];

  if (!authHeader) {
    return res.status(401).json({
      error: 'Authorization header required',
      requestId: req.id,
    });
  }

  const parts = authHeader.split(' ');
  if (parts.length !== 2 || parts[0] !== 'Bearer') {
    return res.status(401).json({
      error: 'Invalid authorization format. Use: Bearer <token>',
      requestId: req.id,
    });
  }

  const token = parts[1];

  jwt.verify(token, JWT_SECRET, (err, decoded) => {
    if (err) {
      logger.warn({
        requestId: req.id,
        error: err.name,
        message: 'Token verification failed',
      });

      if (err.name === 'TokenExpiredError') {
        return res.status(401).json({
          error: 'Token expired',
          requestId: req.id,
        });
      }

      return res.status(403).json({
        error: 'Invalid token',
        requestId: req.id,
      });
    }

    req.user = decoded;
    next();
  });
};

const authorize = (...roles) => {
  return (req, res, next) => {
    if (!req.user) {
      return res.status(401).json({ error: 'Authentication required' });
    }

    if (!roles.includes(req.user.role)) {
      logger.warn({
        requestId: req.id,
        userId: req.user.id,
        requiredRole: roles,
        userRole: req.user.role,
        message: 'Unauthorized access attempt',
      });

      return res.status(403).json({
        error: 'Insufficient permissions',
        requestId: req.id,
      });
    }

    next();
  };
};

// ============================================
// INPUT VALIDATION
// ============================================

const validateUserQuery = [
  query('id').optional().isInt({ min: 1 }).toInt(),
  query('search').optional().trim().isLength({ max: 100 }).escape(),
  query('limit').optional().isInt({ min: 1, max: 100 }).toInt(),
  query('offset').optional().isInt({ min: 0 }).toInt(),
];

const validateLoginBody = [
  body('username')
    .trim()
    .notEmpty()
    .withMessage('Username is required')
    .isLength({ min: 3, max: 50 })
    .withMessage('Username must be between 3 and 50 characters'),

  body('password')
    .notEmpty()
    .withMessage('Password is required')
    .isLength({ min: 8 })
    .withMessage('Password must be at least 8 characters'),
];

// ============================================
// DATA MODELS
// ============================================

// Mock users with hashed passwords
const users = [
  { 
    id: 1, 
    name: 'Alice', 
    email: 'alice@example.com', 
    role: 'admin',
    // Password would be hashed in real application
    passwordHash: '$2a$10$...' // bcrypt hash of 'SecurePassword123!'
  },
  { 
    id: 2, 
    name: 'Bob', 
    email: 'bob@example.com', 
    role: 'user',
    passwordHash: '$2a$10$...' // bcrypt hash
  },
];

// ============================================
// UTILITY FUNCTIONS
// ============================================

const sanitizeUser = (user, requestingUser) => {
  const sanitized = {
    id: user.id,
    name: user.name,
  };

  if (requestingUser?.role === 'admin') {
    sanitized.email = user.email;
    sanitized.role = user.role;
  }

  return sanitized;
};

const generateToken = (user) => {
  return jwt.sign(
    {
      id: user.id,
      username: user.email,
      role: user.role,
    },
    JWT_SECRET,
    { expiresIn: '1h' }
  );
};

const handleValidationErrors = (req, res) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    res.status(400).json({
      error: 'Validation failed',
      requestId: req.id,
      details: errors.array().map(err => ({
        field: err.param,
        message: err.msg,
      })),
    });
    return true;
  }
  return false;
};

// ============================================
// ROUTES
// ============================================

// Health check
app.get('/health', rateLimit({
  windowMs: 60 * 1000,
  max: 1000,
}), (req, res) => {
  res.set('Cache-Control', 'no-store');
  res.json({
    status: 'ok',
    timestamp: new Date().toISOString(),
    environment: NODE_ENV,
  });
});

// Login endpoint - SECURE VERSION
app.post('/login', authLimiter, validateLoginBody, async (req, res) => {
  if (handleValidationErrors(req, res)) return;

  const { username, password } = req.body;

  logger.info({
    requestId: req.id,
    action: 'login_attempt',
    username,
  });

  try {
    // In production, fetch user and verify password with bcrypt
    const user = users.find(u => u.email === username);

    if (!user) {
      logger.warn({
        requestId: req.id,
        action: 'login_failed',
        username,
        reason: 'user_not_found',
      });
      return res.status(401).json({
        error: 'Invalid credentials',
        requestId: req.id,
      });
    }

    // In production: Use bcrypt to verify password
    // const passwordMatch = await bcrypt.compare(password, user.passwordHash);
    // For demo purposes, we'll just validate password format
    if (password.length < 8) {
      return res.status(401).json({
        error: 'Invalid credentials',
        requestId: req.id,
      });
    }

    const token = generateToken(user);

    logger.info({
      requestId: req.id,
      action: 'login_success',
      userId: user.id,
    });

    res.json({
      token,
      expiresIn: '1h',
      user: sanitizeUser(user, user),
    });

  } catch (error) {
    logger.error({
      requestId: req.id,
      action: 'login_error',
      error: error.message,
    });

    res.status(500).json({
      error: 'Internal server error',
      requestId: req.id,
    });
  }
});

// Get users
app.get('/users',
  authenticateToken,
  validateUserQuery,
  (req, res) => {
    if (handleValidationErrors(req, res)) return;

    const { id, search, limit = 10, offset = 0 } = req.query;
    let results = [...users];

    if (id) {
      results = results.filter(u => u.id === id);
    }

    if (search) {
      const searchLower = search.toLowerCase();
      results = results.filter(u =>
        u.name.toLowerCase().includes(searchLower) ||
        (req.user.role === 'admin' && u.email.toLowerCase().includes(searchLower))
      );
    }

    const total = results.length;
    results = results.slice(offset, offset + limit);
    results = results.map(user => sanitizeUser(user, req.user));

    res.json({
      data: results,
      pagination: { offset, limit, total, returned: results.length },
      requestId: req.id,
    });
  }
);

// Get single user
app.get('/users/:id',
  authenticateToken,
  (req, res) => {
    const userId = parseInt(req.params.id);

    if (isNaN(userId)) {
      return res.status(400).json({
        error: 'Invalid user ID',
        requestId: req.id,
      });
    }

    const user = users.find(u => u.id === userId);

    if (!user) {
      return res.status(404).json({
        error: 'User not found',
        requestId: req.id,
      });
    }

    if (req.user.id !== userId && req.user.role !== 'admin') {
      logger.warn({
        requestId: req.id,
        userId: req.user.id,
        requestedUserId: userId,
        message: 'Unauthorized user access',
      });

      return res.status(403).json({
        error: 'Insufficient permissions',
        requestId: req.id,
      });
    }

    res.json({
      data: sanitizeUser(user, req.user),
      requestId: req.id,
    });
  }
);

// ============================================
// ERROR HANDLING
// ============================================

app.use((err, req, res, next) => {
  if (err.message === 'CORS not allowed') {
    logger.warn({
      requestId: req.id || 'unknown',
      origin: req.get('origin'),
      message: 'CORS error',
    });

    return res.status(403).json({
      error: 'CORS not allowed',
      requestId: req.id,
    });
  }
  next(err);
});

app.use((req, res) => {
  logger.warn({
    requestId: req.id,
    message: '404 Not Found',
    path: req.path,
    method: req.method,
  });

  res.status(404).json({
    error: 'Not found',
    requestId: req.id,
  });
});

app.use((err, req, res, next) => {
  logger.error({
    requestId: req.id,
    message: err.message,
    stack: err.stack,
    type: err.constructor.name,
  });

  const isDevelopment = NODE_ENV === 'development';
  const statusCode = err.statusCode || 500;

  res.status(statusCode).json({
    error: isDevelopment ? err.message : 'Internal server error',
    requestId: req.id,
    ...(isDevelopment && { stack: err.stack }),
  });
});

// ============================================
// SERVER STARTUP
// ============================================

/**
 * Start the server
 */
const startServer = async () => {
  try {
    // Initialize secrets before starting
    await initializeSecrets();

    logger.info({
      message: 'Secrets initialized, starting server...',
    });

    const server = app.listen(PORT, () => {
      logger.info({
        message: 'Server started successfully',
        port: PORT,
        environment: NODE_ENV,
        timestamp: new Date().toISOString(),
      });
    });

    // Graceful shutdown
    process.on('SIGTERM', () => {
      logger.info('SIGTERM signal received: closing HTTP server');
      server.close(() => {
        logger.info('HTTP server closed');
        process.exit(0);
      });
    });

    process.on('SIGINT', () => {
      logger.info('SIGINT signal received: closing HTTP server');
      server.close(() => {
        logger.info('HTTP server closed');
        process.exit(0);
      });
    });

  } catch (error) {
    logger.error({
      message: 'Failed to start server',
      error: error.message,
    });
    process.exit(1);
  }
};

// Only start if not being imported as module
if (require.main === module) {
  startServer();
}

process.on('uncaughtException', (err) => {
  logger.error({
    message: 'Uncaught Exception',
    error: err.message,
    stack: err.stack,
  });
  process.exit(1);
});

process.on('unhandledRejection', (reason, promise) => {
  logger.error({
    message: 'Unhandled Rejection',
    reason: reason,
    promise: promise,
  });
  process.exit(1);
});

module.exports = app;

