const logger = winston.createLogger({
  level: process.env.LOG_LEVEL || 'info',
  format: winston.format.json(),
  transports: [
    new winston.transports.File({ filename: 'error.log', level: 'error' }),
    new winston.transports.File({ filename: 'combined.log' })
  ]
});

if (process.env.NODE_ENV !== 'production') {
  logger.add(new winston.transports.Console({
    format: winston.format.simple()
  }));
}

// ==================== SECURITY HEADERS ====================
app.use(helmet());
app.use(helmet.contentSecurityPolicy({
  directives: {
    defaultSrc: ["'self'"],
    scriptSrc: ["'self'"],
    styleSrc: ["'self'", "'unsafe-inline'"],
    imgSrc: ["'self'", "data:", "https:"],
    connectSrc: ["'self'"],
    fontSrc: ["'self'"],
    objectSrc: ["'none'"],
    mediaSrc: ["'self'"],
    frameSrc: ["'none'"]
  }
}));

// ==================== CORS ====================
const corsOptions = {
  origin: function (origin, callback) {
    const allowedOrigins = (process.env.ALLOWED_ORIGINS || 'http://localhost:3000').split(',');
    if (!origin || allowedOrigins.includes(origin.trim())) {
      callback(null, true);
    } else {
      callback(new Error('Not allowed by CORS'));
    }
  },
  credentials: true,
  methods: ['GET', 'POST', 'PUT', 'DELETE'],
  allowedHeaders: ['Content-Type', 'Authorization'],
  maxAge: 3600
};
app.use(cors(corsOptions));

// ==================== BODY PARSER ====================
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ limit: '10kb', extended: false }));

// ==================== RATE LIMITING ====================
const globalLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 100,
  message: 'Too many requests',
  standardHeaders: true,
  legacyHeaders: false
});
app.use(globalLimiter);

const authLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 5,
  message: 'Too many authentication attempts'
});

// ==================== REQUEST ID ====================
app.use((req, res, next) => {
  req.id = req.get('X-Request-ID') || uuidv4();
  res.setHeader('X-Request-ID', req.id);
  next();
});

// ==================== AUTHENTICATION ====================
const authenticateToken = (req, res, next) => {
  const authHeader = req.headers['authorization'];
  const token = authHeader && authHeader.split(' ')[1];

  if (!token) {
    return res.status(401).json({ error: 'Access token required' });
  }

  jwt.verify(token, process.env.ACCESS_TOKEN_SECRET, (err, user) => {
    if (err) {
      logger.warn('Invalid token attempt', { requestId: req.id, ip: req.ip });
      return res.status(403).json({ error: 'Invalid or expired token' });
    }
    req.user = user;
    next();
  });
};

// ==================== ASYNC ERROR HANDLER ====================
const asyncHandler = (fn) => (req, res, next) => {
  Promise.resolve(fn(req, res, next)).catch(next);
};

// ==================== VALIDATION MIDDLEWARE ====================
const handleValidationErrors = (req, res, next) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({ errors: errors.array() });
  }
  next();
};

// ==================== ROUTES ====================
app.get('/api/v1/health', asyncHandler(async (req, res) => {
  logger.info('Health check', { requestId: req.id });
  res.json({ 
    status: 'ok', 
    timestamp: new Date().toISOString(),
    environment: process.env.NODE_ENV
  });
}));

app.get('/api/v1/users', 
  authenticateToken,
  asyncHandler(async (req, res) => {
    logger.info('Fetching users', { requestId: req.id, userId: req.user.id });
    res.json([
      { id: 1, name: 'Alice' },
      { id: 2, name: 'Bob' }
    ]);
  })
);

app.get('/api/v1/users/:id',
  authenticateToken,
  param('id').isInt().toInt(),
  handleValidationErrors,
  asyncHandler(async (req, res) => {
    const userId = req.params.id;
    logger.info('Fetching user', { requestId: req.id, userId });
    res.json({ id: userId, name: 'User' });
  })
);

// ==================== ERROR HANDLING ====================
app.use((err, req, res, next) => {
  logger.error({
    message: err.message,
    stack: err.stack,
    requestId: req.id,
    path: req.path,
    method: req.method,
    ip: req.ip
  });

  const statusCode = err.statusCode || 500;
  const message = process.env.NODE_ENV === 'production' 
    ? 'Internal Server Error' 
    : err.message;

  res.status(statusCode).json({ 
    error: message,
    requestId: req.id 
  });
});

// ==================== 404 HANDLER ====================
app.use((req, res) => {
  logger.warn('Route not found', { requestId: req.id, path: req.path });
  res.status(404).json({ error: 'Not found', requestId: req.id });
});

// ==================== START SERVER ====================
const PORT = process.env.PORT || 3000;
const HOST = process.env.HOST || 'localhost';
const NODE_ENV = process.env.NODE_ENV || 'development';

const requiredEnvVars = ['ACCESS_TOKEN_SECRET'];
requiredEnvVars.forEach((envVar) => {
  if (!process.env[envVar] && NODE_ENV === 'production') {
    logger.error(`Missing required environment variable: ${envVar}`);
    process.exit(1);
  }
});

app.listen(PORT, HOST, () => {
  logger.info(`Server running on ${HOST}:${PORT} in ${NODE_ENV} mode`);
});

module.exports = app;
```

