    const allowedOrigins = (process.env.ALLOWED_ORIGINS || 'http://localhost:3000').split(',');
    const trimmedOrigins = allowedOrigins.map(o => o.trim());

    if (!origin || trimmedOrigins.includes(origin)) {
      callback(null, true);
    } else {
      logger.warn('CORS rejected', { origin });
      callback(new Error('Not allowed by CORS'));
    }
  },
  credentials: true,
  methods: ['GET', 'POST', 'PUT', 'DELETE', 'OPTIONS'],
  allowedHeaders: ['Content-Type', 'Authorization'],
  exposedHeaders: ['X-Request-ID', 'X-RateLimit-Limit', 'X-RateLimit-Remaining'],
  maxAge: 3600
};
app.use(cors(corsOptions));

// ==================== BODY PARSER ====================
app.use(express.json({ 
  limit: '10kb',
  strict: true,
  verify: (req, res, buf, encoding) => {
    req.rawBody = buf.toString(encoding || 'utf8');
  }
}));
app.use(express.urlencoded({ limit: '10kb', extended: false }));

// ==================== RATE LIMITING ====================
const globalLimiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true, // Return rate limit info in the `RateLimit-*` headers
  legacyHeaders: false, // Disable the `X-RateLimit-*` headers
  skip: (req) => {
    // Skip rate limiting for health checks in production
    return process.env.NODE_ENV === 'production' && req.path === '/api/v1/health';
  },
  handler: (req, res) => {
    logger.warn('Rate limit exceeded', { ip: req.ip, path: req.path });
    res.status(429).json({ error: 'Too many requests' });
  }
});
app.use(globalLimiter);

const authLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 5, // 5 attempts
  message: 'Too many authentication attempts, please try again later.',
  skipSuccessfulRequests: true // Don't count successful requests
});

// ==================== REQUEST ID & CONTEXT ====================
app.use((req, res, next) => {
  req.id = req.get('X-Request-ID') || uuidv4();
  res.setHeader('X-Request-ID', req.id);

  // Log incoming request
  logger.info('Incoming request', {
    requestId: req.id,
    method: req.method,
    path: req.path,
    ip: req.ip,
    userAgent: req.get('user-agent')
  });

  next();
});

// ==================== AUTHENTICATION ====================
const authenticateToken = (req, res, next) => {
  const authHeader = req.headers['authorization'];
  const token = authHeader && authHeader.split(' ')[1];

  if (!token) {
    logger.warn('Missing authentication token', { requestId: req.id, ip: req.ip });
    return res.status(401).json({ 
      error: 'Access token required',
      requestId: req.id 
    });
  }

  // Validate token format
  if (typeof token !== 'string' || token.length > 2000) {
    logger.warn('Invalid token format', { requestId: req.id });
    return res.status(401).json({ 
      error: 'Invalid token format',
      requestId: req.id 
    });
  }

  jwt.verify(token, process.env.ACCESS_TOKEN_SECRET, (err, user) => {
    if (err) {
      logger.warn('Token verification failed', { 
        requestId: req.id, 
        ip: req.ip,
        error: err.message 
      });
      return res.status(403).json({ 
        error: 'Invalid or expired token',
        requestId: req.id 
      });
    }

    req.user = user;
    logger.debug('Token verified', { requestId: req.id, userId: user.id });
    next();
  });
};

// ==================== ASYNC ERROR HANDLER ====================
const asyncHandler = (fn) => (req, res, next) => {
  Promise.resolve(fn(req, res, next)).catch(next);
};

// ==================== VALIDATION MIDDLEWARE ====================
const handleValidationErrors = (req, res, next) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    logger.warn('Validation errors', { 
      requestId: req.id,
      errors: errors.array() 
    });
    return res.status(400).json({ 
      error: 'Validation failed',
      details: errors.array(),
      requestId: req.id 
    });
  }
  next();
};

// ==================== ROUTES ====================

/**
 * Health check endpoint
 * GET /api/v1/health
 * Returns: { status, timestamp, environment }
 */
app.get('/api/v1/health', asyncHandler(async (req, res) => {
  logger.info('Health check', { requestId: req.id });
  res.json({ 
    status: 'ok', 
    timestamp: new Date().toISOString(),
    environment: process.env.NODE_ENV,
    requestId: req.id
  });
}));

/**
 * Get all users (requires authentication)
 * GET /api/v1/users
 * Headers: Authorization: Bearer <token>
 * Returns: [{ id, name }]
 */
app.get('/api/v1/users', 
  authenticateToken,
  asyncHandler(async (req, res) => {
    logger.info('Fetching all users', { 
      requestId: req.id, 
      userId: req.user.id 
    });

    // Simulate database query
    const users = [
      { id: 1, name: 'Alice' },
      { id: 2, name: 'Bob' }
    ];

    res.json(users);
  })
);

/**
 * Get user by ID (requires authentication)
 * GET /api/v1/users/:id
 * Headers: Authorization: Bearer <token>
 * Returns: { id, name }
 */
app.get('/api/v1/users/:id',
  authenticateToken,
  param('id')
    .isInt({ min: 1, max: 2147483647 })
    .withMessage('User ID must be a positive integer'),
  handleValidationErrors,
  asyncHandler(async (req, res) => {
    const userId = parseInt(req.params.id);

    logger.info('Fetching user by ID', { 
      requestId: req.id, 
      userId,
      requestingUser: req.user.id 
    });

    // Simulate database query with access control
    const users = { 1: { id: 1, name: 'Alice' }, 2: { id: 2, name: 'Bob' } };
    const user = users[userId];

    if (!user) {
      logger.warn('User not found', { requestId: req.id, userId });
      return res.status(404).json({ 
        error: 'User not found',
        requestId: req.id 
      });
    }

    res.json(user);
  })
);

/**
 * Search users (requires authentication)
 * GET /api/v1/users/search?q=<query>
 * Headers: Authorization: Bearer <token>
 * Returns: [{ id, name }]
 */
app.get('/api/v1/search',
  authenticateToken,
  query('q')
    .trim()
    .isLength({ min: 1, max: 100 })
    .withMessage('Search query must be between 1 and 100 characters')
    .escape(), // Sanitize HTML entities
  handleValidationErrors,
  asyncHandler(async (req, res) => {
    const searchTerm = req.query.q;

    logger.info('Search query', { 
      requestId: req.id,
      searchTerm,
      userId: req.user.id 
    });

    // Simulate search
    const results = [];

    res.json(results);
  })
);

/**
 * Create user (requires authentication)
 * POST /api/v1/users
 * Headers: Authorization: Bearer <token>, Content-Type: application/json
 * Body: { name, email }
 * Returns: { id, name, email }
 */
app.post('/api/v1/users',
  authenticateToken,
  query('name')
    .trim()
    .isLength({ min: 1, max: 100 })
    .withMessage('Name must be between 1 and 100 characters')
    .escape(),
  query('email')
    .trim()
    .isEmail()
    .normalizeEmail()
    .withMessage('Invalid email format'),
  handleValidationErrors,
  asyncHandler(async (req, res) => {
    const { name, email } = req.body;

    logger.info('Creating user', { 
      requestId: req.id,
      userId: req.user.id,
      newUserName: name 
    });

    // Simulate database insert
    const newUser = { id: 3, name, email };

    res.status(201).json(newUser);
  })
);

// ==================== 404 HANDLER ====================
app.use((req, res) => {
  logger.warn('Route not found', { 
    requestId: req.id, 
    path: req.path,
    method: req.method 
  });
  res.status(404).json({ 
    error: 'Not found',
    requestId: req.id 
  });
});

// ==================== GLOBAL ERROR HANDLER ====================
app.use((err, req, res, next) => {
  // Distinguish between expected and unexpected errors
  const statusCode = err.statusCode || 500;
  const isOperationalError = err.isOperational || false;

  logger.error({
    message: err.message,
    stack: err.stack,
    requestId: req.id,
    path: req.path,
    method: req.method,
    ip: req.ip,
    statusCode,
    isOperational: isOperationalError
  });

  // Don't leak error details in production
  const message = process.env.NODE_ENV === 'production' && !isOperationalError
    ? 'Internal Server Error' 
    : err.message;

  res.status(statusCode).json({ 
    error: message,
    requestId: req.id,
    ...(process.env.NODE_ENV !== 'production' && { details: err.stack })
  });
});

// ==================== VALIDATION ====================
function validateEnvironment() {
  const requiredEnvVars = ['ACCESS_TOKEN_SECRET'];
  const missingVars = requiredEnvVars.filter(envVar => !process.env[envVar]);

  if (missingVars.length > 0 && process.env.NODE_ENV === 'production') {
    throw new Error(`Missing required environment variables: ${missingVars.join(', ')}`);
  }

  if (missingVars.length > 0) {
    logger.warn('Missing environment variables', { missingVars });
  }
}

// ==================== START SERVER ====================
const PORT = parseInt(process.env.PORT, 10) || 3000;
const HOST = process.env.HOST || 'localhost';
const NODE_ENV = process.env.NODE_ENV || 'development';

if (PORT < 1 || PORT > 65535) {
  throw new Error('PORT must be between 1 and 65535');
}

try {
  validateEnvironment();

  app.listen(PORT, HOST, () => {
    logger.info(`Server started`, {
      host: HOST,
      port: PORT,
      environment: NODE_ENV,
      timestamp: new Date().toISOString()
    });
  });

  // Graceful shutdown
  process.on('SIGTERM', () => {
    logger.info('SIGTERM received, shutting down gracefully');
    process.exit(0);
  });

  process.on('SIGINT', () => {
    logger.info('SIGINT received, shutting down gracefully');
    process.exit(0);
  });

  // Uncaught exception handler
  process.on('uncaughtException', (err) => {
    logger.error('Uncaught exception', {
      message: err.message,
      stack: err.stack
    });
    process.exit(1);
  });

  process.on('unhandledRejection', (reason, promise) => {
    logger.error('Unhandled rejection', {
      promise,
      reason
    });
  });

} catch (error) {
  logger.error('Failed to start server', {
    message: error.message,
    stack: error.stack
  });
  process.exit(1);
}

