# Vulnerability Examples & Fixes

## 1. SQL Injection

### ❌ VULNERABLE CODE
```javascript
app.get('/users/:id', (req, res) => {
  // Direct concatenation - DANGEROUS!
  const query = `SELECT * FROM users WHERE id = ${req.params.id}`;
  db.query(query, (err, results) => {
    res.json(results);
  });
});

// Attack: GET /users/1 OR 1=1
// Query becomes: SELECT * FROM users WHERE id = 1 OR 1=1
// Returns ALL users regardless of ID!
```

### ✅ FIXED CODE
```javascript
const { param, validationResult } = require('express-validator');

app.get('/users/:id',
  param('id').isInt(),
  (req, res) => {
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({ errors: errors.array() });
    }

    // Use parameterized query
    const userId = parseInt(req.params.id);
    db.query('SELECT * FROM users WHERE id = $1', [userId], (err, results) => {
      if (err) {
        logger.error('Database error', { error: err.message });
        return res.status(500).json({ error: 'Internal server error' });
      }
      res.json(results);
    });
  }
);
```

---

## 2. XSS (Cross-Site Scripting)

### ❌ VULNERABLE CODE
```javascript
app.get('/search', (req, res) => {
  const searchTerm = req.query.q;

  // Directly embedding user input in HTML - DANGEROUS!
  const html = `
    <html>
      <body>
        <h1>Search Results for: ${searchTerm}</h1>
      </body>
    </html>
  `;

  res.send(html);
});

// Attack: GET /search?q=<script>alert('XSS')</script>
// Script executes in user's browser!
```

### ✅ FIXED CODE
```javascript
const { query, validationResult } = require('express-validator');

app.get('/search',
  query('q')
    .trim()
    .isLength({ min: 1, max: 100 })
    .escape(), // Escapes HTML entities
  (req, res) => {
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({ errors: errors.array() });
    }

    const searchTerm = req.query.q; // Now safely escaped: <script>... becomes &lt;script&gt;...

    const html = `
      <html>
        <body>
          <h1>Search Results for: ${searchTerm}</h1>
        </body>
      </html>
    `;

    res.send(html);
  }
);

// Or better - return JSON:
app.get('/search',
  query('q')
    .trim()
    .isLength({ min: 1, max: 100 }),
  (req, res) => {
    const searchTerm = req.query.q;
    res.json({ results: [] });
  }
);
```

---

## 3. Authentication Bypass

### ❌ VULNERABLE CODE
```javascript
app.get('/admin', (req, res) => {
  // No authentication check!
  const adminData = {
    users: 100,
    revenue: 50000
  };
  res.json(adminData);
});

// Attack: Anyone can access /admin
```

### ✅ FIXED CODE
```javascript
const jwt = require('jsonwebtoken');

const requireAdmin = (req, res, next) => {
  const token = req.headers['authorization']?.split(' ')[1];

  if (!token) {
    logger.warn('Missing token on admin endpoint', { ip: req.ip });
    return res.status(401).json({ error: 'Token required' });
  }

  jwt.verify(token, process.env.ACCESS_TOKEN_SECRET, (err, user) => {
    if (err) {
      logger.warn('Invalid token on admin endpoint', { ip: req.ip });
      return res.status(403).json({ error: 'Invalid token' });
    }

    // Check user role
    if (user.role !== 'admin') {
      logger.warn('Non-admin accessing admin endpoint', { userId: user.id });
      return res.status(403).json({ error: 'Admin access required' });
    }

    req.user = user;
    next();
  });
};

app.get('/admin', requireAdmin, (req, res) => {
  const adminData = {
    users: 100,
    revenue: 50000
  };
  res.json(adminData);
});

// Now only users with valid admin token can access
```

---

## 4. CSRF (Cross-Site Request Forgery)

### ❌ VULNERABLE CODE
```javascript
app.post('/transfer-money', (req, res) => {
  const { amount, toAccount } = req.body;

  // No CSRF protection!
  bank.transfer(req.user.id, toAccount, amount);
  res.json({ success: true });
});

// Attack: Attacker's website contains:
// <img src="https://bank.com/transfer-money?amount=1000&toAccount=attacker" />
// Victim's logged-in session automatically transfers money!
```

### ✅ FIXED CODE
```javascript
const csrf = require('csurf');
const cookieParser = require('cookie-parser');

app.use(cookieParser());
app.use(csrf({ cookie: false })); // Use session-based tokens

app.get('/transfer-form', (req, res) => {
  res.json({ csrfToken: req.csrfToken() });
});

app.post('/transfer-money',
  (req, res, next) => {
    // CSRF middleware validates token automatically
    next();
  },
  (req, res) => {
    const { amount, toAccount } = req.body;

    logger.info('Money transfer', {
      from: req.user.id,
      to: toAccount,
      amount
    });

    bank.transfer(req.user.id, toAccount, amount);
    res.json({ success: true });
  }
);

// Client must include CSRF token in POST request
// Attack now fails because attacker doesn't have valid CSRF token
```

---

## 5. Sensitive Data Exposure

### ❌ VULNERABLE CODE
```javascript
app.get('/users', (req, res) => {
  // Returns all data including sensitive information
  res.json([
    { 
      id: 1, 
      name: 'Alice',
      email: 'alice@example.com',
      password: 'hashed_password_here', // EXPOSED!
      ssn: '123-45-6789', // EXPOSED!
      creditCard: '4111-1111-1111-1111' // EXPOSED!
    }
  ]);
});

// Attack: Any unauthorized user can enumerate all users with sensitive data
```

### ✅ FIXED CODE
```javascript
const rateLimit = require('express-rate-limit');

const limiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 100
});

app.get('/users',
  limiter,
  authenticateToken,
  (req, res) => {
    // Only return necessary, non-sensitive data
    res.json([
      { 
        id: 1, 
        name: 'Alice',
        avatar: 'https://cdn.example.com/alice.jpg'
      },
      { 
        id: 2, 
        name: 'Bob',
        avatar: 'https://cdn.example.com/bob.jpg'
      }
    ]);
  }
);

// Separate endpoint for current user's full data
app.get('/me', authenticateToken, (req, res) => {
  const userData = getUserById(req.user.id);
  res.json({
    id: userData.id,
    name: userData.name,
    email: userData.email // User's own email only
    // NO password, SSN, or credit card data
  });
});
```

---

## 6. Broken Access Control

### ❌ VULNERABLE CODE
```javascript
app.get('/user/:id/profile', (req, res) => {
  const userId = req.params.id;

  // No authorization check - user can access anyone's profile!
  const profile = db.getUserProfile(userId);
  res.json(profile);
});

// Attack: GET /user/2/profile (accesses someone else's profile)
```

### ✅ FIXED CODE
```javascript
app.get('/user/:id/profile',
  authenticateToken,
  param('id').isInt(),
  (req, res) => {
    const userId = parseInt(req.params.id);

    // Authorization check - ensure user can only access their own profile
    if (userId !== req.user.id && req.user.role !== 'admin') {
      logger.warn('Unauthorized profile access', {
        requestingUser: req.user.id,
        targetUser: userId
      });
      return res.status(403).json({ error: 'Forbidden' });
    }

    const profile = db.getUserProfile(userId);
    res.json(profile);
  }
);

// Now /user/2/profile fails for user 1 (403 Forbidden)
```

---

## 7. Rate Limit Bypass

### ❌ VULNERABLE CODE
```javascript
app.post('/login', (req, res) => {
  const { email, password } = req.body;

  // No rate limiting - brute force possible!
  const user = db.validateCredentials(email, password);

  if (!user) {
    return res.status(401).json({ error: 'Invalid credentials' });
  }

  const token = generateToken(user);
  res.json({ token });
});

// Attack: Attacker can try millions of password combinations
```

### ✅ FIXED CODE
```javascript
const rateLimit = require('express-rate-limit');

const loginLimiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 5, // 5 attempts
  skipSuccessfulRequests: true, // Don't count successful attempts
  message: 'Too many login attempts, please try again later',
  handler: (req, res) => {
    logger.warn('Login rate limit exceeded', {
      email: req.body.email,
      ip: req.ip
    });
    res.status(429).json({ error: 'Too many attempts' });
  }
});

app.post('/login', loginLimiter, (req, res) => {
  const { email, password } = req.body;

  const user = db.validateCredentials(email, password);

  if (!user) {
    logger.warn('Failed login attempt', { email, ip: req.ip });
    return res.status(401).json({ error: 'Invalid credentials' });
  }

  const token = generateToken(user);
  logger.info('Successful login', { userId: user.id });
  res.json({ token });
});

// Now limited to 5 attempts per 15 minutes
```

---

## 8. Missing HTTPS

### ❌ VULNERABLE CODE
```javascript
// No HTTPS - all traffic is unencrypted!
app.listen(3000, () => {
  console.log('Server running on http://localhost:3000');
});

// Attack: Man-in-the-middle can intercept all data including tokens!
```

### ✅ FIXED CODE
```javascript
const https = require('https');
const fs = require('fs');

// Redirect HTTP to HTTPS
app.use((req, res, next) => {
  if (process.env.NODE_ENV === 'production' && !req.secure) {
    return res.redirect(301, `https://${req.get('host')}${req.url}`);
  }
  next();
});

// Use HTTPS in production
if (process.env.NODE_ENV === 'production') {
  const options = {
    key: fs.readFileSync(process.env.SSL_KEY_PATH),
    cert: fs.readFileSync(process.env.SSL_CERT_PATH)
  };

  https.createServer(options, app).listen(443, () => {
    logger.info('HTTPS server running on port 443');
  });
} else {
  app.listen(3000, () => {
    logger.info('HTTP server running on port 3000 (development only)');
  });
}

// Or use nginx/Apache reverse proxy for HTTPS termination (recommended)
```

---

## 9. Unvalidated Redirects

### ❌ VULNERABLE CODE
```javascript
app.get('/redirect', (req, res) => {
  const url = req.query.url;

  // No validation - attacker can redirect to malicious site!
  res.redirect(url);
});

// Attack: GET /redirect?url=https://malicious.com/phishing
// User is redirected to phishing site while believing they're on your domain
```

### ✅ FIXED CODE
```javascript
const { URL } = require('url');

const isValidRedirect = (urlString) => {
  try {
    const url = new URL(urlString);
    // Only allow redirects to your own domain
    return url.hostname === 'yourdomain.com';
  } catch {
    return false;
  }
};

app.get('/redirect',
  query('url').custom(isValidRedirect),
  (req, res) => {
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({ error: 'Invalid redirect URL' });
    }

    res.redirect(req.query.url);
  }
);

// Only allows redirects within your domain
```

---

## 10. Information Disclosure

### ❌ VULNERABLE CODE
```javascript
app.use((err, req, res, next) => {
  // Leaking full error details to client!
  res.status(500).json({
    error: err.message,
    stack: err.stack,
    sql: err.sql, // Database query revealed!
    connection: err.connection // Connection string revealed!
  });
});

// Attack: Attacker can use error messages to learn about your system
```

### ✅ FIXED CODE
```javascript
app.use((err, req, res, next) => {
  logger.error('Error', {
    message: err.message,
    stack: err.stack,
    requestId: req.id,
    path: req.path
  });

  // Never expose internal details to client
  const message = process.env.NODE_ENV === 'production'
    ? 'Internal Server Error'
    : err.message;

  res.status(err.statusCode || 500).json({
    error: message,
    requestId: req.id
    // NO stack trace, sql, or connection details in production
  });
});

// Only generic error messages shown to users
// Full details logged server-side for debugging
```

---

