# Migration Guide: From Insecure to Secure app.js

## Overview
This guide helps you migrate from the original `app.js` to the security-hardened `app-secure.js`.

## Step-by-Step Migration

### Step 1: Install Dependencies

```bash
npm install \
  helmet \
  cors \
  express-rate-limit \
  express-validator \
  jsonwebtoken \
  uuid \
  winston \
  dotenv
```

### Step 2: Environment Setup

1. Copy `.env.example` to `.env`:
```bash
cp .env.example .env
```

2. Update `.env` with your actual values:
```bash
# Generate a secure ACCESS_TOKEN_SECRET
node -e "console.log(require('crypto').randomBytes(32).toString('hex'))"

# Update in .env
ACCESS_TOKEN_SECRET=<generated-value>
REFRESH_TOKEN_SECRET=<generated-value>
```

3. Add `.env` to `.gitignore`:
```bash
echo ".env" >> .gitignore
```

### Step 3: Update Application Code

Replace `app.js` with `app-secure.js` or apply the following changes:

#### A. Add Security Middleware
```javascript
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');

app.use(helmet());
app.use(cors(corsOptions));
app.use(rateLimit({ ... }));
```

#### B. Add Authentication
```javascript
const jwt = require('jsonwebtoken');

const authenticateToken = (req, res, next) => {
  const token = req.headers['authorization']?.split(' ')[1];
  if (!token) return res.status(401).json({ error: 'Token required' });

  jwt.verify(token, process.env.ACCESS_TOKEN_SECRET, (err, user) => {
    if (err) return res.status(403).json({ error: 'Invalid token' });
    req.user = user;
    next();
  });
};

// Use on protected routes
app.get('/api/v1/users', authenticateToken, (req, res) => { ... });
```

#### C. Add Input Validation
```javascript
const { param, query, validationResult } = require('express-validator');

app.get('/api/v1/users/:id',
  authenticateToken,
  param('id').isInt().toInt(),
  (req, res) => {
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({ errors: errors.array() });
    }
    // ... rest of handler
  }
);
```

#### D. Add Logging
```javascript
const winston = require('winston');

const logger = winston.createLogger({
  level: process.env.LOG_LEVEL || 'info',
  format: winston.format.json(),
  transports: [
    new winston.transports.File({ filename: 'error.log', level: 'error' }),
    new winston.transports.File({ filename: 'combined.log' })
  ]
});

if (process.env.NODE_ENV !== 'production') {
  logger.add(new winston.transports.Console({
    format: winston.format.simple()
  }));
}
```

#### E. Add Error Handling
```javascript
// Async handler wrapper
const asyncHandler = (fn) => (req, res, next) => {
  Promise.resolve(fn(req, res, next)).catch(next);
};

// Global error handler (must be last)
app.use((err, req, res, next) => {
  logger.error({
    message: err.message,
    stack: err.stack,
    requestId: req.id
  });

  res.status(err.statusCode || 500).json({ 
    error: process.env.NODE_ENV === 'production' 
      ? 'Internal Server Error' 
      : err.message 
  });
});
```

