## 🛡️ Secure Implementation Pattern

### Complete Secrets Management Layer

**secrets-manager.js** (Production-Safe)
```javascript
const fs = require('fs');
const path = require('path');
const logger = require('./logger');

class SecretsManager {
  constructor() {
    this.secrets = {};
    this.loadMethod = null;
    this.rotationInterval = null;
  }

  async initialize() {
    if (process.env.NODE_ENV === 'production') {
      await this.initializeProductionSecrets();
    } else {
      await this.initializeDevelopmentSecrets();
    }
  }

  async initializeProductionSecrets() {
    const provider = process.env.SECRETS_PROVIDER || 'aws';

    logger.info('Loading secrets from provider', { provider });

    switch (provider) {
      case 'aws':
        await this.loadFromAwsSecretsManager();
        this.setupRotationTimer('aws');
        break;

      case 'vault':
        await this.loadFromVault();
        this.setupRotationTimer('vault');
        break;

      case 'azure':
        await this.loadFromAzureKeyVault();
        this.setupRotationTimer('azure');
        break;

      case 'gcp':
        await this.loadFromGcpSecretManager();
        this.setupRotationTimer('gcp');
        break;

      default:
        throw new Error(`Unknown secrets provider: ${provider}`);
    }

    // Validate that all required secrets are loaded
    this.validateRequiredSecrets();
  }

  async initializeDevelopmentSecrets() {
    // Only for development
    if (process.env.NODE_ENV !== 'development') {
      throw new Error('Development secrets initialization in non-dev environment');
    }

    logger.warn('Loading secrets from .env file (DEVELOPMENT ONLY)');
    require('dotenv').config();

    this.secrets = {
      ACCESS_TOKEN_SECRET: process.env.ACCESS_TOKEN_SECRET,
      REFRESH_TOKEN_SECRET: process.env.REFRESH_TOKEN_SECRET,
      DATABASE_URL: process.env.DATABASE_URL
    };
  }

  async loadFromAwsSecretsManager() {
    const AWS = require('aws-sdk');
    const client = new AWS.SecretsManager({
      region: process.env.AWS_REGION || 'us-east-1'
    });

    const secrets = [
      'app/jwt-secrets',
      'app/database-config',
      'app/external-apis'
    ];

    for (const secretName of secrets) {
      try {
        const data = await client
          .getSecretValue({ SecretId: secretName })
          .promise();

        const secretValue = 'SecretString' in data 
          ? JSON.parse(data.SecretString)
          : Buffer.from(data.SecretBinary, 'base64').toString('utf8');

        this.secrets[secretName] = secretValue;
        logger.info('Loaded secret', { secret: secretName });
      } catch (error) {
        logger.error('Failed to load secret', { 
          secret: secretName, 
          error: error.message 
        });
        throw error;
      }
    }
  }

  async loadFromVault() {
    const Vault = require('node-vault');

    const vault = new Vault({
      endpoint: process.env.VAULT_ADDR,
      token: process.env.VAULT_TOKEN
    });

    const secretPaths = [
      'secret/data/app/jwt',
      'secret/data/app/database',
      'secret/data/app/external'
    ];

    for (const path of secretPaths) {
      try {
        const result = await vault.read(path);
        this.secrets[path] = result.data.data;
      } catch (error) {
        logger.error('Failed to read from Vault', { path, error: error.message });
        throw error;
      }
    }
  }

  async loadFromAzureKeyVault() {
    const { SecretClient } = require("@azure/keyvault-secrets");
    const { DefaultAzureCredential } = require("@azure/identity");

    const credential = new DefaultAzureCredential();
    const client = new SecretClient(
      process.env.KEY_VAULT_URI,
      credential
    );

    const secretNames = [
      'AccessTokenSecret',
      'RefreshTokenSecret',
      'DatabaseUrl'
    ];

    for (const name of secretNames) {
      try {
        const secret = await client.getSecret(name);
        this.secrets[name] = secret.value;
      } catch (error) {
        logger.error('Failed to get Azure secret', { name, error: error.message });
        throw error;
      }
    }
  }

  async loadFromGcpSecretManager() {
    const { SecretManagerServiceClient } = require('@google-cloud/secret-manager');
    const client = new SecretManagerServiceClient();

    const secretNames = [
      'access-token-secret',
      'refresh-token-secret',
      'database-url'
    ];

    for (const name of secretNames) {
      try {
        const [version] = await client.accessSecretVersion({
          name: `projects/${process.env.GCP_PROJECT}/secrets/${name}/versions/latest`
        });

        this.secrets[name] = version.payload.data.toString('utf8');
      } catch (error) {
        logger.error('Failed to get GCP secret', { name, error: error.message });
        throw error;
      }
    }
  }

  validateRequiredSecrets() {
    const required = [
      'ACCESS_TOKEN_SECRET',
      'REFRESH_TOKEN_SECRET'
    ];

    for (const secret of required) {
      if (!this.getSecret(secret)) {
        throw new Error(`Required secret not loaded: ${secret}`);
      }
    }

    logger.info('All required secrets validated');
  }

  setupRotationTimer(provider) {
    const rotationHours = parseInt(process.env.SECRET_ROTATION_HOURS) || 24;
    const rotationMs = rotationHours * 60 * 60 * 1000;

    this.rotationInterval = setInterval(async () => {
      logger.info('Rotating secrets', { provider, rotationHours });
      try {
        switch (provider) {
          case 'aws':
            await this.loadFromAwsSecretsManager();
            break;
          case 'vault':
            await this.loadFromVault();
            break;
          case 'azure':
            await this.loadFromAzureKeyVault();
            break;
          case 'gcp':
            await this.loadFromGcpSecretManager();
            break;
        }
        logger.info('Secrets rotated successfully');
      } catch (error) {
        logger.error('Secret rotation failed', { error: error.message });
      }
    }, rotationMs);
  }

  getSecret(key) {
    // Never log the actual secret value
    if (!this.secrets[key]) {
      logger.warn('Secret requested but not found', { key });
      return undefined;
    }
    return this.secrets[key];
  }

  getAllSecrets() {
    // Return only keys, never values, for logging purposes
    return Object.keys(this.secrets);
  }

  shutdown() {
    if (this.rotationInterval) {
      clearInterval(this.rotationInterval);
    }
  }
}

module.exports = SecretsManager;
```

**Usage in app-secure.js:**
```javascript
const SecretsManager = require('./secrets-manager');

let secretsManager;

(async () => {
  try {
    secretsManager = new SecretsManager();
    await secretsManager.initialize();

    // Set process.env with loaded secrets (careful!)
    process.env.ACCESS_TOKEN_SECRET = secretsManager.getSecret('ACCESS_TOKEN_SECRET');
    process.env.REFRESH_TOKEN_SECRET = secretsManager.getSecret('REFRESH_TOKEN_SECRET');

    startServer();
  } catch (error) {
    logger.error('Failed to initialize application', { error: error.message });
    process.exit(1);
  }
})();

// Cleanup on shutdown
process.on('SIGTERM', () => {
  secretsManager.shutdown();
  process.exit(0);
});
```

