/**
 * Production-Grade Secrets Manager
 * 
 * Supports: AWS Secrets Manager, HashiCorp Vault, Azure Key Vault, GCP Secret Manager
 * Usage: await secretsManager.initialize()
 */

const logger = require('./logger'); // Assumes logger is available

class SecretsManager {
  constructor() {
    this.secrets = {};
    this.loadMethod = null;
    this.rotationInterval = null;
    this.lastRotation = new Date();
  }

  /**
   * Initialize secrets from configured provider
   */
  async initialize() {
    logger.info('Initializing secrets manager');

    if (process.env.NODE_ENV === 'production') {
      await this.initializeProductionSecrets();
    } else {
      await this.initializeDevelopmentSecrets();
    }

    this.validateRequiredSecrets();
  }

  /**
   * Load secrets from production provider
   */
  async initializeProductionSecrets() {
    const provider = process.env.SECRETS_PROVIDER || 'aws';
    logger.info('Loading secrets from provider', { provider });

    try {
      switch (provider) {
        case 'aws':
          await this.loadFromAwsSecretsManager();
          break;
        case 'vault':
          await this.loadFromVault();
          break;
        case 'azure':
          await this.loadFromAzureKeyVault();
          break;
        case 'gcp':
          await this.loadFromGcpSecretManager();
          break;
        default:
          throw new Error(`Unknown secrets provider: ${provider}`);
      }

      // Setup automatic rotation
      if (process.env.SECRET_ROTATION_HOURS) {
        this.setupRotationTimer(provider);
      }

      logger.info('Secrets loaded successfully from provider', { provider });
    } catch (error) {
      logger.error('Failed to load secrets from provider', {
        provider,
        error: error.message,
        stack: error.stack
      });
      throw error;
    }
  }

  /**
   * Load secrets from .env (development only)
   */
  async initializeDevelopmentSecrets() {
    if (process.env.NODE_ENV !== 'development') {
      throw new Error(
        'Development secrets initialization attempted in non-dev environment'
      );
    }

    logger.warn(
      '⚠️ Loading secrets from .env file - DEVELOPMENT ONLY',
      'Never use .env files in production'
    );

    require('dotenv').config();

    this.secrets = {
      ACCESS_TOKEN_SECRET: process.env.ACCESS_TOKEN_SECRET,
      REFRESH_TOKEN_SECRET: process.env.REFRESH_TOKEN_SECRET,
      DATABASE_URL: process.env.DATABASE_URL,
      EXTERNAL_API_KEY: process.env.EXTERNAL_API_KEY
    };
  }

  /**
   * AWS Secrets Manager loader
   */
  async loadFromAwsSecretsManager() {
    let AWS;
    try {
      AWS = require('aws-sdk');
    } catch (error) {
      throw new Error(
        'aws-sdk not installed. Run: npm install aws-sdk'
      );
    }

    const client = new AWS.SecretsManager({
      region: process.env.AWS_REGION || 'us-east-1'
    });

    const secretNames = [
      'app/jwt-secrets',
      'app/database-config',
      'app/external-apis'
    ];

    for (const secretName of secretNames) {
      try {
        const data = await client
          .getSecretValue({ SecretId: secretName })
          .promise();

        const secretValue = 'SecretString' in data
          ? JSON.parse(data.SecretString)
          : Buffer.from(data.SecretBinary, 'base64').toString('utf8');

        // Store by secret name (flatten if needed)
        if (typeof secretValue === 'object') {
          Object.assign(this.secrets, secretValue);
        } else {
          this.secrets[secretName] = secretValue;
        }

        logger.info('Loaded secret from AWS', { secret: secretName });
      } catch (error) {
        logger.error('Failed to load secret from AWS', {
          secret: secretName,
          error: error.message
        });
        throw error;
      }
    }
  }

  /**
   * HashiCorp Vault loader
   */
  async loadFromVault() {
    let Vault;
    try {
      Vault = require('node-vault');
    } catch (error) {
      throw new Error(
        'node-vault not installed. Run: npm install node-vault'
      );
    }

    const vault = new Vault({
      endpoint: process.env.VAULT_ADDR || 'http://localhost:8200',
      token: process.env.VAULT_TOKEN
    });

    const secretPaths = [
      'secret/data/app/jwt',
      'secret/data/app/database',
      'secret/data/app/external'
    ];

    for (const path of secretPaths) {
      try {
        const result = await vault.read(path);
        // Vault v2 returns data in data.data
        const secretData = result.data.data || result.data;
        Object.assign(this.secrets, secretData);

        logger.info('Loaded secret from Vault', { path });
      } catch (error) {
        logger.error('Failed to read secret from Vault', {
          path,
          error: error.message
        });
        throw error;
      }
    }
  }

  /**
   * Azure Key Vault loader
   */
  async loadFromAzureKeyVault() {
    let SecretClient, DefaultAzureCredential;
    try {
      ({ SecretClient } = require("@azure/keyvault-secrets"));
      ({ DefaultAzureCredential } = require("@azure/identity"));
    } catch (error) {
      throw new Error(
        'Azure SDK not installed. Run: npm install @azure/keyvault-secrets @azure/identity'
      );
    }

    const credential = new DefaultAzureCredential();
    const client = new SecretClient(
      process.env.KEY_VAULT_URI,
      credential
    );

    const secretNames = [
      'AccessTokenSecret',
      'RefreshTokenSecret',
      'DatabaseUrl',
      'ExternalApiKey'
    ];

    for (const name of secretNames) {
      try {
        const secret = await client.getSecret(name);
        this.secrets[name] = secret.value;

        logger.info('Loaded secret from Azure Key Vault', { name });
      } catch (error) {
        logger.error('Failed to get secret from Azure Key Vault', {
          name,
          error: error.message
        });
        throw error;
      }
    }
  }

  /**
   * GCP Secret Manager loader
   */
  async loadFromGcpSecretManager() {
    let SecretManagerServiceClient;
    try {
      ({ SecretManagerServiceClient } = require('@google-cloud/secret-manager'));
    } catch (error) {
      throw new Error(
        'GCP Secret Manager client not installed. Run: npm install @google-cloud/secret-manager'
      );
    }

    const client = new SecretManagerServiceClient();
    const project = process.env.GCP_PROJECT;

    const secretNames = [
      'access-token-secret',
      'refresh-token-secret',
      'database-url',
      'external-api-key'
    ];

    for (const name of secretNames) {
      try {
        const [version] = await client.accessSecretVersion({
          name: `projects/${project}/secrets/${name}/versions/latest`
        });

        this.secrets[name] = version.payload.data.toString('utf8');

        logger.info('Loaded secret from GCP Secret Manager', { name });
      } catch (error) {
        logger.error('Failed to get secret from GCP Secret Manager', {
          name,
          error: error.message
        });
        throw error;
      }
    }
  }

  /**
   * Validate that all required secrets are loaded
   */
  validateRequiredSecrets() {
    const required = [
      'ACCESS_TOKEN_SECRET',
      'REFRESH_TOKEN_SECRET'
    ];

    const missing = required.filter(secret => !this.secrets[secret]);

    if (missing.length > 0) {
      throw new Error(`Required secrets not loaded: ${missing.join(', ')}`);
    }

    logger.info('All required secrets validated successfully');
  }

  /**
   * Setup automatic secret rotation
   */
  setupRotationTimer(provider) {
    const rotationHours = parseInt(process.env.SECRET_ROTATION_HOURS) || 24;
    const rotationMs = rotationHours * 60 * 60 * 1000;

    logger.info('Setting up automatic secret rotation', {
      interval: `${rotationHours} hours`
    });

    this.rotationInterval = setInterval(async () => {
      try {
        logger.info('Starting secret rotation', { provider });

        switch (provider) {
          case 'aws':
            await this.loadFromAwsSecretsManager();
            break;
          case 'vault':
            await this.loadFromVault();
            break;
          case 'azure':
            await this.loadFromAzureKeyVault();
            break;
          case 'gcp':
            await this.loadFromGcpSecretManager();
            break;
        }

        this.lastRotation = new Date();
        logger.info('Secrets rotated successfully');
      } catch (error) {
        logger.error('Secret rotation failed', { error: error.message });
        // Continue running even if rotation fails
      }
    }, rotationMs);
  }

  /**
   * Get a secret value
   * Never log the actual secret!
   */
  getSecret(key) {
    if (!this.secrets[key]) {
      logger.warn('Secret requested but not loaded', { key });
      return undefined;
    }

    return this.secrets[key];
  }

  /**
   * Get all secret names (for debugging - never log values!)
   */
  getLoadedSecrets() {
    return Object.keys(this.secrets);
  }

  /**
   * Get manager status
   */
  getStatus() {
    return {
      initialized: Object.keys(this.secrets).length > 0,
      secretCount: Object.keys(this.secrets).length,
      lastRotation: this.lastRotation,
      rotationEnabled: !!this.rotationInterval,
      provider: process.env.SECRETS_PROVIDER || 'env'
    };
  }

  /**
   * Cleanup on shutdown
   */
  shutdown() {
    logger.info('Shutting down secrets manager');

    if (this.rotationInterval) {
      clearInterval(this.rotationInterval);
      this.rotationInterval = null;
    }

    // Clear secrets from memory
    this.secrets = {};
  }
}

// Export singleton instance
const secretsManager = new SecretsManager();

module.exports = secretsManager;

