# Security Review of app.js

## Executive Summary
This Express.js application has **moderate security issues** that require immediate attention. While the current implementation is relatively simple, it lacks essential security measures including authentication, authorization, input validation, rate limiting, and proper HTTP security headers.

**Risk Level: MEDIUM-HIGH** (in production)

---

## Detailed Vulnerability Analysis

### 1. ❌ MISSING AUTHENTICATION (CRITICAL)

**Issue:** The `/users` endpoint exposes sensitive user data without any authentication mechanism.

**OWASP Top 10:** A07:2021 - Identification and Authentication Failures

**Risk:** Unauthorized access to user information (emails, IDs) allows data exfiltration and potential privacy violations.

**Current Code:**
```javascript
app.get('/users', (req, res) => {
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ]);
});
```

**Recommended Fix:**
```javascript
const jwt = require('jsonwebtoken');

// Authentication middleware
function authenticateToken(req, res, next) {
  const authHeader = req.headers['authorization'];
  const token = authHeader && authHeader.split(' ')[1];

  if (!token) {
    return res.status(401).json({ error: 'No token provided' });
  }

  jwt.verify(token, process.env.JWT_SECRET, (err, user) => {
    if (err) {
      return res.status(403).json({ error: 'Invalid or expired token' });
    }
    req.user = user;
    next();
  });
}

// Protected endpoint
app.get('/users', authenticateToken, (req, res) => {
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ]);
});
```

---

### 2. ❌ NO INPUT VALIDATION (HIGH)

**Issue:** No validation or sanitization of incoming requests. Endpoints don't validate query parameters, path parameters, or request bodies.

**OWASP Top 10:** A03:2021 - Injection

**Risk:** Potential for injection attacks, NoSQL injection, and unexpected application behavior.

**Current Problem:**
```javascript
app.get('/health', (req, res) => {
  // No validation - malicious query params are ignored but could be exploited
  // if this code expands
});
```

**Recommended Fix:**
```javascript
const { query, validationResult } = require('express-validator');

// Example with query parameter validation
app.get('/users', 
  authenticateToken,
  query('limit')
    .optional()
    .isInt({ min: 1, max: 100 })
    .withMessage('Limit must be between 1 and 100'),
  query('offset')
    .optional()
    .isInt({ min: 0 })
    .withMessage('Offset must be a non-negative integer'),
  (req, res) => {
    // Check for validation errors
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({ errors: errors.array() });
    }

    const limit = parseInt(req.query.limit) || 10;
    const offset = parseInt(req.query.offset) || 0;

    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    res.json(users.slice(offset, offset + limit));
  }
);
```

---

### 3. ❌ NO AUTHORIZATION CHECKS (HIGH)

**Issue:** No role-based access control (RBAC) or resource-level authorization.

**OWASP Top 10:** A01:2021 - Broken Access Control

**Risk:** Authenticated users can access any resource without proper permission checks.

**Current Code:**
```javascript
// Any authenticated user can see all users
app.get('/users', authenticateToken, (req, res) => {
  res.json([...]);
});
```

**Recommended Fix:**
```javascript
// Authorization middleware
function authorize(...allowedRoles) {
  return (req, res, next) => {
    if (!allowedRoles.includes(req.user.role)) {
      return res.status(403).json({ 
        error: 'Insufficient permissions' 
      });
    }
    next();
  };
}

// Only admins can view all users
app.get('/users', 
  authenticateToken, 
  authorize('admin'),
  (req, res) => {
    res.json([...]);
  }
);

// Users can only view their own data
app.get('/users/:id',
  authenticateToken,
  (req, res) => {
    const userId = parseInt(req.params.id, 10);

    // Check if user is accessing their own data or is admin
    if (req.user.id !== userId && req.user.role !== 'admin') {
      return res.status(403).json({ 
        error: 'Cannot access other users data' 
      });
    }

    const user = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ].find(u => u.id === userId);

    if (!user) {
      return res.status(404).json({ error: 'User not found' });
    }

    res.json(user);
  }
);
```

---

### 4. ❌ MISSING SECURITY HEADERS (HIGH)

**Issue:** No HTTP security headers configured to protect against XSS, clickjacking, MIME-type sniffing, etc.

**OWASP Top 10:** A05:2021 - Security Misconfiguration

**Risk:** Vulnerable to various client-side attacks.

**Recommended Fix:**
```javascript
const helmet = require('helmet');

app.use(helmet());

// Or configure individually:
app.use(helmet.contentSecurityPolicy({
  directives: {
    defaultSrc: ["'self'"],
    scriptSrc: ["'self'"],
    styleSrc: ["'self'", "'unsafe-inline'"],
    imgSrc: ["'self'", 'data:', 'https:'],
  },
}));

app.use(helmet.hsts({
  maxAge: 31536000,
  includeSubDomains: true,
  preload: true,
}));

app.use(helmet.frameguard({ action: 'deny' }));
app.use(helmet.noSniff());
app.use(helmet.xssFilter());
```

---

### 5. ❌ NO RATE LIMITING (MEDIUM-HIGH)

**Issue:** No protection against brute force attacks or DDoS.

**OWASP Top 10:** A04:2021 - Insecure Design

**Risk:** Application vulnerable to brute force login attempts and resource exhaustion attacks.

**Recommended Fix:**
```javascript
const rateLimit = require('express-rate-limit');

// General rate limiter
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: 'Too many requests, please try again later.',
  standardHeaders: true, // Return rate limit info in RateLimit-* headers
  legacyHeaders: false, // Disable X-RateLimit-* headers
});

// Stricter limiter for login attempts
const loginLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 5, // 5 requests per 15 minutes
  message: 'Too many login attempts, please try again later.',
  skipSuccessfulRequests: true, // Don't count successful requests
});

app.use(limiter);
app.post('/login', loginLimiter, (req, res) => {
  // login logic
});
```

---

### 6. ❌ SENSITIVE DATA EXPOSURE (MEDIUM)

**Issue:** User email addresses are exposed in API responses. No encryption for data in transit or at rest is configured.

**OWASP Top 10:** A02:2021 - Cryptographic Failures

**Risk:** Privacy violations, GDPR/CCPA non-compliance, data breach exposure.

**Current Problem:**
```javascript
res.json([
  { id: 1, name: 'Alice', email: 'alice@example.com' },
  { id: 2, name: 'Bob', email: 'bob@example.com' },
]);
```

**Recommended Fix:**
```javascript
// 1. Use HTTPS in production
const https = require('https');
const fs = require('fs');

const options = {
  key: fs.readFileSync('private-key.pem'),
  cert: fs.readFileSync('certificate.pem'),
};

https.createServer(options, app).listen(443);

// 2. Redact sensitive data in responses
function redactUserData(user, requestingUser) {
  const userData = { id: user.id, name: user.name };

  // Only expose email to own user or admins
  if (requestingUser.id === user.id || requestingUser.role === 'admin') {
    userData.email = user.email;
  }

  return userData;
}

app.get('/users/:id',
  authenticateToken,
  (req, res) => {
    const user = users.find(u => u.id === parseInt(req.params.id));
    if (!user) {
      return res.status(404).json({ error: 'User not found' });
    }

    res.json(redactUserData(user, req.user));
  }
);

// 3. Encrypt sensitive data at rest
const crypto = require('crypto');

function encryptEmail(email) {
  const cipher = crypto.createCipher('aes-256-cbc', process.env.ENCRYPTION_KEY);
  let encrypted = cipher.update(email, 'utf8', 'hex');
  encrypted += cipher.final('hex');
  return encrypted;
}

function decryptEmail(encrypted) {
  const decipher = crypto.createDecipher('aes-256-cbc', process.env.ENCRYPTION_KEY);
  let decrypted = decipher.update(encrypted, 'hex', 'utf8');
  decrypted += decipher.final('utf8');
  return decrypted;
}
```

---

### 7. ❌ MISSING CORS CONFIGURATION (MEDIUM)

**Issue:** No CORS headers configured. Could be vulnerable to cross-origin attacks or overly permissive.

**OWASP Top 10:** A05:2021 - Security Misconfiguration

**Recommended Fix:**
```javascript
const cors = require('cors');

// Strict CORS configuration
const corsOptions = {
  origin: process.env.ALLOWED_ORIGINS?.split(',') || ['https://example.com'],
  credentials: true,
  methods: ['GET', 'POST', 'PUT', 'DELETE'],
  allowedHeaders: ['Content-Type', 'Authorization'],
  optionsSuccessStatus: 200,
  maxAge: 3600,
};

app.use(cors(corsOptions));

// Or for specific routes
app.get('/public-data', cors(corsOptions), (req, res) => {
  res.json({ data: 'public' });
});
```

---

### 8. ❌ NO ERROR HANDLING (MEDIUM)

**Issue:** Unhandled exceptions and no global error handler.

**OWASP Top 10:** A05:2021 - Security Misconfiguration

**Risk:** Information disclosure through error messages.

**Recommended Fix:**
```javascript
// Request logging middleware
const morgan = require('morgan');
app.use(morgan('combined'));

// Global error handler
app.use((err, req, res, next) => {
  console.error(err.stack);

  // Don't expose internal error details in production
  const isProduction = process.env.NODE_ENV === 'production';

  res.status(err.status || 500).json({
    error: isProduction 
      ? 'Internal server error' 
      : err.message,
    requestId: req.id, // for debugging
  });
});

// 404 handler
app.use((req, res) => {
  res.status(404).json({ error: 'Not found' });
});
```

---

### 9. ❌ NO DEPENDENCY SECURITY CHECKS (MEDIUM)

**Issue:** No indication of security practices for dependencies.

**Recommended Actions:**
```bash
# Install security tools
npm install --save-dev npm-audit audit-ci

# Check for vulnerabilities
npm audit

# Add to CI/CD pipeline
audit-ci --moderate
```

**Add to package.json:**
```json
{
  "scripts": {
    "audit": "npm audit --audit-level=moderate",
    "security-check": "audit-ci --moderate"
  }
}
```

---

### 10. ❌ MISSING LOGGING AND MONITORING (MEDIUM)

**Issue:** No structured logging for security events or audit trails.

**OWASP Top 10:** A09:2021 - Security Logging and Monitoring Failures

**Recommended Fix:**
```javascript
const winston = require('winston');

const logger = winston.createLogger({
  level: 'info',
  format: winston.format.json(),
  transports: [
    new winston.transports.File({ filename: 'error.log', level: 'error' }),
    new winston.transports.File({ filename: 'combined.log' }),
  ],
});

if (process.env.NODE_ENV !== 'production') {
  logger.add(new winston.transports.Console({
    format: winston.format.simple(),
  }));
}

// Audit middleware
app.use((req, res, next) => {
  // Log all requests
  logger.info({
    method: req.method,
    path: req.path,
    ip: req.ip,
    userId: req.user?.id,
    timestamp: new Date(),
  });
  next();
});

// Log security events
app.use((err, req, res, next) => {
  if (err.status >= 400) {
    logger.warn({
      type: 'SECURITY_EVENT',
      error: err.message,
      path: req.path,
      method: req.method,
      ip: req.ip,
      userId: req.user?.id,
    });
  }
  next(err);
});
```

---

## Security Checklist

- [ ] Add authentication (JWT, OAuth2, etc.)
- [ ] Implement authorization checks
- [ ] Add input validation for all endpoints
- [ ] Configure security headers (Helmet)
- [ ] Implement rate limiting
- [ ] Enable HTTPS/TLS
- [ ] Add CORS configuration
- [ ] Implement global error handling
- [ ] Add structured logging
- [ ] Set up vulnerability scanning
- [ ] Use environment variables for secrets
- [ ] Add request validation middleware
- [ ] Implement CSRF protection (if needed)
- [ ] Add API versioning
- [ ] Document security policies

---

## Secure Configuration Example

Here's a minimal but secure configuration:

```javascript
const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const jwt = require('jsonwebtoken');
const { query, validationResult } = require('express-validator');
const winston = require('winston');
require('dotenv').config();

const app = express();

// ============ MIDDLEWARE ============

// Security headers
app.use(helmet());

// CORS
app.use(cors({
  origin: process.env.ALLOWED_ORIGINS?.split(',') || ['http://localhost:3000'],
  credentials: true,
}));

// Rate limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 100,
});
app.use(limiter);

// Body parsing
app.use(express.json({ limit: '10kb' }));

// Logging
const logger = winston.createLogger({
  level: 'info',
  format: winston.format.json(),
  transports: [
    new winston.transports.File({ filename: 'error.log', level: 'error' }),
    new winston.transports.File({ filename: 'combined.log' }),
  ],
});

// ============ AUTHENTICATION ============

function authenticateToken(req, res, next) {
  const authHeader = req.headers['authorization'];
  const token = authHeader && authHeader.split(' ')[1];

  if (!token) {
    return res.status(401).json({ error: 'No token provided' });
  }

  jwt.verify(token, process.env.JWT_SECRET, (err, user) => {
    if (err) {
      logger.warn({
        type: 'INVALID_TOKEN',
        ip: req.ip,
        error: err.message,
      });
      return res.status(403).json({ error: 'Invalid token' });
    }
    req.user = user;
    next();
  });
}

// ============ ROUTES ============

app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

app.get('/users',
  authenticateToken,
  query('limit')
    .optional()
    .isInt({ min: 1, max: 100 }),
  (req, res) => {
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({ errors: errors.array() });
    }

    logger.info({
      event: 'USERS_FETCH',
      userId: req.user.id,
      ip: req.ip,
    });

    res.json([
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ]);
  }
);

// ============ ERROR HANDLING ============

app.use((err, req, res, next) => {
  logger.error({
    error: err.message,
    stack: err.stack,
    path: req.path,
    ip: req.ip,
  });

  res.status(err.status || 500).json({
    error: process.env.NODE_ENV === 'production'
      ? 'Internal server error'
      : err.message,
  });
});

// ============ START SERVER ============

const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
  logger.info(`Server running on port ${PORT}`);
});

