const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const jwt = require('jsonwebtoken');
const { query, body, validationResult } = require('express-validator');
const winston = require('winston');
const crypto = require('crypto');
require('dotenv').config();

const app = express();

// ============ LOGGING SETUP ============

const logger = winston.createLogger({
  level: process.env.LOG_LEVEL || 'info',
  format: winston.format.combine(
    winston.format.timestamp(),
    winston.format.errors({ stack: true }),
    winston.format.json()
  ),
  defaultMeta: { service: 'user-api' },
  transports: [
    new winston.transports.File({ filename: 'error.log', level: 'error' }),
    new winston.transports.File({ filename: 'combined.log' }),
  ],
});

if (process.env.NODE_ENV !== 'production') {
  logger.add(new winston.transports.Console({
    format: winston.format.simple(),
  }));
}

// ============ SECURITY MIDDLEWARE ============

// Security headers
app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      scriptSrc: ["'self'"],
      styleSrc: ["'self'"],
      imgSrc: ["'self'", 'data:', 'https:'],
    },
  },
  hsts: {
    maxAge: 31536000,
    includeSubDomains: true,
    preload: true,
  },
}));

// CORS configuration
const corsOptions = {
  origin: (process.env.ALLOWED_ORIGINS || 'http://localhost:3000').split(','),
  credentials: true,
  methods: ['GET', 'POST', 'PUT', 'DELETE', 'OPTIONS'],
  allowedHeaders: ['Content-Type', 'Authorization'],
  optionsSuccessStatus: 200,
  maxAge: 3600,
};
app.use(cors(corsOptions));

// Body parsing with size limits
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ limit: '10kb', extended: false }));

// Rate limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true,
  legacyHeaders: false,
  skip: (req) => req.path === '/health', // Don't rate limit health checks
});

const loginLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 5,
  skipSuccessfulRequests: true,
  message: 'Too many login attempts, please try again later.',
});

app.use(limiter);

// Request logging middleware
app.use((req, res, next) => {
  const requestId = crypto.randomBytes(8).toString('hex');
  req.id = requestId;

  logger.info({
    requestId,
    method: req.method,
    path: req.path,
    ip: req.ip,
    userAgent: req.get('user-agent'),
  });

  // Track response
  res.on('finish', () => {
    logger.info({
      requestId,
      status: res.statusCode,
      method: req.method,
      path: req.path,
    });
  });

  next();
});

// ============ AUTHENTICATION ============

function authenticateToken(req, res, next) {
  const authHeader = req.headers['authorization'];
  const token = authHeader && authHeader.split(' ')[1];

  if (!token) {
    logger.warn({
      type: 'AUTH_MISSING',
      requestId: req.id,
      ip: req.ip,
      path: req.path,
    });
    return res.status(401).json({ error: 'No token provided' });
  }

  jwt.verify(token, process.env.JWT_SECRET, (err, user) => {
    if (err) {
      logger.warn({
        type: 'AUTH_INVALID',
        requestId: req.id,
        error: err.message,
        ip: req.ip,
      });
      return res.status(403).json({ error: 'Invalid or expired token' });
    }
    req.user = user;
    next();
  });
}

// ============ AUTHORIZATION ============

function authorize(...allowedRoles) {
  return (req, res, next) => {
    if (!req.user) {
      return res.status(401).json({ error: 'Not authenticated' });
    }

    if (!allowedRoles.includes(req.user.role)) {
      logger.warn({
        type: 'AUTHZ_DENIED',
        requestId: req.id,
        userId: req.user.id,
        requiredRole: allowedRoles,
        userRole: req.user.role,
        path: req.path,
      });
      return res.status(403).json({ error: 'Insufficient permissions' });
    }

    next();
  };
}

// ============ ROUTES ============

// Health check (no auth required)
app.get('/health', (req, res) => {
  res.json({
    status: 'ok',
    timestamp: new Date().toISOString(),
    uptime: process.uptime(),
  });
});

// Get all users (admin only)
app.get('/users',
  authenticateToken,
  authorize('admin'),
  query('limit')
    .optional()
    .isInt({ min: 1, max: 100 })
    .withMessage('Limit must be between 1 and 100'),
  query('offset')
    .optional()
    .isInt({ min: 0 })
    .withMessage('Offset must be a non-negative integer'),
  (req, res) => {
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({ errors: errors.array() });
    }

    const limit = Math.min(parseInt(req.query.limit) || 10, 100);
    const offset = parseInt(req.query.offset) || 0;

    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com', role: 'user' },
      { id: 2, name: 'Bob', email: 'bob@example.com', role: 'user' },
    ];

    logger.info({
      type: 'USERS_FETCHED',
      requestId: req.id,
      userId: req.user.id,
      limit,
      offset,
      count: users.length,
    });

    res.json({
      data: users.slice(offset, offset + limit),
      total: users.length,
      limit,
      offset,
    });
  }
);

// Get user by ID (own data or admin)
app.get('/users/:id',
  authenticateToken,
  query('id')
    .matches(/^\d+$/)
    .withMessage('Invalid user ID format'),
  (req, res) => {
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({ errors: errors.array() });
    }

    const userId = parseInt(req.params.id, 10);

    // Authorization: users can only view their own data unless admin
    if (req.user.id !== userId && req.user.role !== 'admin') {
      logger.warn({
        type: 'AUTHZ_DENIED_RESOURCE',
        requestId: req.id,
        userId: req.user.id,
        targetUserId: userId,
      });
      return res.status(403).json({ error: 'Cannot access other users\' data' });
    }

    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com', role: 'user' },
      { id: 2, name: 'Bob', email: 'bob@example.com', role: 'user' },
    ];

    const user = users.find(u => u.id === userId);

    if (!user) {
      return res.status(404).json({ error: 'User not found' });
    }

    logger.info({
      type: 'USER_FETCHED',
      requestId: req.id,
      userId: req.user.id,
      targetUserId: userId,
    });

    res.json(user);
  }
);

// Login endpoint (generates JWT token)
app.post('/login',
  loginLimiter,
  body('email')
    .isEmail()
    .normalizeEmail()
    .withMessage('Invalid email address'),
  body('password')
    .isLength({ min: 8 })
    .withMessage('Password must be at least 8 characters'),
  (req, res) => {
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      logger.warn({
        type: 'LOGIN_VALIDATION_FAILED',
        requestId: req.id,
        email: req.body.email,
        errors: errors.array(),
      });
      return res.status(400).json({ errors: errors.array() });
    }

    // TODO: Validate credentials against database
    // This is a mock implementation
    if (req.body.email !== 'admin@example.com' || req.body.password !== 'SecurePassword123!') {
      logger.warn({
        type: 'LOGIN_FAILED',
        requestId: req.id,
        email: req.body.email,
      });
      return res.status(401).json({ error: 'Invalid credentials' });
    }

    const token = jwt.sign(
      {
        id: 1,
        email: req.body.email,
        role: 'admin',
      },
      process.env.JWT_SECRET,
      { expiresIn: '1h' }
    );

    logger.info({
      type: 'LOGIN_SUCCESS',
      requestId: req.id,
      email: req.body.email,
    });

    res.json({ token, expiresIn: 3600 });
  }
);

// ============ VALIDATION & ERROR HANDLING ============

// 404 handler
app.use((req, res) => {
  res.status(404).json({
    error: 'Not found',
    path: req.path,
    method: req.method,
  });
});

// Global error handler
app.use((err, req, res, next) => {
  const status = err.status || err.statusCode || 500;
  const isProduction = process.env.NODE_ENV === 'production';

  logger.error({
    type: 'ERROR',
    requestId: req.id,
    status,
    error: err.message,
    stack: err.stack,
    path: req.path,
    method: req.method,
    ip: req.ip,
  });

  res.status(status).json({
    error: isProduction ? 'Internal server error' : err.message,
    requestId: req.id,
    ...(process.env.NODE_ENV === 'development' && { stack: err.stack }),
  });
});

// ============ SERVER STARTUP ============

const PORT = process.env.PORT || 3000;

// Check for required environment variables
const requiredEnvVars = ['JWT_SECRET'];
const missingEnvVars = requiredEnvVars.filter(envVar => !process.env[envVar]);

if (missingEnvVars.length > 0) {
  logger.error(`Missing required environment variables: ${missingEnvVars.join(', ')}`);
  process.exit(1);
}

app.listen(PORT, () => {
  logger.info(`Server running on port ${PORT} in ${process.env.NODE_ENV || 'development'} mode`);
});

// Graceful shutdown
process.on('SIGTERM', () => {
  logger.info('SIGTERM received, shutting down gracefully');
  process.exit(0);
});

process.on('SIGINT', () => {
  logger.info('SIGINT received, shutting down gracefully');
  process.exit(0);
});

module.exports = app;

# Security Testing Guide

## Quick Reference

### Testing Authentication
```bash
# Without token (should fail)
curl -X GET http://localhost:3000/users

# With valid token
TOKEN=$(curl -X POST http://localhost:3000/login \
  -H "Content-Type: application/json" \
  -d '{"email":"admin@example.com","password":"SecurePassword123!"}' \
  | jq -r '.token')

curl -X GET http://localhost:3000/users \
  -H "Authorization: Bearer $TOKEN"

# With invalid token (should fail)
curl -X GET http://localhost:3000/users \
  -H "Authorization: Bearer invalid.token.here"
```

### Testing Authorization
```bash
# Try to access another user's data with different user account
curl -X GET http://localhost:3000/users/2 \
  -H "Authorization: Bearer $TOKEN_USER1"
# Should return 403 Forbidden

# Admin can access all users
curl -X GET http://localhost:3000/users/1 \
  -H "Authorization: Bearer $TOKEN_ADMIN"
# Should return 200 OK
```

### Testing Input Validation
```bash
# Invalid email format
curl -X POST http://localhost:3000/login \
  -H "Content-Type: application/json" \
  -d '{"email":"not-an-email","password":"SecurePassword123!"}'
# Should return 400 Bad Request

# Password too short
curl -X POST http://localhost:3000/login \
  -H "Content-Type: application/json" \
  -d '{"email":"admin@example.com","password":"short"}'
# Should return 400 Bad Request

# Invalid limit parameter
curl -X GET http://localhost:3000/users?limit=999 \
  -H "Authorization: Bearer $TOKEN"
# Should return 400 Bad Request
```

### Testing Rate Limiting
```bash
# Make rapid requests
for i in {1..101}; do
  curl -X GET http://localhost:3000/health
done
# After 100 requests, should receive 429 Too Many Requests
```

### Testing CORS
```bash
# Check CORS headers
curl -X OPTIONS http://localhost:3000/users \
  -H "Origin: http://localhost:3000" \
  -H "Access-Control-Request-Method: GET" \
  -v

# From unauthorized origin (should fail)
curl -X GET http://localhost:3000/users \
  -H "Origin: http://malicious.com" \
  -H "Authorization: Bearer $TOKEN"
```

### Testing Security Headers
```bash
curl -X GET http://localhost:3000/health -v
# Look for headers:
# - Strict-Transport-Security
# - X-Content-Type-Options
# - X-Frame-Options
# - Content-Security-Policy
```

## Automated Testing

### Unit Tests
Create `app.test.js`:
```javascript
const request = require('supertest');
const app = require('./app-secure');

describe('API Security Tests', () => {
  describe('Authentication', () => {
    test('GET /users without token should return 401', async () => {
      const res = await request(app).get('/users');
      expect(res.statusCode).toBe(401);
      expect(res.body.error).toBe('No token provided');
    });

    test('GET /users with invalid token should return 403', async () => {
      const res = await request(app)
        .get('/users')
        .set('Authorization', 'Bearer invalid.token');
      expect(res.statusCode).toBe(403);
    });
  });

  describe('Input Validation', () => {
    test('POST /login with invalid email should return 400', async () => {
      const res = await request(app)
        .post('/login')
        .send({
          email: 'not-an-email',
          password: 'SecurePassword123!',
        });
      expect(res.statusCode).toBe(400);
    });

    test('GET /users?limit=999 should return 400', async () => {
      const loginRes = await request(app)
        .post('/login')
        .send({
          email: 'admin@example.com',
          password: 'SecurePassword123!',
        });

      const res = await request(app)
        .get('/users')
        .query({ limit: 999 })
        .set('Authorization', `Bearer ${loginRes.body.token}`);
      expect(res.statusCode).toBe(400);
    });
  });

  describe('Authorization', () => {
    test('Non-admin should not access /users endpoint', async () => {
      // Create user token (non-admin)
      const token = jwt.sign(
        { id: 2, email: 'user@example.com', role: 'user' },
        process.env.JWT_SECRET
      );

      const res = await request(app)
        .get('/users')
        .set('Authorization', `Bearer ${token}`);
      expect(res.statusCode).toBe(403);
    });
  });

  describe('Security Headers', () => {
    test('Response should include security headers', async () => {
      const res = await request(app).get('/health');
      expect(res.headers['strict-transport-security']).toBeDefined();
      expect(res.headers['x-content-type-options']).toBe('nosniff');
      expect(res.headers['x-frame-options']).toBe('DENY');
    });
  });
});
```

