/**
 * Production-Grade Secrets Manager
 * Supports AWS Secrets Manager, Azure Key Vault, Vault, and local .env for development
 */

const logger = require('./logger'); // Assuming you have winston logger

/**
 * Secrets Manager Class
 * Handles loading, validating, and accessing secrets from various sources
 */
class SecretsManager {
  constructor(options = {}) {
    this.secrets = null;
    this.source = null;
    this.lastRefresh = 0;
    this.refreshInterval = options.refreshInterval || 3600000; // 1 hour default
    this.provider = process.env.SECRETS_PROVIDER || 'dotenv'; // dotenv, aws, azure, vault, gcp
    this.options = options;
  }

  /**
   * Load secrets from configured provider
   */
  async load() {
    logger.info({
      type: 'SECRETS_LOADING',
      provider: this.provider,
      environment: process.env.NODE_ENV,
    });

    try {
      switch (this.provider) {
        case 'aws':
          await this.loadFromAWS();
          break;
        case 'azure':
          await this.loadFromAzure();
          break;
        case 'vault':
          await this.loadFromVault();
          break;
        case 'gcp':
          await this.loadFromGCP();
          break;
        case 'dotenv':
        default:
          this.loadFromDotenv();
          break;
      }

      // Validate loaded secrets
      this.validate();

      logger.info({
        type: 'SECRETS_LOADED_SUCCESS',
        source: this.source,
        secretCount: Object.keys(this.secrets).length,
        keys: Object.keys(this.secrets).sort(),
      });

      this.lastRefresh = Date.now();
    } catch (error) {
      logger.error({
        type: 'SECRETS_LOAD_ERROR',
        provider: this.provider,
        error: error.message,
      });
      throw new Error(`Failed to load secrets from ${this.provider}: ${error.message}`);
    }
  }

  /**
   * Load from AWS Secrets Manager
   */
  async loadFromAWS() {
    if (process.env.NODE_ENV === 'production' && !process.env.AWS_REGION) {
      throw new Error('AWS_REGION not configured');
    }

    const AWS = require('aws-sdk');
    const client = new AWS.SecretsManager({
      region: process.env.AWS_REGION || 'us-east-1',
    });

    const secretName = process.env.SECRETS_NAME || 'app/production/secrets';

    try {
      const response = await client.getSecretValue({ SecretId: secretName }).promise();

      if (response.SecretString) {
        this.secrets = JSON.parse(response.SecretString);
        this.source = 'AWS Secrets Manager';
      } else if (response.SecretBinary) {
        this.secrets = JSON.parse(
          Buffer.from(response.SecretBinary, 'base64').toString('ascii')
        );
        this.source = 'AWS Secrets Manager (binary)';
      }
    } catch (error) {
      throw new Error(`AWS Secrets Manager error: ${error.message}`);
    }
  }

  /**
   * Load from Azure Key Vault
   */
  async loadFromAzure() {
    if (!process.env.VAULT_NAME) {
      throw new Error('VAULT_NAME not configured for Azure Key Vault');
    }

    const { SecretClient } = require('@azure/keyvault-secrets');
    const { DefaultAzureCredential } = require('@azure/identity');

    const vaultUrl = `https://${process.env.VAULT_NAME}.vault.azure.net/`;
    const credential = new DefaultAzureCredential();
    const client = new SecretClient(vaultUrl, credential);

    const secretNames = [
      'JWT-SECRET',
      'ENCRYPTION-KEY',
      'DATABASE-URL',
    ];

    this.secrets = {};

    try {
      for (const name of secretNames) {
        try {
          const secret = await client.getSecret(name);
          this.secrets[name.replace(/-/g, '_')] = secret.value;
        } catch (error) {
          if (error.code !== 'SecretNotFound') {
            throw error;
          }
          // Secret not found, skip
        }
      }

      this.source = 'Azure Key Vault';
    } catch (error) {
      throw new Error(`Azure Key Vault error: ${error.message}`);
    }
  }

  /**
   * Load from HashiCorp Vault
   */
  async loadFromVault() {
    if (!process.env.VAULT_ADDR) {
      throw new Error('VAULT_ADDR not configured for HashiCorp Vault');
    }

    const vault = require('node-vault')({
      endpoint: process.env.VAULT_ADDR,
      token: process.env.VAULT_TOKEN,
    });

    try {
      const path = process.env.VAULT_PATH || 'secret/data/production/app';
      const response = await vault.read(path);

      this.secrets = response.data.data;
      this.source = 'HashiCorp Vault';
    } catch (error) {
      throw new Error(`Vault error: ${error.message}`);
    }
  }

  /**
   * Load from Google Secret Manager
   */
  async loadFromGCP() {
    if (!process.env.GCP_PROJECT_ID) {
      throw new Error('GCP_PROJECT_ID not configured');
    }

    const { SecretManagerServiceClient } = require('@google-cloud/secret-manager');
    const client = new SecretManagerServiceClient();

    const secretNames = [
      'jwt-secret',
      'encryption-key',
      'database-url',
    ];

    this.secrets = {};

    try {
      for (const name of secretNames) {
        try {
          const secretPath = client.secretVersionPath(
            process.env.GCP_PROJECT_ID,
            name,
            'latest'
          );
          const [version] = await client.accessSecretVersion({ name: secretPath });
          const payload = version.payload.data.toString('utf8');
          this.secrets[name.replace(/-/g, '_').toUpperCase()] = payload;
        } catch (error) {
          if (error.code !== 5) { // NOT_FOUND
            throw error;
          }
          // Secret not found, skip
        }
      }

      this.source = 'Google Secret Manager';
    } catch (error) {
      throw new Error(`Google Secret Manager error: ${error.message}`);
    }
  }

  /**
   * Load from .env file (Development Only)
   */
  loadFromDotenv() {
    // Only allow in development
    if (process.env.NODE_ENV === 'production') {
      throw new Error(
        'dotenv should never be used in production. Use a proper secrets manager.'
      );
    }

    require('dotenv').config();

    this.secrets = {
      JWT_SECRET: process.env.JWT_SECRET,
      ENCRYPTION_KEY: process.env.ENCRYPTION_KEY,
      DATABASE_URL: process.env.DATABASE_URL,
      LOG_LEVEL: process.env.LOG_LEVEL,
    };

    this.source = '.env file (development only)';

    logger.warn('⚠️  Using .env file - development mode only');
    logger.warn('⚠️  In production, use AWS Secrets Manager or similar');
  }

  /**
   * Validate loaded secrets
   */
  validate() {
    if (!this.secrets) {
      throw new Error('Secrets not loaded');
    }

    const errors = [];

    // Validate JWT_SECRET
    if (!this.secrets.JWT_SECRET) {
      errors.push('JWT_SECRET is required');
    } else if (this.secrets.JWT_SECRET.length < 32) {
      errors.push(`JWT_SECRET must be at least 32 characters (current: ${this.secrets.JWT_SECRET.length})`);
    } else if (
      this.secrets.JWT_SECRET.includes('your-') ||
      this.secrets.JWT_SECRET.includes('change') ||
      this.secrets.JWT_SECRET === 'my-secret'
    ) {
      errors.push('JWT_SECRET appears to be a placeholder');
    }

    // Validate ENCRYPTION_KEY if present
    if (
      this.secrets.ENCRYPTION_KEY &&
      this.secrets.ENCRYPTION_KEY.length < 32
    ) {
      errors.push(
        `ENCRYPTION_KEY must be at least 32 characters (current: ${this.secrets.ENCRYPTION_KEY.length})`
      );
    }

    if (errors.length > 0) {
      logger.error('❌ Secret validation failed:');
      errors.forEach((error) => {
        logger.error(`   ❌ ${error}`);
      });

      throw new Error(`Secret validation failed: ${errors.join('; ')}`);
    }

    logger.info('✅ All secrets validated successfully');
  }

  /**
   * Get a specific secret
   */
  get(key) {
    if (!this.secrets) {
      throw new Error('Secrets not loaded - call load() first');
    }

    if (!(key in this.secrets)) {
      throw new Error(
        `Secret '${key}' not found. Available secrets: ${Object.keys(this.secrets).join(', ')}`
      );
    }

    // Log access (without exposing value)
    logger.debug({
      type: 'SECRET_ACCESS',
      key: key,
      source: this.source,
      caller: new Error().stack.split('\n')[2].trim(),
    });

    return this.secrets[key];
  }

  /**
   * Check if secret exists
   */
  has(key) {
    return this.secrets && key in this.secrets;
  }

  /**
   * Get all available secret keys
   */
  keys() {
    return this.secrets ? Object.keys(this.secrets) : [];
  }

  /**
   * Refresh secrets if needed (for auto-rotation)
   */
  async maybeRefresh() {
    if (process.env.NODE_ENV !== 'production') {
      return; // Only refresh in production
    }

    const timeSinceRefresh = Date.now() - this.lastRefresh;
    if (timeSinceRefresh > this.refreshInterval) {
      logger.info({
        type: 'SECRETS_REFRESH',
        timeSinceLastRefresh: timeSinceRefresh,
      });

      await this.load();
    }
  }

  /**
   * Start automatic refresh interval
   */
  startAutoRefresh() {
    if (process.env.NODE_ENV !== 'production') {
      return; // No auto-refresh in development
    }

    logger.info({
      type: 'SECRETS_AUTO_REFRESH_ENABLED',
      interval: this.refreshInterval,
    });

    setInterval(() => this.maybeRefresh(), this.refreshInterval);
  }

  /**
   * Get health status
   */
  getStatus() {
    return {
      loaded: this.secrets !== null,
      source: this.source,
      keyCount: this.secrets ? Object.keys(this.secrets).length : 0,
      lastRefresh: new Date(this.lastRefresh),
      nextRefresh: new Date(this.lastRefresh + this.refreshInterval),
    };
  }
}

/**
 * Middleware to attach secrets manager to requests
 */
function secretsMiddleware(secretsManager) {
  return (req, res, next) => {
    req.secrets = secretsManager;
    next();
  };
}

/**
 * Helper to generate secure random secrets
 */
function generateSecret(length = 32) {
  const crypto = require('crypto');
  return crypto.randomBytes(length).toString('hex');
}

/**
 * Export for use in Express app
 */
module.exports = {
  SecretsManager,
  secretsMiddleware,
  generateSecret,
};

/**
 * Production-Grade Express App with Secure Secrets Management
 * Uses SecretsManager for AWS, Azure, Vault, or local development
 */

const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const jwt = require('jsonwebtoken');
const { query, body, validationResult } = require('express-validator');
const winston = require('winston');
const crypto = require('crypto');

// Import secure secrets manager
const { SecretsManager, secretsMiddleware } = require('./secrets-manager');

// Only require dotenv for development
if (process.env.NODE_ENV !== 'production') {
  require('dotenv').config();
}

const app = express();

// ============ LOGGING SETUP ============

const logger = winston.createLogger({
  level: process.env.LOG_LEVEL || 'info',
  format: winston.format.combine(
    winston.format.timestamp(),
    winston.format.errors({ stack: true }),
    winston.format.json()
  ),
  defaultMeta: { service: 'user-api' },
  transports: [
    new winston.transports.File({ filename: 'error.log', level: 'error' }),
    new winston.transports.File({ filename: 'combined.log' }),
  ],
});

if (process.env.NODE_ENV !== 'production') {
  logger.add(new winston.transports.Console({
    format: winston.format.simple(),
  }));
}

// Export logger for other modules
module.exports.logger = logger;

// ============ SECRETS MANAGER INITIALIZATION ============

const secretsManager = new SecretsManager({
  refreshInterval: 3600000, // 1 hour
});

// ============ SECURITY MIDDLEWARE ============

// Security headers
app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      scriptSrc: ["'self'"],
      styleSrc: ["'self'"],
      imgSrc: ["'self'", 'data:', 'https:'],
    },
  },
  hsts: {
    maxAge: 31536000,
    includeSubDomains: true,
    preload: true,
  },
}));

// CORS configuration
const corsOptions = {
  origin: (process.env.ALLOWED_ORIGINS || 'http://localhost:3000').split(','),
  credentials: true,
  methods: ['GET', 'POST', 'PUT', 'DELETE', 'OPTIONS'],
  allowedHeaders: ['Content-Type', 'Authorization'],
  optionsSuccessStatus: 200,
  maxAge: 3600,
};
app.use(cors(corsOptions));

// Body parsing with size limits
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ limit: '10kb', extended: false }));

// Rate limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 100,
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true,
  legacyHeaders: false,
  skip: (req) => req.path === '/health',
});

const loginLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 5,
  skipSuccessfulRequests: true,
  message: 'Too many login attempts, please try again later.',
});

app.use(limiter);

// Attach secrets manager to all requests
app.use(secretsMiddleware(secretsManager));

// Request logging middleware
app.use((req, res, next) => {
  const requestId = crypto.randomBytes(8).toString('hex');
  req.id = requestId;

  logger.info({
    requestId,
    method: req.method,
    path: req.path,
    ip: req.ip,
  });

  res.on('finish', () => {
    logger.info({
      requestId,
      status: res.statusCode,
      method: req.method,
      path: req.path,
    });
  });

  next();
});

// ============ AUTHENTICATION ============

function authenticateToken(req, res, next) {
  const authHeader = req.headers['authorization'];
  const token = authHeader && authHeader.split(' ')[1];

  if (!token) {
    logger.warn({
      type: 'AUTH_MISSING',
      requestId: req.id,
      ip: req.ip,
      path: req.path,
    });
    return res.status(401).json({ error: 'No token provided' });
  }

  // ✅ SECURE: Use secret from secrets manager, never from process.env
  try {
    const jwtSecret = req.secrets.get('JWT_SECRET');
    jwt.verify(token, jwtSecret, (err, user) => {
      if (err) {
        logger.warn({
          type: 'AUTH_INVALID',
          requestId: req.id,
          error: err.message,
          ip: req.ip,
        });
        return res.status(403).json({ error: 'Invalid or expired token' });
      }
      req.user = user;
      next();
    });
  } catch (error) {
    logger.error({
      type: 'AUTH_ERROR',
      requestId: req.id,
      error: error.message,
    });
    return res.status(500).json({ error: 'Authentication error' });
  }
}

// ============ AUTHORIZATION ============

function authorize(...allowedRoles) {
  return (req, res, next) => {
    if (!req.user) {
      return res.status(401).json({ error: 'Not authenticated' });
    }

    if (!allowedRoles.includes(req.user.role)) {
      logger.warn({
        type: 'AUTHZ_DENIED',
        requestId: req.id,
        userId: req.user.id,
        requiredRole: allowedRoles,
        userRole: req.user.role,
        path: req.path,
      });
      return res.status(403).json({ error: 'Insufficient permissions' });
    }

    next();
  };
}

// ============ ROUTES ============

// Health check
app.get('/health', (req, res) => {
  res.json({
    status: 'ok',
    timestamp: new Date().toISOString(),
    uptime: process.uptime(),
    secretsStatus: req.secrets.getStatus(),
  });
});

// Get all users (admin only)
app.get('/users',
  authenticateToken,
  authorize('admin'),
  query('limit')
    .optional()
    .isInt({ min: 1, max: 100 })
    .withMessage('Limit must be between 1 and 100'),
  query('offset')
    .optional()
    .isInt({ min: 0 })
    .withMessage('Offset must be a non-negative integer'),
  (req, res) => {
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({ errors: errors.array() });
    }

    const limit = Math.min(parseInt(req.query.limit) || 10, 100);
    const offset = parseInt(req.query.offset) || 0;

    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com', role: 'user' },
      { id: 2, name: 'Bob', email: 'bob@example.com', role: 'user' },
    ];

    logger.info({
      type: 'USERS_FETCHED',
      requestId: req.id,
      userId: req.user.id,
      limit,
      offset,
      count: users.length,
    });

    res.json({
      data: users.slice(offset, offset + limit),
      total: users.length,
      limit,
      offset,
    });
  }
);

// Get user by ID
app.get('/users/:id',
  authenticateToken,
  (req, res) => {
    const userId = parseInt(req.params.id, 10);

    if (req.user.id !== userId && req.user.role !== 'admin') {
      logger.warn({
        type: 'AUTHZ_DENIED_RESOURCE',
        requestId: req.id,
        userId: req.user.id,
        targetUserId: userId,
      });
      return res.status(403).json({ error: 'Cannot access other users\' data' });
    }

    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com', role: 'user' },
      { id: 2, name: 'Bob', email: 'bob@example.com', role: 'user' },
    ];

    const user = users.find(u => u.id === userId);

    if (!user) {
      return res.status(404).json({ error: 'User not found' });
    }

    logger.info({
      type: 'USER_FETCHED',
      requestId: req.id,
      userId: req.user.id,
      targetUserId: userId,
    });

    res.json(user);
  }
);

// Login endpoint
app.post('/login',
  loginLimiter,
  body('email')
    .isEmail()
    .normalizeEmail()
    .withMessage('Invalid email address'),
  body('password')
    .isLength({ min: 8 })
    .withMessage('Password must be at least 8 characters'),
  (req, res) => {
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      logger.warn({
        type: 'LOGIN_VALIDATION_FAILED',
        requestId: req.id,
        email: req.body.email,
        errors: errors.array(),
      });
      return res.status(400).json({ errors: errors.array() });
    }

    // Validate credentials
    if (req.body.email !== 'admin@example.com' || req.body.password !== 'SecurePassword123!') {
      logger.warn({
        type: 'LOGIN_FAILED',
        requestId: req.id,
        email: req.body.email,
      });
      return res.status(401).json({ error: 'Invalid credentials' });
    }

    try {
      // ✅ SECURE: Get JWT_SECRET from secrets manager
      const jwtSecret = req.secrets.get('JWT_SECRET');

      const token = jwt.sign(
        {
          id: 1,
          email: req.body.email,
          role: 'admin',
        },
        jwtSecret,
        { expiresIn: '1h' }
      );

      logger.info({
        type: 'LOGIN_SUCCESS',
        requestId: req.id,
        email: req.body.email,
        // ✅ SECURE: Never log the token
      });

      res.json({ token, expiresIn: 3600 });
    } catch (error) {
      logger.error({
        type: 'LOGIN_ERROR',
        requestId: req.id,
        error: error.message,
      });
      return res.status(500).json({ error: 'Login error' });
    }
  }
);

// ============ ERROR HANDLING ============

app.use((req, res) => {
  res.status(404).json({
    error: 'Not found',
    path: req.path,
    method: req.method,
  });
});

app.use((err, req, res, next) => {
  const status = err.status || err.statusCode || 500;
  const isProduction = process.env.NODE_ENV === 'production';

  // ✅ SECURE: Never log secrets or sensitive data
  logger.error({
    type: 'ERROR',
    requestId: req.id,
    status,
    error: err.message,
    path: req.path,
    method: req.method,
    ip: req.ip,
    // Stack trace only in development, never logs secrets
    ...(process.env.NODE_ENV === 'development' && { stack: err.stack }),
  });

  res.status(status).json({
    error: isProduction ? 'Internal server error' : err.message,
    requestId: req.id,
  });
});

// ============ SERVER INITIALIZATION ============

/**
 * Initialize and start the server
 */
async function startServer() {
  try {
    // Load secrets first
    logger.info('Loading secrets...');
    await secretsManager.load();
    logger.info('✅ Secrets loaded successfully');

    // Start auto-refresh in production
    if (process.env.NODE_ENV === 'production') {
      secretsManager.startAutoRefresh();
      logger.info('✅ Secret auto-refresh enabled');
    }

    // Start server
    const PORT = process.env.PORT || 3000;
    app.listen(PORT, () => {
      logger.info({
        type: 'SERVER_STARTED',
        port: PORT,
        environment: process.env.NODE_ENV || 'development',
        secretsSource: secretsManager.source,
      });
      console.log(`✅ Server running on port ${PORT}`);
    });
  } catch (error) {
    logger.error({
      type: 'SERVER_STARTUP_ERROR',
      error: error.message,
    });
    console.error('❌ Failed to start server:', error.message);
    process.exit(1);
  }
}

// Graceful shutdown
process.on('SIGTERM', () => {
  logger.info('SIGTERM received, shutting down gracefully');
  process.exit(0);
});

process.on('SIGINT', () => {
  logger.info('SIGINT received, shutting down gracefully');
  process.exit(0);
});

// Start server if not being imported
if (require.main === module) {
  startServer();
}

module.exports = app;

