// Secure version of app.js with security best practices implemented
// This version addresses all OWASP Top 10 concerns

require('dotenv').config();
const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const jwt = require('jsonwebtoken');
const { query, validationResult } = require('express-validator');
const morgan = require('morgan');
const winston = require('winston');

const app = express();

// ============================================================================
// 1. LOGGING & MONITORING
// ============================================================================

const logger = winston.createLogger({
  level: process.env.LOG_LEVEL || 'info',
  format: winston.format.json(),
  defaultMeta: { service: 'api-service' },
  transports: [
    new winston.transports.File({ 
      filename: 'logs/error.log', 
      level: 'error',
      maxsize: 5242880, // 5MB
      maxFiles: 5,
    }),
    new winston.transports.File({ 
      filename: 'logs/combined.log',
      maxsize: 5242880,
      maxFiles: 5,
    }),
  ],
});

if (process.env.NODE_ENV !== 'production') {
  logger.add(new winston.transports.Console({
    format: winston.format.simple(),
  }));
}

// HTTP request logging
app.use(morgan('combined', {
  stream: {
    write: (message) => logger.info(message.trim()),
  },
}));

// ============================================================================
// 2. ENVIRONMENT VALIDATION
// ============================================================================

const validateEnvironment = () => {
  const required = ['JWT_SECRET', 'NODE_ENV'];
  const missing = required.filter(env => !process.env[env]);

  if (missing.length > 0) {
    logger.error(`Missing required environment variables: ${missing.join(', ')}`);
    process.exit(1);
  }
};

validateEnvironment();

// ============================================================================
// 3. SECURITY HEADERS
// ============================================================================

// Helmet helps secure Express apps by setting various HTTP headers
app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      scriptSrc: ["'self'"],
      styleSrc: ["'self'", "'unsafe-inline'"],
      imgSrc: ["'self'", 'data:', 'https:'],
    },
  },
  hsts: {
    maxAge: 31536000, // 1 year
    includeSubDomains: true,
    preload: true,
  },
  frameguard: { action: 'deny' },
  noSniff: true,
  xssFilter: true,
  referrerPolicy: { policy: 'strict-origin-when-cross-origin' },
}));

// ============================================================================
// 4. CORS CONFIGURATION
// ============================================================================

const allowedOrigins = (process.env.ALLOWED_ORIGINS || 'http://localhost:3000').split(',');

const corsOptions = {
  origin: (origin, callback) => {
    // Allow requests with no origin (like mobile apps or curl requests)
    if (!origin) return callback(null, true);

    if (allowedOrigins.includes(origin)) {
      callback(null, true);
    } else {
      logger.warn(`CORS rejected request from origin: ${origin}`);
      callback(new Error('Not allowed by CORS'));
    }
  },
  credentials: true,
  methods: ['GET', 'POST', 'PUT', 'DELETE'],
  allowedHeaders: ['Content-Type', 'Authorization'],
  maxAge: 3600,
  optionsSuccessStatus: 200,
};

app.use(cors(corsOptions));

// ============================================================================
// 5. BODY PARSING & SANITIZATION
// ============================================================================

app.use(express.json({ limit: '10kb' })); // Limit payload size
app.use(express.urlencoded({ limit: '10kb', extended: false }));

// ============================================================================
// 6. RATE LIMITING
// ============================================================================

// General rate limiter
const generalLimiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true, // Return rate limit info in RateLimit-* headers
  legacyHeaders: false, // Disable X-RateLimit-* headers
  skip: (req) => {
    // Skip rate limiting for health checks in monitoring context
    return req.path === '/health' && process.env.SKIP_HEALTH_RATE_LIMIT === 'true';
  },
});

// Stricter limiter for authentication endpoints
const authLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 5, // 5 attempts per 15 minutes
  skipSuccessfulRequests: true, // Don't count successful requests
  message: 'Too many login attempts, please try again after 15 minutes.',
});

app.use(generalLimiter);

// ============================================================================
// 7. AUTHENTICATION MIDDLEWARE
// ============================================================================

const authenticateToken = (req, res, next) => {
  try {
    const authHeader = req.headers['authorization'];
    const token = authHeader && authHeader.split(' ')[1]; // Bearer TOKEN

    if (!token) {
      logger.warn(`Unauthorized access attempt to ${req.path}`, {
        ip: req.ip,
        userAgent: req.get('user-agent'),
      });
      return res.status(401).json({ 
        error: 'Access token required',
        code: 'MISSING_TOKEN',
      });
    }

    jwt.verify(token, process.env.JWT_SECRET, (err, user) => {
      if (err) {
        logger.warn(`Invalid token used`, {
          ip: req.ip,
          error: err.message,
        });
        return res.status(403).json({ 
          error: 'Invalid or expired token',
          code: 'INVALID_TOKEN',
        });
      }

      req.user = user;
      next();
    });
  } catch (error) {
    logger.error('Authentication error:', error);
    res.status(500).json({ 
      error: 'Authentication failed',
      code: 'AUTH_ERROR',
    });
  }
};

// ============================================================================
// 8. AUTHORIZATION MIDDLEWARE
// ============================================================================

const authorize = (...allowedRoles) => {
  return (req, res, next) => {
    if (!req.user) {
      return res.status(401).json({ 
        error: 'User not authenticated',
        code: 'NOT_AUTHENTICATED',
      });
    }

    if (!allowedRoles.includes(req.user.role)) {
      logger.warn(`Unauthorized access attempt`, {
        userId: req.user.id,
        requiredRole: allowedRoles,
        userRole: req.user.role,
        path: req.path,
      });
      return res.status(403).json({ 
        error: 'Insufficient permissions',
        code: 'INSUFFICIENT_PERMISSIONS',
      });
    }

    next();
  };
};

// ============================================================================
// 9. INPUT VALIDATION
// ============================================================================

const validatePageParams = [
  query('page').optional().isInt({ min: 1 }).toInt(),
  query('limit').optional().isInt({ min: 1, max: 100 }).toInt(),
  query('search').optional().trim().isLength({ max: 100 }).escape(),
];

const handleValidationErrors = (req, res, next) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    logger.warn('Validation error', {
      path: req.path,
      errors: errors.array(),
    });
    return res.status(400).json({ 
      error: 'Validation failed',
      code: 'VALIDATION_ERROR',
      details: errors.array(),
    });
  }
  next();
};

// ============================================================================
// 10. DATA FILTERING (Prevent Sensitive Data Exposure)
// ============================================================================

const filterSensitiveData = (users, userRole) => {
  return users.map(user => ({
    id: user.id,
    name: user.name,
    // Only include email for admins and the user themselves
    ...(userRole === 'admin' && { email: user.email }),
  }));
};

// ============================================================================
// 11. ROUTES
// ============================================================================

// Public health check endpoint (minimal information)
app.get('/health', (req, res) => {
  res.json({ 
    status: 'ok',
    timestamp: new Date().toISOString(),
  });
});

// Protected users endpoint
app.get('/users',
  authenticateToken,
  authorize('admin', 'manager'),
  validatePageParams,
  handleValidationErrors,
  (req, res) => {
    try {
      // Get pagination params with defaults
      const page = req.query.page || 1;
      const limit = req.query.limit || 10;
      const search = req.query.search || '';

      // Log access
      logger.info('Users endpoint accessed', {
        userId: req.user.id,
        userRole: req.user.role,
        page,
        limit,
        search,
      });

      // Mock data (in production, query from database with parameterized queries)
      const allUsers = [
        { id: 1, name: 'Alice', email: 'alice@example.com' },
        { id: 2, name: 'Bob', email: 'bob@example.com' },
      ];

      // Filter if search provided (in production, do this in database)
      let users = allUsers;
      if (search) {
        users = allUsers.filter(u => 
          u.name.toLowerCase().includes(search.toLowerCase()) ||
          u.email.toLowerCase().includes(search.toLowerCase())
        );
      }

      // Apply pagination
      const startIdx = (page - 1) * limit;
      const paginatedUsers = users.slice(startIdx, startIdx + limit);

      // Filter sensitive data based on user role
      const filteredUsers = filterSensitiveData(paginatedUsers, req.user.role);

      res.json({
        data: filteredUsers,
        pagination: {
          page,
          limit,
          total: users.length,
          pages: Math.ceil(users.length / limit),
        },
      });
    } catch (error) {
      logger.error('Error in /users endpoint:', error);
      res.status(500).json({ 
        error: 'Internal server error',
        code: 'INTERNAL_ERROR',
      });
    }
  }
);

// Protected endpoint example: create user
app.post('/users',
  authLimiter, // Stricter rate limiting for write operations
  authenticateToken,
  authorize('admin'),
  (req, res) => {
    try {
      // In production, validate and sanitize input
      const { name, email } = req.body;

      if (!name || !email) {
        return res.status(400).json({
          error: 'Name and email are required',
          code: 'INVALID_INPUT',
        });
      }

      // Additional validation
      if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) {
        return res.status(400).json({
          error: 'Invalid email format',
          code: 'INVALID_EMAIL',
        });
      }

      logger.info('User created', {
        createdBy: req.user.id,
        email,
      });

      res.status(201).json({
        id: Math.floor(Math.random() * 10000),
        name,
        email,
      });
    } catch (error) {
      logger.error('Error creating user:', error);
      res.status(500).json({
        error: 'Internal server error',
        code: 'INTERNAL_ERROR',
      });
    }
  }
);

// ============================================================================
// 12. ERROR HANDLING
// ============================================================================

// CORS error handler
app.use((err, req, res, next) => {
  if (err.message === 'Not allowed by CORS') {
    logger.warn('CORS error', {
      origin: req.get('origin'),
      path: req.path,
    });
    return res.status(403).json({
      error: 'CORS policy violation',
      code: 'CORS_ERROR',
    });
  }
  next(err);
});

// 404 handler
app.use((req, res) => {
  logger.warn('404 Not Found', {
    method: req.method,
    path: req.path,
    ip: req.ip,
  });
  res.status(404).json({ 
    error: 'Endpoint not found',
    code: 'NOT_FOUND',
  });
});

// Global error handler (must be last)
app.use((err, req, res, next) => {
  logger.error('Unhandled error:', {
    message: err.message,
    stack: err.stack,
    path: req.path,
    method: req.method,
  });

  const statusCode = err.statusCode || err.status || 500;

  res.status(statusCode).json({
    error: process.env.NODE_ENV === 'production' 
      ? 'An internal error occurred'
      : err.message,
    code: err.code || 'INTERNAL_ERROR',
    ...(process.env.NODE_ENV !== 'production' && { 
      stack: err.stack,
    }),
  });
});

// ============================================================================
// 13. HTTPS ENFORCEMENT (for production)
// ============================================================================

app.use((req, res, next) => {
  if (process.env.NODE_ENV === 'production' && !req.secure && req.get('x-forwarded-proto') !== 'https') {
    logger.warn('Non-HTTPS request received', {
      method: req.method,
      path: req.path,
      ip: req.ip,
    });
    return res.redirect(301, `https://${req.get('host')}${req.originalUrl}`);
  }
  next();
});

// ============================================================================
// 14. SERVER STARTUP
// ============================================================================

const PORT = process.env.PORT || 3000;
const server = app.listen(PORT, () => {
  logger.info(`Server running on port ${PORT} in ${process.env.NODE_ENV} mode`);
});

// Graceful shutdown
process.on('SIGTERM', () => {
  logger.info('SIGTERM received, shutting down gracefully');
  server.close(() => {
    logger.info('Server closed');
    process.exit(0);
  });
});

