## Code Security Patterns

### ✅ DO: Use Parameterized Queries (Never String Concatenation)

```javascript
// ✅ GOOD: Parameterized query
db.query('SELECT * FROM users WHERE id = $1', [userId]);

// ❌ BAD: String concatenation (SQL Injection vulnerability)
db.query(`SELECT * FROM users WHERE id = ${userId}`);

// ❌ BAD: Template literals without parameterization
db.query(`SELECT * FROM users WHERE email = '${email}'`);
```

### ✅ DO: Use Environment Variables for Secrets

```javascript
// ✅ GOOD
const jwtSecret = process.env.JWT_SECRET;
if (!jwtSecret) throw new Error('JWT_SECRET not configured');

// ❌ BAD
const jwtSecret = 'super-secret-key';
```

### ✅ DO: Validate Input Type and Format

```javascript
// ✅ GOOD
const { query, validationResult } = require('express-validator');

app.get('/users/:id',
  param('id').isInt().toInt(),
  (req, res) => {
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({ errors: errors.array() });
    }
    // Safe to use req.params.id as integer
  }
);

// ❌ BAD: No validation
app.get('/users/:id', (req, res) => {
  // req.params.id could be anything
  db.query(`SELECT * FROM users WHERE id = ${req.params.id}`);
});
```

### ✅ DO: Check Authentication Before Authorization

```javascript
// ✅ GOOD: Authenticate first, then authorize
app.get('/admin/users',
  authenticate,      // Check if user is logged in
  authorize('admin'), // Check if user is admin
  (req, res) => { }
);

// ❌ BAD: Skipping authentication
app.get('/admin/users',
  authorize('admin'), // What if they're not even logged in?
  (req, res) => { }
);
```

### ✅ DO: Return Generic Error Messages to Clients

```javascript
// ✅ GOOD: Generic message to client
app.post('/login', (req, res) => {
  const user = db.query('SELECT * FROM users WHERE email = $1', [req.body.email]);

  if (!user) {
    // Don't reveal if email exists
    return res.status(401).json({ error: 'Invalid credentials' });
  }

  // Log detailed info internally
  logger.warn('Failed login attempt', { email: req.body.email });
});

// ❌ BAD: Leaks information
if (!user) {
  res.status(400).json({ error: 'Email not found' }); // Confirms email doesn't exist
}
```

### ✅ DO: Use HTTPS Only in Production

```javascript
// ✅ GOOD
app.use((req, res, next) => {
  if (process.env.NODE_ENV === 'production' && !req.secure) {
    return res.redirect(301, `https://${req.get('host')}${req.url}`);
  }
  next();
});

// ✅ GOOD: HSTS header
app.use((req, res, next) => {
  res.setHeader('Strict-Transport-Security', 'max-age=31536000; includeSubDomains');
  next();
});
```

### ✅ DO: Limit Request Payload Size

```javascript
// ✅ GOOD
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ limit: '10kb', extended: false }));

// ❌ BAD: No limits
app.use(express.json());
```

### ✅ DO: Use Rate Limiting

```javascript
// ✅ GOOD
const rateLimit = require('express-rate-limit');

const limiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 100,
  message: 'Too many requests',
});

app.use(limiter);
```

### ✅ DO: Log Security Events

```javascript
// ✅ GOOD
app.post('/login', (req, res) => {
  try {
    const user = authenticate(req.body);
    if (!user) {
      logger.warn('Failed login attempt', {
        email: req.body.email,
        ip: req.ip,
        timestamp: new Date(),
      });
      return res.status(401).json({ error: 'Invalid credentials' });
    }
    logger.info('Successful login', {
      userId: user.id,
      ip: req.ip,
    });
  } catch (err) {
    logger.error('Login error', { error: err.message });
  }
});

// ❌ BAD: No logging
if (!user) return res.status(401).json({ error: 'Invalid' });
```

