## Common Vulnerabilities to Avoid

### 1. SQL Injection

```javascript
// ❌ VULNERABLE
app.get('/search', (req, res) => {
  const query = `SELECT * FROM products WHERE name = '${req.query.name}'`;
  db.query(query, (err, results) => {
    res.json(results);
  });
});
// Attack: /search?name='; DROP TABLE products; --

// ✅ SECURE
app.get('/search', (req, res) => {
  db.query('SELECT * FROM products WHERE name = $1', [req.query.name], (err, results) => {
    res.json(results);
  });
});
```

### 2. XSS (Cross-Site Scripting)

```javascript
// ❌ VULNERABLE
app.get('/profile/:name', (req, res) => {
  res.send(`<h1>Welcome ${req.params.name}</h1>`);
});
// Attack: /profile/<script>alert('xss')</script>

// ✅ SECURE
app.get('/profile/:name', (req, res) => {
  res.json({ message: `Welcome ${req.params.name}` });
  // Or if HTML is needed: escape the variable
});
```

### 3. Weak Authentication

```javascript
// ❌ VULNERABLE
app.post('/login', (req, res) => {
  const user = db.query('SELECT * FROM users WHERE username = ?', [req.body.username]);
  if (user.password === req.body.password) { // Plaintext comparison
    res.json({ token: 'secret' });
  }
});

// ✅ SECURE
app.post('/login', (req, res) => {
  const user = db.query('SELECT * FROM users WHERE username = ?', [req.body.username]);
  if (bcrypt.compareSync(req.body.password, user.passwordHash)) {
    const token = jwt.sign({ id: user.id }, process.env.JWT_SECRET);
    res.json({ token });
  }
});
```

### 4. CORS Misconfiguration

```javascript
// ❌ VULNERABLE
app.use(cors({ origin: '*' })); // Allows any origin

// ✅ SECURE
app.use(cors({
  origin: ['https://app.example.com', 'https://www.example.com'],
  credentials: true,
}));
```

### 5. Insecure Deserialization

```javascript
// ❌ VULNERABLE
const data = eval(req.body.data); // Never use eval()

// ✅ SECURE
const data = JSON.parse(req.body.data);
```

