## 📋 Comprehensive Secure Implementation

Here's a complete refactored version of app.js:

```javascript
const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const { v4: uuidv4 } = require('uuid');
const jwt = require('jsonwebtoken');
const { query, validationResult } = require('express-validator');
const winston = require('winston');

const app = express();

// ========== ENVIRONMENT VALIDATION ==========
const validateEnv = () => {
  const required = ['JWT_SECRET', 'NODE_ENV'];
  const missing = required.filter(v => !process.env[v]);
  if (missing.length) throw new Error(`Missing env vars: ${missing.join(', ')}`);
};
validateEnv();

// ========== LOGGING ==========
const logger = winston.createLogger({
  level: process.env.LOG_LEVEL || 'info',
  format: winston.format.json(),
  defaultMeta: { service: 'app' },
  transports: [
    new winston.transports.File({ filename: 'error.log', level: 'error' }),
    new winston.transports.File({ filename: 'combined.log' }),
  ],
});

if (process.env.NODE_ENV !== 'production') {
  logger.add(new winston.transports.Console({
    format: winston.format.simple(),
  }));
}

// ========== REQUEST ID ==========
app.use((req, res, next) => {
  req.id = req.headers['x-request-id'] || uuidv4();
  res.setHeader('X-Request-ID', req.id);
  next();
});

// ========== SECURITY HEADERS ==========
app.use(helmet());
app.use((req, res, next) => {
  res.removeHeader('X-Powered-By');
  next();
});

// ========== CORS ==========
const allowedOrigins = (process.env.ALLOWED_ORIGINS || 'http://localhost:3000').split(',');
app.use(cors({
  origin: (origin, callback) => {
    if (!origin || allowedOrigins.includes(origin)) {
      callback(null, true);
    } else {
      callback(new Error('CORS not allowed'));
    }
  },
  credentials: true,
  methods: ['GET', 'POST', 'PUT', 'DELETE'],
}));

// ========== BODY PARSER WITH SIZE LIMITS ==========
app.use(express.json({ limit: '1mb' }));
app.use(express.urlencoded({ limit: '1mb', extended: true }));

// ========== RATE LIMITING ==========
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 100,
  standardHeaders: true,
  legacyHeaders: false,
  handler: (req, res) => {
    logger.warn(`Rate limit exceeded for IP: ${req.ip}`);
    res.status(429).json({ error: 'Too many requests' });
  },
});
app.use('/api/', limiter);

// ========== AUTHENTICATION MIDDLEWARE ==========
const authenticateToken = (req, res, next) => {
  const authHeader = req.headers['authorization'];
  const token = authHeader?.split(' ')[1];

  if (!token) {
    logger.warn(`Unauthorized access attempt to ${req.path} from ${req.ip}`);
    return res.status(401).json({ error: 'Access token required' });
  }

  jwt.verify(token, process.env.JWT_SECRET, (err, user) => {
    if (err) {
      logger.warn(`Invalid token attempt from ${req.ip}: ${err.message}`);
      return res.status(403).json({ error: 'Invalid token' });
    }
    req.user = user;
    next();
  });
};

// ========== HEALTH CHECK (No Auth Required) ==========
app.get('/health', (req, res) => {
  res.json({ 
    status: 'ok', 
    timestamp: new Date().toISOString(),
    requestId: req.id 
  });
});

// ========== PROTECTED USERS ENDPOINT ==========
app.get('/api/v1/users',
  authenticateToken,
  query('limit')
    .optional()
    .isInt({ min: 1, max: 100 })
    .withMessage('Limit must be 1-100'),
  query('offset')
    .optional()
    .isInt({ min: 0 })
    .withMessage('Offset must be >= 0'),
  (req, res) => {
    // Validate input
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({ errors: errors.array() });
    }

    // Authorization check
    if (req.user.role !== 'admin') {
      logger.warn(`Unauthorized user access attempt: ${req.user.id}`);
      return res.status(403).json({ error: 'Insufficient permissions' });
    }

    const limit = Math.min(parseInt(req.query.limit) || 10, 100);
    const offset = Math.max(parseInt(req.query.offset) || 0, 0);

    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ].slice(offset, offset + limit);

    logger.info(`Users retrieved by ${req.user.id}`, { requestId: req.id });
    res.json(users);
  }
);

// ========== 404 HANDLER ==========
app.use((req, res) => {
  res.status(404).json({ error: 'Not Found', requestId: req.id });
});

// ========== ERROR HANDLER ==========
app.use((err, req, res, next) => {
  logger.error({
    error: err.message,
    stack: err.stack,
    path: req.path,
    method: req.method,
    ip: req.ip,
    requestId: req.id,
  });

  const isDev = process.env.NODE_ENV !== 'production';
  const status = err.status || 500;
  const message = isDev ? err.message : 'Internal server error';

  res.status(status).json({ 
    error: message,
    requestId: req.id,
  });
});

// ========== START SERVER ==========
const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
  logger.info(`Server running on port ${PORT} in ${process.env.NODE_ENV} mode`);
});

module.exports = app;
```

