const authenticateToken = (req, res, next) => {
  const authHeader = req.headers['authorization'];
  const token = authHeader?.split(' ')[1];

  if (!token) {
    logger.warn({
      message: 'Unauthorized access attempt - missing token',
      path: req.path,
      method: req.method,
      ip: req.ip,
      requestId: req.id,
    });
    return res.status(401).json({
      error: 'Access token required',
      requestId: req.id,
    });
  }

  jwt.verify(token, process.env.JWT_SECRET, (err, user) => {
    if (err) {
      logger.warn({
        message: 'Unauthorized access attempt - invalid token',
        error: err.message,
        ip: req.ip,
        requestId: req.id,
      });
      return res.status(403).json({
        error: 'Invalid or expired token',
        requestId: req.id,
      });
    }

    req.user = user;
    logger.debug({
      message: 'Token verified',
      userId: user.id,
      requestId: req.id,
    });

    next();
  });
};

// ========== AUTHORIZATION MIDDLEWARE ==========
const requireRole = (allowedRoles) => {
  return (req, res, next) => {
    if (!allowedRoles.includes(req.user?.role)) {
      logger.warn({
        message: 'Authorization failed - insufficient permissions',
        userId: req.user?.id,
        requiredRoles: allowedRoles,
        userRole: req.user?.role,
        requestId: req.id,
      });
      return res.status(403).json({
        error: 'Insufficient permissions',
        requestId: req.id,
      });
    }
    next();
  };
};

// ========== PUBLIC ENDPOINTS ==========

// Health check endpoint (no authentication required)
app.get('/health', (req, res) => {
  logger.debug({
    message: 'Health check',
    requestId: req.id,
  });

  res.json({
    status: 'ok',
    timestamp: new Date().toISOString(),
    requestId: req.id,
  });
});

// ========== PROTECTED API ENDPOINTS ==========

/**
 * GET /api/v1/users
 * Retrieve list of users (admin only)
 * Query params:
 *   - limit: number (1-100, default 10)
 *   - offset: number (>= 0, default 0)
 */
app.get('/api/v1/users',
  authenticateToken,
  requireRole(['admin']),
  query('limit')
    .optional()
    .isInt({ min: 1, max: 100 })
    .withMessage('Limit must be between 1 and 100'),
  query('offset')
    .optional()
    .isInt({ min: 0 })
    .withMessage('Offset must be a non-negative integer'),
  (req, res) => {
    // Validate query parameters
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      logger.warn({
        message: 'Invalid query parameters',
        errors: errors.array(),
        userId: req.user.id,
        requestId: req.id,
      });
      return res.status(400).json({
        error: 'Invalid query parameters',
        details: errors.array(),
        requestId: req.id,
      });
    }

    try {
      const limit = Math.min(parseInt(req.query.limit) || 10, 100);
      const offset = Math.max(parseInt(req.query.offset) || 0, 0);

      // Sample data - in production, fetch from database
      const allUsers = [
        { id: 1, name: 'Alice', email: 'alice@example.com' },
        { id: 2, name: 'Bob', email: 'bob@example.com' },
      ];

      const users = allUsers.slice(offset, offset + limit);

      logger.info({
        message: 'Users retrieved',
        userId: req.user.id,
        count: users.length,
        requestId: req.id,
      });

      res.json({
        data: users,
        pagination: {
          limit,
          offset,
          total: allUsers.length,
        },
        requestId: req.id,
      });
    } catch (error) {
      logger.error({
        message: 'Error retrieving users',
        error: error.message,
        stack: error.stack,
        userId: req.user.id,
        requestId: req.id,
      });
      res.status(500).json({
        error: 'Internal server error',
        requestId: req.id,
      });
    }
  }
);

/**
 * GET /api/v1/users/:id
 * Retrieve specific user (users can access their own, admins can access all)
 */
app.get('/api/v1/users/:id',
  authenticateToken,
  query('id').trim().escape(),
  (req, res) => {
    const userId = parseInt(req.params.id);

    // Check authorization
    const isAdmin = req.user.role === 'admin';
    const isOwnProfile = req.user.id === userId;

    if (!isAdmin && !isOwnProfile) {
      logger.warn({
        message: 'Unauthorized access to user profile',
        requestedUserId: userId,
        requestingUserId: req.user.id,
        requestId: req.id,
      });
      return res.status(403).json({
        error: 'You do not have permission to access this user',
        requestId: req.id,
      });
    }

    try {
      const users = [
        { id: 1, name: 'Alice', email: 'alice@example.com' },
        { id: 2, name: 'Bob', email: 'bob@example.com' },
      ];

      const user = users.find(u => u.id === userId);

      if (!user) {
        return res.status(404).json({
          error: 'User not found',
          requestId: req.id,
        });
      }

      logger.info({
        message: 'User profile retrieved',
        requestedUserId: userId,
        requestingUserId: req.user.id,
        requestId: req.id,
      });

      res.json({
        data: user,
        requestId: req.id,
      });
    } catch (error) {
      logger.error({
        message: 'Error retrieving user',
        error: error.message,
        userId: req.user.id,
        requestId: req.id,
      });
      res.status(500).json({
        error: 'Internal server error',
        requestId: req.id,
      });
    }
  }
);

// ========== 404 HANDLER ==========
app.use((req, res) => {
  logger.debug({
    message: '404 Not Found',
    path: req.path,
    method: req.method,
    requestId: req.id,
  });

  res.status(404).json({
    error: 'Not Found',
    path: req.path,
    requestId: req.id,
  });
});

// ========== GLOBAL ERROR HANDLER ==========
// Must be last middleware
app.use((err, req, res, next) => {
  logger.error({
    message: 'Unhandled error',
    error: err.message,
    stack: err.stack,
    path: req.path,
    method: req.method,
    ip: req.ip,
    userId: req.user?.id,
    requestId: req.id,
  });

  const isDevelopment = process.env.NODE_ENV !== 'production';
  const statusCode = err.status || err.statusCode || 500;
  const errorMessage = isDevelopment ? err.message : 'Internal server error';

  res.status(statusCode).json({
    error: errorMessage,
    ...(isDevelopment && { stack: err.stack }),
    requestId: req.id,
  });
});

// ========== GRACEFUL SHUTDOWN ==========
process.on('SIGTERM', () => {
  logger.info('SIGTERM signal received: closing HTTP server');
  server.close(() => {
    logger.info('HTTP server closed');
    process.exit(0);
  });
});

// ========== START SERVER ==========
const PORT = process.env.PORT || 3000;
const server = app.listen(PORT, () => {
  logger.info({
    message: 'Server started',
    port: PORT,
    environment: process.env.NODE_ENV,
    timestamp: new Date().toISOString(),
  });
});

// Handle unhandled promise rejections
process.on('unhandledRejection', (reason, promise) => {
  logger.error({
    message: 'Unhandled Rejection at',
    promise,
    reason,
  });
});

// Handle uncaught exceptions
process.on('uncaughtException', (error) => {
  logger.error({
    message: 'Uncaught Exception',
    error: error.message,
    stack: error.stack,
  });
  process.exit(1);
});

module.exports = app;

