#### Vulnerability #2: SQL/NoSQL Injection
**OWASP:** A03:2021  
**CWE:** CWE-89, CWE-90  
**Affected Endpoints:** GET /users

**Problem:**
```javascript
app.get('/users', (req, res) => {
  // ❌ No validation of query parameters
  const limit = req.query.limit;    // Could be "999 OR 1=1"
  const offset = req.query.offset;  // Could be "0; DROP TABLE users"

  // If used in query:
  // db.query(`SELECT * FROM users LIMIT ${limit}`); ❌ VULNERABLE
});
```

**Impact:**
- Database manipulation
- Data extraction
- Data deletion
- Complete database compromise

**Severity:** 🔴 CRITICAL  
**CVSS Score:** 9.9 (Critical)

**Solution:**
```javascript
const { query, validationResult } = require('express-validator');

app.get('/api/v1/users',
  authenticateToken,
  query('limit')
    .optional()
    .isInt({ min: 1, max: 100 })      // ✅ Whitelist valid range
    .withMessage('Invalid limit'),
  query('offset')
    .optional()
    .isInt({ min: 0 })                 // ✅ Non-negative integer only
    .withMessage('Invalid offset'),
  (req, res) => {
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({ errors: errors.array() });
    }

    const limit = parseInt(req.query.limit) || 10;
    const offset = parseInt(req.query.offset) || 0;

    // ✅ Using parameterized queries
    db.query(
      'SELECT * FROM users LIMIT $1 OFFSET $2',
      [limit, offset]
    );
  }
);
```

**Test Cases:**
```bash
# Should fail - invalid type
curl 'http://localhost:3000/api/v1/users?limit=abc'
# Response: 400 Bad Request

# Should fail - exceeds maximum
curl 'http://localhost:3000/api/v1/users?limit=200'
# Response: 400 Bad Request

# Should fail - SQL injection attempt
curl 'http://localhost:3000/api/v1/users?limit=1%20OR%201=1'
# Response: 400 Bad Request

# Should succeed - valid input
curl 'http://localhost:3000/api/v1/users?limit=10&offset=0'
# Response: 200 OK
```

