#### Vulnerability #3: Missing Authentication
**OWASP:** A07:2021  
**CWE:** CWE-306  
**Endpoints:** All endpoints

**Problem:**
```javascript
app.get('/users', (req, res) => {
  // ❌ No authentication mechanism
  res.json([...]);
});

app.listen(3000);
```

**Impact:**
- Anyone can access APIs
- Anonymous abuse
- No user identification
- No audit trail

**Severity:** 🔴 CRITICAL  
**CVSS Score:** 10.0 (Critical)

**Solution:**
```javascript
const jwt = require('jsonwebtoken');

// 1. Implement token generation (login endpoint)
app.post('/auth/login', (req, res) => {
  // Verify credentials (hardcoded for demo)
  const user = { id: 1, role: 'admin' };

  const token = jwt.sign(
    { id: user.id, role: user.role },
    process.env.JWT_SECRET,
    { expiresIn: '1h' }  // Token expires in 1 hour
  );

  res.json({ token });
});

// 2. Middleware to verify token
const authenticateToken = (req, res, next) => {
  const authHeader = req.headers['authorization'];
  const token = authHeader?.split(' ')[1];  // Extract from "Bearer TOKEN"

  if (!token) {
    return res.status(401).json({ error: 'Token required' });
  }

  jwt.verify(token, process.env.JWT_SECRET, (err, user) => {
    if (err) {
      logger.warn(`Invalid token: ${err.message}`);
      return res.status(403).json({ error: 'Invalid token' });
    }
    req.user = user;
    next();
  });
};

// 3. Apply to protected endpoints
app.get('/api/v1/users', authenticateToken, (req, res) => {
  res.json([...]);
});
```

**Usage:**
```bash
# 1. Get token
TOKEN=$(curl -s -X POST http://localhost:3000/auth/login | jq -r '.token')

# 2. Use token in requests
curl -H "Authorization: Bearer $TOKEN" \
  http://localhost:3000/api/v1/users
```

