## 🔒 Production-Ready Secrets Implementation

### Complete Secure Setup for AWS

```javascript
// config/secrets.js
const AWS = require('aws-sdk');
const logger = require('./logger');

class SecretsManager {
  constructor() {
    this.client = new AWS.SecretsManager({
      region: process.env.AWS_REGION || 'us-east-1'
    });
    this.cache = new Map();
    this.cacheTTL = 60 * 60 * 1000; // 1 hour
  }

  async getSecret(secretName) {
    // Check cache
    const cached = this.cache.get(secretName);
    if (cached && cached.expiresAt > Date.now()) {
      return cached.value;
    }

    try {
      const result = await this.client.getSecretValue({
        SecretId: secretName
      }).promise();

      const value = result.SecretString 
        ? JSON.parse(result.SecretString)
        : result.SecretBinary;

      // Cache with TTL
      this.cache.set(secretName, {
        value,
        expiresAt: Date.now() + this.cacheTTL
      });

      logger.info(`Retrieved secret: ${secretName}`);
      return value;
    } catch (error) {
      logger.error(`Failed to retrieve secret ${secretName}:`, error.message);
      throw error;
    }
  }

  async getAllSecrets() {
    // Load all secrets at startup
    try {
      const appSecrets = await this.getSecret('prod/app/secrets');
      const dbSecrets = await this.getSecret('prod/db/secrets');
      const apiSecrets = await this.getSecret('prod/api/secrets');

      return {
        ...appSecrets,
        ...dbSecrets,
        ...apiSecrets
      };
    } catch (error) {
      logger.error('Failed to load all secrets:', error);
      throw new Error('Application cannot start without secrets');
    }
  }

  // Invalidate cache when secret is rotated
  invalidateCache(secretName) {
    this.cache.delete(secretName);
    logger.info(`Cache invalidated for: ${secretName}`);
  }
}

module.exports = new SecretsManager();
```

```javascript
// app.js - With secure secrets management
const express = require('express');
const helmet = require('helmet');
const secretsManager = require('./config/secrets');
const logger = require('./config/logger');

const app = express();

// ===== STARTUP: Load secrets before app initialization =====
async function initializeApp() {
  try {
    logger.info('Loading secrets from AWS Secrets Manager...');
    const secrets = await secretsManager.getAllSecrets();

    // Store in secure context, NOT in global process.env directly
    global.appSecrets = {
      jwt_secret: secrets.jwtSecret,
      db_url: secrets.databaseUrl,
      api_key: secrets.apiKey
    };

    logger.info('Secrets loaded successfully');
  } catch (error) {
    logger.error('Failed to initialize application:', error);
    process.exit(1);
  }

  // Apply middleware
  app.use(helmet());

  // Use secrets from global context
  const authenticateToken = (req, res, next) => {
    const authHeader = req.headers['authorization'];
    const token = authHeader?.split(' ')[1];

    if (!token) {
      return res.status(401).json({ error: 'Token required' });
    }

    try {
      const user = jwt.verify(token, global.appSecrets.jwt_secret);
      req.user = user;
      next();
    } catch (error) {
      // ❌ NEVER log the actual error with JWT_SECRET
      logger.warn('Invalid token: authentication failed');
      return res.status(403).json({ error: 'Invalid token' });
    }
  };

  // Routes
  app.get('/api/v1/users', authenticateToken, (req, res) => {
    res.json({ data: [] });
  });

  const PORT = process.env.PORT || 3000;
  app.listen(PORT, () => {
    logger.info(`App listening on port ${PORT}`);
  });
}

// Start app
initializeApp().catch(error => {
  logger.error('Failed to start application:', error);
  process.exit(1);
});

module.exports = app;
