// secrets-manager.js
// Secure secrets management implementation for production

const logger = require('./logger');

/**
 * Abstract base class for secrets managers
 * Implement this for different secret backends
 */
class SecretsProvider {
  async getSecret(secretName) {
    throw new Error('Not implemented');
  }

  async getAllSecrets() {
    throw new Error('Not implemented');
  }

  invalidateCache(secretName) {
    throw new Error('Not implemented');
  }
}

/**
 * AWS Secrets Manager Implementation
 */
class AWSSecretsManager extends SecretsProvider {
  constructor(region = 'us-east-1') {
    super();
    try {
      const AWS = require('aws-sdk');
      this.client = new AWS.SecretsManager({ region });
    } catch (error) {
      logger.error('AWS SDK not available - install with: npm install aws-sdk');
      throw error;
    }

    this.cache = new Map();
    this.cacheTTL = 60 * 60 * 1000; // 1 hour
    this.secretsToLoad = [
      'prod/app/core-secrets',      // JWT_SECRET, SESSION_SECRET
      'prod/database/credentials',  // DB credentials
      'prod/api/keys',              // External API keys
    ];
  }

  async getSecret(secretName) {
    // Check cache first
    const cached = this.cache.get(secretName);
    if (cached && cached.expiresAt > Date.now()) {
      logger.debug(`Cache hit for secret: ${secretName}`);
      return cached.value;
    }

    try {
      logger.debug(`Fetching secret from AWS: ${secretName}`);

      const result = await this.client.getSecretValue({
        SecretId: secretName,
        VersionStage: 'AWSCURRENT'
      }).promise();

      // Parse JSON secret or use binary
      let secretValue;
      if (result.SecretString) {
        secretValue = JSON.parse(result.SecretString);
      } else if (result.SecretBinary) {
        secretValue = Buffer.from(result.SecretBinary, 'base64');
      }

      // Cache with TTL and expiration tracking
      this.cache.set(secretName, {
        value: secretValue,
        expiresAt: Date.now() + this.cacheTTL,
        version: result.VersionId,
        retrievedAt: new Date().toISOString()
      });

      this._auditSecretAccess(secretName, 'SUCCESS');
      return secretValue;

    } catch (error) {
      this._auditSecretAccess(secretName, 'FAILED', error.message);
      logger.error(`Failed to retrieve secret ${secretName}:`, {
        error: error.message,
        code: error.code
      });
      throw new Error(`Cannot access secret: ${secretName}`);
    }
  }

  async getAllSecrets() {
    logger.info('Loading all secrets from AWS Secrets Manager');
    const allSecrets = {};

    try {
      for (const secretName of this.secretsToLoad) {
        const secret = await this.getSecret(secretName);
        Object.assign(allSecrets, secret);
      }

      logger.info(`Successfully loaded ${Object.keys(allSecrets).length} secrets`);
      return allSecrets;

    } catch (error) {
      logger.error('Failed to load all secrets:', error);
      throw new Error('Application cannot start without all secrets');
    }
  }

  invalidateCache(secretName) {
    this.cache.delete(secretName);
    logger.info(`Cache invalidated for: ${secretName}`);
  }

  invalidateAllCache() {
    this.cache.clear();
    logger.info('All secret cache cleared');
  }

  _auditSecretAccess(secretName, status, error = null) {
    const stackTrace = new Error().stack.split('\n')[3];
    logger.info({
      event: 'SECRET_ACCESS',
      status,
      secretName,
      caller: stackTrace,
      timestamp: new Date().toISOString(),
      environment: process.env.NODE_ENV,
      ...(error && { error })
    });
  }

  async setupRotationListener() {
    // Listen for rotation events and invalidate cache
    logger.info('Setting up secret rotation listener...');

    // In production, set up CloudWatch events to trigger cache invalidation
    // when secrets are rotated
    setInterval(() => {
      logger.debug('Checking for secret updates...');
      this.invalidateAllCache();
    }, 30 * 60 * 1000); // Check every 30 minutes
  }
}

/**
 * HashiCorp Vault Implementation
 */
class VaultSecretsManager extends SecretsProvider {
  constructor(vaultAddr, vaultToken) {
    super();
    try {
      const vault = require('node-vault');
      this.client = vault({
        endpoint: vaultAddr,
        token: vaultToken
      });
    } catch (error) {
      logger.error('node-vault not available - install with: npm install node-vault');
      throw error;
    }

    this.vaultAddr = vaultAddr;
    this.cache = new Map();
    this.cacheTTL = 30 * 60 * 1000; // 30 minutes (shorter than Vault lease)
  }

  async getSecret(secretPath) {
    // Check cache
    const cached = this.cache.get(secretPath);
    if (cached && cached.expiresAt > Date.now()) {
      return cached.value;
    }

    try {
      logger.debug(`Fetching secret from Vault: ${secretPath}`);

      const result = await this.client.read(secretPath);

      // Handle both KV v1 and KV v2
      const secretValue = result.data.data || result.data;

      this.cache.set(secretPath, {
        value: secretValue,
        expiresAt: Date.now() + this.cacheTTL,
        leaseDuration: result.lease_duration,
        leaseId: result.lease_id
      });

      this._auditSecretAccess(secretPath, 'SUCCESS');
      return secretValue;

    } catch (error) {
      this._auditSecretAccess(secretPath, 'FAILED', error.message);
      logger.error(`Failed to retrieve secret from Vault ${secretPath}:`, error.message);
      throw error;
    }
  }

  async getAllSecrets() {
    logger.info('Loading all secrets from Vault');

    const secrets = {
      jwtSecret: await this.getSecret('secret/data/jwt-secret'),
      databaseUrl: await this.getSecret('secret/data/database-url'),
      apiKeys: await this.getSecret('secret/data/api-keys')
    };

    return secrets;
  }

  invalidateCache(secretPath) {
    this.cache.delete(secretPath);
    logger.info(`Cache invalidated for Vault secret: ${secretPath}`);
  }

  _auditSecretAccess(secretPath, status, error = null) {
    logger.info({
      event: 'VAULT_SECRET_ACCESS',
      status,
      secretPath,
      timestamp: new Date().toISOString(),
      ...(error && { error })
    });
  }
}

/**
 * Azure Key Vault Implementation
 */
class AzureKeyVaultManager extends SecretsProvider {
  constructor(vaultName) {
    super();
    try {
      const { SecretClient } = require('@azure/keyvault-secrets');
      const { DefaultAzureCredential } = require('@azure/identity');

      const credential = new DefaultAzureCredential();
      this.client = new SecretClient(
        `https://${vaultName}.vault.azure.net/`,
        credential
      );
    } catch (error) {
      logger.error('Azure SDK not available - install with: npm install @azure/keyvault-secrets @azure/identity');
      throw error;
    }

    this.cache = new Map();
    this.cacheTTL = 60 * 60 * 1000; // 1 hour
  }

  async getSecret(secretName) {
    // Check cache
    const cached = this.cache.get(secretName);
    if (cached && cached.expiresAt > Date.now()) {
      return cached.value;
    }

    try {
      logger.debug(`Fetching secret from Azure Key Vault: ${secretName}`);

      const secret = await this.client.getSecret(secretName);

      this.cache.set(secretName, {
        value: secret.value,
        expiresAt: Date.now() + this.cacheTTL,
        version: secret.version
      });

      this._auditSecretAccess(secretName, 'SUCCESS');
      return secret.value;

    } catch (error) {
      this._auditSecretAccess(secretName, 'FAILED', error.message);
      logger.error(`Failed to retrieve secret from Azure: ${secretName}`, error.message);
      throw error;
    }
  }

  async getAllSecrets() {
    logger.info('Loading secrets from Azure Key Vault');

    const secrets = {
      jwtSecret: await this.getSecret('jwt-secret'),
      databaseUrl: await this.getSecret('database-url'),
      apiKey: await this.getSecret('api-key')
    };

    return secrets;
  }

  invalidateCache(secretName) {
    this.cache.delete(secretName);
    logger.info(`Cache invalidated for: ${secretName}`);
  }

  _auditSecretAccess(secretName, status, error = null) {
    logger.info({
      event: 'AZURE_KEY_VAULT_ACCESS',
      status,
      secretName,
      timestamp: new Date().toISOString(),
      ...(error && { error })
    });
  }
}

/**
 * Development/Testing Implementation (Never in production!)
 */
class DotenvSecretsManager extends SecretsProvider {
  constructor() {
    super();

    // Only load in development
    if (process.env.NODE_ENV === 'production') {
      throw new Error('DotenvSecretsManager cannot be used in production!');
    }

    try {
      require('dotenv-safe').config({
        allowEmptyValues: false,
        example: '.env.example'
      });
    } catch (error) {
      logger.error('Failed to load .env file:', error);
      throw error;
    }

    logger.warn('⚠️  Using .env file for secrets - DEVELOPMENT ONLY');
  }

  async getSecret(secretName) {
    const value = process.env[secretName];
    if (!value) {
      throw new Error(`Secret not found: ${secretName}`);
    }
    return value;
  }

  async getAllSecrets() {
    return {
      jwtSecret: process.env.JWT_SECRET,
      databaseUrl: process.env.DATABASE_URL,
      apiKey: process.env.API_KEY
    };
  }

  invalidateCache(secretName) {
    // No-op for development
  }
}

/**
 * Factory to create appropriate secrets manager
 */
function createSecretsManager() {
  const environment = process.env.NODE_ENV || 'development';
  const secretsBackend = process.env.SECRETS_BACKEND || 'aws';

  logger.info(`Initializing secrets manager: ${secretsBackend} (${environment})`);

  switch (secretsBackend) {
    case 'aws':
      return new AWSSecretsManager(process.env.AWS_REGION);

    case 'vault':
      return new VaultSecretsManager(
        process.env.VAULT_ADDR,
        process.env.VAULT_TOKEN
      );

    case 'azure':
      return new AzureKeyVaultManager(process.env.AZURE_VAULT_NAME);

    case 'dotenv':
      if (environment === 'production') {
        throw new Error('Cannot use dotenv in production');
      }
      return new DotenvSecretsManager();

    default:
      throw new Error(`Unknown secrets backend: ${secretsBackend}`);
  }
}

/**
 * Global secrets manager instance
 */
let secretsManager = null;

async function initializeSecretsManager() {
  try {
    secretsManager = createSecretsManager();

    // Load all secrets at startup
    const secrets = await secretsManager.getAllSecrets();

    // Store in secure global scope (not directly in process.env)
    global.appSecrets = secrets;

    logger.info('Secrets manager initialized successfully');
    return secretsManager;

  } catch (error) {
    logger.error('Failed to initialize secrets manager:', error);
    process.exit(1);
  }
}

/**
 * Get secrets safely
 */
function getSecret(secretName) {
  if (!global.appSecrets) {
    throw new Error('Secrets not initialized - call initializeSecretsManager() first');
  }

  const value = global.appSecrets[secretName];
  if (!value) {
    throw new Error(`Secret not found: ${secretName}`);
  }

  return value;
}

/**
 * Invalidate secret cache (for rotation)
 */
function invalidateSecret(secretName) {
  if (secretsManager) {
    secretsManager.invalidateCache(secretName);
  }

  // Reload secret
  if (global.appSecrets) {
    delete global.appSecrets[secretName];
  }
}

module.exports = {
  initializeSecretsManager,
  getSecret,
  invalidateSecret,
  AWSSecretsManager,
  VaultSecretsManager,
  AzureKeyVaultManager,
  DotenvSecretsManager
};

// app-with-secrets-manager.js
// Express application with secure secrets management

const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const jwt = require('jsonwebtoken');
const { query, validationResult } = require('express-validator');
const logger = require('./logger');
const { initializeSecretsManager, getSecret } = require('./secrets-manager');

const app = express();

// ========== STARTUP: Initialize with secure secrets ==========
async function initializeApp() {
  try {
    logger.info('Starting application...');

    // Initialize secrets manager first
    await initializeSecretsManager();
    logger.info('✅ Secrets manager initialized');

    // Apply middleware
    setupMiddleware();

    // Setup routes
    setupRoutes();

    // Start server
    const PORT = process.env.PORT || 3000;
    app.listen(PORT, () => {
      logger.info(`✅ Application listening on port ${PORT}`);
    });

  } catch (error) {
    logger.error('Failed to initialize application:', error);
    process.exit(1);
  }
}

// ========== MIDDLEWARE SETUP ==========
function setupMiddleware() {
  // Security headers
  app.use(helmet());

  // Remove server info
  app.use((req, res, next) => {
    res.removeHeader('X-Powered-By');
    next();
  });

  // Body parser
  app.use(express.json({ limit: '1mb' }));
  app.use(express.urlencoded({ limit: '1mb', extended: true }));

  // CORS
  const allowedOrigins = (process.env.ALLOWED_ORIGINS || 'http://localhost:3000')
    .split(',')
    .map(o => o.trim());

  app.use(cors({
    origin: (origin, callback) => {
      if (!origin || allowedOrigins.includes(origin)) {
        callback(null, true);
      } else {
        logger.warn(`CORS rejected for origin: ${origin}`);
        callback(new Error('CORS not allowed'));
      }
    },
    credentials: true
  }));

  // Request ID
  app.use((req, res, next) => {
    req.id = req.headers['x-request-id'] || require('uuid').v4();
    res.setHeader('X-Request-ID', req.id);
    next();
  });
}

// ========== AUTHENTICATION MIDDLEWARE ==========
const authenticateToken = (req, res, next) => {
  const authHeader = req.headers['authorization'];
  const token = authHeader?.split(' ')[1];

  if (!token) {
    logger.warn({
      message: 'Unauthorized - no token',
      path: req.path,
      ip: req.ip
    });
    return res.status(401).json({ error: 'Token required' });
  }

  try {
    // Get JWT_SECRET from secure secrets manager
    const jwtSecret = getSecret('jwtSecret');

    const user = jwt.verify(token, jwtSecret);
    req.user = user;
    next();

  } catch (error) {
    // ❌ NEVER log the error directly - it might contain the secret
    logger.warn({
      message: 'Token verification failed',
      errorType: error.name, // Only log error type, not message
      ip: req.ip
    });

    return res.status(403).json({ error: 'Invalid token' });
  }
};

// ========== ROUTES SETUP ==========
function setupRoutes() {
  // Health check (public)
  app.get('/health', (req, res) => {
    res.json({
      status: 'ok',
      timestamp: new Date().toISOString()
    });
  });

  // Protected route
  app.get('/api/v1/users',
    authenticateToken,
    query('limit').optional().isInt({ min: 1, max: 100 }),
    (req, res) => {
      const errors = validationResult(req);
      if (!errors.isEmpty()) {
        return res.status(400).json({ errors: errors.array() });
      }

      try {
        const users = [
          { id: 1, name: 'Alice' },
          { id: 2, name: 'Bob' }
        ];

        logger.info({
          message: 'Users endpoint accessed',
          userId: req.user.id,
          requestId: req.id
        });

        res.json({ data: users });

      } catch (error) {
        logger.error({
          message: 'Error retrieving users',
          errorType: error.name, // Not the full error
          requestId: req.id
        });
        res.status(500).json({ error: 'Internal server error' });
      }
    }
  );

  // Error handling
  app.use((err, req, res, next) => {
    logger.error({
      message: 'Unhandled error',
      errorType: err.name,
      path: req.path,
      requestId: req.id
    });

    res.status(500).json({
      error: 'Internal server error',
      requestId: req.id
    });
  });
}

// ========== GRACEFUL SHUTDOWN ==========
process.on('SIGTERM', () => {
  logger.info('SIGTERM received - shutting down gracefully');
  process.exit(0);
});

process.on('uncaughtException', (error) => {
  logger.error({
    message: 'Uncaught exception',
    errorType: error.name,
    stack: error.stack
  });
  process.exit(1);
});

// ========== START ==========
initializeApp().catch(error => {
  logger.error('Fatal error during startup:', error);
  process.exit(1);
});

module.exports = app;

