    fs.appendFileSync(path.join(logsDir, 'security.log'), log);
  },

  logSuspiciousActivity: (description, data, ip) => {
    const log = `[SUSPICIOUS] ${new Date().toISOString()} - ${description} - IP: ${ip} - Data: ${JSON.stringify(data)}\n`;
    fs.appendFileSync(path.join(logsDir, 'security.log'), log);
  }
};

// ==================== AUTHENTICATION MIDDLEWARE ====================

function authenticateToken(req, res, next) {
  const authHeader = req.headers['authorization'];
  const token = authHeader && authHeader.split(' ')[1]; // Bearer TOKEN

  if (!token) {
    securityLogger.logFailedAuth(req.ip, 'Missing authentication token');
    return res.status(401).json({ error: 'Access token required' });
  }

  jwt.verify(token, SECRET_KEY, (err, user) => {
    if (err) {
      securityLogger.logFailedAuth(req.ip, `Invalid token: ${err.message}`);
      return res.status(403).json({ error: 'Invalid or expired token' });
    }

    // Validate user object structure
    if (!user.id || !user.role) {
      securityLogger.logFailedAuth(req.ip, 'Invalid token structure');
      return res.status(403).json({ error: 'Invalid token' });
    }

    req.user = user;
    next();
  });
}

// ==================== AUTHORIZATION MIDDLEWARE ====================

function authorize(allowedRoles) {
  return (req, res, next) => {
    if (!req.user || !allowedRoles.includes(req.user.role)) {
      securityLogger.logUnauthorizedAccess(
        req.user?.id || 'unknown',
        req.originalUrl,
        req.ip
      );
      return res.status(403).json({ error: 'Insufficient permissions' });
    }
    next();
  };
}

// ==================== ROUTES ====================

// Health check (no auth required for monitoring)
