  authenticateToken,
  authorize(['admin', 'staff']),
  query('limit').optional().isInt({ min: 1, max: 100 }).toInt(),
  query('offset').optional().isInt({ min: 0 }).toInt(),
  (req, res) => {
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      securityLogger.logSuspiciousActivity('Invalid query parameters', errors.array(), req.ip);
      return res.status(400).json({ errors: errors.array() });
    }

    const limit = Math.min(req.query.limit || 10, 100);
    const offset = Math.max(req.query.offset || 0, 0);

    try {
      // In a real application, fetch from database with parameterized queries
      // Example: const users = await db.query('SELECT * FROM users LIMIT ? OFFSET ?', [limit, offset]);

      // Only return necessary data based on user role
      const userData = [
        { id: 1, name: 'Alice' },
        { id: 2, name: 'Bob' },
      ];

      // Admin can see emails, others cannot
      if (req.user.role === 'admin') {
        userData[0].email = 'alice@example.com';
        userData[1].email = 'bob@example.com';
      }

      res.json({
        data: userData,
        pagination: { limit, offset, total: 2 }
      });
    } catch (error) {
      securityLogger.logSuspiciousActivity('Error fetching users', { error: error.message }, req.ip);
      return res.status(500).json({ error: 'Internal server error' });
    }
});

// ==================== ERROR HANDLING ====================

// 404 handler
app.use((req, res) => {
  res.status(404).json({ 
    error: 'Not found',
    path: req.originalUrl
  });
});

// Global error handler
app.use((err, req, res, next) => {
  const isDevelopment = process.env.NODE_ENV === 'development';

  // Log error securely (without sensitive data)
  console.error(`[ERROR] ${new Date().toISOString()} - ${err.message}`);
  if (isDevelopment) {
    console.error(err.stack);
  }

  const response = {
    error: isDevelopment ? err.message : 'An internal server error occurred'
  };

  if (isDevelopment) {
    response.stack = err.stack;
  }

  const statusCode = err.statusCode || 500;

  // Set security headers for error responses
  res.set('X-Content-Type-Options', 'nosniff');
  res.status(statusCode).json(response);
});

// ==================== SERVER STARTUP ====================

const PORT = process.env.PORT || 3000;
const NODE_ENV = process.env.NODE_ENV || 'development';

if (require.main === module) {
