# Security Testing Guide

## Unit Tests for Security Features

Create `app.test.js`:

```javascript
const request = require('supertest');
const app = require('./app_secure');
const jwt = require('jsonwebtoken');

describe('Security Tests', () => {
  const SECRET_KEY = process.env.JWT_SECRET || 'dev-secret-key';

  // Helper to generate valid JWT
  const generateToken = (userId, role = 'user') => {
    return jwt.sign(
      { id: userId, role: role },
      SECRET_KEY,
      { expiresIn: '1h' }
    );
  };

  describe('Authentication', () => {
    test('GET /users without token should return 401', async () => {
      const res = await request(app)
        .get('/users')
        .expect(401);

      expect(res.body.error).toBeDefined();
    });

    test('GET /users with invalid token should return 403', async () => {
      const res = await request(app)
        .get('/users')
        .set('Authorization', 'Bearer invalid-token')
        .expect(403);

      expect(res.body.error).toBeDefined();
    });

    test('GET /users with valid token should return 200', async () => {
      const token = generateToken(1, 'admin');
      const res = await request(app)
        .get('/users')
        .set('Authorization', \`Bearer \${token}\`)
        .expect(200);

      expect(res.body.data).toBeDefined();
    });
  });

  describe('Authorization', () => {
    test('User with "user" role should not access /users', async () => {
      const token = generateToken(1, 'user');
      const res = await request(app)
        .get('/users')
        .set('Authorization', \`Bearer \${token}\`)
        .expect(403);

      expect(res.body.error).toMatch(/insufficient|permission/i);
    });

    test('User with "admin" role should access /users', async () => {
      const token = generateToken(1, 'admin');
      const res = await request(app)
        .get('/users')
        .set('Authorization', \`Bearer \${token}\`)
        .expect(200);

      expect(res.body.data).toBeDefined();
    });
  });

  describe('Input Validation', () => {
    test('Invalid limit parameter should return 400', async () => {
      const token = generateToken(1, 'admin');
      const res = await request(app)
        .get('/users?limit=abc')
        .set('Authorization', \`Bearer \${token}\`)
        .expect(400);

      expect(res.body.errors).toBeDefined();
    });

    test('Limit > 100 should be capped at 100', async () => {
      const token = generateToken(1, 'admin');
      const res = await request(app)
        .get('/users?limit=200')
        .set('Authorization', \`Bearer \${token}\`)
        .expect(200);

      expect(res.body.pagination.limit).toBe(100);
    });

    test('Negative offset should be set to 0', async () => {
      const token = generateToken(1, 'admin');
      const res = await request(app)
        .get('/users?offset=-10')
        .set('Authorization', \`Bearer \${token}\`)
        .expect(200);

      expect(res.body.pagination.offset).toBe(0);
    });
