## Complete Remediation Guide

### SOLUTION 1: AWS Secrets Manager (Recommended for Production)

#### Step 1: Install AWS SDK
```bash
npm install @aws-sdk/client-secrets-manager
```

#### Step 2: Create Secrets Management Module

Create `secrets.js`:
```javascript
const { SecretsManagerClient, GetSecretValueCommand } = require("@aws-sdk/client-secrets-manager");

const client = new SecretsManagerClient({ region: process.env.AWS_REGION || 'us-east-1' });

class SecretsManager {
  constructor() {
    this.cache = new Map();
    this.cacheTTL = 3600 * 1000; // 1 hour cache
  }

  async getSecret(secretName) {
    // Check cache first
    if (this.cache.has(secretName)) {
      const cached = this.cache.get(secretName);
      if (Date.now() - cached.timestamp < this.cacheTTL) {
        console.log(`[SECRETS] Cache hit for ${secretName}`);
        return cached.value;
      }
    }

    try {
      console.log(`[SECRETS] Fetching ${secretName} from Secrets Manager...`);

      const command = new GetSecretValueCommand({
        SecretId: secretName,
        VersionStage: "AWSCURRENT",
      });

      const response = await client.send(command);
      let secretValue;

      if (response.SecretString) {
        secretValue = JSON.parse(response.SecretString);
      } else if (response.SecretBinary) {
        secretValue = response.SecretBinary;
      } else {
        throw new Error(`Secret ${secretName} has no value`);
      }

      // Cache the secret
      this.cache.set(secretName, {
        value: secretValue,
        timestamp: Date.now(),
      });

      console.log(`[SECRETS] Successfully cached ${secretName}`);
      return secretValue;

    } catch (error) {
      console.error(`[SECRETS] Error retrieving ${secretName}:`, error.message);

      // CRITICAL: Fail securely - never fall back to dev secrets
      if (process.env.NODE_ENV === 'production') {
        throw new Error(
          `Failed to retrieve required secret '${secretName}'. ` +
          `Application cannot start without production secrets. ` +
          `Error: ${error.message}`
        );
      }

      // Development: Provide helpful error
      console.warn(`[SECRETS] In development mode, returning undefined for ${secretName}`);
      return undefined;
    }
  }

  async getJWTSecret() {
    const secret = await this.getSecret('jwt-secret');

    if (!secret) {
      throw new Error(
        'JWT_SECRET is required. ' +
        'In production: Create secret in AWS Secrets Manager. ' +
        'In development: Set JWT_SECRET environment variable.'
      );
    }

    return secret.key || secret;
  }

  async getDatabaseConfig() {
    try {
      return await this.getSecret('database-config');
    } catch (error) {
      console.error('[SECRETS] Database config retrieval failed:', error.message);
      throw error;
    }
  }

  async getRedisConfig() {
    try {
      return await this.getSecret('redis-config');
    } catch (error) {
      console.warn('[SECRETS] Redis config not found, continuing without Redis');
      return null;
    }
  }

  // Clear cache on demand (for testing or manual rotation)
  clearCache(secretName) {
    if (secretName) {
      this.cache.delete(secretName);
      console.log(`[SECRETS] Cache cleared for ${secretName}`);
    } else {
      this.cache.clear();
      console.log(`[SECRETS] All cache cleared`);
    }
  }
}

module.exports = new SecretsManager();
```

