## Secrets Rotation Strategy

### Automatic Rotation (Recommended)

```javascript
// rotation-handler.js
const secretsManager = require('./secrets');

class SecretsRotationHandler {

  // Called when AWS rotates the secret
  async onSecretRotated(secretName) {
    console.log(`[ROTATION] ${secretName} rotated at ${new Date().toISOString()}`);

    // Clear local cache to force reload
    secretsManager.clearCache(secretName);

    // Log the rotation event
    this.logRotationEvent({
      secretName,
      timestamp: new Date(),
      status: 'rotated',
    });

    // Alert monitoring system
    await this.notifyMonitoring({
      event: 'secret_rotated',
      secretName,
      severity: 'INFO',
    });
  }

  logRotationEvent(event) {
    // Send to audit log
    console.log(`[AUDIT] ${JSON.stringify(event)}`);
  }

  async notifyMonitoring(alert) {
    // Send to Slack, PagerDuty, CloudWatch, etc.
    console.log(`[MONITORING] ${JSON.stringify(alert)}`);
  }

  // Manual rotation trigger
  async rotateSecret(secretName) {
    if (process.env.NODE_ENV !== 'production') {
      throw new Error('Manual rotation only in production');
    }

    console.log(`[MANUAL-ROTATION] Starting rotation for ${secretName}`);

    // Implementation depends on Secrets Manager
    // For AWS:
    const { SecretsManagerClient, RotateSecretCommand } = 
      require('@aws-sdk/client-secrets-manager');

    const client = new SecretsManagerClient({});
    const command = new RotateSecretCommand({
      SecretId: secretName,
    });

    await client.send(command);
    console.log(`[MANUAL-ROTATION] Rotation initiated for ${secretName}`);
  }
}

module.exports = new SecretsRotationHandler();
```

