## Secrets Audit & Compliance

### Audit Logging Example

```javascript
// audit-logger.js
const fs = require('fs');
const crypto = require('crypto');

class SecretsAuditLogger {

  log(action, details) {
    const auditEntry = {
      timestamp: new Date().toISOString(),
      action,
      userId: details.userId || 'system',
      resource: details.resource,
      result: details.result,
      source: details.source || 'app',
      ipAddress: details.ipAddress,
      signature: this.createSignature(action, details),
    };

    // Write to immutable audit log
    this.writeAuditLog(auditEntry);

    // Send to central logging
    this.sendToCentralLogging(auditEntry);
  }

  createSignature(action, details) {
    const data = `${action}${JSON.stringify(details)}`;
    return crypto.createHash('sha256').update(data).digest('hex');
  }

  writeAuditLog(entry) {
    const logEntry = `${JSON.stringify(entry)}\n`;
    fs.appendFileSync('/var/log/secrets-audit.log', logEntry, { mode: 0o400 });
  }

  sendToCentralLogging(entry) {
    // Send to CloudWatch, ELK, Splunk, etc.
    console.log(`[AUDIT] ${JSON.stringify(entry)}`);
  }

  logSecretAccess(secretName, userId, success = true) {
    this.log('SECRET_ACCESS', {
      resource: secretName,
      userId,
      result: success ? 'SUCCESS' : 'FAILED',
    });
  }

  logSecretRotation(secretName, reason) {
    this.log('SECRET_ROTATION', {
      resource: secretName,
      result: 'INITIATED',
      details: reason,
    });
  }

  logComplianceCheck(result) {
    this.log('COMPLIANCE_CHECK', {
      result: result ? 'PASSED' : 'FAILED',
      details: result,
    });
  }
}

module.exports = new SecretsAuditLogger();
```

