            exit 1
          fi

  deploy:
    needs: secrets-check
    runs-on: ubuntu-latest
    steps:
      - uses: actions/checkout@v3

      # Use secrets from GitHub repository secrets
      - name: Configure AWS credentials
        uses: aws-actions/configure-aws-credentials@v2
        with:
