// secrets-manager.js
// Production-grade secrets management with AWS Secrets Manager
// Supports fallback to local .env for development

const { SecretsManagerClient, GetSecretValueCommand } = require("@aws-sdk/client-secrets-manager");
const fs = require('fs');
const path = require('path');

/**
 * SecureSecretsManager
 * 
 * Provides centralized, secure secret management with:
 * - AWS Secrets Manager for production
 * - Encrypted local cache with TTL
 * - Environment variable fallback for development
 * - Comprehensive audit logging
 * - Fail-secure behavior
 */
class SecureSecretsManager {
  constructor(config = {}) {
    this.environment = process.env.NODE_ENV || 'development';
    this.useAWS = this.environment === 'production';

    // AWS configuration
    this.awsRegion = process.env.AWS_REGION || 'us-east-1';
    this.client = this.useAWS ? 
      new SecretsManagerClient({ region: this.awsRegion }) : 
      null;

    // Cache configuration
    this.cache = new Map();
    this.cacheTTL = config.cacheTTL || 3600000; // 1 hour default

    // Audit logging
    this.auditLogPath = config.auditLogPath || './logs/secrets-audit.log';
    this.ensureAuditLogDirectory();

    // Secrets schema (validate structure)
    this.secretsSchema = {
      'jwt-secret': {
        required: true,
        type: 'object',
        keys: ['key'],
        description: 'JWT signing key',
      },
      'database-config': {
        required: process.env.NODE_ENV === 'production',
        type: 'object',
        keys: ['host', 'port', 'username', 'password', 'database'],
        description: 'Database connection credentials',
      },
      'redis-config': {
        required: false,
        type: 'object',
        keys: ['host', 'port', 'password'],
        description: 'Redis connection credentials',
      },
      'sentry-dsn': {
        required: false,
        type: 'string',
        description: 'Sentry error tracking DSN',
      },
    };

    console.log(`[SECRETS] Manager initialized (${this.useAWS ? 'AWS' : 'LOCAL'} mode)`);
  }

  /**
   * Ensure audit log directory exists
   */
  ensureAuditLogDirectory() {
    const dir = path.dirname(this.auditLogPath);
    if (!fs.existsSync(dir)) {
      fs.mkdirSync(dir, { recursive: true, mode: 0o700 });
    }
  }

  /**
   * Main method: Get a secret
   * @param {string} secretName - Name of the secret
   * @param {object} options - Optional configuration
   * @returns {Promise<any>} - Secret value
   */
  async getSecret(secretName, options = {}) {
    const { 
      useCache = true, 
      required = true,
      decrypt = true,
      validationSchema = null,
    } = options;

    try {
      // Check cache first (if enabled)
      if (useCache) {
        const cached = this.getFromCache(secretName);
        if (cached !== null) {
          this.auditLog('SECRET_CACHE_HIT', { secretName });
          return cached;
        }
      }

      let secretValue;

      if (this.useAWS) {
        // Production: Fetch from AWS Secrets Manager
        secretValue = await this.fetchFromAWS(secretName);
      } else {
        // Development: Fetch from environment variable
        secretValue = this.fetchFromEnvironment(secretName);
      }

      // Validate secret exists if required
      if (required && !secretValue) {
        throw new Error(
          `Required secret '${secretName}' not found. ` +
          `In production: Create in AWS Secrets Manager. ` +
          `In development: Set environment variable ${this.getEnvName(secretName)}.`
        );
      }

      // Validate against schema if provided
      if (secretValue && validationSchema) {
        this.validateSecret(secretName, secretValue, validationSchema);
      }

      // Cache the secret
      if (useCache && secretValue) {
        this.setInCache(secretName, secretValue);
        this.auditLog('SECRET_CACHED', { secretName });
      }

      // Audit log
      this.auditLog('SECRET_RETRIEVED', { 
        secretName,
        source: this.useAWS ? 'aws' : 'environment',
      });

      return secretValue;

    } catch (error) {
      this.auditLog('SECRET_RETRIEVAL_FAILED', {
        secretName,
        error: error.message,
        severity: 'ERROR',
      });

      // Fail securely in production
      if (this.environment === 'production') {
        console.error(`[SECRETS] CRITICAL: Failed to retrieve ${secretName}`);
        throw error;
      }

      // In development, log warning and return undefined
      console.warn(`[SECRETS] Warning: Failed to retrieve ${secretName}: ${error.message}`);
      return undefined;
    }
  }

  /**
   * Get JWT secret specifically
   */
  async getJWTSecret() {
    const secret = await this.getSecret('jwt-secret', {
      required: true,
      validationSchema: this.secretsSchema['jwt-secret'],
    });

    if (!secret) {
      throw new Error('JWT secret is required but not available');
    }

    // Return the key value
    return typeof secret === 'string' ? secret : secret.key;
  }

  /**
   * Get database configuration
   */
  async getDatabaseConfig() {
    return await this.getSecret('database-config', {
      required: this.environment === 'production',
      validationSchema: this.secretsSchema['database-config'],
    });
  }

  /**
   * Get Redis configuration
   */
  async getRedisConfig() {
    return await this.getSecret('redis-config', {
      required: false,
      validationSchema: this.secretsSchema['redis-config'],
    });
  }

  /**
   * Get multiple secrets at once
   */
  async getSecrets(...secretNames) {
    const results = {};
    for (const name of secretNames) {
      results[name] = await this.getSecret(name);
    }
    return results;
  }

  /**
   * Fetch from AWS Secrets Manager
   */
  async fetchFromAWS(secretName) {
    if (!this.client) {
      throw new Error('AWS Secrets Manager client not initialized');
    }

    try {
      const command = new GetSecretValueCommand({
        SecretId: secretName,
        VersionStage: 'AWSCURRENT',
      });

      const response = await client.send(command);

      if (response.SecretString) {
        try {
          return JSON.parse(response.SecretString);
        } catch {
          // If not JSON, return as string
          return response.SecretString;
        }
      } else if (response.SecretBinary) {
        return response.SecretBinary;
      } else {
        throw new Error(`Secret ${secretName} has no value`);
      }

    } catch (error) {
      throw new Error(
        `Failed to retrieve secret from AWS: ${error.message}`
      );
    }
  }

  /**
   * Fetch from environment variable
   */
  fetchFromEnvironment(secretName) {
    const envName = this.getEnvName(secretName);
    const value = process.env[envName];

    if (!value) {
      return null;
    }

    // Try to parse as JSON
    try {
      return JSON.parse(value);
    } catch {
      // Return as string if not JSON
      return value;
    }
  }

  /**
   * Convert secret name to environment variable name
   */
  getEnvName(secretName) {
    return secretName
      .toUpperCase()
      .replace(/-/g, '_');
  }

  /**
   * Validate secret against schema
   */
  validateSecret(secretName, secretValue, schema) {
    if (schema.type === 'object' && typeof secretValue !== 'object') {
      throw new Error(`${secretName} should be an object`);
    }

    if (schema.keys && schema.type === 'object') {
      for (const key of schema.keys) {
        if (!(key in secretValue)) {
          throw new Error(`${secretName} missing required key: ${key}`);
        }
      }
    }
  }

  /**
   * Get from cache
   */
  getFromCache(secretName) {
    if (!this.cache.has(secretName)) {
      return null;
    }

    const cached = this.cache.get(secretName);

    // Check if cache expired
    if (Date.now() - cached.timestamp > this.cacheTTL) {
      this.cache.delete(secretName);
      return null;
    }

    return cached.value;
  }

  /**
   * Set in cache
   */
  setInCache(secretName, value) {
    this.cache.set(secretName, {
      value,
      timestamp: Date.now(),
    });
  }

  /**
   * Clear cache for specific secret or all
   */
  clearCache(secretName = null) {
    if (secretName) {
      this.cache.delete(secretName);
      this.auditLog('CACHE_CLEARED', { secretName });
    } else {
      this.cache.clear();
      this.auditLog('ALL_CACHE_CLEARED', {});
    }
  }

  /**
   * Audit log entry
   */
  auditLog(action, details = {}) {
    const logEntry = {
      timestamp: new Date().toISOString(),
      action,
      environment: this.environment,
      pid: process.pid,
      ...details,
    };

    const logLine = `${JSON.stringify(logEntry)}\n`;

    try {
      // Append to audit log with restricted permissions
      fs.appendFileSync(this.auditLogPath, logLine, { mode: 0o400 });
    } catch (error) {
      // If audit log fails, still log to console in production
      console.error(`[AUDIT-LOG-ERROR] ${error.message}`);
      console.error(`[AUDIT] ${logLine}`);
    }
  }

  /**
   * Get audit log summary
   */
  getAuditSummary(lines = 100) {
    try {
      const content = fs.readFileSync(this.auditLogPath, 'utf8');
      return content
        .split('\n')
        .filter(line => line.trim())
        .slice(-lines)
        .map(line => {
          try {
            return JSON.parse(line);
          } catch {
            return line;
          }
        });
    } catch (error) {
      console.warn(`[AUDIT] Error reading log: ${error.message}`);
      return [];
    }
  }

  /**
   * Initialize all required secrets on startup
   */
  async initialize() {
    console.log('[SECRETS] Initializing required secrets...');

    const requiredSecrets = Object.entries(this.secretsSchema)
      .filter(([name, config]) => config.required)
      .map(([name]) => name);

    const results = {
      success: [],
      failed: [],
    };

    for (const secretName of requiredSecrets) {
      try {
        await this.getSecret(secretName);
        results.success.push(secretName);
        console.log(`[SECRETS] ✓ Loaded ${secretName}`);
      } catch (error) {
        results.failed.push({ name: secretName, error: error.message });
        console.error(`[SECRETS] ✗ Failed to load ${secretName}: ${error.message}`);
      }
    }

    if (results.failed.length > 0) {
      throw new Error(
        `Failed to initialize ${results.failed.length} secret(s). ` +
        `Application cannot start.`
      );
    }

    console.log(`[SECRETS] Successfully initialized ${results.success.length} secret(s)`);
    return results;
  }

  /**
   * Health check for secrets
   */
  async healthCheck() {
    const checks = {};

    for (const [secretName, config] of Object.entries(this.secretsSchema)) {
      try {
        const secret = await this.getSecret(secretName, { required: false });
        checks[secretName] = {
          status: secret ? 'ok' : 'missing',
          required: config.required,
        };
      } catch (error) {
        checks[secretName] = {
          status: 'error',
          error: error.message,
          required: config.required,
        };
      }
    }

    return {
      timestamp: new Date().toISOString(),
      environment: this.environment,
      cacheSize: this.cache.size,
      checks,
    };
  }
}

// Export singleton instance
module.exports = new SecureSecretsManager({
  cacheTTL: parseInt(process.env.SECRETS_CACHE_TTL || '3600000'),
  auditLogPath: process.env.SECRETS_AUDIT_LOG || './logs/secrets-audit.log',
});

// app-with-secure-secrets.js
// Production-ready Express app using secure secrets management

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const cors = require('cors');
const morgan = require('morgan');
const jwt = require('jsonwebtoken');
const { query, validationResult } = require('express-validator');
const fs = require('fs');
const path = require('path');

// CRITICAL: Use secure secrets manager instead of loading from .env
const secretsManager = require('./secrets-manager');

const app = express();

// ==================== INITIALIZATION ====================

// Secrets will be loaded asynchronously
let JWT_SECRET = null;
let isInitialized = false;

/**
 * Initialize application with secrets
 * Must be called before starting server
 */
async function initializeApp() {
  try {
    console.log('[APP] Initializing application...');

    // Load secrets from secure manager
    await secretsManager.initialize();

    // Get JWT secret (this is the critical one)
    JWT_SECRET = await secretsManager.getJWTSecret();

    if (!JWT_SECRET) {
      throw new Error('JWT_SECRET is required but not available');
    }

    isInitialized = true;
    console.log('[APP] ✓ Application initialized successfully');
    console.log('[APP] ✓ Secrets loaded from', 
      process.env.NODE_ENV === 'production' ? 'AWS Secrets Manager' : 'environment'
    );

    return true;
  } catch (error) {
    console.error('[APP] ✗ INITIALIZATION FAILED:', error.message);
    console.error('[APP] Application cannot start without proper secrets');
    process.exit(1);
  }
}

// ==================== MIDDLEWARE ====================

// Ensure initialization before requests
const requireInitialization = (req, res, next) => {
  if (!isInitialized) {
    return res.status(503).json({
      error: 'Service Unavailable',
      message: 'Application is initializing. Please try again in a moment.',
    });
  }
  next();
};

// Security headers
app.use(helmet());
app.use(helmet.contentSecurityPolicy({
  directives: {
    defaultSrc: ["'self'"],
    styleSrc: ["'self'", "'unsafe-inline'"],
    scriptSrc: ["'self'"],
    imgSrc: ["'self'", 'data:', 'https:'],
    objectSrc: ["'none'"],
  },
}));
app.use(helmet.hsts({ maxAge: 31536000, includeSubDomains: true }));

// CORS
const allowedOrigins = process.env.ALLOWED_ORIGINS 
  ? process.env.ALLOWED_ORIGINS.split(',')
  : ['http://localhost:3000'];

const corsOptions = {
  origin: (origin, callback) => {
    if (!origin || allowedOrigins.includes(origin)) {
      callback(null, true);
    } else {
      callback(new Error('Not allowed by CORS'));
    }
  },
  credentials: true,
  methods: ['GET', 'POST', 'PUT', 'DELETE'],
  allowedHeaders: ['Content-Type', 'Authorization'],
  maxAge: 3600,
};
app.use(cors(corsOptions));

// Body parsing with limits
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ limit: '10kb', extended: false }));

// Validate Content-Type
app.use((req, res, next) => {
  if (['POST', 'PUT', 'PATCH'].includes(req.method)) {
    const contentType = req.get('Content-Type');
    if (!contentType || !contentType.includes('application/json')) {
      return res.status(415).json({ error: 'Content-Type must be application/json' });
    }
  }
  next();
});

// HTTP logging
const logsDir = path.join(__dirname, 'logs');
if (!fs.existsSync(logsDir)) {
  fs.mkdirSync(logsDir, { recursive: true });
}

const accessLogStream = fs.createWriteStream(
  path.join(logsDir, 'access.log'),
  { flags: 'a' }
);

morgan.token('auth', (req) => req.headers.authorization ? '[PRESENT]' : '[ABSENT]');
app.use(morgan(':remote-addr - :remote-user [:date[clf]] ":method :url HTTP/:http-version" :status :res[content-length] ":referrer" ":user-agent" auth=:auth', 
  { stream: accessLogStream }
));

// Rate limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 100,
  message: 'Too many requests from this IP',
  standardHeaders: true,
  legacyHeaders: false,
  skip: (req) => process.env.NODE_ENV !== 'production',
});

app.use(limiter);

// Require initialization for all routes
app.use(requireInitialization);

// ==================== LOGGING ====================

const securityLogger = {
  logFailedAuth: (ip, reason) => {
    const log = `[FAILED_AUTH] ${new Date().toISOString()} - IP: ${ip} - Reason: ${reason}\n`;
    fs.appendFileSync(path.join(logsDir, 'security.log'), log);
  },

  logUnauthorizedAccess: (user, resource, ip) => {
    const log = `[UNAUTHORIZED_ACCESS] ${new Date().toISOString()} - User: ${user} - Resource: ${resource} - IP: ${ip}\n`;
    fs.appendFileSync(path.join(logsDir, 'security.log'), log);
  },
};

// ==================== AUTHENTICATION ====================

function authenticateToken(req, res, next) {
  const authHeader = req.headers['authorization'];
  const token = authHeader && authHeader.split(' ')[1];

  if (!token) {
    securityLogger.logFailedAuth(req.ip, 'Missing authentication token');
    return res.status(401).json({ error: 'Access token required' });
  }

  // CRITICAL: Use the loaded JWT_SECRET, never use default
  if (!JWT_SECRET) {
    console.error('[AUTH] CRITICAL: JWT_SECRET not available');
    return res.status(500).json({ error: 'Authentication service unavailable' });
  }

  jwt.verify(token, JWT_SECRET, (err, user) => {
    if (err) {
      securityLogger.logFailedAuth(req.ip, `Invalid token: ${err.message}`);
      return res.status(403).json({ error: 'Invalid or expired token' });
    }

    if (!user.id || !user.role) {
      securityLogger.logFailedAuth(req.ip, 'Invalid token structure');
      return res.status(403).json({ error: 'Invalid token' });
    }

    req.user = user;
    next();
  });
}

// ==================== AUTHORIZATION ====================

function authorize(allowedRoles) {
  return (req, res, next) => {
    if (!req.user || !allowedRoles.includes(req.user.role)) {
      securityLogger.logUnauthorizedAccess(
        req.user?.id || 'unknown',
        req.originalUrl,
        req.ip
      );
      return res.status(403).json({ error: 'Insufficient permissions' });
    }
    next();
  };
}

// ==================== ROUTES ====================

// Health check
app.get('/health', (req, res) => {
  res.json({
    status: 'ok',
    timestamp: new Date().toISOString(),
    environment: process.env.NODE_ENV,
    secretsReady: !!JWT_SECRET,
  });
});

// Secrets health check (admin only)
app.get('/health/secrets', authenticateToken, authorize(['admin']), async (req, res) => {
  try {
    const health = await secretsManager.healthCheck();
    res.json(health);
  } catch (error) {
    res.status(500).json({ error: error.message });
  }
});

// Get users
app.get('/users',
  authenticateToken,
  authorize(['admin', 'staff']),
  query('limit').optional().isInt({ min: 1, max: 100 }).toInt(),
  query('offset').optional().isInt({ min: 0 }).toInt(),
  (req, res) => {
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({ errors: errors.array() });
    }

    const limit = Math.min(req.query.limit || 10, 100);
    const offset = Math.max(req.query.offset || 0, 0);

    try {
      const userData = [
        { id: 1, name: 'Alice' },
        { id: 2, name: 'Bob' },
      ];

      if (req.user.role === 'admin') {
        userData[0].email = 'alice@example.com';
        userData[1].email = 'bob@example.com';
      }

      res.json({
        data: userData,
        pagination: { limit, offset, total: 2 }
      });
    } catch (error) {
      return res.status(500).json({ error: 'Internal server error' });
    }
});

// ==================== ERROR HANDLING ====================

app.use((req, res) => {
  res.status(404).json({ 
    error: 'Not found',
    path: req.originalUrl
  });
});

app.use((err, req, res, next) => {
  const isDevelopment = process.env.NODE_ENV === 'development';

  console.error(`[ERROR] ${new Date().toISOString()} - ${err.message}`);
  if (isDevelopment) {
    console.error(err.stack);
  }

  const response = {
    error: isDevelopment ? err.message : 'An internal server error occurred'
  };

  if (isDevelopment) {
    response.stack = err.stack;
  }

  const statusCode = err.statusCode || 500;
  res.set('X-Content-Type-Options', 'nosniff');
  res.status(statusCode).json(response);
});

// ==================== SERVER STARTUP ====================

const PORT = process.env.PORT || 3000;
const NODE_ENV = process.env.NODE_ENV || 'development';

async function startServer() {
  try {
    // Initialize secrets before starting server
    await initializeApp();

    const server = app.listen(PORT, () => {
      console.log(`\n${'='.repeat(60)}`);
      console.log(`✓ Secure Server Started`);
      console.log(`  Environment: ${NODE_ENV}`);
      console.log(`  Port: ${PORT}`);
      console.log(`  Secrets: Loaded from ${
        NODE_ENV === 'production' ? 'AWS Secrets Manager' : 'Environment'
      }`);
      console.log(`${'='.repeat(60)}\n`);
    });

    // Graceful shutdown
    process.on('SIGTERM', () => {
      console.log('[APP] SIGTERM received, shutting down gracefully...');
      server.close(() => {
        console.log('[APP] Server closed');
        process.exit(0);
      });
    });

    process.on('SIGINT', () => {
      console.log('[APP] SIGINT received, shutting down gracefully...');
      server.close(() => {
        console.log('[APP] Server closed');
        process.exit(0);
      });
    });

  } catch (error) {
    console.error('[APP] Failed to start server:', error.message);
    process.exit(1);
  }
}

// Start if called directly
if (require.main === module) {
  startServer();
}

module.exports = { app, initializeApp, secretsManager };

