## Additional Recommendations

### Development Guidelines
1. **Code Review**: Implement peer review process for all code changes
2. **Security Testing**: Add SAST (Static Application Security Testing) to CI/CD
3. **Dependency Scanning**: Use `npm audit`, Snyk, or WhiteSource
4. **Penetration Testing**: Conduct regular security assessments
5. **Security Training**: Regular training for developers

### Runtime Security
1. **Container Security**: Use non-root user, minimal base images
2. **Network Isolation**: Run in isolated network segments
3. **WAF**: Deploy Web Application Firewall in production
4. **API Versioning**: Implement API versioning for security patches
5. **Backup/Recovery**: Ensure proper backup and disaster recovery

### Compliance
- GDPR: Implement data privacy controls
- PCI-DSS: If handling payment data
- SOC 2: If processing sensitive data
- HIPAA: If handling health information

/**
 * SECURE BASELINE APPLICATION
 * 
 * This file demonstrates production-ready security best practices
 * addressing all findings from the security review.
 */

const express = require('express');
const https = require('https');
const fs = require('fs');
const dotenv = require('dotenv');
const helmet = require('helmet');
const cors = require('cors');
const morgan = require('morgan');
const winston = require('winston');
const rateLimit = require('express-rate-limit');
const jwt = require('jsonwebtoken');
const { query, validationResult } = require('express-validator');

// Load environment variables
dotenv.config();

// Validate required environment variables
const requiredEnvVars = ['JWT_SECRET', 'NODE_ENV'];
const missingEnvVars = requiredEnvVars.filter(envVar => !process.env[envVar]);

if (missingEnvVars.length > 0) {
  console.error(`Missing required environment variables: ${missingEnvVars.join(', ')}`);
  process.exit(1);
}

if (process.env.JWT_SECRET.length < 32) {
  console.error('JWT_SECRET must be at least 32 characters');
  process.exit(1);
}

const isDevelopment = process.env.NODE_ENV === 'development';
const app = express();

// ============================================================================
// LOGGING SETUP
// ============================================================================

const logger = winston.createLogger({
  level: isDevelopment ? 'debug' : 'info',
  format: winston.format.combine(
    winston.format.timestamp({ format: 'YYYY-MM-DD HH:mm:ss' }),
    winston.format.errors({ stack: true }),
    winston.format.json()
  ),
  defaultMeta: { service: 'api-service' },
  transports: [
    new winston.transports.File({ 
      filename: 'logs/error.log', 
      level: 'error',
      maxsize: 5242880, // 5MB
      maxFiles: 5,
    }),
    new winston.transports.File({ 
      filename: 'logs/combined.log',
      maxsize: 5242880, // 5MB
      maxFiles: 5,
    }),
  ],
});

if (isDevelopment) {
  logger.add(new winston.transports.Console({
    format: winston.format.combine(
      winston.format.colorize(),
      winston.format.simple(),
    ),
  }));
}

// ============================================================================
// SECURITY MIDDLEWARE
// ============================================================================

// Helmet: Set comprehensive security headers
app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      scriptSrc: ["'self'"],
      styleSrc: ["'self'", "'unsafe-inline'"],
      imgSrc: ["'self'", 'data:', 'https:'],
      fontSrc: ["'self'"],
      connectSrc: ["'self'"],
      frameSrc: ["'none'"],
      objectSrc: ["'none'"],
    },
  },
  hsts: {
    maxAge: 31536000, // 1 year
    includeSubDomains: true,
    preload: true,
  },
  frameguard: {
    action: 'deny',
  },
  noSniff: true,
  xssFilter: true,
  referrerPolicy: {
    policy: 'strict-origin-when-cross-origin',
  },
}));

// CORS configuration
const corsOptions = {
  origin: function (origin, callback) {
    const allowedOrigins = (process.env.ALLOWED_ORIGINS || 'http://localhost:3000').split(',');

    if (!origin || allowedOrigins.includes(origin.trim())) {
      callback(null, true);
    } else {
      logger.warn(`CORS rejected request from origin: ${origin}`);
      callback(new Error('Not allowed by CORS'));
    }
  },
  credentials: true,
  methods: ['GET', 'POST', 'PUT', 'DELETE', 'OPTIONS'],
  allowedHeaders: ['Content-Type', 'Authorization'],
  maxAge: 3600,
  optionsSuccessStatus: 200,
};

app.use(cors(corsOptions));

// Body size limits to prevent DoS
app.use(express.json({ 
  limit: '10kb',
  strict: true, // Only parse JSON
}));
app.use(express.urlencoded({ 
  limit: '10kb', 
  extended: false,
}));

// HTTP request logging
app.use(morgan(
  ':remote-addr - :remote-user [:date[clf]] ":method :url HTTP/:http-version" :status :res[content-length] ":referrer" ":user-agent"',
  {
    stream: {
      write: (message) => logger.info(message.trim()),
    },
  }
));

// Rate limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true, // Return rate limit info in `RateLimit-*` headers
  legacyHeaders: false, // Disable `X-RateLimit-*` headers
  skip: (req) => {
    // Skip rate limiting for health check
    return req.path === '/health';
  },
  handler: (req, res) => {
    logger.warn(`Rate limit exceeded for IP: ${req.ip}`);
    res.status(429).json({
      status: 429,
      message: 'Too many requests, please try again later.',
    });
  },
});

app.use(limiter);

// Stricter rate limit for authentication attempts
const authLimiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 5, // 5 requests per windowMs
  skipSuccessfulRequests: true,
  message: 'Too many failed authentication attempts, please try again later.',
});

// ============================================================================
// AUTHENTICATION MIDDLEWARE
// ============================================================================

/**
 * Verify JWT token from Authorization header
 */
const authenticateToken = (req, res, next) => {
  const authHeader = req.headers['authorization'];
  const token = authHeader && authHeader.split(' ')[1]; // Bearer TOKEN

  if (!token) {
    logger.warn(`Unauthorized access attempt to ${req.path}`);
    return res.status(401).json({ 
      status: 401,
      error: 'Access token required',
    });
  }

  jwt.verify(token, process.env.JWT_SECRET, (err, user) => {
    if (err) {
      logger.warn(`Invalid token attempt from IP: ${req.ip}`);
      return res.status(403).json({ 
        status: 403,
        error: 'Invalid or expired token',
      });
    }
    req.user = user;
    next();
  });
};

/**
 * Check if user has required role
 */
const authorize = (requiredRoles = []) => {
  return (req, res, next) => {
    if (!req.user) {
      return res.status(401).json({
        status: 401,
        error: 'User not authenticated',
      });
    }

    if (requiredRoles.length > 0 && !requiredRoles.includes(req.user.role)) {
      logger.warn(`Unauthorized role access: user ${req.user.id} attempted to access ${req.path}`);
      return res.status(403).json({
        status: 403,
        error: 'Insufficient permissions',
      });
    }

    next();
  };
};

// ============================================================================
// INPUT VALIDATION
// ============================================================================

const validateUserQuery = [
  query('id')
    .optional()
    .isInt({ min: 1 })
    .toInt()
    .withMessage('ID must be a positive integer'),
  query('name')
    .optional()
    .trim()
    .isLength({ min: 1, max: 255 })
    .withMessage('Name must be between 1 and 255 characters')
    .matches(/^[a-zA-Z\s'-]+$/)
    .withMessage('Name contains invalid characters'),
  query('limit')
    .optional()
    .isInt({ min: 1, max: 100 })
    .toInt()
    .withMessage('Limit must be between 1 and 100'),
];

const validateUserIdParam = [
  query('userId')
    .isInt({ min: 1 })
    .toInt()
    .withMessage('User ID must be a positive integer'),
];

// ============================================================================
// UTILITY FUNCTIONS
// ============================================================================

/**
 * Log security events
 */
const logSecurityEvent = (event, details) => {
  logger.warn({
    timestamp: new Date().toISOString(),
    event,
    ...details,
  });
};

/**
 * Filter user data based on role
 */
const filterUserData = (user, requestingUser) => {
  if (requestingUser.role === 'admin' || requestingUser.id === user.id) {
    // Admin and user viewing own profile see all data
    return user;
  }
  // Regular users only see public information
  return {
    id: user.id,
    name: user.name,
  };
};

/**
 * Mock database
 */
const mockUsers = [
  { id: 1, name: 'Alice', email: 'alice@example.com', role: 'admin' },
  { id: 2, name: 'Bob', email: 'bob@example.com', role: 'user' },
  { id: 3, name: 'Charlie', email: 'charlie@example.com', role: 'user' },
];

// ============================================================================
// ROUTES
// ============================================================================

/**
 * Health check endpoint (no authentication required)
 */
app.get('/health', (req, res) => {
  res.json({ 
    status: 'ok', 
    timestamp: new Date().toISOString(),
    version: '1.0.0',
  });
});

/**
 * Login endpoint - Generate JWT token
 * 
 * In production, verify credentials against database with bcrypt
 */
app.post('/auth/login', authLimiter, (req, res) => {
  const { username, password } = req.body;

  // Input validation
  if (!username || !password) {
    logSecurityEvent('INVALID_LOGIN_ATTEMPT', {
      ip: req.ip,
      reason: 'Missing credentials',
    });
    return res.status(400).json({
      status: 400,
      error: 'Username and password required',
    });
  }

  // Mock authentication (use bcrypt in production)
  const user = mockUsers.find(u => u.name === username);
  if (!user || password !== 'password123') {
    logSecurityEvent('FAILED_LOGIN', {
      ip: req.ip,
      username,
    });
    return res.status(401).json({
      status: 401,
      error: 'Invalid credentials',
    });
  }

  // Generate JWT token
  const token = jwt.sign(
    { 
      id: user.id, 
      name: user.name, 
      role: user.role,
    },
    process.env.JWT_SECRET,
    { 
      expiresIn: '1h',
      issuer: 'api',
      audience: 'web-client',
    }
  );

  logSecurityEvent('SUCCESSFUL_LOGIN', {
    userId: user.id,
    ip: req.ip,
  });

  res.json({
    status: 200,
    message: 'Login successful',
    token,
    expiresIn: 3600,
  });
});

/**
 * Get all users (protected)
 */
app.get('/users', 
  authenticateToken, 
  validateUserQuery,
  (req, res) => {
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      logSecurityEvent('INVALID_QUERY_PARAMS', {
        userId: req.user.id,
        path: req.path,
        errors: errors.array(),
      });
      return res.status(400).json({ 
        status: 400,
        errors: errors.array(),
      });
    }

    const { limit = 10 } = req.query;

    logSecurityEvent('USER_LIST_ACCESS', {
      userId: req.user.id,
      ip: req.ip,
      role: req.user.role,
    });

    // Filter users based on role
    let users = mockUsers;
    if (req.user.role !== 'admin') {
      users = users.map(user => filterUserData(user, req.user));
    }

    res.json({
      status: 200,
      data: users.slice(0, limit),
      total: users.length,
    });
  }
);

/**
 * Get user by ID (protected)
 */
app.get('/users/:id', 
  authenticateToken,
  (req, res) => {
    const userId = parseInt(req.params.id, 10);

    // Validate parameter
    if (isNaN(userId) || userId < 1) {
      logSecurityEvent('INVALID_USER_ID', {
        userId: req.user.id,
        attemptedId: req.params.id,
      });
      return res.status(400).json({ 
        status: 400,
        error: 'Invalid user ID',
      });
    }

    // Authorization check: user can only view their own profile or admin can view any
    if (req.user.id !== userId && req.user.role !== 'admin') {
      logSecurityEvent('UNAUTHORIZED_USER_ACCESS', {
        userId: req.user.id,
        attemptedUserId: userId,
        ip: req.ip,
      });
      return res.status(403).json({ 
        status: 403,
        error: 'Forbidden',
      });
    }

    // Find user
    const user = mockUsers.find(u => u.id === userId);
    if (!user) {
      return res.status(404).json({ 
        status: 404,
        error: 'User not found',
      });
    }

    logSecurityEvent('USER_DETAIL_ACCESS', {
      userId: req.user.id,
      accessedUserId: userId,
      ip: req.ip,
    });

    res.json({
      status: 200,
      data: filterUserData(user, req.user),
    });
  }
);

/**
 * Admin only: Get all users with sensitive data
 */
app.get('/admin/users',
  authenticateToken,
  authorize(['admin']),
  (req, res) => {
    logSecurityEvent('ADMIN_USER_LIST_ACCESS', {
      userId: req.user.id,
      ip: req.ip,
    });

    res.json({
      status: 200,
      data: mockUsers,
      total: mockUsers.length,
    });
  }
);

// ============================================================================
// ERROR HANDLING
// ============================================================================

/**
 * 404 handler
 */
app.use((req, res) => {
  logger.warn(`404 Not Found: ${req.method} ${req.path}`);
  res.status(404).json({ 
    status: 404, 
    message: 'Not found',
  });
});

/**
 * Global error handler (must be last middleware)
 */
app.use((err, req, res, next) => {
  logger.error({
    timestamp: new Date().toISOString(),
    message: err.message,
    stack: err.stack,
    ip: req.ip,
    method: req.method,
    path: req.path,
  });

  // Check if it's a CORS error
  if (err.message === 'Not allowed by CORS') {
    return res.status(403).json({
      status: 403,
      message: 'CORS policy violation',
    });
  }

  // Don't expose error details in production
  const statusCode = err.statusCode || err.status || 500;
  const errorResponse = isDevelopment
    ? {
        status: statusCode,
        message: err.message,
        stack: err.stack,
      }
    : {
        status: statusCode,
        message: statusCode === 500 ? 'Internal server error' : err.message,
      };

  res.status(statusCode).json(errorResponse);
});

// ============================================================================
// SERVER STARTUP
// ============================================================================

const startServer = () => {
  const port = parseInt(process.env.PORT || '3000', 10);

  if (process.env.NODE_ENV === 'production') {
    // Use HTTPS in production
    const options = {
      key: fs.readFileSync(process.env.HTTPS_KEY_PATH || './certs/private-key.pem'),
      cert: fs.readFileSync(process.env.HTTPS_CERT_PATH || './certs/certificate.pem'),
    };

    https.createServer(options, app).listen(port, () => {
      logger.info(`Secure server running on port ${port} (HTTPS)`);
    });

    // Optional: Redirect HTTP to HTTPS
    const httpApp = express();
    httpApp.use((req, res) => {
      res.redirect(`https://${req.hostname}${req.url}`);
    });
    httpApp.listen(3000, () => {
      logger.info('HTTP redirect server running on port 3000');
    });
  } else {
    // HTTP for development
    app.listen(port, () => {
      logger.info(`Development server running on port ${port} (HTTP)`);
    });
  }
};

// Handle uncaught exceptions
process.on('uncaughtException', (err) => {
  logger.error('Uncaught Exception:', err);
  process.exit(1);
});

// Handle unhandled promise rejections
process.on('unhandledRejection', (reason, promise) => {
  logger.error('Unhandled Rejection at:', promise, 'reason:', reason);
  process.exit(1);
});

// Graceful shutdown
process.on('SIGTERM', () => {
  logger.info('SIGTERM received, shutting down gracefully');
  process.exit(0);
});

// Start server
if (require.main === module) {
  startServer();
}

module.exports = app;

