const https = require('https');
const fs = require('fs');
const dotenv = require('dotenv');
const helmet = require('helmet');
const cors = require('cors');
const morgan = require('morgan');
const winston = require('winston');
const rateLimit = require('express-rate-limit');
const jwt = require('jsonwebtoken');
const { query, validationResult } = require('express-validator');

dotenv.config();

// ✅ Validate required configuration
const requiredEnvVars = ['JWT_SECRET', 'NODE_ENV'];
const missing = requiredEnvVars.filter(v => !process.env[v]);
if (missing.length > 0) {
  console.error(`Missing env vars: ${missing.join(', ')}`);
  process.exit(1);
}

const app = express();

// ✅ Comprehensive logging
const logger = winston.createLogger({
  level: process.env.NODE_ENV === 'production' ? 'info' : 'debug',
  format: winston.format.combine(
    winston.format.timestamp(),
    winston.format.json()
  ),
  transports: [
    new winston.transports.File({ filename: 'logs/error.log', level: 'error' }),
    new winston.transports.File({ filename: 'logs/combined.log' }),
  ],
});

// ✅ Security headers with Helmet
app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      scriptSrc: ["'self'"],
    },
  },
  hsts: { maxAge: 31536000, includeSubDomains: true },
  frameguard: { action: 'deny' },
}));

// ✅ CORS with whitelist
app.use(cors({
  origin: (process.env.ALLOWED_ORIGINS || 'http://localhost:3000').split(','),
  credentials: true,
}));

// ✅ Body size limits
app.use(express.json({ limit: '10kb' }));

// ✅ HTTP request logging
app.use(morgan('combined', {
  stream: { write: msg => logger.info(msg.trim()) },
}));

// ✅ Rate limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 100,
  handler: (req, res) => {
    logger.warn(`Rate limit exceeded: ${req.ip}`);
    res.status(429).json({ error: 'Too many requests' });
  },
});
app.use(limiter);

// ✅ Authentication middleware
const authenticateToken = (req, res, next) => {
  const token = req.headers['authorization']?.split(' ')[1];
  if (!token) {
    logger.warn(`Unauthorized access attempt: ${req.path}`);
    return res.status(401).json({ error: 'No token' });
  }

  jwt.verify(token, process.env.JWT_SECRET, (err, user) => {
    if (err) {
      logger.warn(`Invalid token: ${req.ip}`);
      return res.status(403).json({ error: 'Invalid token' });
    }
    req.user = user;
    next();
  });
};

// ✅ Input validation
const validateUserQuery = [
  query('id').optional().isInt({ min: 1 }).toInt(),
  query('limit').optional().isInt({ min: 1, max: 100 }).toInt(),
];

// ✅ Protected endpoint with validation
app.get('/users', authenticateToken, validateUserQuery, (req, res) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({ errors: errors.array() });
  }

  logger.info(`User list accessed by user ${req.user.id}`);

  res.json([
    { id: 1, name: 'Alice' }, // No email for regular users
    { id: 2, name: 'Bob' },
  ]);
});

// ✅ Health check (public endpoint)
app.get('/health', (req, res) => {
  res.json({ 
    status: 'ok', 
    timestamp: new Date().toISOString(),
  });
});

// ✅ Global error handler
app.use((err, req, res, next) => {
  logger.error({
    message: err.message,
    stack: err.stack,
    path: req.path,
    ip: req.ip,
  });

  const status = err.status || 500;
  const message = process.env.NODE_ENV === 'production'
    ? 'Internal server error'
    : err.message;

  res.status(status).json({ status, message });
});

// ✅ 404 handler
app.use((req, res) => {
  res.status(404).json({ status: 404, message: 'Not found' });
});

// ✅ Start server with HTTPS
if (process.env.NODE_ENV === 'production') {
  const options = {
    key: fs.readFileSync(process.env.HTTPS_KEY_PATH),
    cert: fs.readFileSync(process.env.HTTPS_CERT_PATH),
  };
  https.createServer(options, app).listen(3443, () => {
    logger.info('Secure HTTPS server started on port 3443');
  });
} else {
  app.listen(3000, () => {
    logger.info('Development server started on port 3000');
  });
}

module.exports = app;
